INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (5, 'rec0uePVsoi3lQqyF', 90, '90', '1Lord, thou hast been our dwelling-place
in generations all.
2Before thou ever hadst brought forth
the mountains great or small;

Ere ever thou hadst form''d the earth,
and all the world abroad;
Ev''n thou from everlasting art
to everlasting God.

3Thou dost unto destruction
man that is mortal turn;
And unto them thou say''st, Again,
ye sons of men, return.

4Because a thousand years appear
no more before thy sight
Than yesterday, when it is past,
or than a watch by night.

5As with an overflowing flood
thou carry''st them away:
They like a sleep are, like the grass
that grows at morn are they.

6At morn it flourishes and grows,
cut down at ev''n doth fade.
7For by thine anger we''re consum''d,
thy wrath makes us afraid.

8Our sins thou and iniquities
dost in thy presence place,
And sett''st our secret faults before
the brightness of thy face.

9For in thine anger all our days
do pass on to an end;
And as a tale that hath been told,
so we our years do spend.

10Threescore and ten years do sum up
our days and years, we see;
Or, if, by reason of more strength,
in some fourscore they be:

Yet doth the strength of such old men
but grief and labour prove;
For it is soon cut off,
and we fly hence, and soon remove.

11Who knows the power of thy wrath?
according to thy fear
12So is thy wrath: Lord, teach thou us
our end in mind to bear;

And so to count our days, that we
our hearts may still apply
To learn thy wisdom and thy truth,
that we may live thereby.

13Turn yet again to us, O Lord,
how long thus shall it be?
Let it repent thee now for those
that servants are to thee.

14O with thy tender mercies, Lord,
us early satisfy;
So we rejoice shall all our days,
and still be glad in thee.

15According as the days have been,
wherein we grief have had,
And years wherein we ill have seen,
so do thou make us glad.

16O let thy work and pow''r appear
thy servants'' face before;
And shew unto their children dear
thy glory evermore:

17And let the beauty of the Lord
our God be us upon:
Our handy-works establish thou,
establish them each one.', '[{"index": 0, "lines": [{"text": "Lord, thou hast been our dwelling-place", "syllables": ["Lord,", "thou", "hast", "been", "our", "dwellin-", "g-pla-", "ce"], "bibleVerseRef": 1}, {"text": "in generations all."}, {"text": "Before thou ever hadst brought forth", "syllables": ["be-", "fore", "thou", "ever", "hadst", "brou-", "ght", "forth"], "bibleVerseRef": 2}, {"text": "the mountains great or small;"}]}, {"index": 1, "lines": [{"text": "Ere ever thou hadst form''d the earth,", "syllables": ["Ere", "ever", "thou", "hadst", "fo-", "rm''d", "the", "earth,"]}, {"text": "and all the world abroad;", "syllables": ["and", "all", "the", "world", "abro-", "ad;"]}, {"text": "Ev''n thou from everlasting art", "syllables": ["Ev''n", "thou", "from", "eve-", "r-", "las-", "ting", "art"]}, {"text": "to everlasting God.", "syllables": ["to", "eve-", "r-", "las-", "ting", "God."]}]}, {"index": 2, "lines": [{"text": "Thou dost unto destruction", "syllables": ["Thou", "dost", "un-", "to", "des-", "tru-", "c-", "tion"], "bibleVerseRef": 3}, {"text": "man that is mortal turn;"}, {"text": "And unto them thou say''st, Again,"}, {"text": "ye sons of men, return."}]}, {"index": 3, "lines": [{"text": "Because a thousand years appear", "bibleVerseRef": 4}, {"text": "no more before thy sight"}, {"text": "Than yesterday, when it is past,"}, {"text": "or than a watch by night."}]}, {"index": 4, "lines": [{"text": "As with an overflowing flood", "syllables": ["As", "with", "an", "ove-", "r-", "flo-", "wing", "flood"], "bibleVerseRef": 5}, {"text": "thou carry''st them away:"}, {"text": "They like a sleep are, like the grass"}, {"text": "that grows at morn are they."}]}, {"index": 5, "lines": [{"text": "At morn it flourishes and grows,", "bibleVerseRef": 6}, {"text": "cut down at ev''n doth fade."}, {"text": "For by thine anger we''re consum''d,", "bibleVerseRef": 7}, {"text": "thy wrath makes us afraid."}]}, {"index": 6, "lines": [{"text": "Our sins thou and iniquities"