INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (6, 'rec1BFOAgc2naiRtW', 30, '30', '1Lord, I will thee extol, for thou
hast lifted me on high,
And over me thou to rejoice
mad''st not mine enemy.

2O thou who art the Lord my God,
I in distress to thee,
With loud cries lifted up my voice,
and thou hast healed me.

3O Lord, my soul thou hast brought up,
and rescu''d from the grave;
That I to pit should not go down,
alive thou didst me save.

4O ye that are his holy ones,
sing praise unto the Lord;
And give unto him thanks, when ye
his holiness record.

5For but a moment lasts his wrath;
life in his favour lies:
Weeping may for a night endure,
at morn doth joy arise.

6In my prosperity I said,
that nothing shall me move.
7O Lord, thou hast my mountain made
to stand strong by thy love:

But when that thou, O gracious God,
didst hide thy face from me,
Then quickly was my prosp''rous state
turn''d into misery.

8Wherefore unto the Lord my cry
I caused to ascend:
My humble supplication
I to the Lord did send.

9What profit is there in my blood,
when I go down to pit?
Shall unto thee the dust give praise?
thy truth declare shall it?

10Hear, Lord, have mercy; help me, Lord:
11Thou turned hast my sadness
To dancing; yea, my sackcloth loos''d,
and girded me with gladness;

12That sing thy praise my glory may,
and never silent be.
O Lord my God, for evermore
I will give thanks to thee.', '[{"index": 0, "lines": [{"text": "Lord, I will thee extol, for thou", "bibleVerseRef": 1}, {"text": "hast lifted me on high,"}, {"text": "And over me thou to rejoice", "syllables": ["And", "over", "me", "thou", "to", "re-", "joi-", "ce"]}, {"text": "mad''st not mine enemy."}]}, {"index": 1, "lines": [{"text": "O thou who art the Lord my God,", "bibleVerseRef": 2}, {"text": "I in distress to thee,"}, {"text": "With loud cries lifted up my voice,"}, {"text": "and thou hast healed me."}]}, {"index": 2, "lines": [{"text": "O Lord, my soul thou hast brought up,", "bibleVerseRef": 3}, {"text": "and rescu''d from the grave;", "syllables": ["and", "rescu''d", "from", "the", "gra-", "ve;"]}, {"text": "That I to pit should not go down,"}, {"text": "alive thou didst me save."}]}, {"index": 3, "lines": [{"text": "O ye that are his holy ones,", "bibleVerseRef": 4}, {"text": "sing praise unto the Lord;"}, {"text": "And give unto him thanks, when ye"}, {"text": "his holiness record."}]}, {"index": 4, "lines": [{"text": "For but a moment lasts his wrath;", "bibleVerseRef": 5}, {"text": "life in his favour lies:"}, {"text": "Weeping may for a night endure,"}, {"text": "at morn doth joy arise."}]}, {"index": 5, "lines": [{"text": "In my prosperity I said,", "bibleVerseRef": 6}, {"text": "that nothing shall me move."}, {"text": "O Lord, thou hast my mountain made", "bibleVerseRef": 7}, {"text": "to stand strong by thy love:"}]}, {"index": 6, "lines": [{"text": "But when that thou, O gracious God,"}, {"text": "didst hide thy face from me,"}, {"text": "Then quickly was my prosp''rous state", "syllables": ["Then", "qui-", "ckly", "was", "my", "pros-", "p''rous", "state"]}, {"text": "turn''d into misery.", "syllables": ["tu-", "rn''d", "in-", "to", "mise-", "ry."]}]}, {"index": 7, "lines": [{"text": "Wherefore unto the Lord my cry", "bibleVerseRef": 8}, {"text": "I caused to ascend:"}, {"text": "My humble supplication", "syllables": ["My", "hu-", "m-", "ble", "sup-", "pli-", "ca-", "tion"]}, {"text": "I to the Lord did send."}]}, {"index": 8, "lines": [{"text": "What profit is there in my blood,", "bibleVerseRef": 9}, {"text": "when I go down to pit?"}, {"text": "Shall unto thee the dust give praise?"}, {"text": "thy truth declare shall it?"}]}, {"index": 9, "lines": [{"text": "Hear, Lord, have mercy; help me, Lord:", "bibleVerseRef": 10}, {"text": "Thou turned hast my sadness", "syllables": ["Thou", "turned", "hast", "my", "sad-", "ness"], "bibleVerseRef": 11}, {"text": "To dancing; yea, my sackcloth loos''d,"}, {"text": "and girded me with gladness;", "syllables": ["and", "girded", "me", "with", "glad-", "ness;"]}]}, {"index": 10, "lines": [{"text": "That sing thy praise my glory may,", "bibleVerseRef": 12}, {"text": "and never silent be.", "syllables": ["and", "ne-", "ver", "sile-", "nt", "be."]}, {"text": "O Lord my God, for evermore", "syllables": ["O", "Lord", "my", "God,", "for", "eve-", "r-", "more"]}, {"text": "I will give thanks to thee."}]}]', 'CM', NULL, 'Lord, I will thee extol, for thou...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (7, 'rec1cfTEzbgN3CFHB', 71, '71', '1O Lord, my hope and confidence
is plac''d in thee alone;
Then let thy servant never be
put to confusion.

2And let me, in thy righteousness,
from thee deliv''rance have;
Cause me escape, incline thine ear unto me,
and me save.

3Be thou my dwelling-rock, to which
I ever may resort:
Thou gav''st commandment me to save,
for thou''rt my rock and fort.

4Free me, my God, from wicked hands,
hands cruel and unjust:
5For thou, O Lord God, art my hope,
and from my youth my trust.

6Thou from the womb didst hold me up;
thou art the same that me
Out of my mother''s bowels took;
I ever will praise thee.

7To many I a wonder am;
but thou''rt my refuge strong.
8Fill''d let my mouth be with thy praise
and honour all day long.

9O do not cast me off, when as
old age doth overtake me;
And when my strength decayed is,
then do not thou forsake me.

10For those that are mine enemies
against me speak with hate;
And they together counsel take
that for my soul lay wait.

11They said, God leaves him; him pursue
and take: none will him save.
12Be thou not far from me, my God:
thy speedy help I crave.

13Confound, consume them, that unto
my soul are enemies:
Cloth''d be they with reproach and shame
that do my hurt devise.

14But I with expectation
will hope continually;
And yet with praises more and more
I will thee magnify.

15Thy justice and salvation
my mouth abroad shall show,
Ev''n all the day; for I thereof
the numbers do not know.

16And I will constantly go on
in strength of God the Lord;
And thine own righteousness, ev''n thine
alone, I will record.

17For even from my youth, O God,
by thee I have been taught;
And hitherto I have declar''d
the wonders thou hast wrought.

18And now, Lord, leave me not, when I
old and gray-headed grow:
Till to this age thy strength and pow''r
to all to come I show.

19And thy most perfect righteousness
O Lord, is very high,
Who hast so great things done: O God,
who is like unto thee?

20Thou, Lord, who great adversities,
and sore, to me didst show,
Shalt quicken, and bring me again
from depths of earth below.

21My greatness and my pow''r thou wilt
increase, and far extend:
On ev''ry side against all grief
thou wilt me comfort send.

22Thee, ev''n thy truth, I''ll also praise,
my God, with psaltery:
Thou Holy One of Israel,
with harp I''ll sing to thee.

23My lips shall much rejoice in thee,
when I thy praises sound;
My soul, which thou redeemed hast,
in joy shall much abound.

24My tongue thy justice shall proclaim,
continuing all day long;
For they confounded are, and sham''d,
that seek to do me wrong.', '[{"index": 0, "lines": [{"text": "O Lord, my hope and confidence", "syllables": ["O", "Lord,", "my", "hope", "and", "confi-", "den-", "ce"], "bibleVerseRef": 1}, {"text": "is plac''d in thee alone;"}, {"text": "Then let thy servant never be"}, {"text": "put to confusion.", "syllables": ["put", "to", "con-", "fu-", "sio-", "n."]}]}, {"index": 1, "lines": [{"text": "And let me, in thy righteousness,", "bibleVerseRef": 2}, {"text": "from thee deliv''rance have;", "syllables": ["from", "thee", "deliv-", "''ran-", "ce", "have;"]}, {"text": "Cause me escape, incline thine ear unto me,", "syllables": ["Cause", "me", "escape,", "incline", "thine", "ear", "unto", "me,"]}, {"text": "and me save.", "syllables": ["and", "me", "save-", "-", "-", "."]}]}, {"index": 2, "lines": [{"text": "Be thou my dwelling-rock, to which", "bibleVerseRef": 3}, {"text": "I ever may resort:", "syllables": ["I", "ever", "may", "re-", "so-", "rt:"]}, {"text": "Thou gav''st commandment me to save,"}, {"text": "for thou''rt my rock and fort."}]}, {"index": 3, "lines": [{"text": "Free me, my God, from wicked hands,", "bibleVerseRef": 4}, {"text": "hands cruel and unjust:", "syllables": ["ha-", "nds", "cruel", "and", "un-", "just:"]}, {"text": "For thou, O Lord God, art my hope,", "bibleVerseRef": 5}, {"text": "and from my youth my trust."}]}, {"index": 4, "lines": [{"text": "Thou from the womb didst hold me up;", "bibleVerseRef": 6}, {"text": "thou art the same that me"}, {"text": "Out of my mother''s bowels took;", "syllables": ["Out", "of", "my", "mo-", "the-", "r''s", "bowels", "took;"]}, {"text": "I ever will praise thee.", "syllables": ["I", "ever", "will", "prai-", "se", "thee."]}]}, {"index": 5, "lines": [{"text": "To many I a wonder am;", "bibleVerseRef": 7}, {"text": "but thou''rt my refuge strong."}, {"text": "Fill''d let my mouth be with thy praise", "bibleVerseRef": 8}, {"text": "and honour all day long."}]}, {"index": 6, "lines": [{"text": "O do not cast me off