INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (3, 'rec0nktaSJL3WGGtk', 149, '149', '1Praise ye the Lord: unto him sing
a new song, and his praise
In the assembly of his saints
in sweet psalms do ye raise.

2Let Isr''el in his Maker joy,
and to him praises sing:
Let all that Sion''s children are
be joyful in their King.

3O let them unto his great name
give praises in the dance;
Let them with timbrel and with harp
in songs his praise advance.

4For God doth pleasure take in those
that his own people be;
And he with his salvation
the meek will beautify.

5And in his glory excellent
let all his saints rejoice:
Let them to him upon their beds
aloud lift up their voice.

6Let in their mouth aloft be rais''d
the high praise of the Lord,
And let them have in their right hand
a sharp two-edged sword;

7To execute the vengeance due
upon the heathen all,
And make deserved punishment
upon the people fall.

8And ev''n with chains, as pris''ners, bind
their kings that them command;
Yea, and with iron fetters strong,
the nobles of their land.

9On them the judgment to perform
found written in his word:
This honour is to all his saints.
O do ye praise the Lord.', '[{"index": 0, "lines": [{"text": "Praise ye the Lord: unto him sing", "bibleVerseRef": 1}, {"text": "a new song, and his praise"}, {"text": "In the assembly of his saints"}, {"text": "in sweet psalms do ye raise."}]}, {"index": 1, "lines": [{"text": "Let Isr''el in his Maker joy,", "syllables": ["Let", "is-", "r''el", "in", "his", "Make-", "r", "joy,"], "bibleVerseRef": 2}, {"text": "and to him praises sing:", "syllables": ["and", "to", "him", "praise-", "s", "sing:"]}, {"text": "Let all that Sion''s children are", "syllables": ["Let", "all", "that", "Sio-", "n''s", "chil-", "dren", "are"]}, {"text": "be joyful in their King."}]}, {"index": 2, "lines": [{"text": "O let them unto his great name", "bibleVerseRef": 3}, {"text": "give praises in the dance;"}, {"text": "Let them with timbrel and with harp"}, {"text": "in songs his praise advance.", "syllables": ["in", "songs", "his", "praise", "advan-", "ce."]}]}, {"index": 3, "lines": [{"text": "For God doth pleasure take in those", "bibleVerseRef": 4}, {"text": "that his own people be;", "syllables": ["that", "his", "own", "peo-", "ple", "be;"]}, {"text": "And he with his salvation", "syllables": ["And", "he", "wi-", "th", "his", "sal-", "va-", "tion"]}, {"text": "the meek will beautify."}]}, {"index": 4, "lines": [{"text": "And in his glory excellent", "syllables": ["And", "in", "his", "glo-", "ry", "ex-", "celle-", "nt"], "bibleVerseRef": 5}, {"text": "let all his saints rejoice:"}, {"text": "Let them to him upon their beds"}, {"text": "aloud lift up their voice."}]}, {"index": 5, "lines": [{"text": "Let in their mouth aloft be rais''d", "bibleVerseRef": 6}, {"text": "the high praise of the Lord,"}, {"text": "And let them have in their right hand"}, {"text": "a sharp two-edged sword;"}]}, {"index": 6, "lines": [{"text": "To execute the vengeance due", "bibleVerseRef": 7}, {"text": "upon the heathen all,"}, {"text": "And make deserved punishment"}, {"text": "upon the people fall.", "syllables": ["upon", "the", "pe-", "o-", "ple", "fall."]}]}, {"index": 7, "lines": [{"text": "And ev''n with chains, as pris''ners, bind", "bibleVerseRef": 8}, {"text": "their kings that them command;"}, {"text": "Yea, and with iron fetters strong,"}, {"text": "the nobles of their land."}]}, {"index": 8, "lines": [{"text": "On them the judgment to perform", "bibleVerseRef": 9}, {"text": "found written in his word:"}, {"text": "This honour is to all his saints."}, {"text": "O do ye praise the Lord."}]}]', 'CM', NULL, 'Praise ye the Lord: unto him sing...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (17, 'rec5JcEAPxE9XUkDo', 102, '102 (Second Version, Recommended)', '1Lord, hear my pray''r, and let my cry
Have speedy access unto thee;
2In day of my calamity
O hide not thou thy face from me.

Hear when I call to thee; that day
An answer speedily return:
3My days, like smoke, consume away,
And, as an hearth, my bones do burn.

4My heart is wounded very sore,
And withered, like grass doth fade:
I am forgetful grown therefore
To take and eat my daily bread.

5By reason of my smart within,
And voice of my most grievous groans,
My flesh consumed is, my skin,
All parch''d, doth cleave unto my bones.

6The pelican of wilderness,
The owl in desert, I do match;
7And, sparrow-like, companionless,
Upon the house''s top, I watch.

8I all day long am made a scorn,
Reproach''d by my malicious foes:
The madmen are against me sworn,
The men against me that arose.

9For I have ashes eaten up,
To me as if they had been bread;
And with my drink I in my cup
Of bitter tears a mixture made.

10Because thy wrath was not appeas''d,
And dreadful indignation:
Therefore it was that thou me rais''d,
And thou again didst cast me down.

11My days are like a shade alway,
Which doth declining swiftly pass;
And I am withered away,
Much like unto the fading grass.

12But thou, O Lord, shalt still endure,
From change and all mutation free,
And to all generations sure
Shall thy remembrance ever be.

13Thou shalt arise, and mercy yet
Thou to mount Sion shalt extend:
Her time for favour which was set,
Behold, is now come to an end.

14Thy saints take pleasure in her stones,
Her very dust to them is dear.
15All heathen lands and kingly thrones
On earth thy glorious name shall fear.

16God in his glory shall appear,
When Sion he builds and repairs.
17He shall regard and lend his ear
Unto the needy''s humble pray''rs:

Th'' afflicted''s pray''r he will not scorn.
18All times this shall be on record:
And generations yet unborn
Shall praise and magnify the Lord.

19He from his holy place look''d down,
The earth he view''d from heav''n on high;
20To hear the pris''ner''s mourning groan,
And free them that are doom''d to die;

21That Sion, and Jerus''lem too,
His name and praise may well record,
22When people and the kingdoms do
Assemble all to praise the Lord.

23My strength he weaken''d in the way,
My days of life he shortened
24My God, O take me not away
In mid-time of my days, I said:

Thy years throughout all ages last
25Of old thou hast established
The earth''s foundation firm and fast:
Thy mighty hands the heav''ns have made.

26They perish shall, as garments do,
But thou shalt evermore endure;
As vestures, thou shalt change them so;
And they shall all be changed sure:

27But from all changes thou art free;
Thy endless years do last for aye
28Thy servants, and their seed who be,
Establish''d shall before thee stay.', '[{"index": 0, "lines": [{"text": "Lord, hear my pray''r, and let my cry", "bibleVerseRef": 1}, {"text": "Have speedy access unto thee;"}, {"text": "In day of my calamity", "bibleVerseRef": 2}, {"text": "O hide not thou thy face from me."}]}, {"index": 1, "lines": [{"text": "Hear when I call to thee; that day"}, {"text": "An answer speedily return:"}, {"text": "My days, like smoke, consume away,", "syllables": ["My", "days,", "like", "smoke,", "con-", "sume", "a-", "way,"], "bibleVerseRef": 3}, {"text": "And, as an hearth, my bones do burn."}]}, {"index": 2, "lines": [{"text": "My heart is wounded very sore,", "bibleVerseRef": 4}, {"text": "And withered, like grass doth fade:"}, {"text": "I am forgetful grown therefore"}, {"text": "To take and eat my daily bread."}]}, {"index": 3, "lines": [{"text": "By reason of my smart within,", "bibleVerseRef": 5}, {"text": "And voice of my most grievous groans,", "syllables": ["And", "voice", "of", "my", "most", "grievous", "gro-", "ans,"]}, {"text": "My flesh consumed is, my skin,"}, {"text": "All parch''d, doth cleave unto my bones.", "syllables": ["All", "parch''d,", "doth", "cleave", "un-", "to", "my", "bones."]}]}, {"index": 4, "lines": [{"text": "The pelican of wilderness,", "bibleVerseRef": 6}, {"text": "The owl in desert, I do match;"}, {"text": "And, sparrow-like, companionless,", "syllables": ["And,", "sparrow-", "-li-", "ke,", "com-", "pa-", "nion-", "less,"], "bibleVerseRef": 7}, {"text": "Upon the house''s top, I watch.", "syllables": ["u-", "pon", "the", "house-", "''s", "top,", "I", "watch."]}]}, {"index": 5, "lines": [{"text": "I all day long am made a scorn,", "bibleVerseRef": 8}, {"text": "Reproach''d by my malicious foes:", "syllables": ["repro-", "ach''d", "by", "my", "ma-", "li-", "cious", "foes:"]}, {"text": "The madmen are against me sworn,"}, {"text": "The men against me that arose."}]}, {"index": 6, "lines": [{"text": "For I have ashes eaten up,", "bibleVerseRef": 