INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (15, 'rec4vwfL1pJ1v4e5k', 64, '64', '1When I to thee my prayer make,
Lord, to my voice give ear;
My life save from the enemy,
of whom I stand in fear.

2Me from their secret counsel hide
who do live wickedly;
From insurrection of those men
that work iniquity:

3Who do their tongues with malice whet,
and make them cut like swords;
In whose bent bows are arrows set,
ev''n sharp and bitter words:

4That they may at the perfect man
in secret aim their shot;
Yea, suddenly they dare at him to shoot,
and fear it not.

5In ill encourage they themselves,
and their snares close do lay:
Together conference they have;
Who shall them see? they say.

6They have search''d out iniquities,
a perfect search they keep:
Of each of them the inward thought,
and very heart, is deep.

7God shall an arrow shoot at them,
and wound them suddenly:
8So their own tongue shall them confound;
all who them see shall fly.

9And on all men a fear shall fall,
God''s works they shall declare;
For they shall wisely notice take
what these his doings are.

10In God the righteous shall rejoice,
and trust upon his might;
Yea, they shall greatly glory all
in heart that are upright.', '[{"index": 0, "lines": [{"text": "When I to thee my prayer make,", "bibleVerseRef": 1}, {"text": "Lord, to my voice give ear;"}, {"text": "My life save from the enemy,"}, {"text": "of whom I stand in fear."}]}, {"index": 1, "lines": [{"text": "Me from their secret counsel hide", "bibleVerseRef": 2}, {"text": "who do live wickedly;"}, {"text": "From insurrection of those men"}, {"text": "that work iniquity:"}]}, {"index": 2, "lines": [{"text": "Who do their tongues with malice whet,", "bibleVerseRef": 3}, {"text": "and make them cut like swords;"}, {"text": "In whose bent bows are arrows set,"}, {"text": "ev''n sharp and bitter words:"}]}, {"index": 3, "lines": [{"text": "That they may at the perfect man", "bibleVerseRef": 4}, {"text": "in secret aim their shot;"}, {"text": "Yea, suddenly they dare at him to shoot,", "syllables": ["Yea,", "suddenly", "they", "dare", "at", "him", "to", "shoot,"]}, {"text": "and fear it not.", "syllables": ["and", "fea-", "-", "r", "it", "not."]}]}, {"index": 4, "lines": [{"text": "In ill encourage they themselves,", "syllables": ["In", "ill", "encou-", "rage", "they", "them-", "sel-", "ves,"], "bibleVerseRef": 5}, {"text": "and their snares close do lay:", "syllables": ["and", "their", "snares", "close", "do", "lay:"]}, {"text": "Together conference they have;", "syllables": ["toge-", "ther", "con-", "fe-", "ren-", "ce", "they", "have;"]}, {"text": "Who shall them see? they say."}]}, {"index": 5, "lines": [{"text": "They have search''d out iniquities,", "bibleVerseRef": 6}, {"text": "a perfect search they keep:"}, {"text": "Of each of them the inward thought,"}, {"text": "and very heart, is deep."}]}, {"index": 6, "lines": [{"text": "God shall an arrow shoot at them,", "bibleVerseRef": 7}, {"text": "and wound them suddenly:"}, {"text": "So their own tongue shall them confound;", "syllables": ["So", "their", "own", "tongue", "shall", "them", "con-", "found;"], "bibleVerseRef": 8}, {"text": "all who them see shall fly."}]}, {"index": 7, "lines": [{"text": "And on all men a fear shall fall,", "bibleVerseRef": 9}, {"text": "God''s works they shall declare;"}, {"text": "For they shall wisely notice take"}, {"text": "what these his doings are.", "syllables": ["what", "these", "his", "doi-", "ngs", "are."]}]}, {"index": 8, "lines": [{"text": "In God the righteous shall rejoice,", "bibleVerseRef": 10}, {"text": "and trust upon his might;"}, {"text": "Yea, they shall greatly glory all"}, {"text": "in heart that are upright."}]}]', 'CM', NULL, 'When I to thee my prayer make...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (16, 'rec5Fc64aKwEGz57P', 8, '8', '1How excellent in all the earth,
Lord, our Lord, is thy name!
Who hast thy glory far advanc''d
above the starry frame.

2From infants'' and from sucklings'' mouth
thou didest strength ordain,
For thy foes'' cause, that so thou might''st
th'' avenging foe restrain.

3When I look up unto the heav''ns,
which thine own fingers fram''d,
Unto the moon, and to the stars,
which were by thee ordain''d;

4Then say I, What is man, that he
remember''d is by thee?
Or what the son of man, that thou
so kind to him should''st be?

5For thou a little lower hast
him than the angels made;
With glory and with dignity
thou crowned hast his head.

6Of thy hands'' works thou mad''st him lord,
all under''s feet didst lay;
7All sheep and oxen, yea, and beasts
that in the field do stray;

8Fowls of the air, fish of the sea,
all that pass through the same.
9How excellent in all the earth,
Lord, our Lord, is thy name!', '[{"index": 0, "lines": [{"text": "How excellent in all the earth,", "syllables": ["How", "ex-", "celle-", "nt", "in", "all", "the", "earth,"], "bibleVerseRef": 1}, {"text": "Lord, our Lord, is thy name!"}, {"text": "Who hast thy glory far advanc''d"}, {"text": "above the starry frame.", "syllables": ["above", "the", "star-", "ry", "fra-", "me."]}]}, {"index": 1, "lines": [{"text": "From infants'' and from sucklings'' mouth", "bibleVerseRef": 2}, {"text": "thou didest strength ordain,"}, {"text": "For thy foes'' cause, that so thou might''st"}, {"text": "th'' avenging foe restrain."}]}, {"index": 2, "lines": [{"text": "When I look up unto the heav''ns,", "bibleVerseRef": 3}, {"text": "which thine own fingers fram''d,"}, {"text": "Unto the moon, and to the stars,"}, {"text": "which were by thee ordain''d;"}]}, {"index": 3, "lines": [{"text": "Then say I, What is man, that he", "bibleVerseRef": 4}, {"text": "remember''d is by thee?"}, {"text": "Or what the son of man, that thou"}, {"text": "so kind to him should''st be?"}]}, {"index": 4, "lines": [{"text": "For thou a little lower hast", "syllables": ["For", "thou", "a", "lit-", "tle", "lowe-", "r", "hast"], "bibleVerseRef": 5}, {"text": "him than the angels made;"}, {"text": "With glory and with dignity"}, {"text": "thou crowned hast his head."}]}, {"index": 5, "lines": [{"text": "Of thy hands'' works thou mad''st him lord,", "bibleVerseRef": 6}, {"text": "all under''s feet didst lay;"}, {"text": "All sheep and oxen, yea, and beasts", "syllables": ["All", "sheep", "and", "oxen,", "yea,", "and", "bea-", "sts"], "bibleVerseRef": 7}, {"text": "that in the field do stray;"}]}, {"index": 6, "lines": [{"text": "Fowls of the air, fish of the sea,", "bibleVerseRef": 8}, {"text": "all that pass through the same."}, {"text": "How excellent in all the earth,", "syllables": ["How", "ex-", "celle-", "nt", "in", "all", "the", "earth,"], "bibleVerseRef": 9}, {"text": "Lord, our Lord, is thy name!"}]}]', 'CM', NULL, 'How excellent in all the earth...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (9, 'rec2IrtCotT8lNiMj', 55, '55', '1Lord, hear my pray''r, hide not thyself
from my entreating voice:
2Attend and hear me; in my plaint
I mourn and make a noise.

3Because of th'' en''my''s voice, and for
lewd men''s oppression great:
On me they cast iniquity,
and they in wrath me hate.

4Sore pain''d within me is my heart:
death''s terrors on me fall.
5On me comes trembling, fear and dread
o''erwhelmed me withal.

6O that I, like a dove, had wings,
said I, then would I flee
Far hence, that I might find a place
where I in rest might be.

7Lo, then far off I wander would,
and in the desert stay;
8From windy storm and tempest I
would haste to ''scape away.

9O Lord, on them destruction bring,
and do their tongues divide;
For in the city violence
and strife I have espy''d.

10They day and night upon the walls
do go about it round:
There mischief is, and sorrow there
in midst of it is found.

11Abundant wickedness there is
within her inward part;
And from her streets deceitfulness
and guile do not depart.

12He was no foe that me reproach''d,
then that endure I could;
Nor hater that did ''gainst me boast,
from him me hide I would.

13But thou, man, who mine equal, guide,
and mine acquaintance wast:
14We join''d sweet counsels, to God''s house
in company we past.

15Let death upon them seize, and down
let them go quick to hell;
For wickedness doth much abound
among them where they dwell.

16I''ll call on God: God will me save.
17I''ll pray, and make a noise
At ev''ning, morning, and at noon;
and he shall hear my voice.

18He hath my soul delivered,
that it in peace might be
From battle that against me was;
for many were with me.

19The Lord shall hear, and them afflict,
of old who hath abode:
Because they never changes have,
therefore they fear not God.

20''Gainst those that were at peace with him
he hath put forth his hand:
The covenant that he had made,
by breaking he profan''d.

21More smooth than butter were his words,
while in his heart was war;
His speeches were more soft than oil,
and yet drawn swords they are.

22Cast thou thy burden on the Lord,
and he shall thee sustain;
Yea, he shall cause the righteous man
unmoved to remain.

23But thou, O Lord my God, those men
in justice shalt o''erthrow,
And in destruction''s dungeon dark
at last shalt lay them low:

The bloody and deceitful men
shall not live half their days:
But upon thee with confidence
I will depend always.', '[{"index": 0, "lines": [{"text": "Lord, hear my pray''r, hide not thyself", "syllables": ["Lord,", "hear", "my", "pray-", "''r,", "hide", "not", "thyself"], "bibleVerseRef": 1}, {"text": "from my entreating voice:"}, {"text": "Attend and hear me; in my plaint", "bibleVerseRef": 2}, {"text": "I mourn and make a noise."}]}, {"index": 1, "lines": [{"text": "Because of th'' en''my''s voice, and for", "syllables": ["because", "of", "th''", "en-", "''my''s", "voice,", "and", "for"], "bibleVerseRef": 3}, {"text": "lewd men''s oppression great:"}, {"text": "On me they cast iniquity,"}, {"text": "and they in wrath me hate."}]}, {"index": 2, "lines": [{"text": "Sore pain''d within me is my heart:", "bibleVerseRef": 4}, {"text": "death''s terrors on me fall."}, {"text": "On me comes trembling, fear and dread", "bibleVerseRef": 5}, {"text": "o''erwhelmed me withal."}]}, {"index": 3, "lines": [{"text": "O that I, like a dove, had wings,", "bibleVerseRef": 6}, {"text": "said I, then would I flee"}, {"text": "Far hence, that I might find a place", "syllables": ["Far", "hence,", "that", "I", "might", "find", "a", "place"]}, {"text": "where I in rest might be."}]}, {"index": 4, "lines": [{"text": "Lo, then far off I wander would,", "bibleVerseRef": 7}, {"text": "and in the desert stay;"}, {"text": "From windy storm and tempest I", "bibleVerseRef": 8}, {"text": "would haste to ''scape away.", "syllables": ["would", "haste", "to", "''scape", "a-", "way."]}]}, {"index": 5, "lines": [{"text": "O Lord, on them destruction bring,", "bibleVerseRef": 9}, {"text": "and do their tongues divide;"}, {"text": "For in the city violence", "syllables": ["For", "in", "the", "ci-", "ty", "viole-", "n-", "ce"]}, {"text": "and strife I have espy''d.", "syllables": ["and", "strife", "I", "have", "es-", "py''d."]}]}, {"index": 6, "lines": [{"text": "They day and night upon the walls", "bibleVerseRef": 10}, {"text": "do go about it round:"}, {"text": "There mischief is, and sorrow there"}, {"text": "in midst of it is found."}]}, {"index": 7, "lines": [{"text": "Abundant wickedness there is", "bibleVerseRef": 11}, {"text": "within her inward part;"}, {"text": "And from her streets deceitfulness"}, {"text": "and guile do not depart.", "syllables": ["and", "guile", "do", "not", "de-", "part."]}]}, {"index": 8, "lines": [{"text": "He was no foe that me reproach''d,", "syllables": ["He", "was", "no", "foe", "that", "me", "repro-", "ach''d,"], "bibleVerseRef": 12}, {"text": "then that endure I could;"}, {"text": "Nor hater that did ''gainst me boast,"}, {"text": "from him me hide I would."}]}, {"index": 9, "lines": [{"text": "But thou, man, who mine equal, guide,", "syllables": ["But", "thou,", "man,", "who", "mine", "equal,", "gui-", "de,"], "bibleVerseRef": 13}, {"text": "and mine acquaintance wast:", "syllables": ["and", "mine", "acquain-", "tan-", "ce", "wast:"]}, {"text": "We join''d sweet counsels, to God''s house", "bibleVerseRef": 14}, {"text": "in company we past."}]}, {"index": 10, "lines": [{"text": "Let death upon them seize, and down", "bibleVerseRef": 15}, {"text": "let them go quick to hell;", "syllables": ["let", "them", "go", "quick", "to", "hell;"]}, {"text": "For wickedness doth much abound"}, {"text": "among them where they dwell."}]}, {"index": 11, "lines": [{"text": "I''ll call on God: God will me save.", "bibleVerseRef": 16}, {"text": "I''ll pray, and make a noise", "bibleVerseRef": 17}, {"text": "At ev''ning, morning, and at noon;"}, {"text": "and he shall hear my voice."}]}, {"index": 12, "lines": [{"text": "He hath my soul delivered,", "bibleVerseRef": 18}, {"text": "that it in peace might be"}, {"text": "From battle that against me was;"}, {"text": "for many were with me."}]}, {"index": 13, "lines": [{"text": "The Lord shall hear, and them afflict,", "bibleVerseRef": 19}, {"text": "of old who hath abode:"}, {"text": "Because they never changes have,"}, {"text": "therefore they fear not God."}]}, {"index": 14, "lines": [{"text": "''Gainst those that were at peace with him", "bibleVerseRef": 20}, {"text": "he hath put forth his hand:"}, {"text": "The covenant that he had made,", "syllables": ["The", "cove-", "-", "nant", "that", "he", "had", "made,"]}, {"text": "by breaking he profan''d."}]}, {"index": 15, "lines": [{"text": "More smooth than butter were his words,", "bibleVerseRef": 21}, {"text": "while in his heart was war;"}, {"text": "His speeches were more soft than oil,"}, {"text": "and yet drawn swords they are."}]}, {"index": 16, "lines": [{"text": "Cast thou thy burden on the Lord,", "bibleVerseRef": 22}, {"text": "and he shall thee sustain;"}, {"text": "Yea, he shall cause the righteous man"}, {"text": "unmoved to remain."}]}, {"index": 17, "lines": [{"text": "But thou, O Lord my God, those men", "bibleVerseRef": 23}, {"text": "in justice shalt o''erthrow,"}, {"text": "And in destruction''s dungeon dark", "syllables": ["And", "in", "destruc-", "tion''s", "dun-", "ge-", "on", "dark"]}, {"text": "at last shalt lay them low:"}]}, {"index": 18, "lines": [{"text": "The bloody and deceitful men"}, {"text": "shall not live half their days:"}, {"text": "But upon thee with confidence", "syllables": ["But", "upon", "thee", "with", "con-", "fi-", "den-", "ce"]}, {"text": "I will depend always."}]}]', 'CM', NULL, 'Lord, hear my pray''r, hide not thyself...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (12, 'rec31IjidHEAQoClF', 96, '96', '1O sing a new song to the Lord:
sing all the earth to God.
2To God sing, bless his name, shew still
his saving health abroad.

3Among the heathen nations
his glory do declare;
And unto all the people shew
his works that wondrous are.

4For great''s the Lord,
and greatly he is to be magnify''d;
Yea, worthy to be fear''d is he
above all gods beside.

5For all the gods are idols dumb,
which blinded nations fear;
But our God is the Lord, by whom
the heav''ns created were.

6Great honour is before his face,
and majesty divine;
Strength is within his holy place,
and there doth beauty shine.

7Do ye ascribe unto the Lord,
of people ev''ry tribe,
Glory do ye unto the Lord,
and mighty pow''r ascribe.

8Give ye the glory to the Lord
that to his name is due;
Come ye into his courts, and bring
an offering with you.

9In beauty of his holiness,
O do the Lord adore;
Likewise let all the earth throughout
tremble his face before.

10Among the heathen say, God reigns;
the world shall stedfastly
Be fix''d from moving; he shall judge
the people righteously.

11Let heav''ns be glad before the Lord,
and let the earth rejoice;
Let seas, and all that is therein,
cry out, and make a noise.

12Let fields rejoice, and ev''ry thing
that springeth of the earth:
Then woods and ev''ry tree shall sing
with gladness and with mirth

13Before the Lord; because he comes,
to judge the earth comes he:
He''ll judge the world with righteousness,
the people faithfully.', '[{"index": 0, "lines": [{"text": "O sing a new song to the Lord:", "bibleVerseRef": 1}, {"text": "sing all the earth to God."}, {"text": "To God sing, bless his name, shew still", "bibleVerseRef": 2}, {"text": "his saving health abroad.", "syllables": ["his", "saving", "health", "ab-", "ro-", "ad."]}]}, {"index": 1, "lines": [{"text": "Among the heathen nations", "syllables": ["a-", "mong", "the", "hea-", "then", "na-", "tio-", "ns"], "bibleVerseRef": 3}, {"text": "his glory do declare;"}, {"text": "And unto all the people shew", "syllables": ["And", "unto", "all", "the", "pe-", "o-", "ple", "shew"]}, {"text": "his works that wondrous are."}]}, {"index": 2, "lines": [{"text": "For great''s the Lord,", "syllables": ["For", "grea-", "-", "-", "-", "t''s", "the", "Lord,"], "bibleVerseRef": 4}, {"text": "and greatly he is to be magnify''d;", "syllables": ["and", "greatly", "he", "is", "to", "bemagnify''d;"]}, {"text": "Yea, worthy to be fear''d is he"}, {"text": "above all gods beside."}]}, {"index": 3, "lines": [{"text": "For all the gods are idols dumb,", "bibleVerseRef": 5}, {"text": "which blinded nations fear;"}, {"text": "But our God is the Lord, by whom"}, {"text": "the heav''ns created were.", "syllables": ["the", "hea-", "v''ns", "crea-", "ted", "were."]}]}, {"index": 4, "lines": [{"text": "Great honour is before his face,", "bibleVerseRef": 6}, {"text": "and majesty divine;"}, {"text": "Strength is within his holy place,", "syllables": ["Strength", "is", "within", "his", "ho-", "ly", "pla-", "ce,"]}, {"text": "and there doth beauty shine."}]}, {"index": 5, "lines": [{"text": "Do ye ascribe unto the Lord,", "syllables": ["Do", "ye", "ascri-", "be", "un-", "to", "the", "Lord,"], "bibleVerseRef": 7}, {"text": "of people ev''ry tribe,", "syllables": ["of", "people", "ev-", "''ry", "tri-", "be,"]}, {"text": "Glory do ye unto the Lord,"}, {"text": "and mighty pow''r ascribe.", "syllables": ["and", "mighty", "pow''r", "as-", "cri-", "be."]}]}, {"index": 6, "lines": [{"text": "Give ye the glory to the Lord", "bibleVerseRef": 8}, {"text": "that to his name is due;"}, {"text": "Come ye into his courts, and bring"}, {"text": "an offering with you."}]}, {"index": 7, "lines": [{"text": "In beauty of his holiness,", "bibleVerseRef": 9}, {"text": "O do the Lord adore;"}, {"text": "Likewise let all the earth throughout"}, {"text": "tremble his face before.", "syllables": ["tre-", "mble", "his", "face", "be-", "fore."]}]}, {"index": 8, "lines": [{"text": "Among the heathen say, God reigns;", "bibleVerseRef": 10}, {"text": "the world shall stedfastly"}, {"text": "Be fix''d from moving; he shall judge", "syllables": ["Be", "fix''d", "from", "moving;", "he", "shall", "jud-", "ge"]}, {"text": "the people righteously.", "syllables": ["the", "people", "righte-", "o-", "us-", "ly."]}]}, {"index": 9, "lines": [{"text": "Let heav''ns be glad before the Lord,", "bibleVerseRef": 11}, {"text": "and let the earth rejoice;"}, {"text": "Let seas, and all that is therein,", "syllables": ["Let", "seas,", "and", "all", "that", "is", "therei-", "n,"]}, {"text": "cry out, and make a noise."}]}, {"index": 10, "lines": [{"text": "Let fields rejoice, and ev''ry thing", "bibleVerseRef": 12}, {"text": "that springeth of the earth:"}, {"text": "Then woods and ev''ry tree shall sing"}, {"text": "with gladness and with mirth"}]}, {"index": 11, "lines": [{"text": "Before the Lord; because he comes,", "bibleVerseRef": 13}, {"text": "to judge the earth comes he:", "syllables": ["to", "judge", "the", "earth", "comes", "he:"]}, {"text": "He''ll judge the world with righteousness,", "syllables": ["He''ll", "judge", "the", "world", "with", "righ-", "teous-", "ness,"]}, {"text": "the people faithfully.", "syllables": ["the", "peo-", "ple", "fait-", "hful-", "ly."]}]}]', 'CM', NULL, 'O sing a new song to the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (10, 'rec2LqlMgvUBDYhtp', 104, '104', '1Bless God, my soul. O Lord my God,
thou art exceeding great;
With honour and with majesty
thou clothed art in state.

2With light, as with a robe, thyself
thou coverest about;
And, like unto a curtain, thou
the heavens stretchest out.

3Who of his chambers doth the beams
within the waters lay;
Who doth the clouds his chariot make,
on wings of wind make way.

4Who flaming fire his ministers,
his angels sp''rits, doth make:
5Who earth''s foundations did lay,
that it should never shake.

6Thou didst it cover with the deep,
as with a garment spread:
The waters stood above the hills,
when thou the word but said.

7But at the voice of thy rebuke
they fled, and would not stay;
They at thy thunder''s dreadful voice
did haste them fast away.

8They by the mountains do ascend,
and by the valley-ground
Descend, unto that very place
which thou for them didst found.

9Thou hast a bound unto them set,
that they may not pass over,
That they do not return again
the face of earth to cover.

10He to the valleys sends the springs,
which run among the hills:
11They to all beasts of field give drink,
wild asses drink their fills.

12By them the fowls of heav''n shall have
their habitation,
Which do among the branches sing
with delectation.

13He from his chambers watereth
the hills, when they are dry''d:
With fruit and increase of thy works
the earth is satisfy''d.

14For cattle he makes grass to grow,
he makes the herb to spring
For th'' use of man, that food to him
he from the earth may bring;

15And wine, that to the heart of man
doth cheerfulness impart,
Oil that his face makes shine,
and bread that strengtheneth his heart.

16The trees of God are full of sap;
the cedars that do stand
In Lebanon, which planted were
by his almighty hand.

17Birds of the air upon their boughs
do chuse their nests to make;
As for the stork, the fir-tree she
doth for her dwelling take.

18The lofty mountains for wild goats
a place of refuge be;
The conies also to the rocks
do for their safety flee.

19He sets the moon in heav''n, thereby
the seasons to discern:
From him the sun his certain time
of going down doth learn.

20Thou darkness mak''st, ''tis night, then beasts
of forests creep abroad.
21The lions young roar for their prey,
and seek their meat from God.

22The sun doth rise, and home they flock,
down in their dens they lie.
23Man goes to work, his labour he
doth to the ev''ning ply.

24How manifold, Lord, are thy works!
in wisdom wonderful
Thou ev''ry one of them hast made;
earth''s of thy riches full:

25So is this great and spacious sea,
wherein things creeping are,
Which number''d cannot be; and beasts
both great and small are there.

26There ships go; there thou mak''st to play
that leviathan great.
27These all wait on thee, that thou may''st
in due time give them meat.

28That which thou givest unto them
they gather for their food;
Thine hand thou open''st lib''rally,
they filled are with good.

29Thou hid''st thy face; they troubled are,
their breath thou tak''st away;
Then do they die, and to their dust
return again do they.

30Thy quick''ning spirit thou send''st forth,
then they created be;
And then the earth''s decayed face
renewed is by thee.

31The glory of the mighty Lord
continue shall for ever:
The Lord JEHOVAH shall rejoice
in all his works together.

32Earth, as affrighted, trembleth all,
if he on it but look;
And if the mountains he but touch,
they presently do smoke.

33I will sing to the Lord most high,
so long as I shall live;
And while I being have I shall
to my God praises give.

34Of him my meditation shall
sweet thoughts to me afford;
And as for me, I will rejoice
in God, my only Lord.

35From earth let sinners be consum''d,
let ill men no more be.
O thou my soul, bless thou the Lord.
Praise to the Lord give ye.', '[{"index": 0, "lines": [{"text": "Bless God, my soul. O Lord my God,", "bibleVerseRef": 1}, {"text": "thou art exceeding great;"}, {"text": "With honour and with majesty"}, {"text": "thou clothed art in state."}]}, {"index": 1, "lines": [{"text": "With light, as with a robe, thyself", "syllables": ["With", "light,", "as", "with", "a", "robe,", "thyse-", "lf"], "bibleVerseRef": 2}, {"text": "thou coverest about;", "syllables": ["thou", "cove-", "-", "rest", "a-", "bout;"]}, {"text": "And, like unto a curtain, thou"}, {"text": "the heavens stretchest out.", "syllables": ["the", "heave-", "ns", "stret-", "chest", "out."]}]}, {"index": 2, "lines": [{"text": "Who of his chambers doth the beams", "bibleVerseRef": 3}, {"text": "within the waters lay;", "syllables": ["wi-", "thin", "the", "wate-", "rs", "lay;"]}, {"text": "Who doth the clouds his chariot make,"}, {"text": "on wings of wind make way."}]}, {"index": 3, "lines": [{"text": "Who flaming fire his ministers,", "bibleVerseRef": 4}, {"text": "his angels sp''rits, doth make:"}, {"text": "Who earth''s foundations did lay,", "syllables": ["Who", "ea-", "rth''s", "foun-", "da-", "tions", "did", "lay,"], "bibleVerseRef": 5}, {"text": "that it should never shake."}]}, {"index": 4, "lines": [{"text": "Thou didst it cover with the deep,", "syllables": ["Thou", "di-", "dst", "it", "cover", "with", "the", "deep,"], "bibleVerseRef": 6}, {"text": "as with a garment spread:"}, {"text": "The waters stood above the hills,", "syllables": ["The", "wate-", "rs", "stood", "a-", "bove", "the", "hills,"]}, {"text": "when thou the word but said."}]}, {"index": 5, "lines": [{"text": "But at the voice of thy rebuke", "bibleVerseRef": 7}, {"text": "they fled, and would not stay;"}, {"text": "They at thy thunder''s dreadful voice"}, {"text": "did haste them fast away.", "syllables": ["did", "haste", "them", "fast", "a-", "way."]}]}, {"index": 6, "lines": [{"text": "They by the mountains do ascend,", "bibleVerse