INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (30, 'rec8EBIBVaE1i5wK1', 3, '3', '1O Lord, how are my foes increas''d?
against me many rise.
2Many say of my soul, For him
in God no succour lies.

3Yet thou my shield and glory art,
th'' uplifter of mine head.
4I cry''d, and, from his holy hill,
the Lord me answer made.

5I laid me down and slept; I wak''d;
for God sustained me.
6I will not fear though thousands ten
set round against me be.

7Arise, O Lord; save me, my God;
for thou my foes hast stroke
All on the cheek-bone, and the teeth
of wicked men hast broke.

8Salvation doth appertain
unto the Lord alone:
Thy blessing, Lord, for evermore
thy people is upon.', '[{"index": 0, "lines": [{"text": "O Lord, how are my foes increas''d?", "bibleVerseRef": 1}, {"text": "against me many rise."}, {"text": "Many say of my soul, For him", "bibleVerseRef": 2}, {"text": "in God no succour lies."}]}, {"index": 1, "lines": [{"text": "Yet thou my shield and glory art,", "bibleVerseRef": 3}, {"text": "th'' uplifter of mine head.", "syllables": ["th''", "uplif-", "ter", "of", "mine", "head."]}, {"text": "I cry''d, and, from his holy hill,", "bibleVerseRef": 4}, {"text": "the Lord me answer made."}]}, {"index": 2, "lines": [{"text": "I laid me down and slept; I wak''d;", "bibleVerseRef": 5}, {"text": "for God sustained me."}, {"text": "I will not fear though thousands ten", "bibleVerseRef": 6}, {"text": "set round against me be."}]}, {"index": 3, "lines": [{"text": "Arise, O Lord; save me, my God;", "bibleVerseRef": 7}, {"text": "for thou my foes hast stroke", "syllables": ["for", "thou", "my", "foes", "hast", "stroke"]}, {"text": "All on the cheek-bone, and the teeth", "syllables": ["All", "on", "the", "cheek-bo-", "ne,", "and", "the", "teeth"]}, {"text": "of wicked men hast broke.", "syllables": ["of", "wicked", "men", "hast", "bro-", "ke."]}]}, {"index": 4, "lines": [{"text": "Salvation doth appertain", "syllables": ["sa-", "l-", "va-", "tion", "doth", "ap-", "per-", "tain"], "bibleVerseRef": 8}, {"text": "unto the Lord alone:"}, {"text": "Thy blessing, Lord, for evermore", "syllables": ["Thy", "ble-", "s-", "sing,", "Lord,", "for", "ever-", "more"]}, {"text": "thy people is upon.", "syllables": ["thy", "peo-", "ple", "is", "u-", "pon."]}]}]', 'CM', NULL, 'O Lord, how are my foes increas''d...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (11, 'rec2OjrwUfFYrGrqf', 143, '143 (First Version)', '1Lord, hear my pray''r, attend my suits;
and in thy faithfulness
Give thou an answer unto me,
and in thy righteousness.

2Thy servant also bring thou not
in judgment to be try''d:
Because no living man can be
in thy sight justify''d.

3For th'' en''my hath pursu''d my soul,
my life to ground down tread:
In darkness he hath made me dwell,
as who have long been dead.

4My sp''rit is therefore overwhelm''d
in me perplexedly;
Within me is my very heart
amazed wondrously.

5I call to mind the days of old,
to meditate I use
On all thy works; upon the deeds
I of thy hands do muse.

6My hands to thee I stretch; my soul
thirsts, as dry land, for thee.
7Haste, Lord, to hear, my spirit fails:
hide not thy face from me;

Lest like to them I do become
that go down to the dust.
8At morn let me thy kindness hear;
for in thee do I trust.

Teach me the way that I should walk:
I lift my soul to thee.
9Lord, free me from my foes; I flee
to thee to cover me.

10Because thou art my God, to do
thy will do me instruct:
Thy Sp''rit is good, me to the land
of uprightness conduct.

11Revive and quicken me, O Lord,
ev''n for thine own name''s sake;
And do thou, for thy righteousness,
my soul from trouble take.

12And of thy mercy slay my foes;
let all destroyed be
That do afflict my soul: for I
a servant am to thee.', '[{"index": 0, "lines": [{"text": "Lord, hear my pray''r, attend my suits;", "syllables": ["Lord,", "hear", "my", "pray''r,", "attend", "my", "su-", "its;"], "bibleVerseRef": 1}, {"text": "and in thy faithfulness"}, {"text": "Give thou an answer unto me,"}, {"text": "and in thy righteousness."}]}, {"index": 1, "lines": [{"text": "Thy servant also bring thou not", "bibleVerseRef": 2}, {"text": "in judgment to be try''d:"}, {"text": "Because no living man can be"}, {"text": "in thy sight justify''d."}]}, {"index": 2, "lines": [{"text": "For th'' en''my hath pursu''d my soul,", "syllables": ["For", "th''", "en''my", "hath", "pur-", "su''d", "my", "soul,"], "bibleVerseRef": 3}, {"text": "my life to ground down tread:"}, {"text": "In darkness he hath made me dwell,"}, {"text": "as who have long been dead."}]}, {"index": 3, "lines": [{"text": "My sp''rit is therefore overwhelm''d", "syllables": ["My", "sp''rit", "is", "there-", "fore", "over-", "whe-", "lm''d"], "bibleVerseRef": 4}, {"text": "in me perplexedly;"}, {"text": "Within me is my very heart"}, {"text": "amazed wondrously."}]}, {"index": 4, "lines": [{"text": "I call to mind the days of old,", "bibleVerseRef": 5}, {"text": "to meditate I use"}, {"text": "On all thy works; upon the deeds"}, {"text": "I of thy hands do muse."}]}, {"index": 5, "lines": [{"text": "My hands to thee I stretch; my soul", "bibleVerseRef": 6}, {"text": "thirsts, as dry land, for thee."}, {"text": "Haste, Lord, to hear, my spirit fails:", "syllables": ["haste,", "Lord,", "to", "hear,", "my", "spi-", "rit", "fails:"], "bibleVerseRef": 7}, {"text": "hide not thy face from me;"}]}, {"index": 6, "lines": [{"text": "Lest like to them I do become"}, {"text": "that go down to the dust."}, {"text": "At morn let me thy kindness hear;", "bibleVerseRef": 8}, {"text": "for in thee do I trust."}]}, {"index": 7, "lines": [{"text": "Teach me the way that I should walk:"}, {"text": "I lift my soul to thee."}, {"text": "Lord, free me from my foes; I flee", "bibleVerseRef": 9}, {"text": "to thee to cover me.", "syllables": ["to", "thee", "to", "cove-", "r", "me."]}]}, {"index": 8, "lines": [{"text": "Because thou art my God, to do", "bibleVerseRef": 10}, {"text": "thy will do me instruct:"}, {"text": "Thy Sp''rit is good, me to the land"}, {"text": "of uprightness conduct."}]}, {"index": 9, "lines": [{"text": "Revive and quicken me, O Lord,", "syllables": ["revive", "and", "qu-", "i-", "cken", "me,", "O", "Lord,"], "bibleVerseRef": 11}, {"text": "ev''n for thine own name''s sake;"}, {"text": "And do thou, for thy righteousness,"}, {"text": "my soul from trouble take."}]}, {"index": 10, "lines": [{"text": "And of thy mercy slay my foes;", "bibleVerseRef": 12}, {"text": "let all destroyed be", "syllables": ["let", "all", "des-", "troye-", "d", "be"]}, {"text": "That do afflict my soul: for I"}, {"text": "a servant am to thee."}]}]', 'CM', 'First Version', 'Lord, hear my pray''r, attend my suits...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (31, 'rec8XNUjP6EK9Lmi7', 31, '31', '1In thee, O Lord, I put my trust,
sham''d let me never be;
According to thy righteousness
do thou deliver me.

2Bow down thine ear to me, with speed
send me deliverance:
To save me, my strong rock be thou,
and my house of defence.

3Because thou art my rock, and thee
I for my fortress take;
Therefore do thou me lead and guide,
ev''n for thine own name''s sake.

4And sith thou art my strength, therefore
pull me out of the net,
Which they in subtilty for me
so privily have set.

5Into thine hands I do commit
my sp''rit: for thou art he,
O thou, JEHOVAH, God of truth,
that hast redeemed me.

6Those that do lying vanities
regard, I have abhorr''d:
But as for me, my confidence
is fixed on the Lord.

7I''ll in thy mercy gladly joy:
for thou my miseries
Consider''d hast; thou hast my soul
known in adversities:

8And thou hast not inclosed me
within the en''my''s hand;
And by thee have my feet been made
in a large room to stand.

9O Lord, upon me mercy have,
for trouble is on me:
Mine eye, my belly, and my soul,
with grief consumed be.

10Because my life with grief is spent,
my years with sighs and groans:
My strength doth fail; and for my sin
consumed are my bones.

11I was a scorn to all my foes,
and to my friends a fear;
And specially reproach''d of those
that were my neighbours near:

When they me saw they from me fled.
12Ev''n so I am forgot,
As men are out of mind when dead:
I''m like a broken pot.

13For slanders I of many heard;
fear compass''d me, while they
Against me did consult, and plot
to take my life away.

14But as for me, O Lord, my trust
upon thee I did lay;
And I to thee, Thou art my God,
did confidently say.

15My times are wholly in thine hand:
do thou deliver me
From their hands that mine enemies
and persecutors be.

16Thy countenance to shine do thou
upon thy servant make:
Unto me give salvation,
for thy great mercies'' sake.

17Let me not be asham''d, O Lord,
for on thee call''d I have:
Let wicked men be sham''d, let them
be silent in the grave.

18To silence put the lying lips,
that grievous things do say,
And hard reports, in pride and scorn,
on righteous men do lay.

19How great''s the goodness thou for them
that fear thee keep''st in store,
And wrought''st for them that trust in thee
the sons of men before!

20In secret of thy presence thou
shalt hide them from man''s pride:
From strife of tongues thou closely shalt,
as in a tent, them hide.

21All praise and thanks be to the Lord;
for he hath magnify''d
His wondrous love to me within
a city fortify''d.

22For from thine eyes cut off I am,
I in my haste had said;
My voice yet heard''st thou, when to thee
with cries my moan I made.

23O love the Lord, all ye his saints;
because the Lord doth guard
The faithful, and he plenteously
proud doers doth reward.

24Be of good courage, and he strength
unto your heart shall send,
All ye whose hope and confidence
doth on the Lord depend.', '[{"index": 0, "lines": [{"text": "In thee, O Lord, I put my trust,", "bibleVerseRef": 1}, {"text": "sham''d let me never be;"}, {"text": "According to thy righteousness"}, {"text": "do thou deliver me.", "syllables": ["do", "thou", "de-", "live-", "r", "me."]}]}, {"index": 1, "lines": [{"text": "Bow down thine ear to me, with speed", "bibleVerseRef": 2}, {"text": "send me deliverance:", "syllables": ["send", "me", "deli-", "ve-", "ran-", "ce:"]}, {"text": "To save me, my strong rock be thou,"}, {"text": "and my house of defence."}]}, {"index": 2, "lines": [{"text": "Because thou art my rock, and thee", "bibleVerseRef": 3}, {"text": "I for my fortress take;"}, {"text": "Therefore do thou me lead and guide,", "syllables": ["therefore", "do", "thou", "me", "lead", "and", "gui-", "de,"]}, {"text": "ev''n for thine own name''s sake."}]}, {"index": 3, "lines": [{"text": "And sith thou art my strength, therefore", "bibleVerseRef": 4}, {"text": "pull me out of the net,"}, {"text": "Which they in subtilty for me"}, {"text": "so privily have set."}]}, {"index": 4, "lines": [{"text": "Into thine hands I do commit", "bibleVerseRef": 5}, {"text": "my sp''rit: for thou art he,"}, {"text": "O thou, JEHOVAH, God of truth,"}, {"text": "that hast redeemed me."}]}, {"index": 5, "lines": [{"text": "Those that do lying vanities", "syllables": ["Tho-", "se", "that", "do", "lying", "va-", "ni-", "ties"], "bibleVerseRef": 6}, {"text": "regard, I have abhorr''d:"}, {"text": "But as for me, my confidence", "syllables": ["But", "as", "for", "me,", "my", "confi-", "den-", "ce"]}, {"text": "is fixed on the Lord."}]}, {"index": 6, "lines": [{"text": "I''ll in thy mercy gladly joy:", "bibleVerseRef": 7}, {"text": "for thou my miseries", "syllables": ["for", "thou", "my", "mise-", "-", "ries"]}, {"text": "Consider''d hast; thou hast my soul"}, {"text": "known in adversities:"}]}, {"index": 7, "lines": [{"text": "And thou hast not inclosed me", "bibleVerseRef": 8}, {"text": "within the en''my''s hand;"}, {"text": "And by thee have my feet been made"}, {"text": "in a large room to stand.", "syllables": ["in", "a", "large", "room", "to", "stand."]}]}, {"index": 8, "lines": [{"text": "O Lord, upon me mercy have,", "bibleVerseRef": 9}, {"text": "for trouble is on me:"}, {"text": "Mine eye, my belly, and my soul,"}, {"text": "with grief consumed be."}]}, {"index": 9, "lines": [{"text": "Because my life with grief is spent,", "bibleVerseRef": 10}, {"text": "my years with sighs and groans:", "syllables": ["my", "years", "with", "sighs", "and", "groans:"]}, {"text": "My strength doth fail; and for my sin"}, {"text": "consumed are my bones."}]}, {"index": 10, "lines": [{"text": "I was a scorn to all my foes,", "bibleVerseRef": 11}, {"text": "and to my friends a fear;"}, {"text": "And specially reproach''d of those", "syllables": ["And", "specia-", "lly", "rep-", "ro-", "ach''d", "of", "those"]}, {"text": "that were my neighbours near:"}]}, {"index": 11, "lines": [{"text": "When they me saw they from me fled."}, {"text": "Ev''n so I am forgot,", "bibleVerseRef": 12}, {"text": "As men are out of mind when dead:"}, {"text": "I''m like a broken pot."}]}, {"index": 12, "lines": [{"text": "For slanders I of many heard;", "bibleVerseRef": 13}, {"text": "fear compass''d me, while they"}, {"text": "Against me did consult, and plot"}, {"text": "to take my life away."}]}, {"index": 13, "lines": [{"text": "But as for me, O Lord, my trust", "bibleVerseRef": 14}, {"text": "upon thee I did lay;"}, {"text": "And I to thee, Thou art my God,"}, {"text": "did confidently say."}]}, {"index": 14, "lines": [{"text": "My times are wholly in thine hand:", "bibleVerseRef": 15}, {"text": "do thou deliver me", "syllables": ["do", "thou", "de-", "live-", "r", "me"]}, {"text": "From their hands that mine enemies"}, {"text": "and persecutors be."}]}, {"index": 15, "lines": [{"text": "Thy countenance to shine do thou", "syllables": ["Thy", "counte-", "nan-", "ce", "to", "shine", "do", "thou"], "bibleVerseRef": 16}, {"text": "upon thy servant make:"}, {"text": "Unto me give salvation,", "syllables": ["un-", "to", "me", "give", "sal-", "va-", "tio-", "n,"]}, {"text": "for thy great mercies'' sake."}]}, {"index": 16, "lines": [{"text": "Let me not be asham''d, O Lord,", "bibleVerseRef": 17}, {"text": "for on thee call''d I have:"}, {"text": "Let wicked men be sham''d, let them"}, {"text": "be silent in the grave."}]}, {"index": 17, "lines": [{"text": "To silence put the lying lips,", "syllables": ["To", "sile-", "n-", "ce", "put", "the", "lying", "lips,"], "bibleVerseRef": 18}, {"text": "that grievous things do say,"}, {"text": "And hard reports, in pride and scorn,", "syllables": ["And", "hard", "reports,", "in", "pri-", "de", "and", "scorn,"]}, {"text": "on righteous men do lay."}]}, {"index": 18, "lines": [{"text": "How great''s the goodness thou for them", "bibleVerseRef": 19}, {"text": "that fear thee keep''st in store,", "syllables": ["that", "fear", "thee", "keep''st", "in", "store,"]}, {"text": "And wrought''st for them that trust in thee"}, {"text": "the sons of men before!"}]}, {"index": 19, "lines": [{"text": "In secret of thy presence thou", "bibleVerseRef": 20}, {"text": "shalt hide them from man''s pride:", "syllables": ["shalt", "hide", "them", "from", "man''s", "pride:"]}, {"text": "From strife of tongues thou closely shalt,", "syllables": ["From", "strife", "of", "tongues", "thou", "close-", "ly", "shalt,"]}, {"text": "as in a tent, them hide."}]}, {"index": 20, "lines": [{"text": "All praise and thanks be to the Lord;", "bibleVerseRef": 21}, {"text": "for he hath magnify''d"}, {"text": "His wondrous love to me within"}, {"text": "a city fortify''d."}]}, {"index": 21, "lines": [{"text": "For from thine eyes cut off I am,", "bibleVerseRef": 22}, {"text": "I in my haste had said;", "syllables": ["I", "in", "my", "haste", "had", "said;"]}, {"text": "My voice yet heard''st thou, when to thee"}, {"text": "with cries my moa