INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (28, 'rec7gOoe08DFwIkfK', 12, '12', '1Help, Lord, because the godly man
doth daily fade away;
And from among the sons of men
the faithful do decay.

2Unto his neighbour ev''ry one
doth utter vanity:
They with a double heart do speak,
and lips of flattery.

3God shall cut off all flatt''ring lips,
tongues that speak proudly thus,
4We''ll with our tongue prevail, our lips
are ours: who''s lord o''er us?

5For poor oppress''d,
and for the sighs of needy, rise will
I, Saith God, and him in safety set
from such as him defy.

6The words of God are words most pure;
they be like silver try''d
In earthen furnace, seven times
that hath been purify''d.

7Lord, thou shalt them preserve and keep
for ever from this race.
8On each side walk the wicked, when
vile men are high in place.', '[{"index": 0, "lines": [{"text": "Help, Lord, because the godly man", "bibleVerseRef": 1}, {"text": "doth daily fade away;"}, {"text": "And from among the sons of men"}, {"text": "the faithful do decay."}]}, {"index": 1, "lines": [{"text": "Unto his neighbour ev''ry one", "bibleVerseRef": 2}, {"text": "doth utter vanity:"}, {"text": "They with a double heart do speak,"}, {"text": "and lips of flattery."}]}, {"index": 2, "lines": [{"text": "God shall cut off all flatt''ring lips,", "bibleVerseRef": 3}, {"text": "tongues that speak proudly thus,"}, {"text": "We''ll with our tongue prevail, our lips", "syllables": ["We''ll", "with", "our", "tongue", "pre-", "vail,", "our", "lips"], "bibleVerseRef": 4}, {"text": "are ours: who''s lord o''er us?"}]}, {"index": 3, "lines": [{"text": "For poor oppress''d,", "syllables": ["For", "poo-", "-", "-", "r", "op-", "pre-", "ss''d,"], "bibleVerseRef": 5}, {"text": "and for the sighs of needy, rise will", "syllables": ["and", "for", "the", "sighs", "of", "needy,risewill"]}, {"text": "I, Saith God, and him in safety set", "syllables": ["I,", "Saith", "God,", "and", "him", "in", "safety", "set"]}, {"text": "from such as him defy."}]}, {"index": 4, "lines": [{"text": "The words of God are words most pure;", "bibleVerseRef": 6}, {"text": "they be like silver try''d"}, {"text": "In earthen furnace, seven times"}, {"text": "that hath been purify''d."}]}, {"index": 5, "lines": [{"text": "Lord, thou shalt them preserve and keep", "bibleVerseRef": 7}, {"text": "for ever from this race.", "syllables": ["for", "ever", "from", "this", "race-", "."]}, {"text": "On each side walk the wicked, when", "bibleVerseRef": 8}, {"text": "vile men are high in place.", "syllables": ["vile", "men", "are", "high", "in", "place."]}]}]', 'CM', NULL, 'Help, Lord, because the godly man...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (39, 'recAeOlgIVErfVLzR', 4, '4', '1Give ear unto me when I call,
God of my righteousness:
Have mercy, hear my pray''r; thou hast
enlarg''d me in distress.

2O ye the sons of men! how long
will ye love vanities?
How long my glory turn to shame,
and will ye follow lies?

3But know, that for himself the Lord
the godly man doth choose:
The Lord, when I on him do call,
to hear will not refuse.

4Fear, and sin not; talk with your heart on bed,
and silent be.
5Off ''rings present of righteousness,
and in the Lord trust ye.

6O who will shew us any good?
is that which many say:
But of thy countenance the light,
Lord, lift on us alway.

7Upon my heart, bestow''d by thee,
more gladness I have found
Than they, ev''n then, when corn and wine
did most with them abound.

8I will both lay me down in peace,
and quiet sleep will take;
Because thou only me to dwell
in safety, Lord, dost make.', '[{"index": 0, "lines": [{"text": "Give ear unto me when I call,", "bibleVerseRef": 1}, {"text": "God of my righteousness:"}, {"text": "Have mercy, hear my pray''r; thou hast"}, {"text": "enlarg''d me in distress."}]}, {"index": 1, "lines": [{"text": "O ye the sons of men! how long", "bibleVerseRef": 2}, {"text": "will ye love vanities?"}, {"text": "How long my glory turn to shame,"}, {"text": "and will ye follow lies?"}]}, {"index": 2, "lines": [{"text": "But know, that for himself the Lord", "bibleVerseRef": 3}, {"text": "the godly man doth choose:"}, {"text": "The Lord, when I on him do call,"}, {"text": "to hear will not refuse."}]}, {"index": 3, "lines": [{"text": "Fear, and sin not; talk with your heart on bed,", "syllables": ["Fear,", "and", "sin", "not;", "talk", "with", "your", "heartonbed,"], "bibleVerseRef": 4}, {"text": "and silent be.", "syllables": ["and", "sile-", "-", "-", "nt", "be."]}, {"text": "Off ''rings present of righteousness,", "syllables": ["Off", "''rings", "prese-", "nt", "of", "righ-", "teous-", "ness,"], "bibleVerseRef": 5}, {"text": "and in the Lord trust ye."}]}, {"index": 4, "lines": [{"text": "O who will shew us any good?", "bibleVerseRef": 6}, {"text": "is that which many say:"}, {"text": "But of thy countenance the light,", "syllables": ["But", "of", "thy", "counte-", "nan-", "ce", "the", "light,"]}, {"text": "Lord, lift on us alway."}]}, {"index": 5, "lines": [{"text": "Upon my heart, bestow''d by thee,", "bibleVerseRef": 7}, {"text": "more gladness I have found"}, {"text": "Than they, ev''n then, when corn and wine"}, {"text": "did most with them abound."}]}, {"index": 6, "lines": [{"text": "I will both lay me down in peace,", "bibleVerseRef": 8}, {"text": "and quiet sleep will take;", "syllables": ["and", "qui-", "et", "sleep", "will", "take;"]}, {"text": "Because thou only me to dwell"}, {"text": "in safety, Lord, dost make."}]}]', 'CM', NULL, 'Give ear unto me when I call...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (21, 'rec63RvKAleqOkCcw', 132, '132', '1David, and his afflictions all,
Lord, do thou think upon;
2How unto God he sware,
and vow''d to Jacob''s mighty One.

3I will not come within my house,
nor rest in bed at all;
4Nor shall mine eyes take any sleep,
nor eyelids slumber shall;

5Till for the Lord a place I find,
where he may make abode;
A place of habitation
for Jacob''s mighty God.

6Lo, at the place of Ephratah
of it we understood;
And we did find it in the fields,
and city of the wood.

7We''ll go into his tabernacles,
and at his footstool bow.
8Arise, O Lord, into thy rest,
th'' ark of thy strength, and thou.

9O let thy priests be clothed, Lord,
with truth and righteousness;
And let all those that are thy saints
shout loud for joyfulness.

10For thine own servant David''s sake,
do not deny thy grace;
Nor of thine own anointed one
turn thou away the face.

11The Lord in truth to David sware,
he will not turn from it,
I of thy body''s fruit will make
upon thy throne to sit.

12My cov''nant if thy sons will keep,
and laws to them made known,
Their children then shall also sit
for ever on thy throne.

13For God of Sion hath made choice;
there he desires to dwell.
14This is my rest, here still I''ll stay;
for I do like it well.

15Her food I''ll greatly bless; her poor
with bread will satisfy.
16Her priests I''ll clothe with health; her saints
shall shout forth joyfully.

17And there will I make David''s horn
to bud forth pleasantly:
For him that mine anointed is
a lamp ordain''d have I.

18As with a garment I will clothe
with shame his en''mies all:
But yet the crown that he doth wear
upon him flourish shall.', '[{"index": 0, "lines": [{"text": "David, and his afflictions all,", "bibleVerseRef": 1}, {"text": "Lord, do thou think upon;"}, {"text": "How unto God he sware,", "syllables": ["How", "un-", "to", "God", "he", "swa-", "-", "re,"], "bibleVerseRef": 2}, {"text": "and vow''d to Jacob''s mighty One.", "syllables": ["and", "vow''d", "to", "jacob''s", "mighty", "One."]}]}, {"index": 1, "lines": [{"text": "I will not come within my house,", "bibleVerseRef": 3}, {"text": "nor rest in bed at all;"}, {"text": "Nor shall mine eyes take any sleep,", "bibleVerseRef": 4}, {"text": "nor eyelids slumber shall;"}]}, {"index": 2, "lines": [{"text": "Till for the Lord a place I find,", "syllables": ["Till", "for", "the", "Lord", "a", "place", "I", "find,"], "bibleVerseRef": 5}, {"text": "where he may make abode;"}, {"text": "A place of habitation"}, {"text": "for Jacob''s mighty God."}]}, {"index": 3, "lines": [{"text": "Lo, at the place of Ephratah", "syllables": ["Lo,", "at", "the", "place", "of", "ep-", "hra-", "tah"], "bibleVerseRef": 6}, {"text": "of it we understood;"}, {"text": "And we did find it in the fields,"}, {"text": "and city of the wood."}]}, {"index": 4, "lines": [{"text": "We''ll go into his tabernacles,", "bibleVerseRef": 7}, {"text": "and at his footstool bow."}, {"text": "Arise, O Lord, into thy rest,", "bibleVerseRef": 8}, {"text": "th'' ark of thy strength, and thou.", "syllables": ["th''", "ark", "of", "thy", "strength,", "andthou."]}]}, {"index": 5, "lines": [{"text": "O let thy priests be clothed, Lord,", "bibleVerseRef": 9}, {"text": "with truth and righteousness;"}, {"text": "And let all those that are thy saints"}, {"text": "shout loud for joyfulness."}]}, {"index": 6, "lines": [{"text": "For thine own servant David''s sake,", "bibleVerseRef": 10}, {"text": "do not deny thy grace;", "syllables": ["do", "not", "deny", "thy", "gra-", "ce;"]}, {"text": "Nor of thine own anointed one"}, {"text": "turn thou away the face."}]}, {"index": 7, "lines": [{"text": "The Lord in truth to David sware,", "syllables": ["The", "Lord", "in", "truth", "to", "david", "swa-", "re,"], "bibleVerseRef": 11}, {"text": "he will not turn from it,"}, {"text": "I of thy body''s fruit will make", "syllables": ["I", "of", "thy", "body''s", "fru-", "it", "will", "make"]}, {"text": "upon thy throne to sit.", "syllables": ["upon", "thy", "thro-", "ne", "to", "sit."]}]}, {"index": 8, "lines": [{"text": "My cov''nant if thy sons will keep,", "bibleVerseRef": 12}, {"text": "and laws to them made known,"}, {"text": "Their children then shall also sit"}, {"text": "for ever on thy throne."}]}, {"index": 9, "lines": [{"text": "For God of Sion hath made choice;", "syllables": ["For", "God", "of", "Sion", "hath", "made", "choice-", ";"], "bibleVerseRef": 13}, {"text": "there he desires to dwell."}, {"text": "This is my rest, here still I''ll stay;", "bibleVerseRef": 14}, {"text": "for I do like it well."}]}, {"index": 10, "lines": [{"text": "Her food I''ll greatly bless; her poor", "bibleVerseRef": 15}, {"text": "with bread will satisfy."}, {"text": "Her priests I''ll clothe with health; her saints", "syllables": ["Her", "priests", "I''ll", "clothe", "with", "health;", "her", "saints"], "bibleVerseRef": 16}, {"text": "shall shout forth joyfully."}]}, {"index": 11, "lines": [{"text": "And there will I make David''s horn", "bibleVerseRef": 17}, {"text": "to bud forth pleasantly:"}, {"text": "For him that mine anointed is"}, {"text": "a lamp ordain''d have I."}]}, {"index": 12, "lines": [{"text": "As with a garment I will clothe", "syllables": ["As", "with", "a", "garment", "I", "will", "clo-", "the"], "bibleVerseRef": 18}, {"text": "with shame his en''mies all:"}, {"text": "But yet the crown that he doth wear"}, {"text": "upon him flourish shall."}]}]', 'CM', NULL, 'David, and his afflictions all...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (38, 'rec9s4rtiKYbpZojV', 40, '40', '1I waited for the Lord my God,
and patiently did bear;
At length to me he did incline
my voice and cry to hear.

2He took me from a fearful pit,
and from the miry clay,
And on a rock he set my feet,
establishing my way.

3He put a new song in my mouth,
our God to magnify:
Many shall see it, and shall fear,
and on the Lord rely.

4O blessed is the man whose trust
upon the Lord relies;
Respecting not the proud, nor such
as turn aside to lies.

5O Lord my God, full many are
the wonders thou hast done;
Thy gracious thoughts to us-ward far
above all thoughts are gone:

In order none can reckon them
to thee: if them declare,
And speak of them I would, they more
than can be number''d are.

6No sacrifice nor offering
didst thou at all desire;
Mine ears thou bor''d: sin-off ''ring thou
and burnt didst not require:

7Then to the Lord these were my words,
I come, behold and see;
Within the volume of the book
it written is of me:

8To do thy will I take delight,
O thou my God that art;
Yea, that most holy law of thine
I have within my heart.

9Within the congregation great
I righteousness did preach:
Lo, thou dost know, O Lord, that I
refrained not my speech.

10I never did within my heart
conceal thy righteousness;
I thy salvation have declar''d,
and shown thy faithfulness:

Thy kindness, which most loving is,
concealed have not I,
Nor from the congregation great
have hid thy verity.

11Thy tender mercies, Lord, from me
O do thou not restrain;
Thy loving-kindness, and thy truth,
let them me still maintain.

12For ills past reck''ning compass me,
and mine iniquities
Such hold upon me taken have,
I cannot lift mine eyes:

They more than hairs are on mine head,
thence is my heart dismay''d.
13Be pleased, Lord, to rescue me;
Lord, hasten to mine aid.

14Sham''d and confounded be they all
that seek my soul to kill;
Yea, let them backward driven be,
and sham''d, that wish me ill.

15For a reward of this their shame
confounded let them be.
That in this manner scoffing say,
Aha, aha! to me.

16In thee let all be glad, and joy,
who seeking thee abide;
Who thy salvation love, say still,
The Lord be magnify''d.

17I''m poor and needy, yet the Lord
of me a care doth take:
Thou art my help and saviour,
my God, no tarrying make.', '[{"index": 0, "lines": [{"text": "I waited for the Lord my God,", "bibleVerseRef": 1}, {"text": "and patiently did bear;"}, {"text": "At length to me he did incline", "syllables": ["At", "length", "to", "me", "he", "did", "incli-", "ne"]}, {"text": "my voice and cry to hear."}]}, {"index": 1, "lines": [{"text": "He took me from a fearful pit,", "bibleVerseRef": 2}, {"text": "and from the miry clay,"}, {"text": "And on a rock he set my feet,"}, {"text": "establishing my way."}]}, {"index": 2, "lines": [{"text": "He put a new song in my mouth,", "bibleVerseRef": 3}, {"text": "our God to magnify:"}, {"text": "Many shall see it, and shall fear,"}, {"text": "and on the Lord rely."}]}, {"index": 3, "lines": [{"text": "O blessed is the man whose trust", "bibleVerseRef": 4}, {"text": "upon the Lord relies;"}, {"text": "Respecting not the proud, nor such"}, {"text": "as turn aside to lies."}]}, {"index": 4, "lines": [{"text": "O Lord my God, full many are", "bibleVerseRef": 5}, {"text": "the wonders thou hast done;"}, {"text": "Thy gracious thoughts to us-ward far"}, {"text": "above all thoughts are gone:"}]}, {"index": 5, "lines": [{"text": "In order none can reckon them", "syllables": ["In", "order", "no-", "ne", "can", "rec-", "kon", "them"]}, {"text": "to thee: if them declare,"}, {"text": "And speak of them I would, they more"}, {"text": "than can be number''d are."}]}, {"index": 6, "lines": [{"text": "No sacrifice nor offering", "bibleVerseRef": 6}, {"text": "didst thou at all desire;"}, {"text": "Mine ears thou bor''d: sin-off ''ring thou"}, {"text": "and burnt didst not require:", "syllables": ["and", "burnt", "didst", "not", "requi-", "re:"]}]}, {"index": 7, "lines": [{"text": "Then to the Lord these were my words,", "bibleVerseRef": 7}, {"text": "I come, behold and see;"}, {"text": "Within the volume of the book"}, {"text": "it written is of me:"}]}, {"index": 8, "lines": [{"text": "To do thy will I take delight,", "bibleVerseRef": 8}, {"text": "O thou my God that art;"}, {"text": "Yea, that most holy law of thine"}, {"text": "I have within my heart."}]}, {"index": 9, "lines": [{"text": "Within the congregation great", "bibleVerseRef": 9}, {"text": "I righteousness did preach:"}, {"text": "Lo, thou dost know, O Lord, that I"}, {"text": "refrained not my speech."}]}, {"index": 10, "lines": [{"text": "I never did within my heart", "bibleVerseRef": 10}, {"text": "conceal thy righteousness;"}, {"text": "I thy salvation have declar''d,"}, {"text": "and shown thy faithfulness:"}]}, {"index": 11, "lines": [{"text": "Thy kindness, which most loving is,"}, {"text": "concealed have not I,"}, {"text": "Nor from the congregation great"}, {"text": "have hid thy verity."}]}, {"index": 12, "lines": [{"text": "Thy tender mercies, Lord, from me", "bibleVerseRef": 11}, {"text": "O do thou not restrain;"}, {"text": "Thy loving-kindness, and thy truth,"}, {"text": "let them me still maintain."}]}, {"index": 13, "lines": [{"text": "For ills past reck''ning compass me,", "bibleVerseRef": 12}, {"text": "and mine iniquities"}, {"text": "Such hold upon me taken have,", "syllables": ["Such", "hold", "u-", "pon", "me", "take-", "n", "have,"]}, {"text": "I cannot lift mine eyes:"}]}, {"index": 14, "lines": [{"text": "They more than hairs are on mine head,"}, {"text": "thence is my heart dismay''d."}, {"text": "Be pleased, Lord, to rescue me;", "bibleVerseRef": 13}, {"text": "Lord, hasten to mine aid."}]}, {"index": 15, "lines": [{"text": "Sham''d and confounded be they all", "bibleVerseRef": 14}, {"text": "that seek my soul to kill;"}, {"text": "Yea, let them backward driven be,"}, {"text": "and sham''d, that wish me ill."}]}, {"index": 16, "lines": [{"text": "For a reward of this their shame", "bibleVerseRef": 15}, {"text": "confounded let them be."}, {"text": "That in this manner scoffing say,"}, {"text": "Aha, aha! to me."}]}, {"index": 17, "lines": [{"text": "In thee let all be glad, and joy,", "bibleVerseRef": 16}, {"te