INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (40, 'recBhzTTovFzVXPzD', 119, '119:129-136 (17)', '129Thy statutes, Lord, are wonderful,
my soul them keeps with care.
130The entrance of thy words gives light,
makes wise who simple are.

131My mouth I have wide opened,
and panted earnestly,
While after thy commandements
I long''d exceedingly.

132Look on me, Lord, and merciful
do thou unto me prove,
As thou art wont to do
to those thy name who truly love.

133O let my footsteps in thy word
aright still order''d be:
Let no iniquity obtain
dominion over me.

134From man''s oppression save thou me;
so keep thy laws I will.
135Thy face make on thy servant shine;
teach me thy statutes still.

136Rivers of waters from mine eyes
did run down, when I saw
How wicked men run on in sin,
and do not keep thy law.

137O Lord, thou art most righteous;
thy judgments are upright.
138Thy testimonies thou command''st
most faithful are and right.
', '[{"index": 0, "lines": [{"text": "Thy statutes, Lord, are wonderful,", "syllables": ["Thy", "statu-", "tes,", "Lord,", "are", "won-", "der-", "ful,"], "bibleVerseRef": 129}, {"text": "my soul them keeps with care."}, {"text": "The entrance of thy words gives light,", "syllables": ["The", "entran-", "ce", "of", "thy", "words", "gives", "light,"], "bibleVerseRef": 130}, {"text": "makes wise who simple are."}]}, {"index": 1, "lines": [{"text": "My mouth I have wide opened,", "syllables": ["My", "mou-", "th", "I", "have", "wide", "ope-", "ned,"], "bibleVerseRef": 131}, {"text": "and panted earnestly,"}, {"text": "While after thy commandements"}, {"text": "I long''d exceedingly."}]}, {"index": 2, "lines": [{"text": "Look on me, Lord, and merciful", "bibleVerseRef": 132}, {"text": "do thou unto me prove,", "syllables": ["do", "thou", "unto", "me", "pro-", "ve,"]}, {"text": "As thou art wont to do", "syllables": ["As", "tho-", "-", "u", "art", "wont", "to", "do"]}, {"text": "to those thy name who truly love.", "syllables": ["to", "those", "thy", "name", "who", "trulylove."]}]}, {"index": 3, "lines": [{"text": "O let my footsteps in thy word", "bibleVerseRef": 133}, {"text": "aright still order''d be:"}, {"text": "Let no iniquity obtain"}, {"text": "dominion over me.", "syllables": ["do-", "mi-", "nio-", "n", "over", "me."]}]}, {"index": 4, "lines": [{"text": "From man''s oppression save thou me;", "bibleVerseRef": 134}, {"text": "so keep thy laws I will."}, {"text": "Thy face make on thy servant shine;", "bibleVerseRef": 135}, {"text": "teach me thy statutes still.", "syllables": ["teach", "me", "thy", "statu-", "tes", "still."]}]}, {"index": 5, "lines": [{"text": "Rivers of waters from mine eyes", "syllables": ["Rive-", "rs", "of", "wate-", "rs", "from", "mine", "eyes"], "bibleVerseRef": 136}, {"text": "did run down, when I saw"}, {"text": "How wicked men run on in sin,"}, {"text": "and do not keep thy law."}]}, {"index": 6, "lines": [{"text": "O Lord, thou art most righteous;", "syllables": ["O", "Lord,", "thou", "art", "most", "righ-", "teou-", "s;"], "bibleVerseRef": 137}, {"text": "thy judgments are upright."}, {"text": "Thy testimonies thou command''st", "bibleVerseRef": 138}, {"text": "most faithful are and right."}]}]', 'CM', 'Part 17', 'Thy statutes, Lord, are wonderful...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (33, 'rec94YxV5l4ITYdVF', 2, '2', '1Why rage the heathen? and vain things 
why do the people mind?
2Kings of the earth do set themselves,
and princes are combin''d,

To plot against the Lord, and his
Anointed, saying thus,
3Let us asunder break their bands,
and cast their cords from us.

4He that in heaven sits shall laugh;
the Lord shall scorn them all.
5Then shall he speak to them in wrath,
in rage he vex them shall.

6Yet, notwithstanding,
I have him to be my King appointed;
And over Sion, my holy hill,
I have him King anointed.

7The sure decree I will declare:
The Lord hath said to me,
Thou art mine only Son;
this day I have begotten thee.

8Ask of me, and for heritage
the heathen I''ll make thine;
And, for possession, I to thee
will give earth''s utmost line.

9Thou shalt, as with a weighty rod
of iron, break them all;
And, as a potter''s sherd, thou shalt
them dash in pieces small.

10Now therefore, kings, be wise;
be taught, ye judges of the earth:
11Serve God in fear, and see that
ye join trembling with your mirth.

12Kiss ye the Son, lest in his ire
ye perish from the way,
If once his wrath begin to burn:
bless''d all that on him stay.', '[{"index": 0, "lines": [{"text": "Why rage the heathen? and vain things", "bibleVerseRef": 1}, {"text": "why do the people mind?", "syllables": ["why", "do", "the", "peo-", "ple", "mind?"]}, {"text": "Kings of the earth do set themselves,", "syllables": ["Kings", "of", "the", "earth", "do", "set", "themsel-", "ves,"], "bibleVerseRef": 2}, {"text": "and princes are combin''d,"}]}, {"index": 1, "lines": [{"text": "To plot against the Lord, and his"}, {"text": "Anointed, saying thus,", "syllables": ["a-", "noin-", "ted,", "sayi-", "ng", "thus,"]}, {"text": "Let us asunder break their bands,", "bibleVerseRef": 3}, {"text": "and cast their cords from us."}]}, {"index": 2, "lines": [{"text": "He that in heaven sits shall laugh;", "syllables": ["He", "that", "in", "heave-", "n", "sits", "shall", "laugh;"], "bibleVerseRef": 4}, {"text": "the Lord shall scorn them all."}, {"text": "Then shall he speak to them in wrath,", "bibleVerseRef": 5}, {"text": "in rage he vex them shall."}]}, {"index": 3, "lines": [{"text": "Yet, notwithstanding,", "syllables": ["Yet,", "not-", "wit-", "hsta-", "-", "-", "n-", "ding,"], "bibleVerseRef": 6}, {"text": "I have him to be my King appointed;", "syllables": ["I", "have", "him", "to", "be", "myKingappointed;"]}, {"text": "And over Sion, my holy hill,", "syllables": ["And", "over", "Sio-", "n,", "my", "ho-", "ly", "hill,"]}, {"text": "I have him King anointed.", "syllables": ["I", "have", "him", "King", "anoin-", "ted."]}]}, {"index": 4, "lines": [{"text": "The sure decree I will declare:", "bibleVerseRef": 7}, {"text": "The Lord hath said to me,"}, {"text": "Thou art mine only Son;", "syllables": ["Tho-", "-", "u", "art", "mine", "on-", "ly", "Son;"]}, {"text": "this day I have begotten thee.", "syllables": ["this", "day", "I", "have", "begotten", "thee."]}]}, {"index": 5, "lines": [{"text": "Ask of me, and for heritage", "bibleVerseRef": 8}, {"text": "the heathen I''ll make thine;"}, {"text": "And, for possession, I to thee"}, {"text": "will give earth''s utmost line."}]}, {"index": 6, "lines": [{"text": "Thou shalt, as with a weighty rod", "bibleVerseRef": 9}, {"text": "of iron, break them all;"}, {"text": "And, as a potter''s sherd, thou shalt"}, {"text": "them dash in pieces small.", "syllables": ["them", "dash", "in", "piece-", "s", "small."]}]}, {"index": 7, "lines": [{"text": "Now therefore, kings, be wise;", "syllables": ["Now", "there-", "-", "-", "fore,", "kings,", "be", "wise;"], "bibleVerseRef": 10}, {"text": "be taught, ye judges of the earth:", "syllables": ["be", "taught,", "ye", "judges", "of", "theearth:"]}, {"text": "Serve God in fear, and see that", "syllables": ["Se-", "rve", "God", "in", "fear,", "and", "see", "that"], "bibleVerseRef": 11}, {"text": "ye join trembling with your mirth.", "syllables": ["ye", "join", "trembling", "with", "your", "mirth."]}]}, {"index": 8, "lines": [{"text": "Kiss ye the Son, lest in his ire", "bibleVerseRef": 12}, {"text": "ye perish from the way,"}, {"text": "If once his wrath begin to burn:", "syllables": ["If", "once", "his", "wrath", "be-", "gin", "to", "burn:"]}, {"text": "bless''d all that on him stay."}]}]', 'CM', NULL, 'Why rage the heathen? and vain things...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (37, 'rec9iHmPYrX7DHX6c', 58, '58', '1Do ye, O congregation,
indeed speak righteousness?
O ye that are the sons of men,
judge ye with uprightness?

2Yea, ev''n within your very hearts
ye wickedness have done;
And ye the vi''lence of your hands
do weigh the earth upon.

3The wicked men estranged are,
ev''n from the very womb;
They, speaking lies, do stray as soon
as to the world they come.

4Unto a serpent''s poison like
their poison doth appear;
Yea, they are like the adder deaf,
that closely stops her ear;

5That so she may not hear the voice
of one that charm her would,
No, not though he most cunning were,
and charm most wisely could.

6Their teeth, O God, within their mouth
break thou in pieces small;
The great teeth break thou out, O Lord,
of these young lions all.

7Let them like waters melt away,
which downward still do flow:
In pieces cut his arrows all,
when he shall bend his bow.

8Like to a snail that melts away,
let each of them be gone;
Like woman''s birth untimely, that
they never see the sun.

9He shall them take away before
your pots the thorns can find,
Both living, and in fury great,
as with a stormy wind.

10The righteous, when he vengeance sees,
he shall be joyful then;
The righteous one shall wash his feet
in blood of wicked men.

11So men shall say, The righteous man
reward shall never miss:
And verily upon the earth
a God to judge there is.', '[{"index": 0, "lines": [{"text": "Do ye, O congregation,", "syllables": ["Do", "ye,", "O", "con-", "gre-", "ga-", "tio-", "n,"], "bibleVerseRef": 1}, {"text": "indeed speak righteousness?"}, {"text": "O ye that are the sons of men,"}, {"text": "judge ye with uprightness?", "syllables": ["judge", "ye", "with", "up-", "rig-", "htness?"]}]}, {"index": 1, "lines": [{"text": "Yea, ev''n within your very hearts", "bibleVerseRef": 2}, {"text": "ye wickedness have done;"}, {"text": "And ye the vi''lence of your hands", "syllables": ["And", "ye", "the", "vi''len-", "ce", "of", "your", "hands"]}, {"text": "do weigh the earth upon."}]}, {"index": 2, "lines": [{"text": "The wicked men estranged are,", "bibleVerseRef": 3}, {"text": "ev''n from the very womb;"}, {"text": "They, speaking lies, do stray as soon"}, {"text": "as to the world they come."}]}, {"index": 3, "lines": [{"text": "Unto a serpent''s poison like", "bibleVerseRef": 4}, {"text": "their poison doth appear;"}, {"text": "Yea, they are like the adder deaf,"}, {"text": "that closely stops her ear;", "syllables": ["that", "close-", "ly", "stops", "her", "ear;"]}]}, {"index": 4, "lines": [{"text": "That so she may not hear the voice", "bibleVerseRef": 5}, {"text": "of one that charm her would,"}, {"text": "No, not though he most cunning were,"}, {"text": "and charm most wisely could."}]}, {"index": 5, "lines": [{"text": "Their teeth, O God, within their mouth", "bibleVerseRef": 6}, {"text": "break thou in pieces small;", "syllables": ["break", "thou", "in", "piece-", "s", "small;"]}, {"text": "The great teeth break thou out, O Lord,"}, {"text": "of these young lions all.", "syllables": ["of", "the-", "se", "young", "lions", "all."]}]}, {"index": 6, "lines": [{"text": "Let them like waters melt away,", "syllables": ["Let", "them", "like", "wate-", "rs", "melt", "a-", "way,"], "bibleVerseRef": 7}, {"text": "which downward still do flow:"}, {"text": "In pieces cut his arrows all,", "syllables": ["In", "piece-", "s", "cut", "his", "ar-", "rows", "all,"]}, {"text": "when he shall bend his bow."}]}, {"index": 7, "lines": [{"text": "Like to a snail that melts away,", "bibleVerseRef": 8}, {"text": "let each of them be gone;"}, {"text": "Like woman''s birth untimely, that", "syllables": ["Like", "woman''s", "birth", "un-", "ti-", "me-", "ly,", "that"]}, {"text": "they never see the sun."}]}, {"index": 8, "lines": [{"text": "He shall them take away before", "bibleVerseRef": 9}, {"text": "your pots the thorns can find,"}, {"text": "Both living, and in fury great,"}, {"text": "as with a stormy wind."}]}, {"index": 9, "lines": [{"text": "The righteous, when he vengeance sees,", "syllables": ["The", "righteous,", "when", "he", "ven-", "gean-", "ce", "sees,"], "bibleVerseRef": 10}, {"text": "he shall be joyful then;"}, {"text": "The righteous one shall wash his feet"}, {"text": "in blood of wicked men."}]}, {"index": 10, "lines": [{"text": "So men shall say, The righteous man", "bibleVerseRef": 11}, {"text": "reward shall never miss:"}, {"text": "And verily upon the earth"}, {"text": "a God to judge there is.", "syllables": ["a", "God", "to", "judge", "there", "is."]}]}]', 'CM', NULL, 'Do ye, O congregation...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (47, 'recEhPLRvq9DDUjR6', 26, '26', '1Judge me, O Lord, for I have walk''d
in mine integrity:
I trusted also in the Lord;
slide therefore shall not I.

2Examine me, and do me prove;
try heart and reins, O God:
3For thy love is before mine eyes,
thy truth''s paths I have trode.

4With persons vain I have not sat,
nor with dissemblers gone:
5Th'' assembly of ill men I hate;
to sit with such I shun.

6Mine hands in innocence, O Lord,
I''ll wash and purify;
So to thine holy altar go,
and compass it will I:

7That I, with voice of thanksgiving,
may publish and declare,
And tell of all thy mighty works,
that great and wondrous are.

8The habitation of thy house,
Lord, I have loved well;
Yea, in that place I do delight
where doth thine honour dwell.

9With sinners gather not my soul,
and such as blood would spill:
10Whose hands mischievous plots, right hand
corrupting bribes do fill.

11But as for me, I will walk on
in mine integrity:
Do thou redeem me, and, O Lord,
be merciful to me.

12My foot upon an even place
doth stand with stedfastness:
Within the congregations
th'' Eternal I will bless.', '[{"index": 0, "lines": [{"text": "Judge me, O Lord, for I have walk''d", "syllables": ["judge", "me,", "O", "Lord,", "for", "I", "have", "walk''d"], "bibleVerseRef": 1}, {"text": "in mine integrity:"}, {"text": "I trusted also in the Lord;"}, {"text": "slide therefore shall not I.", "syllables": ["slide", "there-", "fore", "shall", "not", "I."]}]}, {"index": 1, "lines": [{"text": "Examine me, and do me prove;", "syllables": ["exa-", "mine", "me,", "and", "do", "me", "pro-", "ve;"], "bibleVerseRef": 2}, {"text": "try heart and reins, O God:"}, {"text": "For thy love is before mine eyes,", "bibleVerseRef": 3}, {"text": "thy truth''s paths I have trode.", "syllables": ["thy", "truth''s", "paths", "I", "have", "trode."]}]}, {"index": 2, "lines": [{"text": "With persons vain I have not sat,", "bibleVerseRef": 4}, {"text": "nor with dissemblers gone:"}, {"text": "Th'' assembly of ill men I hate;", "syllables": ["Th''", "assem-", "bly", "of", "ill", "men", "I", "hate;"], "bibleVerseRef": 5}, {"text": "to sit with such I shun."}]}, {"index": 3, "lines": [{"text": "Mine hands in innocence, O Lord,", "syllables": ["Mine", "hands", "in", "inno-", "cen-", "ce,", "O", "Lord,"], "bibleVerseRef": 6}, {"text": "I''ll wash and purify;"}, {"text": "So to thine holy altar go,"}, {"text": "and compass it will I:"}]}, {"index": 4, "lines": [{"text": "That I, with voice of thanksgiving,", "bibleVerseRef": 7}, {"text": "may publish and declare,"}, {"text": "And tell of all thy mighty works,"}, {"text": "that great and wondrous are."}]}, {"index": 5, "lines": [{"text": "The habitation of thy house,", "bibleVerseRef": 8}, {"text": "Lord, I have loved well;"}, {"text": "Yea, in that place I do delight", "syllables": ["Yea,", "in", "that", "place", "I", "do", "de-", "light"]}, {"text": "where doth thine honour dwell."}]}, {"index": 6, "lines": [{"text": "With sinners gather not my soul,", "bibleVerseRef": 9}, {"text": "and such as blood would spill:"}, {"text": "Whose hands mischievous plots, right hand", "bibleVerseRef": 10}, {"text": "corrupting bribes do fill.", "syllables": ["corrup-", "ting", "bri-", "bes", "do", "fill."]}]}, {"index": 7, "lines": [{"text": "But as for me, I will walk on", "bibleVerseRef": 11}, {"text": "in mine integrity:"}, {"text": "Do thou redeem me, and, O Lord,"}, {"text": "be merciful to me."}]}, {"index": 8, "lines": [{"text": "My foot upon an even place", "bibleVerseRef": 12}, {"text": "doth stand with stedfastness:"}, {"text": "Within the congregations", "syllables": ["wi-", "thin", "the", "con-", "gre-", "ga-", "tio-", "ns"]}, {"text": "th'' Eternal I will bless."}]}]', 'CM', NULL, 'Judge me, O Lord, for I have walk''d...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (41, 'recCwExNUU20rFc0H', 60, '60', '1O Lord, thou hast rejected us,
and scatter''d us abroad;
Thou justly hast displeased been;
return to us, O God.

2The earth to tremble thou hast made;
therein didst breaches make:
Do thou thereof the breaches heal,
because the land doth shake.

3Unto thy people thou hard things hast shew''d,
and on them sent;
And thou hast caused us to drink
wine of astonishment.

4And yet a banner thou hast giv''n
to them who thee do fear;
That it by them, because of truth,
displayed may appear.

5That thy beloved people may
deliver''d be from thrall,
Save with the pow''r of thy right hand,
and hear me when I call.

6God in his holiness hath spoke;
herein I will take pleasure:
Shechem I will divide, and forth
will Succoth''s valley measure.

7Gilead I claim as mine by right;
Manasseh mine shall be;
Ephraim is of mine head the strength;
Judah gives laws for me;

8Moab''s my washing-pot; my shoe
I''ll over Edom throw;
And over Palestina''s land
I will in triumph go.

9O who is he will bring me to
the city fortify''d?
O who is he that to the land
of Edom will me guide?

10O God, which hadest us cast off,
this thing wilt thou not do?
Ev''n thou, O God, which didest not
forth with our armies go?

11Help us from trouble; for the help
is vain which man supplies.
12Through God we''ll do great acts; he shall
tread down our enemies.', '[{"index": 0, "lines": [{"text": "O Lord, thou hast rejected us,", "bibleVerseRef": 1}, {"text": "and scatter''d us abroad;", "syllables": ["and", "scatter''d", "us", "ab-", "ro-", "ad;"]}, {"text": "Thou justly hast displeased been;"}, {"text": "return to us, O God."}]}, {"index": 1, "lines": [{"text": "The earth to tremble thou hast made;", "syllables": ["The", "earth", "to", "tre-", "mble", "thou", "hast", "made;"], "bibleVerseRef": 2}, {"text": "therein didst breaches make:", "syllables": ["therei-", "n", "didst", "brea-", "ches", "make:"]}, {"text": "Do thou thereof the breaches heal,"}, {"text": "because the land doth shake."}]}, {"index": 2, "lines": [{"text": "Unto thy people thou hard things hast shew''d,", "syllables": ["unto", "thy", "people", "thou", "hard", "things", "hast", "shew''d,"], "bibleVerseRef": 3}, {"text": "and on them sent;", "syllables": ["and", "on", "the-", "m", "se-", "nt;"]}, {"text": "And thou hast caused us to drink"}, {"text": "wine of astonishment."}]}, {"index": 3, "lines": [{"text": "And yet a banner thou hast giv''n", "bibleVerseRef": 4}, {"text": "to them who thee do fear;"}, {"text": "That it by them, because of truth,"}, {"text": "displayed may appear.", "syllables": ["dis-", "playe-", "d", "may", "ap-", "pear."]}]}, {"index": 4, "lines": [{"text": "That thy beloved people may", "syllables": ["That", "thy", "belo-", "ved", "pe-", "o-", "ple", "may"], "bibleVerseRef": 5}, {"text": "deliver''d be from thrall,"}, {"text": "Save with the pow''r of thy right hand,"}, {"text": "and hear me when I call."}]}, {"index": 5, "lines": [{"text": "God in his holiness hath spoke;", "syllables": ["God", "in", "his", "holi-", "ness", "hath", "spo-", "ke;"], "bibleVerseRef": 6}, {"text": "herein I will take pleasure:", "syllables": ["herein", "I", "will", "take", "plea-", "sure:"]}, {"text": "Shechem I will divide, and forth"}, {"text": "will Succoth''s valley measure.", "syllables": ["will", "succoth''s", "val-", "ley", "mea-", "sure."]}]}, {"index": 6, "lines": [{"text": "Gilead I claim as mine by right;", "syllables": ["Gilea-", "d", "I", "claim", "as", "mine", "by", "right;"], "bibleVerseRef": 7}, {"text": "Manasseh mine shall be;"}, {"text": "Ephraim is of mine head the strength;"}, {"text": "Judah gives laws for me;"}]}, {"index": 7, "lines": [{"text": "Moab''s my washing-pot; my shoe", "bibleVerseRef": 8}, {"text": "I''ll over Edom throw;", "syllables": ["I''ll", "over", "e-", "dom", "thro-", "w;"]}, {"text": "And over Palestina''s land", "syllables": ["And", "over", "pale-", "-", "s-", "ti-", "na''s", "land"]}, {"text": "I will in triumph go.", "syllables": ["I", "will", "in", "triu-", "mph", "go."]}]}, {"index": 8, "lines": [{"text": "O who is he will bring me to", "bibleVerseRef": 9}, {"text": "the city fortify''d?"}, {"text": "O who is he that to the land"}, {"text": "of Edom will me guide?", "syllables": ["of", "edom", "will", "me", "gui-", "de?"]}]}, {"index": 9, "lines": [{"text": "O God, which hadest us cast off,", "syllables": ["O", "God,", "which", "hade-", "st", "us", "cast", "off,"], "bibleVerseRef": 10}, {"text": "this thing wilt thou not do?"}, {"text": "Ev''n thou, O God, which didest not"}, {"text": "forth with our armies go?"}]}, {"index": 10, "lines": [{"text": "Help us from trouble; for the help", "bibleVerseRef": 11}, {"text": "is vain which man supplies."}, {"text": "Through God we''ll do great acts; he shall", "bibleVerseRef": 12}, {"text": "tread down our enemies."}]}]', 'CM', NULL, 'O Lord, thou hast rejected us...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (44, 'recE1jPj5wGbSmx2u', 119, '119:89-96 (12)', '89Thy word for ever is, O Lord,
in heaven settled fast;
90Unto all generations
thy faithfulness doth last:

The earth thou hast established,
and it abides by thee.
91This day they stand as thou ordain''dst;
for all thy servants be.

92Unless in thy most perfect law
my soul delights had found,
I should have perished, when as
my troubles did abound.

93Thy precepts I will ne''er forget;
they quick''ning to me brought.
94Lord, I am thine; O save thou me:
thy precepts I have sought.

95For me the wicked have laid wait,
me seeking to destroy:
But I thy testimonies true
consider will with joy.

96An end of all perfection
here have I seen, O God:
But as for thy commandement,
it is exceeding broad.
', '[{"index": 0, "lines": [{"text": "Thy word for ever is, O Lord,", "syllables": ["Thy", "word", "for", "ever", "is,", "O", "Lo-", "rd,"], "bibleVerseRef": 89}, {"text": "in heaven settled fast;", "syllables": ["in", "heave-", "n", "set-", "tled", "fast;"]}, {"text": "Unto all generations", "syllables": ["un-", "to", "all", "ge-", "ne-", "ra-", "tio-", "ns"], "bibleVerseRef": 90}, {"text": "thy faithfulness doth last:"}]}, {"index": 1, "lines": [{"text": "The earth thou hast established,"}, {"text": "and it abides by thee."}, {"text": "This day they stand as thou ordain''dst;", "bibleVerseRef": 91}, {"text": "for all thy servants be."}]}, {"index": 2, "lines": [{"text": "Unless in thy most perfect law", "bibleVerseRef": 92}, {"text": "my soul delights had found,"}, {"text": "I should have perished, when as"}, {"text": "my troubles did abound."}]}, {"index": 3, "lines": [{"text": "Thy precepts I will ne''er forget;", "syllables": ["Thy", "precepts", "I", "will", "ne-", "''er", "for-", "get;"], "bibleVerseRef": 93}, {"text": "they quick''ning to me brought.", "syllables": ["they", "qui-", "ck''ning", "to", "me", "brought."]}, {"text": "Lord, I am thine; O save thou me:", "bibleVerseRef": 94}, {"text": "thy precepts I have sought."}]}, {"index": 4, "lines": [{"text": "For me the wicked have laid wait,", "bibleVerseRef": 95}, {"text": "me seeking to destroy:"}, {"text": "But I thy testimonies true"}, {"text": "consider will with joy.", "syllables": ["con-", "side-", "r", "will", "with", "joy."]}]}, {"index": 5, "lines": [{"text": "An end of all perfection", "syllables": ["An", "end", "of", "all", "pe-", "r-", "fec-", "tion"], "bibleVerseRef": 96}, {"text": "here have I seen, O God:"}, {"text": "But as for thy commandement,"}, {"text": "it is exceeding broad.", "syllables": ["it", "is", "excee-", "ding", "bro-", "ad."]}]}]', 'CM', 'Part 12', 'Thy word for ever is, O Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (55, 'recJAd5cwvDoc6cZT', 122, '122', '1I joy''d when to the house of God,
Go up, they said to me.
2Jerusalem, within thy gates
our feet shall standing be.

3Jerus''lem, as a city, is
compactly built together:
4Unto that place the tribes go up,
the tribes of God go thither:

To Isr''el''s testimony, there
to God''s name thanks to pay.
5For thrones of judgment, ev''n the thrones
of David''s house, there stay.

6Pray that Jerusalem may have
peace and felicity:
Let them that love thee and thy peace
have still prosperity.

7Therefore I wish that peace may still
within thy walls remain,
And ever may thy palaces
prosperity retain.

8Now, for my friends'' and brethren''s sakes,
Peace be in thee, I''ll say.
9And for the house of God our Lord,
I''ll seek thy good alway.', '[{"index": 0, "lines": [{"text": "I joy''d when to the house of God,", "bibleVerseRef": 1}, {"text": "Go up, they said to me."}, {"text": "Jerusalem, within thy gates", "bibleVerseRef": 2}, {"text": "our feet shall standing be."}]}, {"index": 1, "lines": [{"text": "Jerus''lem, as a city, is", "bibleVerseRef": 3}, {"text": "compactly built together:", "syllables": ["compactly", "bu-", "ilt", "to-", "ge-", "ther:"]}, {"text": "Unto that place the tribes go up,", "syllables": ["unto", "that", "place", "the", "tri-", "bes", "go", "up,"], "bibleVerseRef": 4}, {"text": "the tribes of God go thither:", "syllables": ["the", "tribes", "of", "God", "go", "thither:"]}]}, {"index": 2, "lines": [{"text": "To Isr''el''s testimony, there"}, {"text": "to God''s name thanks to pay."}, {"text": "For thrones of judgment, ev''n the thrones", "syllables": ["For", "thrones", "of", "judgment,", "ev''n", "the", "thro-", "nes"], "bibleVerseRef": 5}, {"text": "of David''s house, there stay."}]}, {"index": 3, "lines": [{"text": "Pray that Jerusalem may have", "syllables": ["Pray", "that", "je-", "ru-", "sale-", "m", "may", "have"], "bibleVerseRef": 6}, {"text": "peace and felicity:"}, {"text": "Let them that love thee and thy peace"}, {"text": "have still prosperity."}]}, {"index": 4, "lines": [{"text": "Therefore I wish that peace may still", "bibleVerseRef": 7}, {"text": "within thy walls remain,"}, {"text": "And ever may thy palaces", "syllables": ["And", "ever", "may", "thy", "pa-", "lace-", "-", "s"]}, {"text": "prosperity retain."}]}, {"index": 5, "lines": [{"text": "Now, for my friends'' and brethren''s sakes,", "bibleVerseRef": 8}, {"text": "Peace be in thee, I''ll say."}, {"text": "And for the house of God our Lord,", "bibleVerseRef": 9}, {"text": "I''ll seek thy good alway."}]}]', 'CM', NULL, 'I joy''d when to the house of God...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (64, 'recMV6HyB3nCpMWDd', 133, '133', '1Behold, how good a thing it is,
and how becoming well,
Together such as brethren are
in unity to dwell!

2Like precious ointment on the head,
that down the beard did flow,
Ev''n Aaron''s beard, and to the skirts,
did of his garments go.

3As Hermon''s dew, the dew that doth
on Sion'' hills descend:
For there the blessing God commands,
life that shall never end.', '[{"index": 0, "lines": [{"text": "Behold, how good a thing it is,", "bibleVerseRef": 1}, {"text": "and how becoming well,"}, {"text": "Together such as brethren are"}, {"text": "in unity to dwell!"}]}, {"index": 1, "lines": [{"text": "Like precious ointment on the head,", "bibleVerseRef": 2}, {"text": "that down the beard did flow,"}, {"text": "Ev''n Aaron''s beard, and to the skirts,"}, {"text": "did of his garments go."}]}, {"index": 2, "lines": [{"text": "As Hermon''s dew, the dew that doth", "bibleVerseRef": 3}, {"text": "on Sion'' hills descend:", "syllables": ["on", "Sio-", "n''", "hills", "des-", "cend:"]}, {"text": "For there the blessing God commands,"}, {"text": "life that shall never end."}]}]', 'CM', NULL, 'Behold, how good a thing it is...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (77, 'recU4IUrVDgPckHKa', 67, '67 (Second Version)', '1Lord, unto us be merciful,
do thou us also bless;
And graciously cause shine on us
the brightness of thy face:

2That so thy way upon the earth
to all men may be known;
Also among the nations all
thy saving health be shown.

3O let the people praise thee, Lord;
let people all thee praise.
4O let the nations be glad,
and sing for joy always:

For rightly thou shalt people judge,
and nations rule on earth.
5Let people praise thee, Lord; let all
the folk praise thee with mirth.

6Then shall the earth yield her increase;
God, our God, bless us shall.
7God shall us bless; and of the earth
the ends shall fear him all.', '[{"index": 0, "lines": [{"text": "Lord, unto us be merciful,", "bibleVerseRef": 1}, {"text": "do thou us also bless;"}, {"text": "And graciously cause shine on us"}, {"text": "the brightness of thy face:"}]}, {"index": 1, "lines": [{"text": "That so thy way upon the earth", "bibleVerseRef": 2}, {"text": "to all men may be known;"}, {"text": "Also among the nations all"}, {"text": "thy saving health be shown."}]}, {"index": 2, "lines": [{"text": "O let the people praise thee, Lord;", "syllables": ["O", "let", "the", "peo-", "ple", "praise", "thee,", "Lord;"], "bibleVerseRef": 3}, {"text": "let people all thee praise.", "syllables": ["let", "peo-", "ple", "all", "thee", "praise."]}, {"text": "O let the nations be glad,", "syllables": ["O", "let", "the", "na-", "tio-", "ns", "be", "glad,"], "bibleVerseRef": 4}, {"text": "and sing for joy always:"}]}, {"index": 3, "lines": [{"text": "For rightly thou shalt people judge,", "syllables": ["For", "rightly", "thou", "shalt", "peo-", "ple", "jud-", "ge,"]}, {"text": "and nations rule on earth."}, {"text": "Let people praise thee, Lord; let all", "syllables": ["Let", "peo-", "ple", "praise", "thee,", "Lord;", "let", "all"], "bibleVerseRef": 5}, {"text": "the folk praise thee with mirth."}]}, {"index": 4, "lines": [{"text": "Then shall the earth yield her increase;", "syllables": ["Then", "shall", "the", "earth", "yield", "her", "increa-", "se;"], "bibleVerseRef": 6}, {"text": "God, our God, bless us shall."}, {"text": "God shall us bless; and of the earth", "bibleVerseRef": 7}, {"text": "the ends shall fear him all."}]}]', 'CM', 'Second Version', 'Lord, unto us be merciful...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (52, 'recGovtk8I1sxGnhh', 89, '89', '1God''s mercies I will ever sing;
and with my mouth I shall
Thy faithfulness make to be known
to generations all.

2For mercy shall be built, said I,
for ever to endure;
Thy faithfulness, ev''n in the heav''ns,
thou wilt establish sure.

3I with my chosen One have made
a cov''nant graciously;
And to my servant, whom I lov''d,
to David sworn have I;

4That I thy seed establish shall
for ever to remain,
And will to generations all
thy throne build and maintain.

5The praises of thy wonders, Lord,
the heavens shall express;
And in the congregation
of saints thy faithfulness.

6For who in heaven with the Lord
may once himself compare?
Who is like God among the sons
of those that mighty are?

7Great fear in meeting of the saints
is due unto the Lord;
And he of all about him should
with rev''rence be ador''d.

8O thou that art the Lord of hosts,
what Lord in mightiness
Is like to thee? who compass''d round
art with thy faithfulness.

9Ev''n in the raging of the sea
thou over it dost reign;
And when the waves thereof do swell,
thou stillest them again.

10Rahab in pieces thou didst break,
like one that slaughter''d is;
And with thy mighty arm thou hast
dispers''d thine enemies.

11The heav''ns are thine, thou for thine own
the earth dost also take;
The world, and fulness of the same,
thy pow''r did found and make.

12The north and south from thee alone
their first beginning had;
Both Tabor mount and Hermon hill
shall in thy name be glad.

13Thou hast an arm that''s full of pow''r,
thy hand is great in might;
And thy right hand exceedingly
exalted is in height.

14Justice and judgment of thy throne
are made the dwelling-place;
Mercy, accompany''d with truth,
shall go before thy face.

15O greatly bless''d the people are
the joyful sound that know;
In brightness of thy face, O Lord,
they ever on shall go.

16They in thy name shall all the day
rejoice exceedingly;
And in thy righteousness shall they
exalted be on high.

17Because the glory of their strength
doth only stand in thee;
And in thy favour shall our horn
and pow''r exalted be.

18For God is our defence; and he
to us doth safety bring:
The Holy One of Israel
is our almighty King.

19In vision to thy Holy One
thou saidst, I help upon
A strong one laid; out of the folk
I rais''d a chosen one;

20Ev''n David, I have found him out
a servant unto me;
And with my holy oil my King
anointed him to be.

21With whom my hand shall stablish''d be;
mine arm shall make him strong.
22On him the foe shall not exact,
nor son of mischief wrong.

23I will beat down before his face
all his malicious foes;
I will them greatly plague who do
with hatred him oppose.

24My mercy and my faithfulness
with him yet still shall be;
And in my name his horn and pow''r
men shall exalted see.

25His hand and pow''r shall reach afar;
I''ll set it in the sea;
And his right hand established
shall in the rivers be.

26Thou art my Father, he shall cry,
thou art my God alone;
And he shall say, Thou art the Rock
of my salvation.

27I''ll make him my first-born, more high
than kings of any land.
28My love I''ll ever keep for him,
my cov''nant fast shall stand.

29His seed I by my pow''r will make
for ever to endure;
And, as the days of heav''n, his throne
shall stable be, and sure.

30But if his children shall forsake
my laws, and go astray,
And in my judgments shall not walk,
but wander from my way:

31If they my laws break,
and do not keep my commandements;
32I''ll visit then their faults with rods,
their sins with chastisements.

33Yet I''ll not take my love from him,
nor false my promise make.
34My cov''nant I''ll not break, nor change
what with my mouth I spake.

35Once by my holiness I sware,
to David I''ll not lie;
36His seed and throne shall, as the sun,
before me last for aye.

37It, like the moon, shall ever be
establish''d stedfastly;
And like to that which in the heav''n
doth witness faithfully.

38But thou, displeased, hast cast off,
thou didst abhor and loathe;
With him that thine anointed is
thou hast been very wroth.

39Thou hast thy servant''s covenant
made void, and quite cast by;
Thou hast profan''d his crown, while it
cast on the ground doth lie.

40Thou all his hedges hast broke down,
his strong holds down hast torn.
41He to all passers-by a spoil,
to neighbours is a scorn.

42Thou hast set up his foes'' right hand;
mad''st all his en''mies glad:
43Turn''d his sword''s edge, and him
to stand in battle hast not made.

44His glory thou hast made to cease,
his throne to ground down cast;
45Shorten''d his days of youth, and him
with shame thou cover''d hast.

46How long, Lord, wilt thou hide thyself?
for ever, in thine ire?
And shall thine indignation
burn like unto a fire?

47Remember, Lord, how short a time
I shall on earth remain:
O wherefore is it so that thou
has made all men in vain?

48What man is he that liveth here,
and death shall never see?
Or from the power of the grave
what man his soul shall free?

49Thy former loving-kindnesses,
O Lord, where be they now?
Those which in truth and faithfulness
to David sworn hast thou?

50Mind, Lord, thy servant''s sad reproach;
how I in bosom bear
The scornings of the people all,
who strong and mighty are.

51Wherewith thy raging enemies
reproach''d, O Lord, think on;
Wherewith they have reproach''d the steps
of thine anointed one.

52All blessing to the Lord our God
let be ascribed then:
For evermore so let it be.
Amen, yea, and amen.', '[{"index": 0, "lines": [{"text": "God''s mercies I will ever sing;", "syllables": ["Go-", "d''s", "mer-", "cies", "I", "will", "ever", "sing;"], "bibleVerseRef": 1}, {"text": "and with my mouth I shall"}, {"text": "Thy faithfulness make to be known"}, {"text": "to generations all."}]}, {"index": 1, "lines": [{"text": "For mercy shall be built, said I,", "syllables": ["For", "mercy", "shall", "be", "bu-", "ilt,", "said", "I,"], "bibleVerseRef": 2}, {"text": "for ever to endure;", "syllables": ["for", "ever", "to", "en-", "dure-", ";"]}, {"text": "Thy faithfulness, ev''n in the heav''ns,"}, {"text": "thou wilt establish sure."}]}, {"index": 2, "lines": [{"text": "I with my chosen One have made", "syllables": ["I", "with", "my", "chose-", "n", "One", "have", "made"], "bibleVerseRef": 3}, {"text": "a cov''nant graciously;"}, {"text": "And to my servant, whom I lov''d,"}, {"text": "to David sworn have I;"}]}, {"index": 3, "lines": [{"text": "That I thy seed establish shall", "bibleVerseRef": 4}, {"text": "for ever to remain,", "syllables": ["for", "ever", "to", "re-", "mai-", "n,"]}, {"text": "And will to generations all"}, {"text": "thy throne build and maintain.", "syllables": ["thy", "throne", "build", "and", "main-", "tain."]}]}, {"index": 4, "lines": [{"text": "The praises of thy wonders, Lord,", "syllables": ["The", "praise-", "s", "of", "thy", "won-", "ders,", "Lord,"], "bibleVerseRef": 5}, {"text": "the heavens shall express;", "syllables": ["the", "heave-", "ns", "shall", "ex-", "press;"]}, {"text": "And in the congregation", "syllables": ["And", "in", "the", "co-", "n-", "gre-", "ga-", "tion"]}, {"text": "of saints thy faithfulness."}]}, {"index": 5, "lines": [{"text": "For who in heaven with the Lord", "syllables": ["For", "who", "in", "heave-", "n", "with", "the", "Lord"], "bibleVerseRef": 6}, {"text": "may once himself compare?", "syllables": ["may", "once", "him-", "self", "com-", "pare?"]}, {"text": "Who is like God among the sons"}, {"text": "of those that mighty are?"}]}, {"index": 6, "lines": [{"text": "Great fear in meeting of the saints", "bibleVerseRef": 7}, {"text": "is due unto the Lord;"}, {"text": "And he of all about him should"}, {"text": "with rev''rence be ador''d."}]}, {"index": 7, "lines": [{"text": "O thou that art the Lord of hosts,", "bibleVerseRef": 8}, {"text": "what Lord in mightiness"}, {"text": "Is like to thee? who compass''d round"}, {"text": "art with thy faithfulness."}]}, {"index": 8, "lines": [{"text": "Ev''n in the raging of the sea", "bibleVerseRef": 9}, {"text": "thou over it dost reign;", "syllables": ["thou", "over", "it", "dost", "rei-", "gn;"]}, {"text": "And when the waves thereof do swell,"}, {"text": "thou stillest them again."}]}, {"index": 9, "lines": [{"text": "Rahab in pieces thou didst break,", "syllables": ["ra-", "hab", "in", "piece-", "s", "thou", "didst", "break,"], "bibleVerseRef": 10}, {"text": "like one that slaughter''d is;"}, {"text": "And with thy mighty arm thou hast"}, {"text": "dispers''d thine enemies."}]}, {"index": 10, "lines": [{"text": "The heav''ns are thine, thou for thine own", "bibleVerseRef": 11}, {"text": "the earth dost also take;"}, {"text": "The world, and fulness of the same,"}, {"text": "thy pow''r did found and make."}]}, {"index": 11, "lines": [{"text": "The north and south from thee alone", "bibleVerseRef": 12}, {"text": "their first beginning had;"}, {"text": "Both Tabor mount and Hermon hill"}, {"text": "shall in thy name be glad."}]}, {"index": 12, "lines": [{"text": "Thou hast an arm that''s full of pow''r,", "bibleVerseRef": 13}, {"text": "thy hand is great in might;"}, {"text": "And thy right hand exceedingly"}, {"text": "exalted is in height."}]}, {"index": 13, "lines": [{"text": "Justice and judgment of thy throne", "syllables": ["justice", "and", "jud-", "gment", "of", "thy", "thro-", "ne"], "bibleVerseRef": 14}, {"text": "are made the dwelling-place;", "syllables": ["are", "made", "the", "dwellin-", "g-pla-"