INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (57, 'recJf9nm1HewQelCg', 78, '78', '1Attend, my people, to my law;
thereto give thou an ear;
The words that from my mouth proceed
attentively do hear.

2My mouth shall speak a parable,
and sayings dark of old;
3The same which we have heard and known,
and us our fathers told.

4We also will them not conceal
from their posterity;
Them to the generation
to come declare will we:

The praises of the Lord our God,
and his almighty strength,
The wondrous works that he hath done,
we will shew forth at length.

5His testimony and his law
in Isr''el he did place,
And charg''d our fathers it to show
to their succeeding race;

6That so the race which was to come
might well them learn and know;
And sons unborn, who should arise,
might to their sons them show:

7That they might set their hope in God,
and suffer not to fall
His mighty works out of their mind,
but keep his precepts all:

8And might not, like their fathers, be
a stiff rebellious race;
A race not right in heart; with God
whose sp''rit not stedfast was.

9The sons of Ephraim, who nor bows
nor other arms did lack,
When as the day of battle was,
they faintly turned back.

10They brake God''s cov''nant,
and refus''d in his commands to go;
11His works and wonders they forgot,
which he to them did show.

12Things marvellous he brought to pass;
their fathers them beheld
Within the land of Egypt done,
yea, ev''n in Zoan''s field.

13By him divided was the sea,
he caus''d them through to pass;
And made the waters so to stand,
as like an heap it was.

14With cloud by day, with light of fire
all night, he did them guide.
15In desert rocks he clave,
and drink, as from great depths, supply''d.

16He from the rock brought streams, like floods
made waters to run down.
17Yet sinning more, in desert they
provok''d the Highest One.

18For in their heart they tempted God,
and, speaking with mistrust,
They greedily did meat require
to satisfy their lust.

19Against the Lord himself they spake,
and, murmuring, said thus,
A table in the wilderness
can God prepare for us?

20Behold, he smote the rock, and thence
came streams and waters great;
But can he give his people bread?
and send them flesh to eat?

21The Lord did hear, and waxed wroth;
so kindled was a flame
''Gainst Jacob, and ''gainst Israel
up indignation came.

22For they believ''d not God, nor trust
in his salvation had;
23Though clouds above he did command,
and heav''n''s doors open made,

24And manna rain''d on them,
and gave them corn of heav''n to eat.
25Man angels'' food did eat; to them
he to the full sent meat.

26And in the heaven he did cause
an eastern wind to blow;
And by his power he let out
the southern wind to go.

27Then flesh as thick as dust he made
to rain down them among;
And feather''d fowls, like as the sand
which li''th the shore along.

28At his command amidst their camp
these show''rs of flesh down fell,
All round about the tabernacles
and tents where they did dwell.

29So they did eat abundantly,
and had of meat their fill;
For he did give to them what was
their own desire and will.

30They from their lust had not estrang''d
their heart and their desire;
But while the meat was in their mouths,
which they did so require,

31God''s wrath upon them came,
and slew the fattest of them all;
So that the choice of Israel,
o''erthrown by death, did fall.

32Yet, notwithstanding of all this,
they sinned still the more;
And though he had great wonders wrought,
believ''d him not therefore:

33Wherefore their days in vanity
he did consume and waste;
And by his wrath their wretched years
away in trouble past.

34But when he slew them, then they did
to seek him shew desire;
Yea, they return''d, and after God
right early did enquire.

35And that the Lord had been their Rock,
they did remember then;
Ev''n that the high almighty God
had their Redeemer been.

36Yet with their mouth they flatter''d him,
and spake but feignedly;
And they unto the God of truth
with their false tongues did lie.

37For though their words were good, their heart
with him was not sincere;
Unstedfast and perfidious
they in his cov''nant were.

38But, full of pity, he forgave
their sin, them did not slay;
Nor stirr''d up all his wrath, but oft
his anger turn''d away.

39For that they were but fading flesh
to mind he did recall;
A wind that passeth soon away,
and not returns at all.

40How often did they him provoke
within the wilderness!
And in the desert did him grieve
with their rebelliousness!

41Yea, turning back, they tempted God,
and limits set upon
Him, who in midst of Isr''el is
the only Holy One.

42They did not call to mind his pow''r,
nor yet the day when he
Deliver''d them out of the hand
of their fierce enemy;

43Nor how great signs in Egypt land
he openly had wrought;
What miracles in Zoan''s field
his hand to pass had brought.

44How lakes and rivers ev''ry where
he turned into blood;
So that nor man nor beast could drink
of standing lake or flood.

45He brought among them swarms of flies,
which did them sore annoy;
And divers kinds of filthy frogs
he sent them to destroy.

46He to the caterpillar gave
the fruits of all their soil;
Their labours he deliver''d up
unto the locusts'' spoil.

47Their vines with hail, their sycamores
he with the frost did blast:
48Their beasts to hail he gave; their flocks
hot thunderbolts did waste.

49Fierce burning wrath he on them cast,
and indignation strong,
And troubles sore, by sending forth
ill angels them among.

50He to his wrath made way; their soul
from death he did not save;
But over to the pestilence
the lives of them he gave.

51In Egypt land the first-born all
he smote down ev''ry where;
Among the tents of Ham, ev''n these
chief of their strength that were.

52But his own people, like to sheep,
thence to go forth he made;
And he, amidst the wilderness,
them, as a flock, did lead.

53And he them safely on did lead,
so that they did not fear;
Whereas their en''mies by the sea
quite overwhelmed were.

54To borders of his sanctuary
the Lord his people led,
Ev''n to the mount which his right hand
for them had purchased.

55The nations of Canaan,
by his almighty hand,
Before their face he did expel
out of their native land;

Which for inheritance to them
by line he did divide,
And made the tribes of Israel
within their tents abide.

56Yet God most high they did provoke,
and tempted ever still;
And to observe his testimonies
did not incline their will:

57But, like their fathers, turned back,
and dealt unfaithfully:
Aside they turned, like a bow
that shoots deceitfully.

58For they to anger did provoke
him with their places high;
And with their graven images
mov''d him to jealousy.

59When God heard this, he waxed wroth,
and much loath''d Isr''el then:
60So Shiloh''s tent he left, the tent
which he had plac''d with men.

61And he his strength delivered
into captivity;
He left his glory in the hand
of his proud enemy.

62His people also he gave o''er
unto the sword''s fierce rage:
So sore his wrath inflamed was
against his heritage.

63The fire consum''d their choice young men;
their maids no marriage had;
64And when their priests fell by the sword,
their wives no mourning made.

65But then the Lord arose, as one
that doth from sleep awake;
And like a giant that, by wine
refresh''d, a shout doth make:

66Upon his en''mies'' hinder parts
he made his stroke to fall;
And so upon them he did put
a shame perpetual.

67Moreover, he the tabernacle
of Joseph did refuse;
The mighty tribe of Ephraim
he would in no wise chuse:

68But he did chuse Jehudah''s tribe
to be the rest above;
And of mount Sion he made choice,
which he so much did love.

69And he his sanctuary built
like to a palace high,
Like to the earth which he did found
to perpetuity.

70Of David, that his servant was,
he also choice did make,
And even from the folds of sheep
was pleased him to take:

71From waiting on the ewes with young,
he brought him forth to feed
Israel, his inheritance,
his people, Jacob''s seed.

72So after the integrity
he of his heart them fed;
And by the good skill of his hands
them wisely governed.', '[{"index": 0, "lines": [{"text": "Attend, my people, to my law;", "syllables": ["attend,", "my", "pe-", "o-", "ple,", "to", "my", "law;"], "bibleVerseRef": 1}, {"text": "thereto give thou an ear;"}, {"text": "The words that from my mouth proceed"}, {"text": "attentively do hear.", "syllables": ["atten-", "ti-", "ve-", "ly", "do", "hear."]}]}, {"index": 1, "lines": [{"text": "My mouth shall speak a parable,", "bibleVerseRef": 2}, {"text": "and sayings dark of old;", "syllables": ["and", "sayi-", "ngs", "dark", "of", "old;"]}, {"text": "The same which we have heard and known,", "bibleVerseRef": 3}, {"text": "and us our fathers told."}]}, {"index": 2, "lines": [{"text": "We also will them not conceal", "bibleVerseRef": 4}, {"text": "from their posterity;"}, {"text": "Them to the generation", "syllables": ["The-", "m", "to", "the", "ge-", "ne-", "ra-", "tion"]}, {"text": "to come declare will we:"}]}, {"index": 3, "lines": [{"text": "The praises of the Lord our God,", "syllables": ["The", "praise-", "s", "of", "the", "Lord", "our", "God,"]}, {"text": "and his almighty strength,"}, {"text": "The wondrous works that he hath done,"}, {"text": "we will shew forth at length."}]}, {"index": 4, "lines": [{"text": "His testimony and his law", "bibleVerseRef": 5}, {"text": "in Isr''el he did place,", "syllables": ["in", "isr''el", "he", "did", "pla-", "ce,"]}, {"text": "And charg''d our fathers it to show"}, {"text": "to their succeeding race;"}]}, {"index": 5, "lines": [{"text": "That so the race which was to come", "bibleVerseRef": 6}, {"text": "might well them learn and know;"}, {"text": "And sons unborn, who should arise,"}, {"text": "might to their sons them show:"}]}, {"index": 6, "lines": [{"text": "That they might set their hope in God,", "bibleVerseRef": 7}, {"text": "and suffer not to fall"}, {"text": "His mighty works out of their mind,"}, {"text": "but keep his precepts all:"}]}, {"index": 7, "lines": [{"text": "And might not, like their fathers, be", "bibleVerseRef": 8}, {"text": "a stiff rebellious race;"}, {"text": "A race not right in heart; with God"}, {"text": "whose sp''rit not stedfast was."}]}, {"index": 8, "lines": [{"text": "The sons of Ephraim, who nor bows", "bibleVerseRef": 9}, {"text": "nor other arms did lack,"}, {"text": "When as the day of battle was,"}, {"text": "they faintly turned back."}]}, {"index": 9, "lines": [{"text": "They brake God''s cov''nant,", "syllables": ["They", "bra-", "ke", "Go-", "d''s", "cov-", "''na-", "nt,"], "bibleVerseRef": 10}, {"text": "and refus''d in his commands to go;", "syllables": ["and", "refus''d", "in", "his", "commands", "togo;"]}, {"text": "His works and wonders they forgot,", "bibleVerseRef": 11}, {"text": "which he to them did show."}]}, {"index": 10, "lines": [{"text": "Things marvellous he brought to pass;", "bibleVerseRef": 12}, {"text": "their fathers them beheld"}, {"text": "Within the land of Egypt done,"}, {"text": "yea, ev''n in Zoan''s field."}]}, {"index": 11, "lines": [{"text": "By him divided was the sea,", "bibleVerseRef": 13}, {"text": "he caus''d them through to pass;"}, {"text": "And made the waters so to stand,", "syllables": ["And", "made", "the", "wate-", "rs", "so", "to", "stand,"]}, {"text": "as like an heap it was."}]}, {"index": 12, "lines": [{"text": "With cloud by day, with light of fire", "bibleVerseRef": 14}, {"text": "all night, he did them guide.", "syllables": ["all", "night,", "he", "did", "them", "guide."]}, {"text": "In desert rocks he clave,", "syllables": ["In", "de-", "sert", "ro-", "cks", "he", "cla-", "ve,"], "bibleVerseRef": 15}, {"text": "and drink, as from great depths, supply''d.", "syllables": ["and", "drink,", "as", "from", "great", "depths,supply''d."]}]}, {"index": 13, "lines": [{"text": "He from the rock brought streams, like floods", "bibleVerseRef": 16}, {"text": "made waters to run down.", "syllables": ["made", "wate-", "rs", "to", "run", "down."]}, {"text": "Yet sinning more, in desert they", "bibleVerseRef": 17}, {"text": "provok''d the Highest One."}]}, {"index": 14, "lines": [{"text": "For in their heart they tempted God,", "bibleVerseRef": 18}, {"text": "and, speaking with mistrust,"}, {"text": "They greedily did meat require", "syllables": ["They", "greedily", "did", "meat", "re-", "qu-", "i-", "re"]}, {"text": "to satisfy their lust."}]}, {"index": 15, "lines": [{"text": "Against the Lord himself they spake,", "syllables": ["against", "the", "Lord", "him-", "self", "they", "spa-", "ke,"], "bibleVerseRef": 19}, {"text": "and, murmuring, said thus,"}, {"text": "A table in the wilderness"}, {"text": "can God prepare for us?"}]}, {"index": 16, "lines": [{"text": "Behold, he smote the rock, and thence", "syllables": ["behold,", "he", "smo-", "te", "the", "rock,", "and", "thence"], "bibleVerseRef": 20}, {"text": "came streams and waters great;", "syllables": ["came", "strea-", "ms", "and", "waters", "great;"]}, {"text": "But can he give his people bread?", "syllables": ["But", "can", "he", "give", "his", "peo-", "ple", "bread?"]}, {"text": "and send them flesh to eat?"}]}, {"index": 17, "lines": [{"text": "The Lord did hear, and waxed wroth;", "bibleVerseRef": 21}, {"text": "so kindled was a flame", "syllables": ["so", "kindled", "was", "a", "fla-", "me"]}, {"text": "''Gainst Jacob, and ''gainst Israel", "syllables": ["''Gai-", "nst", "ja-", "cob,", "and", "''gainst", "is-", "rael"]}, {"text": "up indignation came."}]}, {"index": 18, "lines": [{"text": "For they believ''d not God, nor trust", "bibleVerseRef": 22}, {"text": "in his salvation had;"}, {"text": "Though clouds above he did command,", "bibleVerseRef": 23}, {"text": "and heav''n''s doors open made,", "syllables": ["and", "hea-", "v''n''s", "doors", "open", "made,"]}]}, {"index": 19, "lines": [{"text": "And manna rain''d on them,", "syllables": ["And", "man-", "na", "rai-", "n''d", "on", "the-", "m,"], "bibleVerseRef": 24}, {"text": "and gave them corn of heav''n to eat.", "syllables": ["and", "gave", "them", "corn", "of", "heav''ntoeat."]}, {"text": "Man angels'' food did eat; to them", "bibleVerseRef": 25}, {"text": "he to the full sent meat."}]}, {"index": 20, "lines": [{"text": "And in the heaven he did cause", "syllables": ["And", "in", "the", "heave-", "n", "he", "did", "cause"], "bibleVerseRef": 26}, {"text": "an eastern wind to blow;"}, {"text": "And by his power he let out", "syllables": ["And", "by", "his", "powe-", "r", "he", "let", "out"]}, {"text": "the southern wind to go."}]}, {"index": 21, "lines": [{"text": "Then flesh as thick as dust he made", "bibleVerseRef": 27}, {"text": "to rain down them among;"}, {"text": "And feather''d fowls, like as the sand"}, {"text": "which li''th the shore along."}]}, {"index": 22, "lines": [{"text": "At his command amidst their camp", "bibleVerseRef": 28}, {"text": "these show''rs of flesh down fell,"}, {"text": "All round about the tabernacles"}, {"text": "and tents where they did dwell."}]}, {"index": 23, "lines": [{"text": "So they did eat abundantly,", "bibleVerseRef": 29}, {"text": "and had of meat their fill;"}, {"text": "For he did give to them what was"}, {"text": "their own desire and will."}]}, {"index": 24, "lines": [{"text": "They from their lust had not estrang''d", "bibleVerseRef": 30}, {"text": "their heart and their desire;"}, {"text": "But while the meat was in their mouths,"}, {"text": "which they did so require,", "syllables": ["which", "they", "did", "so", "requi-", "re,"]}]}, {"index": 25, "lines": [{"text": "God''s wrath upon them came,", "syllables": ["Go-", "d''s", "wra-", "th", "u-", "pon", "them", "came,"], "bibleVerseRef": 31}, {"text": "and slew the fattest of them all;", "syllables": ["and", "slew", "the", "fattest", "of", "themall;"]}, {"text": "So that the choice of Israel,", "syllables": ["So", "that", "the", "choi-", "ce", "of", "is-", "rael,"]}, {"text": "o''erthrown by death, did fall."}]}, {"index": 26, "lines": [{"text": "Yet, notwithstanding of all this,", "bibleVerseRef": 32}, {"text": "they sinned still the more;"}, {"text": "And though he had great wonders wrought,"}, {"text": "believ''d him not therefore:"}]}, {"index": 27, "lines": [{"text": "Wherefore their days in vanity", "bibleVerseRef": 33}, {"text": "he did consume and waste;", "syllables": ["he", "did", "consume", "and", "was-", "te;"]}, {"text": "And by his wrath their wretched years"}, {"text": "away in trouble past."}]}, {"index": 28, "lines": [{"text": "But when he slew them, then they did", "bibleVerseRef": 34}, {"text": "to seek him shew desire;"}, {"text": "Yea, they return''d, and after God"}, {"text": "right early did enquire.", "syllables": ["right", "early", "did", "enqu-", "i-", "re."]}]}, {"index": 29, "lines": [{"text": "And that the Lord had been their Rock,", "bibleVerseRef": 35}, {"text": "they did remember then;"}, {"text": "Ev''n that the high almighty God"}, {"text": "had their Redeemer been.", "syllables": ["had", "their", "re-", "deeme-", "r", "been."]}]}, {"index": 30, "lines": [{"text": "Yet with their mouth they flatter''d him,", "bibleVerseRef": 36}, {"text": "and spake but feignedly;", "syllables": ["and", "spake", "but", "feig-", "ned-", "ly;"]}, {"text": "And they unto the God of truth"}, {"text": "with their false tongues did lie.", "syllables": ["with", "their", "false", "tongues", "did", "lie."]}]}, {"index": 31, "lines": [{"text": "For though their words were good, their heart", "bibleVerseRef": 37}, {"text": "with him was not sincere;", "syllables": ["with", "him", "was", "not", "since-", "re;"]}, {"text": "Unstedfast and perfidious", "syllables": ["un-", "ste-", "d-", "fast", "and", "per-", "fi-", "dious"]}, {"text": "they in his cov''nant were."}]}, {"index": 32, "lines": [{"text": "But, full of pity, he forgave", "bibleVerseRef": 38}, {"text": "their sin, them did not slay;"}, {"text": "Nor stirr''d up all his wrath, but oft"}, {"text": "his anger turn''d away."}]}, {"index": 33, "lines": [{"text": "For that they were but fading flesh", "bibleVerseRef": 39}, {"text": "to mind he did recall;"}, {"text": "A wind that passeth soon away,"}, {"text": "and not returns at all."}]}, {"index": 34, "lines": [{"text": "How often did they him provoke", "bibleVerseRef": 40}, {"text": "within the wilderness!"}, {"text": "And in the desert did him grieve", "syllables": ["And", "in", "the", "desert", "did", "him", "grie-", "ve"]}, {"text": "with their rebelliousness!"}]}, {"index": 35, "lines": [{"text": "Yea, turning back, they tempted God,", "bibleVerseRef": 41}, {"text": "and limits set upon"}, {"text": "Him, who in midst of Isr''el is"}, {"text": "the only Holy One."}]}, {"index": 36, "lines": [{"text": "They did not call to mind his pow''r,", "bibleVerseRef": 42}, {"text": "nor yet the day when he"}, {"text": "Deliver''d them out of the hand"}, {"text": "of their fierce enemy;", "syllables": ["of", "their", "fierce", "en-", "e-", "my;"]}]}, {"index": 37, "lines": [{"text": "Nor how great signs in Egypt land", "bibleVerseRef": 43}, {"text": "he openly had wrought;", "syllables": ["he", "open-", "ly", "had", "wrou-", "ght;"]}, {"text": "What miracles in Zoan''s field"}, {"text": "his hand to pass had brought."}]}, {"index": 38, "lines": [{"text": "How lakes and rivers ev''ry where", "syllables": ["How", "lakes", "and", "rive-", "rs", "ev-", "''ry", "where"], "bibleVerseRef": 44}, {"text": "he turned into blood;"}, {"text": "So that nor man nor beast could drink"}, {"text": "of standing lake or flood."}]}, {"index": 39, "lines": [{"text": "He brought among them swarms of flies,", "bibleVerseRef": 45}, {"text": "which did them sore annoy;"}, {"text": "And divers kinds of filthy frogs", "syllables": ["And", "dive-", "rs", "kinds", "of", "fil-", "thy", "frogs"]}, {"text": "he sent them to destroy."}]}, {"index": 40, "lines": [{"text": "He to the caterpillar gave", "syllables": ["He", "to", "the", "cate-", "r-", "pil-", "lar", "gave"], "bibleVerseRef": 46}, {"text": "the fruits of all their soil;", "syllables": ["the", "fruits", "of", "all", "their", "soil;"]}, {"text": "Their labours he deliver''d up"}, {"text": "unto the locusts'' spoil."}]}, {"index": 41, "lines": [{"text": "Their vines with hail, their sycamores", "bibleVerseRef": 47}, {"text": "he with the frost did blast:"}, {"text": "Their beasts to hail he gave; their flocks", "bibleVerseRef": 48}, {"text": "hot thunderbolts did waste.", "syllables": ["hot", "thunder-", "bolts", "did", "was-", "te."]}]}, {"index": 42, "lines": [{"text": "Fierce burning wrath he on them cast,", "syllables": ["fierce", "bur-", "ning", "wrath", "he", "on", "them", "cast,"], "bibleVerseRef": 49}, {"text": "and indignation strong,"}, {"text": "And troubles sore, by sending forth"}, {"text": "ill angels them among."}]}, {"index": 43, "lines": [{"text": "He to his wrath made way; their soul", "bibleVerseRef": 50}, {"text": "from death he did not save;"}, {"text": "But over to the pestilence"}, {"text": "the lives of them he gave."}]}, {"index": 44, "lines": [{"text": "In Egypt land the first-born all", "bibleVerseRef": 51}, {"text": "he smote down ev''ry where;", "syllables": ["he", "smote", "down", "ev-", "''ry", "where;"]}, {"text": "Among the tents of Ham, ev''n these"}, {"text": "chief of their strength that were."}]}, {"index": 45, "lines": [{"text": "But his own people, like to sheep,", "syllables": ["But", "his", "own", "peo-", "ple,", "like", "to", "sheep,"], "bibleVerseRef": 52}, {"text": "thence to go forth he made;"}, {"text": "And he, amidst the wilderness,"}, {"text": "them, as a flock, did lead."}]}, {"index": 46, "lines": [{"text": "And he them safely on did lead,", "bibleVerseRef": 53}, {"text": "so that they did not fear;"}, {"text": "Whereas their en''mies by the sea", "syllables": ["Wherea-", "s", "their", "en-", "''mies", "by", "the", "sea"]}, {"text": "quite overwhelmed were.", "syllables": ["qui-", "te", "over-", "whel-", "med", "were."]}]}, {"index": 47, "lines": [{"text": "To borders of his sanctuary", "syllables": ["To", "borders", "of", "his", "san-", "ctu-", "a-", "ry"], "bibleVerseRef": 54}, {"text": "the Lord his people led,", "syllables": ["the", "Lord", "his", "peo-", "ple", "led,"]}, {"text": "Ev''n to the mount which his right hand"}, {"text": "for them had purchased."}]}, {"index": 48, "lines": [{"text": "The nations of Canaan,", "syllables": ["The", "na-", "tio-", "ns", "of", "ca-", "naa-", "n,"], "bibleVerseRef": 55}, {"text": "by his almighty hand,"}, {"text": "Before their face he did expel"}, {"text": "out of their native land;"}]}, {"index": 49, "lines": [{"text": "Which for inheritance to them", "syllables": ["Which", "for", "inhe-", "ri-", "tan-", "ce", "to", "them"]}, {"text": "by line he did divide,"}, {"text": "And made the tribes of Israel"}, {"text": "within their tents abide."}]}, {"index": 50, "lines": [{"text": "Yet God most high they did provoke,", "bibleVerseRef": 56}, {"text": "and tempted ever still;", "syllables": ["and", "tem-", "pted", "ever", "sti-", "ll;"]}, {"text": "And to observe his testimonies", "syllables": ["And", "to", "observe", "his", "tes-", "ti-", "mo-", "nies"]}, {"text": "did not incline their will:", "syllables": ["did", "not", "incli-", "ne", "their", "will:"]}]}, {"index": 51, "lines": [{"text": "But, like their fathers, turned back,", "bibleVerseRef": 57}, {"text": "and dealt unfaithfully:"}, {"text": "Aside they turned, like a bow"}, {"text": "that shoots deceitfully."}]}, {"index": 52, "lines": [{"text": "For they to anger did provoke", "bibleVerseRef": 58}, {"text": "him with their places high;"}, {"text": "And with their graven images", "syllables": ["And", "with", "thei-", "r", "gra-", "ven", "i-", "mages"]}, {"text": "mov''d him to jealousy."}]}, {"index": 53, "lines": [{"text": "When God heard this, he waxed wroth,", "bibleVerseRef": 59}, {"text": "and much loath''d Isr''el then:", "syllables": ["and", "much", "loath''d", "is-", "r''el", "then:"]}, {"text": "So Shiloh''s tent he left, the tent", "bibleVerseRef": 60}, {"text": "which he had plac''d with men."}]}, {"index": 54, "lines": [{"text": "And he his strength delivered", "bibleVerseRef": 61}, {"text": "into captivity;"}, {"text": "He left his glory in the hand"}, {"text": "of his proud enemy."}]}, {"index": 55, "lines": [{"text": "His people also he gave o''er", "syllables": ["His", "peo-", "ple", "al-", "so", "he", "gave", "o''er"], "bibleVerseRef": 62}, {"text": "unto the sword''s fierce rage:", "syllables": ["unto", "the", "sword''s", "fier-", "ce", "rage:"]}, {"text": "So sore his wrath inflamed was"}, {"text": "against his heritage."}]}, {"index": 56, "lines": [{"text": "The fire consum''d their choice young men;", "bibleVerseRef": 63}, {"text": "their maids no marriage had;", "syllables": ["their", "maids", "no", "marria-", "ge", "had;"]}, {"text": "And when their priests fell by the sword,", "bibleVerseRef": 64}, {"text": "their wives no mourning made."}]}, {"index": 57, "lines": [{"text": "But then the Lord arose, as one", "bibleVerseRef": 65}, {"text": "that doth from sleep awake;"}, {"text": "And like a giant that, by wine"}, {"text": "refresh''d, a shout doth make:"}]}, {"index": 58, "lines": [{"text": "Upon his en''mies'' hinder parts", "bibleVerseRef": 66}, {"text": "he made his stroke to fall;", "syllables": ["he", "made", "his", "stroke", "to", "fall;"]}, {"text": "And so upon them he did put"}, {"text": "a shame perpetual."}]}, {"index": 59, "lines": [{"text": "Moreover, he the tabernacle", "bibleVerseRef": 67}, {"text": "of Joseph did refuse;", "syllables": ["of", "Jose-", "ph", "did", "re-", "fuse;"]}, {"text": "The mighty tribe of Ephraim"}, {"text": "he would in no wise chuse:"}]}, {"index": 60, "lines": [{"text": "But he did chuse Jehudah''s tribe", "syllables": ["But", "he", "did", "chuse", "jehu-", "dah''s", "tri-", "be"], "bibleVerseRef": 68}, {"text": "to be the rest above;"}, {"text": "And of mount Sion he made choice,", "syllables": ["And", "of", "mount", "Sion", "he", "made", "choice-", ","]}, {"text": "which he so much did love."}]}, {"index": 61, "lines": [{"text": "And he his sanctuary built", "syllables": ["And", "he", "his", "sanctu-", "a-", "ry", "bu-", "ilt"], "bibleVerseRef": 69}, {"text": "like to a palace high,"}, {"text": "Like to the earth which he did found"}, {"text": "to perpetuity."}]}, {"index": 62, "lines": [{"text": "Of David, that his servant was,", "bibleVerseRef": 70}, {"text": "he also choice did make,"}, {"text": "And even from the folds of sheep", "syllables": ["And", "even", "from", "the", "fo-", "lds", "of", "sheep"]}, {"text": "was pleased him to take:"}]}, {"index": 63, "lines": [{"text": "From waiting on the ewes with young,", "bibleVerseRef": 71}, {"text": "he brought him forth to feed"}, {"text": "Israel, his inheritance,"}, {"text": "his people, Jacob''s seed.", "syllables": ["his", "peo-", "ple,", "ja-", "cob''s", "seed."]}]}, {"index": 64, "lines": [{"text": "So after the integrity", "bibleVerseRef": 72}, {"text": "he of his heart them fed;"}, {"text": "And by the good skill of his hands"}, {"text": "them wisely governed.", "syllables": ["them", "wise-", "ly", "gove-", "r-", "ned."]}]}]', 'CM', NULL, 'Attend, my people, to my law...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (61, 'recLKr3FGrIwFXeTj', 49, '49', '1Hear this, all people, and give ear,
all in the world that dwell;
2Both low and high, both rich and poor.
3My mouth shall wisdom tell:

My heart shall knowledge meditate.
4I will incline mine ear
To parables, and on the harp
my sayings dark declare.

5Amidst those days that evil be,
why should I, fearing, doubt?
When of my heels th'' iniquity
shall compass me about.

6Whoe''er they be that in their wealth
their confidence do pitch,
And boast themselves, because they are
become exceeding rich:

7Yet none of these his brother can
redeem by any way;
Nor can he unto God for him
sufficient ransom pay,

8(Their soul''s redemption precious is,
and it can never be,)
9That still he should for ever live,
and not corruption see.

10For why? he seeth that wise men die,
and brutish fools also
Do perish; and their wealth, when dead,
to others they let go.

11Their inward thought is, that their house
and dwelling-places shall
Stand through all ages; they their lands
by their own names do call.

12But yet in honour shall not man
abide continually;
But passing hence, may be compar''d
unto the beasts that die.

13Thus brutish folly plainly is
their wisdom and their way;
Yet their posterity approve
what they do fondly say.

14Like sheep they in the grave are laid,
and death shall them devour;
And in the morning upright men
shall over them have pow''r:

Their beauty from their dwelling shall
consume within the grave.
15But from hell''s hand God will me free,
for he shall me receive.

16Be thou not then afraid when one
enriched thou dost see,
Nor when the glory of his house
advanced is on high:

17For he shall carry nothing hence
when death his days doth end;
Nor shall his glory after him
into the grave descend.

18Although he his own soul did bless
whilst he on earth did live;
(And when thou to thyself dost well,
men will thee praises give;)

19He to his fathers'' race shall go,
they never shall see light.
20Man honour''d wanting knowledge is
like beasts that perish quite.', '[{"index": 0, "lines": [{"text": "Hear this, all people, and give ear,", "syllables": ["Hear", "this,", "all", "peo-", "ple,", "and", "give", "ear,"], "bibleVerseRef": 1}, {"text": "all in the world that dwell;"}, {"text": "Both low and high, both rich and poor.", "bibleVerseRef": 2}, {"text": "My mouth shall wisdom tell:", "bibleVerseRef": 3}]}, {"index": 1, "lines": [{"text": "My heart shall knowledge meditate.", "syllables": ["My", "heart", "shall", "knowled-", "ge", "me-", "di-", "tate."]}, {"text": "I will incline mine ear", "syllables": ["I", "will", "incli-", "ne", "mine", "ear"], "bibleVerseRef": 4}, {"text": "To parables, and on the harp"}, {"text": "my sayings dark declare.", "syllables": ["my", "sayi-", "ngs", "dark", "dec-", "lare."]}]}, {"index": 2, "lines": [{"text": "Amidst those days that evil be,", "bibleVerseRef": 5}, {"text": "why should I, fearing, doubt?"}, {"text": "When of my heels th'' iniquity", "syllables": ["When", "of", "my", "heels", "th''", "iniq-", "ui-", "ty"]}, {"text": "shall compass me about."}]}, {"index": 3, "lines": [{"text": "Whoe''er they be that in their wealth", "syllables": ["Whoe''e-", "r", "they", "be", "that", "in", "their", "wealth"], "bibleVerseRef": 6}, {"text": "their confidence do pitch,", "syllables": ["their", "confi-", "den-", "ce", "do", "pitch,"]}, {"text": "And boast themselves, because they are", "syllables": ["And", "boast", "themsel-", "ves,", "be-", "cause", "they", "are"]}, {"text": "become exceeding rich:"}]}, {"index": 4, "lines": [{"text": "Yet none of these his brother can", "syllables": ["Yet", "none", "of", "these", "his", "bro-", "ther", "can"], "bibleVerseRef": 7}, {"text": "redeem by any way;"}, {"text": "Nor can he unto God for him"}, {"text": "sufficient ransom pay,"}]}, {"index": 5, "lines": [{"text": "(Their soul''s redemption precious is,", "bibleVerseRef": 8}, {"text": "and it can never be,)"}, {"text": "That still he should for ever live,", "syllables": ["That", "still", "he", "shou-", "ld", "for", "ever", "live,"], "bibleVerseRef": 9}, {"text": "and not corruption see."}]}, {"index": 6, "lines": [{"text": "For why? he seeth that wise men die,", "bibleVerseRef": 10}, {"text": "and brutish fools also"}, {"text": "Do perish; and their wealth, when dead,"}, {"text": "to others they let go."}]}, {"index": 7, "lines": [{"text": "Their inward thought is, that their house", "bibleVerseRef": 11}, {"text": "and dwelling-places shall"}, {"text": "Stand through all ages; they their lands", "syllables": ["Stand", "throu-", "gh", "all", "ages;", "they", "their", "lands"]}, {"text": "by their own names do call."}]}, {"index": 8, "lines": [{"text": "But yet in honour shall not man", "bibleVerseRef": 12}, {"text": "abide continually;", "syllables": ["abide", "con-", "ti-", "nu-", "a-", "lly;"]}, {"text": "But passing hence, may be compar''d"}, {"text": "unto the beasts that die."}]}, {"index": 9, "lines": [{"text": "Thus brutish folly plainly is", "bibleVerseRef": 13}, {"text": "their wisdom and their way;"}, {"text": "Yet their posterity approve", "syllables": ["Yet", "their", "poste-", "ri-", "ty", "ap-", "pro-", "ve"]}, {"text": "what they do fondly say."}]}, {"index": 10, "lines": [{"text": "Like sheep they in the grave are laid,", "syllables": ["Like", "sheep", "they", "in", "the", "grave", "are", "laid,"], "bibleVerseRef": 14}, {"text": "and death shall them devour;"}, {"text": "And in the morning upright men"}, {"text": "shall over them have pow''r:", "syllables": ["shall", "over", "them", "have", "po-", "w''r:"]}]}, {"index": 11, "lines": [{"text": "Their beauty from their dwelling shall"}, {"text": "consume within the grave.", "syllables": ["consume", "wi-", "thin", "the", "gra-", "ve."]}, {"text": "But from hell''s hand God will me free,", "bibleVerseRef": 15}, {"text": "for he shall me receive."}]}, {"index": 12, "lines": [{"text": "Be thou not then afraid when one", "bibleVerseRef": 16}, {"text": "enriched thou dost see,"}, {"text": "Nor when the glory of his house"}, {"text": "advanced is on high:"}]}, {"index": 13, "lines": [{"text": "For he shall carry nothing hence", "bibleVerseRef": 17}, {"text": "when death his days doth end;"}, {"text": "Nor shall his glory after him"}, {"text": "into the grave descend.", "syllables": ["into", "the", "gra-", "ve", "des-", "cend."]}]}, {"index": 14, "lines": [{"text": "Although he his own soul did bless", "bibleVerseRef": 18}, {"text": "whilst he on earth did live;"}, {"text": "(And when thou to thyself dost well,", "syllables": ["(And", "when", "thou", "to", "thyse-", "lf", "dost", "well,"]}, {"text": "men will thee praises give;)", "syllables": ["men", "will", "thee", "praise-", "s", "give;)"]}]}, {"index": 15, "lines": [{"text": "He to his fathers'' race shall go,", "bibleVerseRef": 19}, {"text": "they never shall see light."}, {"text": "Man honour''d wanting knowledge is", "syllables": ["Man", "honour''d", "wan-", "ting", "know-", "led-", "ge", "is"], "bibleVerseRef": 20}, {"text": "like beasts that perish quite.", "syllables": ["like", "beasts", "that", "perish", "qui-", "te."]}]}]', 'CM', NULL, 'Hear this, all people, and give ear...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (58, 'recK2jH0krLjJyC17', 109, '109', '1O thou the God of all my praise,
do thou not hold thy peace;
2For mouths of wicked men to speak
against me do not cease:

The mouths of vile deceitful men
against me open''d be;
And with a false and lying tongue
they have accused me.

3They did beset me round about
with words of hateful spight:
And though to them no cause I gave,
against me they did fight.

4They for my love became my foes,
but I me set to pray.
5Evil for good, hatred for love,
to me they did repay.

6Set thou the wicked over him;
and upon his right hand
Give thou his greatest enemy,
ev''n Satan, leave to stand.

7And when by thee he shall be judg''d,
let him condemned be;
And let his pray''r be turn''d to sin,
when he shall call on thee.

8Few be his days, and in his room
his charge another take.
9His children let be fatherless,
his wife a widow make.

10His children let be vagabonds,
and beg continually;
And from their places desolate
seek bread for their supply.

11Let covetous extortioners
catch all he hath away:
Of all for which he labour''d hath
let strangers make a prey.

12Let there be none to pity him,
let there be none at all
That on his children fatherless
will let his mercy fall.

13Let his posterity from earth
cut off for ever be,
And in the foll''wing age their name
be blotted out by thee.

14Let God his father''s wickedness
still to remembrance call;
And never let his mother''s sin
be blotted out at all.

15But let them all before the Lord
appear continually,
That he may wholly from the earth
cut off their memory.

16Because he mercy minded not,
but persecuted still
The poor and needy, that he might
the broken-hearted kill.

17As he in cursing pleasure took,
so let it to him fall;
As he delighted not to bless,
so bless him not at all.

18As cursing he like clothes put on,
into his bowels so,
Like water, and into his bones,
like oil, down let it go.

19Like to the garment let it be
which doth himself array,
And for a girdle, wherewith he
is girt about alway.

20From God let this be their reward
that en''mies are to me,
And their reward that speak against
my soul maliciously.

21But do thou, for thine own name''s sake,
O God the Lord, for me:
Sith good and sweet thy mercy is,
from trouble set me free.

22For I am poor and indigent,
afflicted sore am I,
My heart within me also is
wounded exceedingly.

23I pass like a declining shade,
am like the locust tost:
24My knees through fasting weaken''d are,
my flesh hath fatness lost.

25I also am a vile reproach
unto them made to be;
And they that did upon me look
did shake their heads at me.

26O do thou help and succour me,
who art my God and Lord:
And, for thy tender mercy''s sake,
safety to me afford:

27That thereby they may know that this
is thy almighty hand;
And that thou, Lord, hast done the same,
they may well understand.

28Although they curse with spite, yet, Lord,
bless thou with loving voice:
Let them asham''d be when they rise;
thy servant let rejoice.

29Let thou mine adversaries all
with shame be clothed over;
And let their own confusion
them, as a mantle, cover.

30But as for me, I with my mouth
will greatly praise the Lord;
And I among the multitude
his praises will record.

31For he shall stand at his right hand
who is in poverty,
To save him from all those that would
condemn his soul to die.', '[{"index": 0, "lines": [{"text": "O thou the God of all my praise,", "bibleVerseRef": 1}, {"text": "do thou not hold thy peace;"}, {"text": "For mouths of wicked men to speak", "bibleVerseRef": 2}, {"text": "against me do not cease:"}]}, {"index": 1, "lines": [{"text": "The mouths of vile deceitful men"}, {"text": "against me open''d be;", "syllables": ["a-", "gai-", "nst", "me", "open''d", "be;"]}, {"text": "And with a false and lying tongue", "syllables": ["And", "with", "a", "false", "and", "lying", "ton-", "gue"]}, {"text": "they have accused me."}]}, {"index": 2, "lines": [{"text": "They did beset me round about", "bibleVerseRef": 3}, {"text": "with words of hateful spight:"}, {"text": "And though to them no cause I gave,"}, {"text": "against me they did fight."}]}, {"index": 3, "lines": [{"text": "They for my love became my foes,", "bibleVerseRef": 4}, {"text": "but I me set to pray."}, {"text": "Evil for good, hatred for love,", "bibleVerseRef": 5}, {"text": "to me they did repay."}]}, {"index": 4, "lines": [{"text": "Set thou the wicked over him;", "syllables": ["Set", "tho-", "u", "the", "wic-", "ked", "over", "him;"], "bibleVerseRef": 6}, {"text": "and upon his right hand"}, {"text": "Give thou his greatest enemy,"}, {"text": "ev''n Satan, leave to stand."}]}, {"index": 5, "lines": [{"text": "And when by thee he shall be judg''d,", "bibleVerseRef": 7}, {"text": "let him condemned be;"}, {"text": "And let his pray''r be turn''d to sin,"}, {"text": "when he shall call on thee."}]}, {"index": 6, "lines": [{"text": "Few be his days, and in his room", "bibleVerseRef": 8}, {"text": "his charge another take.", "syllables": ["his", "charge", "a-", "no-", "ther", "take."]}, {"text": "His children let be fatherless,", "bibleVerseRef": 9}, {"text": "his wife a widow make."}]}, {"index": 7, "lines": [{"text": "His children let be vagabonds,", "bibleVerseRef": 10}, {"text": "and beg continually;", "syllables": ["and", "beg", "conti-", "nu-", "a-", "lly;"]}, {"text": "And from their places desolate"}, {"text": "seek bread for their supply."}]}, {"index": 8, "lines": [{"text": "Let covetous extortioners", "syllables": ["Let", "cove-", "-", "tous", "ex-", "tor-", "tio-", "ners"], "bibleVerseRef": 11}, {"text": "catch all he hath away:"}, {"text": "Of all for which he labour''d hath"}, {"text": "let strangers make a prey."}]}, {"index": 9, "lines": [{"text": "Let there be none to pity him,", "syllables": ["Let", "there", "be", "none", "to", "pi-", "ty", "him,"], "bibleVerseRef": 12}, {"text": "let there be none at all", "syllables": ["let", "there", "be", "none", "at", "all"]}, {"text": "That on his children fatherless"}, {"text": "will let his mercy fall."}]}, {"index": 10, "lines": [{"text": "Let his posterity from earth", "bibleVerseRef": 13}, {"text": "cut off for ever be,", "syllables": ["cut", "off", "for", "eve-", "r", "be,"]}, {"text": "And in the foll''wing age their name"}, {"text": "be blotted out by thee."}]}, {"index": 11, "lines": [{"text": "Let God his father''s wickedness", "bibleVerseRef": 14}, {"text": "still to remembrance call;", "syllables": ["still", "to", "remem-", "bran-", "ce", "call;"]}, {"text": "And never let his mother''s sin"}, {"text": "be blotted out at all."}]}, {"index": 12, "lines": [{"text": "But let them all before the Lord", "bibleVerseRef": 15}, {"text": "appear continually,", "syllables": ["appear", "con-", "ti-", "nu-", "a-", "lly,"]}, {"text": "That he may wholly from the earth"}, {"text": "cut off their memory."}]}, {"index": 13, "lines": [{"text": "Because he mercy minded not,", "bibleVerseRef": 16}, {"text": "but persecuted still"}, {"text": "The poor and needy, that he might"}, {"text": "the broken-hearted kill."}]}, {"index": 14, "lines": [{"text": "As he in cursing pleasure took,", "bibleVerseRef": 17}, {"text": "so let it to him fall;"}, {"text": "As he delighted not to bless,"}, {"text": "so bless him not at all."}]}, {"index": 15, "lines": [{"text": "As cursing he like clothes put on,", "syllables": ["As", "cursing", "he", "like", "clo-", "thes", "put", "on,"], "bibleVerseRef": 18}, {"text": "into his bowels so,", "syllables": ["in-", "to", "his", "bowe-", "ls", "so,"]}, {"text": "Like water, and into his bones,", "syllables": ["Like", "wate-", "r,", "and", "in-", "to", "his", "bones,"]}, {"text": "like oil, down let it go."}]}, {"index": 16, "lines": [{"text": "Like to the garment let it be", "bibleVerseRef": 19}, {"text": "which doth himself array,"}, {"text": "And for a girdle, wherewith he"}, {"text": "is girt about alway."}]}, {"index": 17, "lines": [{"text": "From God let this be their reward", "bibleVerseRef": 20}, {"text": "that en''mies are to me,"}, {"text": "And their reward that speak against"}, {"text": "my soul maliciously."}]}, {"index": 18, "lines": [{"text": "But do thou, for thine own name''s sake,", "bibleVerseRef": 21}, {"text": "O God the Lord, for me:"}, {"text": "Sith good and sweet thy mercy is,"}, {"text": "from trouble set me free."}]}, {"index": 19, "lines": [{"text": "For I am poor and indigent,", "bibleVerseRef": 22}, {"text": "afflicted sore am I,"}, {"text": "My heart within me also is"}, {"text": "wounded exceedingly."}]}, {"index": 20, "lines": [{"text": "I pass like a declining shade,", "bibleVerseRef": 23}, {"text": "am like the locust tost:"}, {"text": "My knees through fasting weaken''d are,", "syllables": ["My", "knees", "through", "fas-", "ting", "weake-", "n''d", "are,"], "bibleVerseRef": 24}, {"text": "my flesh hath fatness lost."}]}, {"index": 21, "lines": [{"text": "I also am a vile reproach", "syllables": ["I", "also", "am", "a", "vile", "rep-", "ro-", "ach"], "bibleVerseRef": 25}, {"text": "unto them made to be;"}, {"text": "And they that did upon me look"}, {"text": "did shake their heads at me."}]}, {"index": 22, "lines": [{"text": "O do thou help and succour me,", "bibleVerseRef": 26}, {"text": "who art my God and Lord:"}, {"text": "And, for thy tender mercy''s sake,"}, {"text": "safety to me afford:"}]}, {"index": 23, "lines": [{"text": "That thereby they may know that this", "bibleVerseRef": 27}, {"text": "is thy almighty hand;"}, {"text": "And that thou, Lord, hast done the same,"}, {"text": "they may well understand."}]}, {"index": 24, "lines": [{"text": "Although they curse with spite, yet, Lord,", "syllables": ["although", "they", "curse", "with", "spi-", "te,", "yet,", "Lord,"], "bibleVerseRef": 28}, {"text": "bless thou with loving voice:"}, {"text": "Let them asham''d be when they rise;"}, {"text": "thy servant let rejoice."}]}, {"index": 25, "lines": [{"text": "Let thou mine adversaries all", "bibleVerseRef": 29}, {"text": "with shame be clothed over;"}, {"text": "And let their own confusion", "syllables": ["And", "let", "thei-", "r", "own", "con-", "fu-", "sion"]}, {"text": "them, as a mantle, cover."}]}, {"index": 26, "lines": [{"text": "But as for me, I with my mouth", "bibleVerseRef": 30}, {"text": "will greatly praise the Lord;"}, {"text": "And I among the multitude"}, {"text": "his praises will record.", "syllables": ["his", "praise-", "s", "will", "re-", "cord."]}]}, {"index": 27, "lines": [{"text": "For he shall stand at his right hand", "bibleVerseRef": 31}, {"text": "who is in poverty,", "syllables": ["who", "is", "in", "pove-", "r-", "ty,"]}, {"text": "To save him from all those that would"}, {"text": "condemn his soul to die."}]}]', 'CM', NULL, 'O thou the God of all my praise...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (62, 'recLXdSjpoyC34dHy', 69, '69', '1Save me, O God, because the floods
do so environ me,
That ev''n unto my very soul
come in the waters be.

2I downward in deep mire do sink,
where standing there is none:
I am into deep waters come,
where floods have o''er me gone.

3I weary with my crying am,
my throat is also dry''d;
Mine eyes do fail, while for my God
I waiting do abide.

4Those men that do without a cause
bear hatred unto me,
Than are the hairs upon my head
in number more they be:

They that would me destroy, and are
mine en''mies wrongfully,
Are mighty: so what I took not,
to render forc''d was I.

5Lord, thou my folly know''st, my sins
not cover''d are from thee.
6Let none that wait on thee be sham''d,
Lord God of hosts, for me.

O Lord, the God of Israel,
let none, who search do make,
And seek thee, be at any time
confounded for my sake.

7For I have borne reproach for thee,
my face is hid with shame.
8To brethren strange, to mother''s sons
an alien I became.

9Because the zeal did eat me up,
which to thine house I bear;
And the reproaches cast at thee,
upon me fallen are.

10My tears and fasts, t'' afflict my soul,
were turned to my shame.
11When sackcloth I did wear, to them
a proverb I became.

12The men that in the gate do sit
against me evil spake;
They also that vile drunkards were
of me their song did make.

13But, in an acceptable time,
my pray''r, Lord, is to thee:
In truth of thy salvation, Lord,
and mercy great, hear me.

14Deliver me out of the mire,
from sinking do me keep;
Free me from those that do me hate,
and from the waters deep.

15Let not the flood on me prevail,
whose water overflows;
Nor deep me swallow, nor the pit
her mouth upon me close.

16Hear me, O Lord, because thy love
and kindness is most good;
Turn unto me, according to
thy mercies'' multitude.

17Nor from thy servant hide thy face:
I''m troubled, soon attend.
18Draw near my soul, and it redeem;
me from my foes defend.

19To thee is my reproach well known,
my shame, and my disgrace:
Those that mine adversaries be
are all before thy face.

20Reproach hath broke my heart; I''m full
of grief: I look''d for one
To pity me, but none I found;
comforters found I none.

21They also bitter gall did give
unto me for my meat:
They gave me vinegar to drink,
when as my thirst was great.

22Before them let their table prove
a snare; and do thou make
Their welfare and prosperity
a trap themselves to take.

23Let thou their eyes so darken''d be,
that sight may them forsake;
And let their loins be made by thee
continually to shake.

24Thy fury pour thou out on them,
and indignation;
And let thy wrathful anger, Lord,
fast hold take them upon.

25All waste and desolate let be
their habitation;
And in their tabernacles all
inhabitants be none.

26Because him they do persecute,
whom thou didst smite before;
They talk unto the grief of those
whom thou hast wounded sore.

27Add thou iniquity unto
their former wickedness;
And do not let them come at all
into thy righteousness.

28Out of the book of life let them
be raz''d and blotted quite;
Among the just and righteous
let not their names be writ.

29But now become exceeding poor
and sorrowful am I:
By thy salvation, O my God,
let me be set on high.

30The name of God I with a song
most cheerfully will praise;
And I, in giving thanks to him,
his name shall highly raise.

31This to the Lord a sacrifice
more gracious shall prove
Than bullock, ox, or any beast
that hath both horn and hoof.

32When this the humble men shall see,
it joy to them shall give:
O all ye that do seek the Lord,
your hearts shall ever live.

33For God the poor hears, and will not
his prisoners contemn.
34Let heav''n, and earth, and seas, him praise,
and all that move in them.

35For God will Judah''s cities build,
and he will Sion save,
That they may dwell therein,
and it in sure possession have.

36And they that are his servants'' seed
inherit shall the same;
So shall they have their dwelling there
that love his blessed name.', '[{"index": 0, "lines": [{"text": "Save me, O God, because the floods", "bibleVerseRef": 1}, {"text": "do so environ me,"}, {"text": "That ev''n unto my very soul"}, {"text": "come in the waters be.", "syllables": ["come", "in", "the", "wate-", "rs", "be."]}]}, {"index": 1, "lines": [{"text": "I downward in deep mire do sink,", "bibleVerseRef": 2}, {"text": "where standing there is none:", "syllables": ["where", "standing", "there", "is", "no-", "ne:"]}, {"text": "I am into deep waters come,", "syllables": ["I", "am", "in-", "to", "deep", "wate-", "rs", "come,"]}, {"text": "where floods have o''er me gone."}]}, {"index": 2, "lines": [{"text": "I weary with my crying am,", "syllables": ["I", "wea-", "ry", "with", "my", "cryi-", "ng", "am,"], "bibleVerseRef": 3}, {"text": "my throat is also dry''d;", "syllables": ["my", "throat", "is", "al-", "so", "dry''d;"]}, {"text": "Mine eyes do fail, while for my God"}, {"text": "I waiting do abide."}]}, {"index": 3, "lines": [{"text": "Those men that do without a cause", "bibleVerseRef": 4}, {"text": "bear hatred unto me,"}, {"text": "Than are the hairs upon my head"}, {"text": "in number more they be:"}]}, {"index": 4, "lines": [{"text": "They that would me destroy, and are"}, {"text": "mine en''mies wrongfully,"}, {"text": "Are mighty: so what I took not,"}, {"text": "to render forc''d was I."}]}, {"index": 5, "lines": [{"text": "Lord, thou my folly know''st, my sins", "bibleVerseRef": 5}, {"text": "not cover''d are from thee.", "syllables": ["not", "cove-", "r''d", "are", "from", "thee."]}, {"text": "Let none that wait on thee be sham''d,", "syllables": ["Let", "none", "that", "wait", "on", "thee", "be", "sham''d,"], "bibleVerseRef": 6}, {"text": "Lord God of hosts, for me."}]}, {"index": 6, "lines": [{"text": "O Lord, the God of Israel,", "syllables": ["O", "Lo-", "rd,", "the", "God", "of", "is-", "rael,"]}, {"text": "let none, who search do make,", "syllables": ["let", "none,", "who", "search", "do", "make,"]}, {"text": "And seek thee, be at any time"}, {"text": "confounded for my sake."}]}, {"index": 7, "lines": [{"text": "For I have borne reproach for thee,", "syllables": ["For", "I", "have", "borne", "repro-", "ach", "for", "thee,"], "bibleVerseRef": 7}, {"text": "my face is hid with shame."}, {"text": "To brethren strange, to mother''s sons", "syllables": ["To", "brethren", "stran-", "ge,", "to", "mo-", "ther''s", "sons"], "bibleVerseRef": 8}, {"text": "an alien I became."}]}, {"index": 8, "lines": [{"text": "Because the zeal did eat me up,", "bibleVerseRef": 9}, {"text": "which to thine house I bear;"}, {"text": "And the reproaches cast at thee,", "syllables": ["And", "the", "repro-", "a-", "ches", "cast", "at", "thee,"]}, {"text": "upon me fallen are."}]}, {"index": 9, "lines": [{"text": "My tears and fasts, t'' afflict my soul,", "syllables": ["My", "tears", "and", "fasts,", "t''", "afflict", "my", "soul,"], "bibleVerseRef": 10}, {"text": "were turned to my shame."}, {"text": "When sackcloth I did wear, to them", "bibleVerseRef": 11}, {"text": "a proverb I became."}]}, {"index": 10, "lines": [{"text": "The men that in the gate do sit", "bibleVerseRef": 12}, {"text": "against me evil spake;", "syllables": ["against", "me", "e-", "vil", "spa-", "ke;"]}, {"text": "They also that vile drunkards were"}, {"text": "of me their song did make."}]}, {"index": 11, "lines": [{"text": "But, in an acceptable time,", "bibleVerseRef": 13}, {"text": "my pray''r, Lord, is to thee:"}, {"text": "In truth of thy salvation, Lord,"}, {"text": "and mercy great, hear me."}]}, {"index": 12, "lines": [{"text": "Deliver me out of the mire,", "syllables": ["de-", "live-", "r", "me", "out", "of", "the", "mire,"], "bibleVerseRef": 14}, {"text": "from sinking do me keep;"}, {"text": "Free me from those that do me hate,"}, {"text": "and from the waters deep.", "syllables": ["and", "from", "the", "wate-", "rs", "deep."]}]}, {"index": 13, "lines": [{"text": "Let not the flood on me prevail,", "bibleVerseRef": 15}, {"text": "whose water overflows;", "syllables": ["who-", "se", "water", "over-", "flo-", "ws;"]}, {"text": "Nor deep me swallow, nor the pit"}, {"text": "her mouth upon me close.", "syllables": ["her", "mouth", "upon", "me", "clo-", "se."]}]}, {"index": 14, "lines": [{"text": "Hear me, O Lord, because thy love", "bibleVerseRef": 16}, {"text": "and kindness is most good;"}, {"text": "Turn unto me, according to"}, {"text": "thy mercies'' multitude."}]}, {"index": 15, "lines": [{"text": "Nor from thy servant hide thy face:", "bibleVerseRef": 17}, {"text": "I''m troubled, soon attend."}, {"text": "Draw near my soul, and it redeem;", "bibleVerseRef": 18}, {"text": "me from my foes defend."}]}, {"index": 16, "lines": [{"text": "To thee is my reproach well known,", "syllables": ["To", "thee", "is", "my", "repro-", "ach", "well", "known,"], "bibleVerseRef": 19}, {"text": "my shame, and my disgrace:", "syllables": ["my", "shame,", "and", "my", "disgra-", "ce:"]}, {"text": "Those that mine adversaries be"}, {"text": "are all before thy face."}]}, {"index": 17, "lines": [{"text": "Reproach hath broke my heart; I''m full", "syllables": ["reproach", "hath", "bro-", "ke", "my", "heart;", "I''m", "full"], "bibleVerseRef": 20}, {"text": "of grief: I look''d for one"}, {"text": "To pity me, but none I found;", "syllables": ["To", "pity", "me,", "but", "no-", "ne", "I", "found;"]}, {"text": "comforters found I none.", "syllables": ["comfor-", "ters", "found", "I", "no-", "ne."]}]}, {"index": 18, "lines": [{"text": "They also bitter gall did give", "bibleVerseRef": 21}, {"text": "unto me for my meat:"}, {"text": "They gave me vinegar to drink,", "syllables": ["They", "gave", "me", "vine-", "gar", "to", "dri-", "nk,"]}, {"text": "when as my thirst was great."}]}, {"index": 19, "lines": [{"text": "Before them let their table prove", "syllables": ["before", "them", "let", "their", "tab-", "le", "pro-", "ve"], "bibleVerseRef": 22}, {"text": "a snare; and do thou make", "syllables": ["a", "snare;", "and", "do", "thou", "make"]}, {"text": "Their welfare and prosperity"}, {"text": "a trap themselves to take.", "syllables": ["a", "trap", "themsel-", "ves", "to", "take."]}]}, {"index": 20, "lines": [{"text": "Let thou their eyes so darken''d be,", "bibleVerseRef": 23}, {"text": "that sight may them forsake;"}, {"text": "And let their loins be made by thee"}, {"text": "continually to shake.", "syllables": ["conti-", "nu-", "a-", "lly", "to", "shake."]}]}, {"index": 21, "lines": [{"text": "Thy fury pour thou out on them,", "bibleVerseRef": 24}, {"text": "and indignation;", "syllables": ["and", "in-", "dig-", "na-", "tio-", "n;"]}, {"text": "And let thy wrathful anger, Lord,"}, {"text": "fast hold take them upon."}]}, {"index": 22, "lines": [{"text": "All waste and desolate let be", "syllables": ["All", "waste", "and", "de-", "so-", "late", "let", "be"], "bibleVerseRef": 25}, {"text": "their habitation;", "syllables": ["thei-", "r", "ha-", "bi-", "ta-", "tion;"]}, {"text": "And in their tabernacles all", "syllables": ["And", "in", "their", "tabe-", "r-", "nac-", "les", "all"]}, {"text": "inhabitants be none.", "syllables": ["inha-", "bi-", "tants", "be", "no-", "ne."]}]}, {"index": 23, "lines": [{"text": "Because him they do persecute,", "bibleVerseRef": 26}, {"text": "whom thou didst smite before;", "syllables": ["whom", "thou", "didst", "smite", "be-", "fore;"]}, {"text": "They talk unto the grief of those"}, {"text": "whom thou hast wounded sore."}]}, {"index": 24, "lines": [{"text": "Add thou iniquity unto", "bibleVerseRef": 27}, {"text": "their former wickedness;"}, {"text": "And do not let them come at all"}, {"text": "into thy righteousness."}]}, {"index": 25, "lines": [{"text": "Out of the book of life let them", "bibleVerseRef": 28}, {"text": "be raz''d and blotted quite;", "syllables": ["be", "raz''d", "and", "blotted", "qui-", "te;"]}, {"text": "Among the just and righteous", "syllables": ["a-", "mong", "the", "just", "and", "ri-", "gh-", "teous"]}, {"text": "let not their names be writ."}]}, {"index": 26, "lines": [{"text": "But now become exceeding poor", "bibleVerseRef": 29}, {"text": "and sorrowful am I:"}, {"text": "By thy salvation, O my God,"}, {"text": "let me be set on high."}]}, {"index": 27, "lines": [{"text": "The name of God I with a song", "bibleVerseRef": 30}, {"text": "most cheerfully will praise;"}, {"text": "And I, in giving thanks to him,"}, {"text": "his name shall highly raise."}]}, {"index": 28, "lines": [{"text": "This to the Lord a sacrifice", "bibleVerseRef": 31}, {"text": "more gracious shall prove"}, {"text": "Than bullock, ox, or any beast"}, {"text": "that hath both horn and hoof."}]}, {"index": 29, "lines": [{"text": "When this the humble men shall see,", "bibleVerseRef": 32}, {"text": "it joy to them shall give:"}, {"text": "O all ye that do seek the Lord,"}, {"text": "your hearts shall ever live.", "syllables": ["your", "hea-", "rts", "shall", "ever", "live."]}]}, {"index": 30, "lines": [{"text": "For God the poor hears, and will not", "bibleVerseRef": 33}, {"text": "his prisoners contemn."}, {"text": "Let heav''n, and earth, and seas, him praise,", "bibleVerseRef": 34}, {"text": "and all that move in them."}]}, {"index": 31, "lines": [{"text": "For God will Judah''s cities build,", "syllables": ["For", "God", "will", "judah''s", "ci-", "ties", "bu-", "ild,"], "bibleVerseRef": 35}, {"text": "and he will Sion save,", "syllables": ["and", "he", "will", "Sion", "save-", ","]}, {"text": "That they may dwell therein,", "syllables": ["That", "they", "may", "dwell", "therei-", "-", "-", "n,"]}, {"text": "and it in sure possession have.", "syllables": ["and", "it", "in", "sure", "possession", "have."]}]}, {"index": 32, "lines": [{"text": "And they that are his servants'' seed", "bibleVerseRef": 36}, {"text": "inherit shall the same;"}, {"text": "So shall they have their dwelling there"}, {"text": "that love his blessed name."}]}]', 'CM', NULL, 'Save 