INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (60, 'recL2h1kfnKP26Qhl', 111, '111', '1Praise ye the Lord: with my whole heart
I will God''s praise declare,
Where the assemblies of the just
and congregations are.

2The whole works of the Lord our God
are great above all measure,
Sought out they are of ev''ry one
that doth therein take pleasure.

3His work most honourable is,
most glorious and pure,
And his untainted righteousness
for ever doth endure.

4His works most wonderful he hath
made to be thought upon:
The Lord is gracious,
and he is full of compassion.

5He giveth meat unto all those
that truly do him fear;
And evermore his covenant
he in his mind will bear.

6He did the power of his works
unto his people show,
When he the heathen''s heritage
upon them did bestow.

7His handy-works are truth and right;
all his commands are sure:
8And, done in truth and uprightness,
they evermore endure.

9He sent redemption to his folk;
his covenant for aye
He did command: holy his name
and rev''rend is alway.

10Wisdom''s beginning is God''s fear:
good understanding they
Have all that his commands fulfill:
his praise endures for aye.', '[{"index": 0, "lines": [{"text": "Praise ye the Lord: with my whole heart", "bibleVerseRef": 1}, {"text": "I will God''s praise declare,"}, {"text": "Where the assemblies of the just"}, {"text": "and congregations are."}]}, {"index": 1, "lines": [{"text": "The whole works of the Lord our God", "bibleVerseRef": 2}, {"text": "are great above all measure,", "syllables": ["are", "great", "above", "all", "mea-", "sure,"]}, {"text": "Sought out they are of ev''ry one"}, {"text": "that doth therein take pleasure."}]}, {"index": 2, "lines": [{"text": "His work most honourable is,", "bibleVerseRef": 3}, {"text": "most glorious and pure,", "syllables": ["most", "glo-", "riou-", "s", "and", "pure,"]}, {"text": "And his untainted righteousness"}, {"text": "for ever doth endure.", "syllables": ["for", "ever", "doth", "en-", "dure-", "."]}]}, {"index": 3, "lines": [{"text": "His works most wonderful he hath", "bibleVerseRef": 4}, {"text": "made to be thought upon:"}, {"text": "The Lord is gracious,", "syllables": ["The", "Lord", "is", "gra-", "ciou-", "-", "-", "s,"]}, {"text": "and he is full of compassion.", "syllables": ["and", "he", "is", "full", "of", "compassion."]}]}, {"index": 4, "lines": [{"text": "He giveth meat unto all those", "bibleVerseRef": 5}, {"text": "that truly do him fear;"}, {"text": "And evermore his covenant", "syllables": ["And", "eve-", "r-", "more", "his", "cove-", "-", "nant"]}, {"text": "he in his mind will bear."}]}, {"index": 5, "lines": [{"text": "He did the power of his works", "syllables": ["He", "did", "the", "powe-", "r", "of", "his", "works"], "bibleVerseRef": 6}, {"text": "unto his people show,", "syllables": ["unto", "his", "pe-", "o-", "ple", "show,"]}, {"text": "When he the heathen''s heritage"}, {"text": "upon them did bestow."}]}, {"index": 6, "lines": [{"text": "His handy-works are truth and right;", "bibleVerseRef": 7}, {"text": "all his commands are sure:"}, {"text": "And, done in truth and uprightness,", "bibleVerseRef": 8}, {"text": "they evermore endure.", "syllables": ["they", "eve-", "r-", "more", "en-", "dure."]}]}, {"index": 7, "lines": [{"text": "He sent redemption to his folk;", "bibleVerseRef": 9}, {"text": "his covenant for aye", "syllables": ["his", "cove-", "-", "nant", "for", "aye"]}, {"text": "He did command: holy his name"}, {"text": "and rev''rend is alway."}]}, {"index": 8, "lines": [{"text": "Wisdom''s beginning is God''s fear:", "bibleVerseRef": 10}, {"text": "good understanding they"}, {"text": "Have all that his commands fulfill:"}, {"text": "his praise endures for aye."}]}]', 'CM', NULL, 'Praise ye the Lord: with my whole heart...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (66, 'recO1HxZXpm4wvamv', 72, '72', '1O Lord, thy judgments give the king,
his son thy righteousness.
2With right he shall thy people judge,
thy poor with uprightness.

3The lofty mountains shall bring forth
unto the people peace;
Likewise the little hills the same
shall do by righteousness.

4The people''s poor ones he shall judge,
the needy''s children save;
And those shall he in pieces break
who them oppressed have.

5They shall thee fear, while sun and moon
do last, through ages all.
6Like rain on mown grass he shall drop,
or show''rs on earth that fall.

7The just shall flourish in his days,
and prosper in his reign:
He shall, while doth the moon endure,
abundant peace maintain.

8His large and great dominion shall
from sea to sea extend:
It from the river shall reach forth
unto earth''s utmost end.

9They in the wilderness that dwell
bow down before him must;
And they that are his enemies
shall lick the very dust.

10The kings of Tarshish, and the isles,
to him shall presents bring;
And unto him shall offer gifts
Sheba''s and Seba''s king.

11Yea, all the mighty kings on earth
before him down shall fall;
And all the nations of the world
do service to him shall.

12For he the needy shall preserve,
when he to him doth call;
The poor also, and him that hath
no help of man at all.

13The poor man and the indigent
in mercy he shall spare;
He shall preserve alive the souls
of those that needy are.

14Both from deceit and violence
their soul he shall set free;
And in his sight right precious
and dear their blood shall be.

15Yea, he shall live, and giv''n to him
shall be of Sheba''s gold:
For him still shall they pray, and he
shall daily be extoll''d.

16Of corn an handful in the earth
on tops of mountains high,
With prosp''rous fruit shall shake, like trees
on Lebanon that be.

The city shall be flourishing,
her citizens abound
In number shall, like to the grass
that grows upon the ground.

17His name for ever shall endure;
last like the sun it shall:
Men shall be bless''d in him,
and bless''d all nations shall him call.

18Now blessed be the Lord our God,
the God of Israel,
For he alone doth wondrous works,
in glory that excel.

19And blessed be his glorious name
to all eternity:
The whole earth let his glory fill.
Amen, so let it be.

#The prayers of David the son of Jesse are ended.', NULL, 'CM', NULL, 'O Lord, thy judgments give the king...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (53, 'recGuEG193K5Tc4Jn', 62, '62', '1My soul with expectation
depends on God indeed;
My strength and my salvation doth
from him alone proceed.

2He only my salvation is,
and my strong rock is he:
He only is my sure defence;
much mov''d I shall not be.

3How long will ye against a man
plot mischief? ye shall all
Be slain; ye as a tott''ring fence shall be,
and bowing wall.

4They only plot to cast him down
from his excellency:
They joy in lies; with mouth they bless,
but they curse inwardly.

5My soul, wait thou with patience
upon thy God alone;
On him dependeth all my hope
and expectation.

6He only my salvation is,
and my strong rock is he;
He only is my sure defence:
I shall not moved be.

7In God my glory placed is,
and my salvation sure;
In God the rock is of my strength,
my refuge most secure.

8Ye people, place your confidence
in him continually;
Before him pour ye out your heart:
God is our refuge high.

9Surely mean men are vanity,
and great men are a lie;
In balance laid, they wholly are
more light than vanity.

10Trust ye not in oppression,
in robb''ry be not vain;
On wealth set not your hearts, when as
increased is your gain.

11God hath it spoken once to me,
yea, this I heard again,
That power to Almighty God
alone doth appertain.

12Yea, mercy also unto thee
belongs, O Lord, alone:
For thou according to his work
rewardest ev''ry one.', '[{"index": 0, "lines": [{"text": "My soul with expectation", "syllables": ["My", "sou-", "l", "with", "ex-", "pec-", "ta-", "tion"], "bibleVerseRef": 1}, {"text": "depends on God indeed;"}, {"text": "My strength and my salvation doth"}, {"text": "from him alone proceed."}]}, {"index": 1, "lines": [{"text": "He only my salvation is,", "bibleVerseRef": 2}, {"text": "and my strong rock is he:"}, {"text": "He only is my sure defence;"}, {"text": "much mov''d I shall not be."}]}, {"index": 2, "lines": [{"text": "How long will ye against a man", "bibleVerseRef": 3}, {"text": "plot mischief? ye shall all"}, {"text": "Be slain; ye as a tott''ring fence shall be,", "syllables": ["Be", "slain;", "ye", "as", "a", "tott''ring", "fence", "shallbe,"]}, {"text": "and bowing wall.", "syllables": ["and", "bo-", "wi-", "ng", "wa-", "ll."]}]}, {"index": 3, "lines": [{"text": "They only plot to cast him down", "bibleVerseRef": 4}, {"text": "from his excellency:"}, {"text": "They joy in lies; with mouth they bless,"}, {"text": "but they curse inwardly.", "syllables": ["but", "they", "curse", "in-", "war-", "dly."]}]}, {"index": 4, "lines": [{"text": "My soul, wait thou with patience", "bibleVerseRef": 5}, {"text": "upon thy God alone;"}, {"text": "On him dependeth all my hope"}, {"text": "and expectation.", "syllables": ["and", "ex-", "pec-", "ta-", "tio-", "n."]}]}, {"index": 5, "lines": [{"text": "He only my salvation is,", "bibleVerseRef": 6}, {"text": "and my strong rock is he;"}, {"text": "He only is my sure defence:"}, {"text": "I shall not moved be."}]}, {"index": 6, "lines": [{"text": "In God my glory placed is,", "bibleVerseRef": 7}, {"text": "and my salvation sure;"}, {"text": "In God the rock is of my strength,"}, {"text": "my refuge most secure."}]}, {"index": 7, "lines": [{"text": "Ye people, place your confidence", "syllables": ["Ye", "people,", "place", "your", "con-", "fi-", "den-", "ce"], "bibleVerseRef": 8}, {"text": "in him continually;", "syl