INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (69, 'recPuiosBkZoLXIUL', 115, '115', '1Not unto us, Lord, not to us,
but do thou glory take
Unto thy name, ev''n for thy truth,
and for thy mercy''s sake.

2O wherefore should the heathen say,
Where is their God now gone?
3But our God in the heavens is,
what pleas''d him he hath done.

4Their idols silver are and gold,
work of men''s hands they be.
5Mouths have they, but they do not speak;
and eyes, but do not see;

6Ears have they, but they do not hear;
noses, but savour not;
7Hands, feet, but handle not, nor walk;
nor speak they through their throat.

8Like them their makers are, and all
on them their trust that build.
9O Isr''el, trust thou in the Lord,
he is their help and shield.

10O Aaron''s house, trust in the Lord,
their help and shield is he.
11Ye that fear God, trust in the Lord,
their help and shield he''ll be.

12The Lord of us hath mindful been,
and he will bless us still:
He will the house of Isr''el bless,
bless Aaron''s house he will.

13Both small and great, that fear the Lord,
he will them surely bless.
14The Lord will you, you and your seed,
aye more and more increase.

15O blessed are ye of the Lord,
who made the earth and heav''n.
16The heav''n, ev''n heav''ns, are God''s, but he
earth to men''s sons hath giv''n.

17The dead, nor who to silence go,
God''s praise do not record.
18But henceforth we for ever will
bless God. Praise ye the Lord.', '[{"index": 0, "lines": [{"text": "Not unto us, Lord, not to us,", "bibleVerseRef": 1}, {"text": "but do thou glory take"}, {"text": "Unto thy name, ev''n for thy truth,"}, {"text": "and for thy mercy''s sake."}]}, {"index": 1, "lines": [{"text": "O wherefore should the heathen say,", "bibleVerseRef": 2}, {"text": "Where is their God now gone?"}, {"text": "But our God in the heavens is,", "syllables": ["But", "our", "God", "in", "the", "heave-", "ns", "is,"], "bibleVerseRef": 3}, {"text": "what pleas''d him he hath done."}]}, {"index": 2, "lines": [{"text": "Their idols silver are and gold,", "bibleVerseRef": 4}, {"text": "work of men''s hands they be."}, {"text": "Mouths have they, but they do not speak;", "bibleVerseRef": 5}, {"text": "and eyes, but do not see;"}]}, {"index": 3, "lines": [{"text": "Ears have they, but they do not hear;", "bibleVerseRef": 6}, {"text": "noses, but savour not;", "syllables": ["nose-", "s,", "but", "sa-", "vour", "not;"]}, {"text": "Hands, feet, but handle not, nor walk;", "bibleVerseRef": 7}, {"text": "nor speak they through their throat.", "syllables": ["nor", "speak", "they", "through", "their", "throat."]}]}, {"index": 4, "lines": [{"text": "Like them their makers are, and all", "syllables": ["Like", "them", "their", "make-", "rs", "are,", "and", "all"], "bibleVerseRef": 8}, {"text": "on them their trust that build.", "syllables": ["on", "them", "their", "trust", "that", "build."]}, {"text": "O Isr''el, trust thou in the Lord,", "bibleVerseRef": 9}, {"text": "he is their help and shield."}]}, {"index": 5, "lines": [{"text": "O Aaron''s house, trust in the Lord,", "bibleVerseRef": 10}, {"text": "their help and shield is he."}, {"text": "Ye that fear God, trust in the Lord,", "bibleVerseRef": 11}, {"text": "their help and shield he''ll be."}]}, {"index": 6, "lines": [{"text": "The Lord of us hath mindful been,", "bibleVerseRef": 12}, {"text": "and he will bless us still:"}, {"text": "He will the house of Isr''el bless,"}, {"text": "bless Aaron''s house he will."}]}, {"index": 7, "lines": [{"text": "Both small and great, that fear the Lord,", "bibleVerseRef": 13}, {"text": "he will them surely bless."}, {"text": "The Lord will you, you and your seed,", "bibleVerseRef": 14}, {"text": "aye more and more increase.", "syllables": ["aye", "more", "and", "more", "increa-", "se."]}]}, {"index": 8, "lines": [{"text": "O blessed are ye of the Lord,", "bibleVerseRef": 15}, {"text": "who made the earth and heav''n."}, {"text": "The heav''n, ev''n heav''ns, are God''s, but he", "bibleVerseRef": 16}, {"text": "earth to men''s sons hath giv''n."}]}, {"index": 9, "lines": [{"text": "The dead, nor who to silence go,", "bibleVerseRef": 17}, {"text": "God''s praise do not record."}, {"text": "But henceforth we for ever will", "bibleVerseRef": 18}, {"text": "bless God. Praise ye the Lord."}]}]', 'CM', NULL, 'Not unto us, Lord, not to us...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (74, 'recSgPEEcjFNEHeBh', 44, '44', '1O God, we with our ears have heard,
our fathers have us told,
What works thou in their days hadst done,
ev''n in the days of old.

2Thy hand did drive the heathen out,
and plant them in their place;
Thou didst afflict the nations,
but them thou didst increase.

3For neither got their sword the land,
nor did their arm them save;
But thy right hand, arm, countenance;
for thou them favour gave.

4Thou art my King: for Jacob, Lord,
deliv''rances command.
5Through thee we shall push down our foes,
that do against us stand:

We, through thy name, shall tread down those
that ris''n against us have.
6For in my bow I shall not trust,
nor shall my sword me save.

7But from our foes thou hast us sav''d,
our haters put to shame.
8In God we all the day do boast,
and ever praise thy name.

9But now we are cast off by thee,
and us thou putt''st to shame;
And when our armies do go forth,
thou go''st not with the same.

10Thou mak''st us from the enemy,
faint-hearted, to turn back;
And they who hate us for themselves
our spoils away do take.

11Like sheep for meat thou gavest us;
''mong heathen cast we be.
12Thou didst for nought thy people sell;
their price enrich''d not thee.

13Thou mak''st us a reproach to be
unto our neighbours near;
Derision and a scorn to them
that round about us are.

14A by-word also thou dost us
among the heathen make;
The people, in contempt and spite,
at us their heads do shake.

15Before me my confusion
continually abides;
And of my bashful countenance
the shame me ever hides:

16For voice of him that doth reproach,
and speaketh blasphemy;
By reason of th'' avenging foe,
and cruel enemy.

17All this is come on us, yet we
have not forgotten thee;
Nor falsely in thy covenant
behav''d ourselves have we.

18Back from thy way our heart not turn''d;
our steps no straying made;
19Though us thou brak''st in dragons'' place,
and cover''dst with death''s shade.

20If we God''s name forgot, or stretch''d
to a strange god our hands,
21Shall not God search this out? for he
heart''s secrets understands.

22Yea, for thy sake we''re kill''d all day,
counted as slaughter-sheep.
23Rise, Lord, cast us not ever off;
awake, why dost thou sleep?

24O wherefore hidest thou thy face?
forgett''st our cause distress''d,
25And our oppression? For our soul
is to the dust down press''d:

Our belly also on the earth
fast cleaving, hold doth take.
26Rise for our help, and us redeem,
ev''n for thy mercies'' sake.', '[{"index": 0, "lines": [{"text": "O God, we with our ears have heard,", "bibleVerseRef": 1}, {"text": "our fathers have us told,"}, {"text": "What works thou in their days hadst done,"}, {"text": "ev''n in the days of old."}]}, {"index": 1, "lines": [{"text": "Thy hand did drive the heathen out,", "syllables": ["Thy", "hand", "did", "drive", "the", "hea-", "then", "out,"], "bibleVerseRef": 2}, {"text": "and plant them in their place;", "syllables": ["and", "plant", "them", "in", "their", "place;"]}, {"text": "Thou didst afflict the nations,", "syllables": ["Thou", "didst", "af-", "flict", "the", "na-", "tio-", "ns,"]}, {"text": "but them thou didst increase.", "syllables": ["but", "them", "thou", "didst", "increa-", "se."]}]}, {"index": 2, "lines": [{"text": "For neither got their sword the land,", "bibleVerseRef": 3}, {"text": "nor did their arm them save;"}, {"text": "But thy right hand, arm, countenance;", "syllables": ["But", "thy", "right", "hand,", "arm,", "counte-", "nan-", "ce;"]}, {"text": "for thou them favour gave."}]}, {"index": 3, "lines": [{"text": "Thou art my King: for Jacob, Lord,", "bibleVerseRef": 4}, {"text": "deliv''rances command."}, {"text": "Through thee we shall push down our foes,", "bibleVerseRef": 5}, {"text": "that do against us stand:"}]}, {"index": 4, "lines": [{"text": "We, through thy name, shall tread down those"}, {"text": "that ris''n against us have."}, {"text": "For in my bow I shall not trust,", "bibleVerseRef": 6}, {"text": "nor shall my sword me save."}]}, {"index": 5, "lines": [{"text": "But from our foes thou hast us sav''d,", "bibleVerseRef": 7}, {"text": "our haters put to shame.", "syllables": ["our", "hate-", "rs", "put", "to", "shame."]}, {"text": "In God we all the day do boast,", "syllables": ["In", "God", "we", "all", "the", "day", "do", "boast,"], "bibleVerseRef": 8}, {"text": "and ever praise thy name.", "syllables": ["and", "ever", "prai-", "se", "thy", "name."]}]}, {"index": 6, "lines": [{"text": "But now we are cast off by thee,", "bibleVerseRef": 9}, {"text": "and us thou putt''st to shame;"}, {"text": "And when our armies do go forth,"}, {"text": "thou go''st not with the same."}]}, {"index": 7, "lines": [{"text": "Thou mak''st us from the enemy,", "bibleVerseRef": 10}, {"text": "faint-hearted, to turn back;"}, {"text": "And they who hate us for themselves", "syllables": ["And", "they", "who", "hate", "us", "for", "themsel-", "ves"]}, {"text": "our spoils away do take."}]}, {"index": 8, "lines": [{"text": "Like sheep for meat thou gavest us;", "syllables": ["Like", "sheep", "for", "meat", "thou", "gave-", "st", "us;"], "bibleVerseRef": 11}, {"text": "''mong heathen cast we be."}, {"text": "Thou didst for nought thy people sell;", "syllables": ["Thou", "didst", "for", "nought", "thy", "peo-", "ple", "sell;"], "bibleVerseRef": 12}, {"text": "their price enrich''d not thee.", "syllables": ["their", "price", "en-", "rich''d", "not", "thee."]}]}, {"index": 9, "lines": [{"text": "Thou mak''st us a reproach to be", "syllables": ["Thou", "mak''st", "us", "a", "repro-", "ach", "to", "be"], "bibleVerseRef": 13}, {"text": "unto our neighbours near;"}, {"text": "Derision and a scorn to them"}, {"text": "that round about us are."}]}, {"index": 10, "lines": [{"text": "A by-word also thou dost us", "bibleVerseRef": 14}, {"text": "among the heathen make;"}, {"text": "The people, in contempt and spite,", "syllables": ["The", "people,", "in", "con-", "tempt", "and", "spi-", "te,"]}, {"text": "at us their heads do shake."}]}, {"index": 11, "lines": [{"text": "Before me my confusion", "syllables": ["be-", "fo-", "re", "me", "my", "con-", "fu-", "sion"], "bibleVerseRef": 15}, {"text": "continually abides;", "syllables": ["conti-", "nu-", "a-", "lly", "a-", "bides;"]}, {"text": "And of my bashful countenance", "syllables": ["And", "of", "my", "bashful", "coun-", "te-", "nan-", "ce"]}, {"text": "the shame me ever hides:", "syllables": ["the", "shame", "me", "ever", "hide-", "s:"]}]}, {"index": 12, "lines": [{"text": "For voice of him that doth reproach,", "syllables": ["For", "voice", "of", "him", "that", "doth", "repro-", "ach,"], "bibleVerseRef": 16}, {"text": "and speaketh blasphemy;"}, {"text": "By reason of th'' avenging foe,"}, {"text": "and cruel enemy.", "syllables": ["and", "crue-", "l", "en-", "e-", "my."]}]}, {"index": 13, "lines": [{"text": "All this is come on us, yet we", "bibleVerseRef": 17}, {"text": "have not forgotten thee;"}, {"text": "Nor falsely in thy covenant"}, {"text": "behav''d ourselves have we.", "syllables": ["behav''d", "our-", "sel-", "ves", "have", "we."]}]}, {"index": 14, "lines": [{"text": "Back from thy way our heart not turn''d;", "bibleVerseRef": 18}, {"text": "our steps no straying made;", "syllables": ["our", "steps", "no", "strayi-", "ng", "made;"]}, {"text": "Though us thou brak''st in dragons'' place,", "syllables": ["Though", "us", "thou", "brak''st", "in", "dragons''", "pla-", "ce,"], "bibleVerseRef": 19}, {"text": "and cover''dst with death''s shade.", "syllables": ["and", "cove-", "r''dst", "with", "death''s", "shade."]}]}, {"index": 15, "lines": [{"text": "If we God''s name forgot, or stretch''d", "bibleVerseRef": 20}, {"text": "to a strange god our hands,", "syllables": ["to", "a", "strange", "god", "our", "hands,"]}, {"text": "Shall not God search this out? for he", "bibleVerseRef": 21}, {"text": "heart''s secrets understands."}]}, {"index": 16, "lines": [{"text": "Yea, for thy sake we''re kill''d all day,", "bibleVerseRef": 22}, {"text": "counted as slaughter-sheep."}, {"text": "Rise, Lord, cast us not ever off;", "syllables": ["Rise-", ",", "Lord,", "cast", "us", "not", "ever", "off;"], "bibleVerseRef": 23}, {"text": "awake, why dost thou sleep?"}]}, {"index": 17, "lines": [{"text": "O wherefore hidest thou thy face?", "syllables": ["O", "where-", "-", "fore", "hidest", "thou", "thy", "face?"], "bibleVerseRef": 24}, {"text": "forgett''st our cause distress''d,"}, {"text": "And our oppression? For our soul", "bibleVerseRef": 25}, {"text": "is to the dust down press''d:"}]}, {"index": 18, "lines": [{"text": "Our belly also on the earth"}, {"text": "fast cleaving, hold doth take."}, {"text": "Rise for our help, and us redeem,", "bibleVerseRef": 26}, {"text": "ev''n for thy mercies'' sake."}]}]', 'CM', NULL, 'O God, we with our ears have heard...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (75, 'recTGeDo2O51dL5IC', 112, '112', '1Praise ye the Lord. The man is bless''d
that fears the Lord aright,
He who in his commandements
doth greatly take delight.

2His seed and offspring powerful
shall be the earth upon:
Of upright men blessed shall be
the generation.

3Riches and wealth shall ever be
within his house in store;
And his unspotted righteousness
endures for evermore.

4Unto the upright light doth rise,
though he in darkness be:
Compassionate, and merciful,
and righteous, is he.

5A good man doth his favour shew,
and doth to others lend:
He with discretion his affairs
will guide unto the end.

6Surely there is not any thing
that ever shall him move:
The righteous man''s memorial
shall everlasting prove.

7When he shall evil tidings hear,
he shall not be afraid:
His heart is fix''d, his confidence
upon the Lord is stay''d.

8His heart is firmly stablished,
afraid he shall not be,
Until upon his enemies
he his desire shall see.

9He hath dispers''d, giv''n to the poor;
his righteousness shall be
To ages all; with honour shall
his horn be raised high.

10The wicked shall it see, and fret,
his teeth gnash, melt away:
What wicked men do most desire
shall utterly decay.', '[{"index": 0, "lines": [{"text": "Praise ye the Lord. The man is bless''d", "bibleVerseRef": 1}, {"text": "that fears the Lord aright,"}, {"text": "He who in his commandements"}, {"text": "doth greatly take delight."}]}, {"index": 1, "lines": [{"text": "His seed and offspring powerful", "syllables": ["His", "seed", "and", "of-", "fspri-", "ng", "power-", "ful"], "bibleVerseRef": 2}, {"text": "shall be the earth upon:"}, {"text": "Of upright men blessed shall be"}, {"text": "the generation.", "syllables": ["the", "ge-", "ne-", "ra-", "tio-", "n."]}]}, {"index": 2, "lines": [{"text": "Riches and wealth shall ever be", "syllables": ["ri-", "ches", "and", "wea-", "lth", "shall", "ever", "be"], "bibleVerseRef": 3}, {"text": "within his house in store;", "syllables": ["within", "his", "house", "in", "sto-", "re;"]}, {"text": "And his unspotted righteousness"}, {"text": "endures for evermore.", "syllables": ["en-", "dure-", "s", "for", "ever-", "more."]}]}, {"index": 3, "lines": [{"text": "Unto the upright light doth rise,", "bibleVerseRef": 4}, {"text": "though he in darkness be:"}, {"text": "Compassionate, and merciful,"}, {"text": "and righteous, is he.", "syllables": ["and", "righ-", "teou-", "s,", "is", "he."]}]}, {"index": 4, "lines": [{"text": "A good man doth his favour shew,", "bibleVerseRef": 5}, {"text": "and doth to others lend:"}, {"text": "He with discretion his affairs"}, {"text": "will guide unto the end.", "syllables": ["will", "guide", "un-", "to", "the", "end."]}]}, {"index": 5, "lines": [{"text": "Surely there is not any thing", "bibleVerseRef": 6}, {"text": "that ever shall him move:", "syllables": ["that", "ever", "sha-", "ll", "him", "move:"]}, {"text": "The righteous man''s memorial"}, {"text": "shall everlasting prove."}]}, {"index": 6, "lines": [{"text": "When he shall evil tidings hear,", "bibleVerseRef": 7}, {"text": "he shall not be afraid:"}, {"text": "His heart is fix''d, his confidence", "syllables": ["His", "heart", "is", "fix''d,", "his", "confi-", "den-", "ce"]}, {"text": "upon the Lord is stay''d."}]}, {"index": 7, "lines": [{"text": "His heart is firmly stablished,", "bibleVerseRef": 8}, {"text": "afraid he shall not be,"}, {"text": "Until upon his enemies"}, {"text": "he his desire shall see."}]}, {"index": 8, "lines": [{"text": "He hath dispers''d, giv''n to the poor;", "bibleVerseRef": 9}, {"text": "his righteousness shall be"}, {"text": "To ages all; with honour shall", "syllables": ["To", "ages", "all;", "with", "ho-", "nour", "sha-", "ll"]}, {"text": "his horn be raised high.", "syllables": ["his", "horn", "be", "raise-", "d", "high."]}]}, {"index": 9, "lines": [{"text": "The wicked shall it see, and fret,", "bibleVerseRef": 10}, {"text": "his teeth gnash, melt away:"}, {"text": "What wicked men do most desire"}, {"text": "shall utterly decay."}]}]', 'CM', NULL, 'Praise ye the Lord. The man is bless''d...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (76, 'recTyNPxRQkrW4Oz0', 145, '145 (Second Version, Recommended)', '1 O Lord, thou art my God and King;
Thee will I magnify and praise:
I will thee bless, and gladly sing
Unto thy holy name always.

2 Each day I rise I will thee bless,
And praise thy name time without end.
3 Much to be praised, and great God is;
His greatness none can comprehend.

4 Race shall thy works praise unto race,
The mighty acts show done by thee.
5 I will speak of the glorious grace,
And honor of thy majesty;

Thy wondrous works I will record.
6 By men the might shall be extolled
Of all thy dreadful acts, O Lord:
And I thy greatness will unfold.

7 They utter shall abundantly
The mem’ry of thy goodness great;
And shall sing praises cheerfully,
Whilst they thy righteousness relate.

8 The Lord our God is gracious,
Compassionate is he also;
In mercy he is plenteous,
But unto wrath and anger slow.

9 Good unto all men is the Lord:
O’er all his works his mercy is.
10 Thy works all praise to thee afford:
Thy saints, O Lord, thy name shall bless.

11 The glory of thy kingdom show
Shall they, and of thy power tell:
12 That so men’s sons his deeds may know,
His kingdom’s grace that doth excel.

13 Thy kingdom hath none end at all,
It doth through ages all remain.
14 The Lord upholdeth all that fall,
The cast-down raiseth up again.

15 The eyes of all things, Lord, attend,
And on thee wait that here do live,
And thou, in season due, dost send
Sufficient food them to relieve.

16 Yea, thou thine hand dost open wide,
And ev’ry thing dost satisfy
That lives, and doth on earth abide,
Of thy great liberality.

17 The Lord is just in his ways all,
And holy in his works each one.
18 He’s near to all that on him call,
Who call in truth on him alone.

19 God will the just desire fulfill
Of such as do him fear and dread:
Their cry regard, and hear he will,
And save them in the time of need.

20 The Lord preserves all, more and less,
That bear to him a loving heart:
But workers all of wickedness
Destroy will he, and clean subvert.

21 Therefore my mouth and lips I’ll frame
To speak the praises of the Lord:
To magnify his holy name
For ever let all flesh accord.', '[{"index": 0, "lines": [{"text": "O Lord, thou art my God and King;", "bibleVerseRef": 1}, {"text": "Thee will I magnify and praise:"}, {"text": "I will thee bless, and gladly sing"}, {"text": "Unto thy holy name always."}]}, {"index": 1, "lines": [{"text": "Each day I rise I will thee bless,", "bibleVerseRef": 2}, {"text": "And praise thy name time without end."}, {"text": "Much to be praised, and great God is;", "bibleVerseRef": 3}, {"text": "His greatness none can comprehend.", "syllables": ["His", "greatness", "no-", "ne", "can", "com-", "pre-", "hend."]}]}, {"index": 2, "lines": [{"text": "Race shall thy works praise unto race,", "bibleVerseRef": 4}, {"text": "The mighty acts show done by thee."}, {"text": "I will speak of the glorious grace,", "syllables": ["I", "will", "speak", "of", "the", "glorious", "gra-", "ce,"], "bibleVerseRef": 5}, {"text": "And honor of thy majesty;"}]}, {"index": 3, "lines": [{"text": "Thy wondrous works I will record."}, {"text": "By men the might shall be extolled", "syllables": ["By", "men", "the", "might", "shall", "be", "extol-", "led"], "bibleVerseRef": 6}, {"text": "Of all thy dreadful acts, O Lord:"}, {"text": "And I thy greatness will unfold."}]}, {"index": 4, "lines": [{"text": "They utter shall abundantly", "bibleVerseRef": 7}, {"text": "The mem’ry of thy goodness great;"}, {"text": "And shall sing praises cheerfully,", "syllables": ["And", "shall", "sing", "praise-", "s", "cheer-", "ful-", "ly,"]}, {"text": "Whilst they thy righteousness relate."}]}, {"index": 5, "lines": [{"text": "The Lord our God is gracious,", "syllables": ["The", "Lord", "our", "God", "is", "gra-", "ciou-", "s,"], "bibleVerseRef": 8}, {"text": "Compassionate is he also;"}, {"text": "In mercy he is plenteous,", "syllables": ["In", "mercy", "he", "is", "plen-", "te-", "o-", "us,"]}, {"text": "But unto wrath and anger slow."}]}, {"index": 6, "lines": [{"text": "Good unto all men is the Lord:", "bibleVerseRef": 9}, {"text": "O’er all his works his mercy is."}, {"text": "Thy works all praise to thee afford:", "bibleVerseRef": 10}, {"text": "Thy saints, O Lord, thy name shall bless."}]}, {"index": 7, "lines": [{"text": "The glory of thy kingdom show", "bibleVerseRef": 11}, {"text": "Shall they, and of thy power tell:", "syllables": ["Sha-", "ll", "they,", "and", "of", "thy", "power", "tell:"]}, {"text": "That so men’s sons his deeds may know,", "bibleVerseRef": 12}, {"text": "His kingdom’s grace that doth excel.", "syllables": ["His", "kingdom’s", "gra-", "ce", "that", "doth", "ex-", "cel."]}]}, {"index": 8, "lines": [{"text": "Thy kingdom hath none end at all,", "syllables": ["Thy", "kingdom", "hath", "no-", "ne", "end", "at", "all,"], "bibleVerseRef": 13}, {"text": "It doth through ages all remain.", "syllables": ["It", "doth", "throu-", "gh", "ages", "all", "re-", "main."]}, {"text": "The Lord upholdeth all that fall,", "bibleVerseRef": 14}, {"text": "The cast-down raiseth up again."}]}, {"index": 9, "lines": [{"text": "The eyes of all things, Lord, attend,", "bibleVerseRef": 15}, {"text": "And on thee wait that here do live,"}, {"text": "And thou, in season due, dost send"}, {"text": "Sufficient food them to relieve."}]}, {"index": 10, "lines": [{"text": "Yea, thou thine hand dost open wide,", "syllables": ["Yea,", "thou", "thi-", "ne", "hand", "dost", "open", "wide,"], "bibleVerseRef": 16}, {"text": "And ev’ry thing dost satisfy"}, {"text": "That lives, and doth on earth abide,"}, {"text": "Of thy great liberality.", "syllables": ["Of", "thy", "grea-", "t", "libe-", "ra-", "li-", "ty."]}]}, {"index": 11, "lines": [{"text": "The Lord is just in his ways all,", "bibleVerseRef": 17}, {"text": "And holy in his works each one."}, {"text": "He’s near to all that on him call,", "bibleVerseRef": 18}, {"text": "Who call in truth on him alone."}]}, {"index": 12, "lines": [{"text": "God will the just desire fulfill", "bibleVerseRef": 19}, {"text": "Of such as do him fear and dread:"}, {"text": "Their cry regard, and hear he will,"}, {"text": "And save them in the time of need."}]}, {"index": 13, "lines": [{"text": "The Lord preserves all, more and less,", "syllables": ["The", "Lord", "preser-", "ves", "all,", "more", "and", "less,"], "bibleVerseRef": 20}, {"text": "That bear to him a loving heart:"}, {"text": "But workers all of wickedness"}, {"text": "Destroy will he, and clean subvert."}]}, {"index": 14, "lines": [{"text": "Therefore my mouth and lips I’ll frame", "syllables": ["therefore", "my", "mouth", "and", "lips", "I’ll", "fra-", "me"], "bibleVerseRef": 21}, {"text": "To speak the praises of the Lord:", "syllables": ["To", "speak", "the", "praise-", "s", "of", "the", "Lord:"]}, {"text": "To magnify his holy name"}, {"text": "For ever let all flesh accord.", "syllables": ["For", "ever", "let", "all", "fle-", "sh", "ac-", "cord."]}]}]', 'LM (long meter, 88 88)', 'Second Version', 'O Lord, thou art my God and King...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (73, 'recSbl3iixVXT3WX6', 57, '57', '1Be merciful to me, O God;
thy mercy unto me
Do thou extend; because my soul
doth put her trust in thee:

Yea, in the shadow of thy wings
my refuge I will place,
Until these sad calamities
do wholly overpass.

2My cry I will cause to ascend
unto the Lord most high;
To God, who doth all things for me
perform most perfectly.

3From heav''n he shall send down, and me
from his reproach defend
That would devour me: God his truth
and mercy forth shall send.

4My soul among fierce lions is,
I firebrands live among,
Men''s sons, whose teeth are spears and darts,
a sharp sword is their tongue.

5Be thou exalted very high
above the heav''ns, O God;
Let thou thy glory be advanc''d
o''er all the earth abroad.

6My soul''s bow''d down; for they a net
have laid, my steps to snare:
Into the pit which they have digg''d
for me, they fallen are.

7My heart is fix''d, my heart is fix''d,
O God; I''ll sing and praise.
8My glory wake; wake psalt''ry, harp;
myself I''ll early raise.

9I''ll praise thee ''mong the people, Lord;
''mong nations sing will I:
10For great to heav''n thy mercy is,
thy truth is to the sky.

11O Lord, exalted be thy name
above the heav''ns to stand:
Do thou thy glory far advance
above both sea and land.', '[{"index": 0, "lines": [{"text": "Be merciful to me, O God;", "bibleVerseRef": 1}, {"text": "thy mercy unto me"}, {"text": "Do thou extend; because my soul"}, {"text": "doth put her trust in thee:"}]}, {"index": 1, "lines": [{"text": "Yea, in the shadow of thy wings"}, {"text": "my refuge I will place,", "syllables": ["my", "refuge", "I", "will", "pla-", "ce,"]}, {"text": "Until these sad calamities"}, {"text": "do wholly overpass.", "syllables": ["do", "who-", "l-", "ly", "over-", "pass."]}]}, {"index": 2, "lines": [{"text": "My cry I will cause to ascend", "bibleVerseRef": 2}, {"text": "unto the Lord most high;"}, {"text": "To God, who doth all things for me"}, {"text": "perform most perfectly."}]}, {"index": 3, "lines": [{"text": "From heav''n he shall send down, and me", "bibleVerseRef": 3}, {"text": "from his reproach defend", "syllables": ["from", "his", "repro-", "ach", "de-", "fend"]}, {"text": "That would devour me: God his truth"}, {"text": "and mercy forth shall send."}]}, {"index": 4, "lines": [{"text": "My soul among fierce lions is,", "bibleVerseRef": 4}, {"text": "I firebrands live among,"}, {"text": "Men''s sons, whose teeth are spears and darts,"}, {"text": "a sharp sword is their tongue.", "syllables": ["a", "sharp", "sword", "is", "their", "tongue."]}]}, {"index": 5, "lines": [{"text": "Be thou exalted very high", "bibleVerseRef": 5}, {"text": "above the heav''ns, O God;"}, {"text": "Let thou thy glory be advanc''d"}, {"text": "o''er all the earth abroad.", "syllables": ["o''er", "all", "the", "earth", "abro-", "ad."]}]}, {"index": 6, "lines": [{"text": "My soul''s bow''d down; for they a net", "bibleVerseRef": 6}, {"text": "have laid, my steps to snare:", "syllables": ["have", "laid,", "my", "steps", "to", "snare:"]}, {"text": "Into the pit which they have digg''d"}, {"text": "for me, they fallen are."}]}, {"index": 7, "lines": [{"text": "My heart is fix''d, my heart is fix''d,", "bibleVerseRef": 7}, {"text": "O God; I''ll sing and praise."}, {"text": "My glory wake; wake psalt''ry, harp;", "bibleVerseRef": 8}, {"text": "myself I''ll early raise.", "syllables": ["myse-", "lf", "I''ll", "ear-", "ly", "raise."]}]}, {"index": 8, "lines": [{"text": "I''ll praise thee ''mong the people, Lord;", "syllables": ["I''ll", "praise", "thee", "''mong", "the", "peo-", "ple,", "Lord;"], "bibleVerseRef": 9}, {"text": "''mong nations sing will I:"}, {"text": "For great to heav''n thy mercy is,", "bibleVerseRef": 10}, {"text": "thy truth is to the sky."}]}, {"index": 9, "lines": [{"text": "O Lord, exalted be thy name", "bibleVerseRef": 11}, {"text": "above the heav''ns to stand:"}, {"text": "Do thou thy glory far advance", "syllables": ["Do", "thou", "thy", "glory", "far", "ad-", "van-", "ce"]}, {"text": "above both sea and land."}]}]', 'CM', NULL, 'Be merciful to me, O God...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (83, 'recUxetCgUhG6ckCO', 137, '137', '1By Babel''s streams we sat and wept,
when Sion we thought on.
2In midst thereof we hang''d our harps
the willow-trees upon.

3For there a song required they,
who did us captive bring:
Our spoilers call''d for mirth, and said,
A song of Sion sing.

4O how the Lord''s song shall we sing
within a foreign land?
5If thee, Jerus''lem, I forget,
skill part from my right hand.

6My tongue to my mouth''s roof let cleave,
if I do thee forget,
Jerusalem, and thee above
my chief joy do not set.

7Remember Edom''s children, Lord,
who in Jerus''lems day,
Ev''n unto its foundation,
Raze, raze it quite, did say.

8O daughter thou of Babylon,
near to destruction;
Bless''d shall he be that thee rewards,
as thou to us hast done.

9Yea, happy surely shall he be
thy tender little ones
Who shall lay hold upon,
and them shall dash against the stones.', '[{"index": 0, "lines": [{"text": "By Babel''s streams we sat and wept,", "bibleVerseRef": 1}, {"text": "when Sion we thought on.", "syllables": ["when", "Sion", "we", "thou-", "ght", "on."]}, {"text": "In midst thereof we hang''d our harps", "bibleVerseRef": 2}, {"text": "the willow-trees upon."}]}, {"index": 1, "lines": [{"text": "For there a song required they,", "syllables": ["For", "there", "a", "song", "requ-", "i-", "red", "they,"], "bibleVerseRef": 3}, {"text": "who did us captive bring:"}, {"text": "Our spoilers call''d for mirth, and said,"}, {"text": "A song of Sion sing.", "syllables": ["A", "song", "of", "Sion", "si-", "ng."]}]}, {"index": 2, "lines": [{"text": "O how the Lord''s song shall we sing", "bibleVerseRef": 4}, {"text": "within a foreign land?", "syllables": ["wi-", "thin", "a", "forei-", "gn", "land?"]}, {"text": "If thee, Jerus''lem, I forget,", "bibleVerseRef": 5}, {"text": "skill part from my right hand."}]}, {"index": 3, "lines": [{"text": "My tongue to my mouth''s roof let cleave,", "syllables": ["My", "tongue", "to", "my", "mouth''s", "roof", "let", "cleave,"], "bibleVerseRef": 6}, {"text": "if I do thee forget,"}, {"text": "Jerusalem, and thee above", "syllables": ["je-", "ru-", "sale-", "m,", "and", "thee", "a-", "bove"]}, {"text": "my chief joy do not set."}]}, {"index": 4, "lines": [{"text": "Remember Edom''s children, Lord,", "bibleVerseRef": 7}, {"text": "who in Jerus''lems day,"}, {"text": "Ev''n unto its foundation,", "syllables": ["Ev''n", "un-", "to", "its", "fou-", "n-", "da-", "tion,"]}, {"text": "Raze, raze it quite, did say.", "syllables": ["Raze,", "raze", "it", "quite,", "did", "say."]}]}, {"index": 5, "lines": [{"text": "O daughter thou of Babylon,", "bibleVerseRef": 8}, {"text": "near to destruction;", "syllables": ["near", "to", "des-", "tru-", "c-", "tion;"]}, {"text": "Bless''d shall he be that thee rewards,"}, {"text": "as thou to us hast done."}]}, {"index": 6, "lines": [{"text": "Yea, happy surely shall he be", "bibleVerseRef": 9}, {"text": "thy tender little ones"}, {"text": "Who shall lay hold upon,", "syllables": ["Who", "sha-", "-", "ll", "lay", "hold", "u-", "pon,"]}, {"text": "and them shall dash against the stones.", "syllables": ["and", "them", "shall", "dash", "against", "thestones."]}]}]', 'CM', NULL, 'By Babel''s streams we sat and wept...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (85, 'recVRb3GpPgq6FEKc', 148, '148 (Second Version, Recommended)', '1The Lord of heav''n confess,
On high his glory raise
2Him let all angels bless,
Him all his armies praise

3Him glorify
Sun, moon, and stars;
4Ye higher spheres,
And cloudy sky.

5From God your beings are,
Him therefore famous make;
You all created were,
When he the word but spake.

6And from that place,
Where fix''d you be
By his decree,
You cannot pass.

7Praise God from earth below,
Ye dragons, and ye deeps:
8Fire, hail, clouds, wind, and snow.
Whom in command he keeps.

9Praise ye his name,
Hills great and small,
Trees low and tall;
10Beasts wild and tame;

All things that creep or fly.
11Ye kings, ye vulgar throng,
All princes mean or high;
12Both men and virgins young,

Ev''n young and old,
13Exalt his name;
For much his fame
Should be extoll''d.

O let God''s name be prais''d
Above both earth and sky;
14For he his saints hath rais''d,
And set their horn on high;

Ev''n those that be
Of Isr''el''s race,
Near to his grace.
The Lord praise ye.', NULL, '66 66 88', 'Second Version', 'The Lord of heav''n confess...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (67, 'recOAbcfAhtfWJ5B4', 146, '146', '1Praise God. The Lord praise, O my soul.
2I''ll praise God while I live;
While I have being to my God
in songs I''ll praises give.

3Trust not in princes, nor man''s son,
in whom there is no stay:
4His breath departs, to''s earth he turns;
that day his thoughts decay.

5O happy is that man and blest,
whom Jacob''s God doth aid;
Whose hope upon the Lord doth rest,
and on his God is stay''d:

6Who made the earth and heavens high,
who made the swelling deep,
And all that is within the same;
who truth doth ever keep:

7Who righteous judgment executes
for those oppress''d that be,
Who to the hungry giveth food;
God sets the pris''ners free.

8The Lord doth give the blind their sight,
the bowed down doth raise:
The Lord doth dearly love all those
that walk in upright ways.

9The stranger''s shield, the widow''s stay,
the orphan''s help, is he:
But yet by him the wicked''s way
turn''d upside down shall be.

10The Lord shall reign for evermore:
thy God, O Sion, he
Reigns to all generations.
Praise to the Lord give ye.', '[{"index": 0, "lines": [{"text": "Praise God. The Lord praise, O my soul.", "bibleVerseRef": 1}, {"text": "I''ll praise God while I live;", "bibleVerseRef": 2}, {"text": "While I have being to my God", "syllables": ["Whi-", "le", "I", "have", "being", "to", "my", "God"]}, {"text": "in songs I''ll praises give.", "syllables": ["in", "songs", "I''ll", "praise-", "s", "give."]}]}, {"index": 1, "lines": [{"text": "Trust not in princes, nor man''s son,", "bibleVerseRef": 3}, {"text": "in whom there is no stay:"}, {"text": "His breath departs, to''s earth he turns;", "bibleVerseRef": 4}, {"text": "that day his thoughts decay."}]}, {"index": 2, "lines": [{"text": "O happy is that man and blest,", "bibleVerseRef": 5}, {"text": "whom Jacob''s God doth aid;"}, {"text": "Whose hope upon the Lord doth rest,"}, {"text": "and on his God is stay''d:"}]}, {"index": 3, "lines": [{"text": "Who made the earth and heavens high,", "syllables": ["Who", "made", "the", "earth", "and", "heave-", "ns", "high,"], "bibleVerseRef": 6}, {"text": "who made the swelling deep,"}, {"text": "And all that is within the same;"}, {"text": "who truth doth ever keep:", "syllables": ["who", "tru-", "th", "doth", "ever", "keep:"]}]}, {"index": 4, "lines": [{"text": "Who righteous judgment executes", "syllables": ["Who", "ri-", "gh-", "teous", "jud-", "gment", "exe-", "cutes"], "bibleVerseRef": 7}, {"text": "for those oppress''d that be,"}, {"text": "Who to the hungry giveth food;"}, {"text": "God sets the pris''ners free."}]}, {"index": 5, "lines": [{"text": "The Lord doth give the blind their sight,", "bibleVerseRef": 8}, {"text": "the bowed down doth raise:"}, {"text": "The Lord doth dearly love all those"}, {"text": "that walk in upright ways."}]}, {"index": 6, "lines": [{"text": "The stranger''s shield, the widow''s stay,", "bibleVerseRef": 9}, {"text": "the orphan''s help, is he:"}, {"text": "But yet by him the wicked''s way"}, {"text": "turn''d upside down shall be."}]}, {"index": 7, "lines": [{"text": "The Lord shall reign for evermore:", "syllables": ["The", "Lord", "sha-", "ll", "reign", "for", "ever-", "more:"], "bibleVerseRef": 10}, {"text": "thy God, O Sion, he", "syllables": ["thy", "God,", "O", "Sio-", "n,", "he"]}, {"text": "Reigns to all generations.", "syllables": ["Rei-", "gns", "to", "all", "ge-", "ne-", "ra-", "tions."]}, {"text": "Praise to the Lord give ye."}]}]', 'CM', NULL, 'Praise God. The Lord praise, O my soul...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (82, 'recUsvfMTDWTv8WLr', 43, '43', '1Judge me, O God, and plead my cause
against th'' ungodly nation;
From the unjust and crafty man,
O be thou my salvation.

2For thou the God art of my strength;
why thrusts thou me thee fro''?
For th'' enemy''s oppression
why do I mourning go?

3O send thy light forth and thy truth;
let them be guides to me,
And bring me to thine holy hill,
ev''n where thy dwellings be.

4Then will I to God''s altar go,
to God my chiefest joy:
Yea, God, my God, thy name to praise
my harp I will employ.

5Why art thou then cast down, my soul?
what should discourage thee?
And why with vexing thoughts art thou
disquieted in me?

Still trust in God; for him to praise
good cause I yet shall have:
He of my count''nance is the health,
my God that doth me save.', '[{"index": 0, "lines": [{"text": "Judge me, O God, and plead my cause", "syllables": ["judge", "me,", "O", "God,", "and", "plead", "my", "cause"], "bibleVerseRef": 1}, {"text": "against th'' ungodly nation;", "syllables": ["against", "th''", "ungod-", "ly", "na-", "tion;"]}, {"text": "From the unjust and crafty man,"}, {"text": "O be thou my salvation.", "syllables": ["O", "be", "thou", "my", "salva-", "tion."]}]}, {"index": 1, "lines": [{"text": "For thou the God art of my strength;", "bibleVerseRef": 2}, {"text": "why thrusts thou me thee fro''?"}, {"text": "For th'' enemy''s oppression", "syllables": ["For", "th''", "ene-", "my''s", "op-", "pre-", "s-", "sion"]}, {"text": "why do I mourning go?"}]}, {"index": 2, "lines": [{"text": "O send thy light forth and thy truth;", "bibleVerseRef": 3}, {"text": "let them be guides to me,", "syllables": ["let", "them", "be", "guides", "to", "me,"]}, {"text": "And bring me to thine holy hill,"}, {"text": "ev''n where thy dwellings be."}]}, {"index": 3, "lines": [{"text": "Then will I to God''s altar go,", "bibleVerseRef": 4}, {"text": "to God my chiefest joy:", "syllables": ["to", "God", "my", "chiefe-", "st", "joy:"]}, {"text": "Yea, God, my God, thy name to praise"}, {"text": "my harp I will employ."}]}, {"index": 4, "lines": [{"text": "Why art thou then cast down, my soul?", "bibleVerseRef": 5}, {"text": "what should discourage thee?"}, {"text": "And why with vexing thoughts art thou"}, {"text": "disquieted in me?", "syllables": ["disqu-", "i-", "e-", "ted", "in", "me?"]}]}, {"index": 5, "lines": [{"text": "Still trust in God; for him to praise"}, {"text": "good cause I yet shall have:"}, {"text": "He of my count''nance is the health,", "syllables": ["He", "of", "my", "count''nan-", "ce", "is", "the", "health,"]}, {"text": "my God that doth me save."}]}]', 'CM', NULL, 'Judge me, O God, and plead my cause...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (86, 'recVTQAWztonB4rcp', 25, '25 (Second Version)', '1To thee I lift my soul, O Lord:
2My God, I trust in thee:
Let me not be asham''d;
let not my foes triumph o''er me

3Yea, let thou none ashamed be
that do on thee attend:
Ashamed let them be, O Lord,
who without cause offend.

4Thy ways, Lord, shew; teach me thy paths:
5Lead me in truth, teach me:
For of my safety thou art God;
all day I wait on thee.

6Thy mercies, that most tender are,
do thou, O Lord, remember,
And loving-kindnesses; for they
have been of old for ever.

7Let not the errors of my youth,
nor sins, remember''d be:
In mercy, for thy goodness'' sake,
O Lord, remember me.

8The Lord is good and gracious,
he upright is also:
He therefore sinners will instruct
in ways that they should go.

9The meek and lowly he will guide
in judgment just alway:
To meek and poor afflicted ones
he''ll clearly teach his way.

10The whole paths of the Lord our God
are truth and mercy sure,
To such as keep his covenant,
and testimonies pure.

11Now, for thine own name''s sake, O Lord,
I humbly thee entreat
To pardon mine iniquity;
for it is very great.

12What man fears God? him shall he teach
he way that he shall chuse.
13His soul shall dwell at ease; his seed
the earth, as heirs, shall use.

14The secret of the Lord is with
such as do fear his name;
And he his holy covenant
will manifest to them.

15Towards the Lord my waiting eyes
continually are set;
For he it is that shall bring forth
my feet out of the net.

16O turn thee unto me, O God,
have mercy me upon;
Because I solitary am,
and in affliction.

17Enlarg''d the griefs are of mine heart;
me from distress relieve.
18See mine affliction and my pain,
and all my sins forgive.

19Consider thou mine enemies,
because they many are;
And it a cruel hatred is
which they against me bear.

20O do thou keep my soul;
O God, do thou deliver me:
Let me not be asham''d;
for I do put my trust in thee.

21O let integrity and truth
keep me, who thee attend.
22Redemption, Lord, to Israel
from all his troubles send.', '[{"index": 0, "lines": [{"text": "To thee I lift my soul, O Lord:", "bibleVerseRef": 1}, {"text": "My God, I trust in thee:", "bibleVerseRef": 2}, {"text": "Let me not be asham''d;", "syllables": ["Let", "me", "not", "be", "a-", "sha-", "-", "m''d;"]}, {"text": "let not my foes triumph o''er me", "syllables": ["let", "not", "my", "foes", "triumph", "o''erme"]}]}, {"index": 1, "lines": [{"text": "Yea, let thou none ashamed be", "syllables": ["Yea,", "let", "thou", "none", "a-", "sha-", "med", "be"], "bibleVerseRef": 3}, {"text": "that do on thee attend:"}, {"text": "Ashamed let them be, O Lord,"}, {"text": "who without cause offend."}]}, {"index": 2, "lines": [{"text": "Thy ways, Lord, shew; teach me thy paths:", "bibleVerseRef": 4}, {"text": "Lead me in truth, teach me:", "bibleVerseRef": 5}, {"text": "For of my safety thou art God;"}, {"text": "all day I wait on thee."}]}, {"index": 3, "lines": [{"text": "Thy mercies, that most tender are,", "bibleVerseRef": 6}, {"text": "do thou, O Lord, remember,", "syllables": ["do", "thou,", "O", "Lord,", "remem-", "ber,"]}, {"text": "And loving-kindnesses; for they"}, {"text": "have been of old for ever."}]}, {"index": 4, "lines": [{"text": "Let not the errors of my youth,", "bibleVerseRef": 7}, {"text": "nor sins, remember''d be:"}, {"text": "In mercy, for thy goodness'' sake,"}, {"text": "O Lord, remember me."}]}, {"index": 5, "lines": [{"text": "The Lord is good and gracious,", "syllables": ["The", "Lord", "is", "good", "and", "gra-", "ciou-", "s,"], "bibleVerseRef": 8}, {"text": "he upright is also:"}, {"text": "He therefore sinners will instruct"}, {"text": "in ways that they should go."}]}, {"index": 6, "lines": [{"text": "The meek and lowly he will guide", "syllables": ["The", "meek", "and", "lowly", "he", "will", "gui-", "de"], "bibleVerseRef": 9}, {"text": "in judgment just alway:"}, {"text": "To meek and poor afflicted ones"}, {"text": "he''ll clearly teach his way."}]}, {"index": 7, "lines": [{"text": "The whole paths of the Lord our God", "bibleVerseRef": 10}, {"text": "are truth and mercy sure,"}, {"text": "To such as keep his covenant,", "syllables": ["To", "such", "as", "keep", "his", "cove-", "-", "nant,"]}, {"text": "and testimonies pure."}]}, {"index": 8, "lines": [{"text": "Now, for thine own name''s sake, O Lord,", "bibleVerseRef": 11}, {"text": "I humbly thee entreat"}, {"text": "To pardon mine iniquity;"}, {"text": "for it is very great."}]}, {"index": 9, "lines": [{"text": "What man fears God? him shall he teach", "bibleVerseRef": 12}, {"text": "he way that he shall chuse."}, {"text": "His soul shall dwell at ease; his seed", "syllables": ["His", "soul", "shall", "dwell", "at", "ease;", "his", "seed"], "bibleVerseRef": 13}, {"text": "the earth, as heirs, shall use."}]}, {"index": 10, "lines": [{"text": "The secret of the Lord is with", "bibleVerseRef": 14}, {"text": "such as do fear his name;"}, {"text": "And he his holy covenant", "syllables": ["And", "he", "his", "ho-", "ly", "cove-", "-", "nant"]}, {"text": "will manifest to them."}]}, {"index": 11, "lines": [{"text": "Towards the Lord my waiting eyes", "bibleVerseRef": 15}, {"text": "continually are set;", "syllables": ["conti-", "nu-", "a-", "lly", "are", "set;"]}, {"text": "For he it is that shall bring forth"}, {"text": "my feet out of the net."}]}, {"index": 12, "lines": [{"text": "O turn thee unto me, O God,", "bibleVerseRef": 16}, {"text": "have mercy me upon;"}, {"text": "Because I solitary am,"}, {"text": "and in affliction.", "syllables": ["and", "in", "af-", "fli-", "c-", "tion."]}]}, {"index": 13, "lines": [{"text": "Enlarg''d the griefs are of mine heart;", "bibleVerseRef": 17}, {"text": "me from distress relieve."}, {"text": "See mine affliction and my pain,", "bibleVerseRef": 18}, {"text": "and all my sins forgive."}]}, {"index": 14, "lines": [{"text": "Consider thou mine enemies,", "syllables": ["con-", "side-", "r", "thou", "mine", "en-", "e-", "mies,"], "bibleVerseRef": 19}, {"text": "because they many are;"}, {"text": "And it a cruel hatred is", "syllables": ["And", "it", "a", "crue-", "l", "hat-", "red", "is"]}, {"text": "which they against me bear."}]}, {"index": 15, "lines": [{"text": "O do thou keep my soul;", "syllables": ["O", "do", "tho-", "u", "keep", "my", "sou-", "l;"], "bibleVerseRef": 20}, {"text": "O God, do thou deliver me:", "syllables": ["O", "God,", "do", "thou", "deliver", "me:"]}, {"text": "Let me not be asham''d;", "syllables": ["Let", "me", "not", "be", "a-", "sha-", "-", "m''d;"]}, {"text": "for I do put my trust in thee.", "syllables": ["for", "I", "do", "put", "my", "trustinthee."]}]}, {"index": 16, "lines": [{"text": "O let integrity and truth", "bibleVerseRef": 21}, {"text": "keep me, who thee attend."}, {"text": "Redemption, Lord, to Israel", "syllables": ["re-", "dem-", "ptio-", "n,", "Lord,", "to", "is-", "rael"], "bibleVerseRef": 22}, {"text": "from all his troubles send."}]}]', 'CM', 'Second Version', 'To thee I lift my soul, O Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (90, 'recW6Fj4SvrnrnHz0', 27, '27', '1The Lord''s my light and saving health,
who shall make me dismay''d?
My life''s strength is the Lord, of whom
then shall I be afraid?

2When as mine enemies and foes,
most wicked persons all,
To eat my flesh against me rose,
they stumbled and did fall.

3Against me though an host encamp,
my heart yet fearless is:
Though war against me rise, I will
be confident in this.

4One thing I of the Lord desir''d,
and will seek to obtain,
That all days of my life I may
within God''s house remain;

That I the beauty of the Lord
behold may and admire,
And that I in his holy place
may rev''rently enquire.

5For he in his pavilion shall
me hide in evil days;
In secret of his tent me hide,
and on a rock me raise.

6And now, ev''n at this present time,
mine head shall lifted be
Above all those that are my foes,
and round encompass me:

Therefore unto his tabernacle
I''ll sacrifices bring
Of joyfulness; I''ll sing, yea, I
to God will praises sing.

7O Lord, give ear unto my voice,
when I do cry to thee;
Upon me also mercy have,
and do thou answer me.

8When thou didst say, Seek ye my face,
then unto thee reply
Thus did my heart, Above all things
thy face, Lord, seek will I.

9Far from me hide not thou thy face;
put not away from thee
Thy servant in thy wrath: thou hast
an helper been to me.

O God of my salvation,
leave me not, nor forsake:
10Though me my parents both should leave,
the Lord will me up take.

11O Lord, instruct me in thy way,
to me a leader be
In a plain path, because of those
that hatred bear to me.

12Give me not to mine en''mies'' will;
for witnesses that lie
Against me risen are, and such
as breathe out cruelty.

13I fainted had, unless that I
believed had to see
The Lord''s own goodness in the land
of them that living be.

14Wait on the Lord, and be thou strong,
and he shall strength afford
Unto thine heart; yea, do thou wait,
I say, upon the Lord.', '[{"index": 0, "lines": [{"text": "The Lord''s my light and saving health,", "bibleVerseRef": 1}, {"text": "who shall make me dismay''d?"}, {"text": "My life''s strength is the Lord, of whom"}, {"text": "then shall I be afraid?"}]}, {"index": 1, "lines": [{"text": "When as mine enemies and foes,", "bibleVerseRef": 2}, {"text": "most wicked persons all,"}, {"text": "To eat my flesh against me rose,"}, {"text": "they stumbled and did fall."}]}, {"index": 2, "lines": [{"text": "Against me though an host encamp,", "bibleVerseRef": 3}, {"text": "my heart yet fearless is:"}, {"text": "Though war against me rise, I will"}, {"text": "be confident in this."}]}, {"index": 3, "lines": [{"text": "One thing I of the Lord desir''d,", "bibleVerseRef": 4}, {"text": "and will seek to obtain,"}, {"text": "That all days of my life I may"}, {"text": "within God''s house remain;"}]}, {"index": 4, "lines": [{"text": "That I the beauty of the Lord"}, {"text": "behold may and admire,"}, {"text": "And that I in his holy place", "syllables": ["And", "that", "I", "in", "his", "holy", "pla-", "ce"]}, {"text": "may rev''rently enquire.", "syllables": ["may", "rev''rently", "en-", "qu-", "i-", "re."]}]}, {"index": 5, "lines": [{"text": "For he in his pavilion shall", "bibleVerseRef": 5}, {"text": "me hide in evil days;"}, {"text": "In secret of his tent me hide,"}, {"text": "and on a rock me raise."}]}, {"index": 6, "lines": [{"text": "And now, ev''n at this present time,", "syllables": ["And", "now,", "ev''n", "at", "this", "prese-", "nt", "time,"], "bibleVerseRef": 6}, {"text": "mine head shall lifted be"}, {"text": "Above all those that are my foes,"}, {"text": "and round encompass me:"}]}, {"index": 7, "lines": [{"text": "Therefore unto his tabernacle"}, {"text": "I''ll sacrifices bring", "syllables": ["I''ll", "sac-", "ri-", "fice-", "s", "bring"]}, {"text": "Of joyfulness; I''ll sing, yea, I"}, {"text": "to God will praises sing.", "syllables": ["to", "God", "will", "praise-", "s", "sing."]}]}, {"index": 8, "lines": [{"text": "O Lord, give ear unto my voice,", "bibleVerseRef": 7}, {"text": "when I do cry to thee;"}, {"text": "Upon me also mercy have,"}, {"text": "and do thou answer me."}]}, {"index": 9, "lines": [{"text": "When thou didst say, Seek ye my face,", "bibleVerseRef": 8}, {"text": "then unto thee reply"}, {"text": "Thus did my heart, Above all things"}, {"text": "thy face, Lord, seek will I."}]}, {"index": 10, "lines": [{"text": "Far from me hide not thou thy face;", "bibleVerseRef": 9}, {"text": "put not away from thee"}, {"text": "Thy servant in thy wrath: thou hast"}, {"text": "an helper been to me."}]}, {"index": 11, "lines": [{"text": "O God of my salvation,", "syllables": ["O", "God", "of", "my", "sal-", "va-", "tio-", "n,"]}, {"text": "leave me not, nor forsake:"}, {"text": "Though me my parents both should leave,", "syllables": ["Though", "me", "my", "pare-", "nts", "both", "should", "leave,"], "bibleVerseRef": 10}, {"text": "the Lord will me up take."}]}, {"index": 12, "lines": [{"text": "O Lord, instruct me in thy way,", "bibleVerseRef": 11}, {"text": "to me a leader be", "syllables": ["to", "me", "a", "leade-", "r", "be"]}, {"text": "In a plain path, because of those"}, {"text": "that hatred bear to me."}]}, {"index": 13, "lines": [{"text": "Give me not to mine en''mies'' will;", "bibleVerseRef": 12}, {"text": "for witnesses that lie"}, {"text": "Against me risen are, and such", "syllables": ["a-", "gai-", "nst", "me", "risen", "are,", "and", "such"]}, {"text": "as breathe out cruelty."}]}, {"index": 14, "lines": [{"text": "I fainted had, unless that I", "bibleVerseRef": 13}, {"text": "believed had to see"}, {"text": "The Lord''s own goodness in the land"}, {"text": "of them that living be."}]}, {"index": 15, "lines": [{"text": "Wait on the Lord, and be thou strong,", "bibleVerseRef": 14}, {"text": "and he shall strength afford"}, {"text": "Unto thine heart; yea, do thou wait,"}, {"text": "I say, upon the Lord."}]}]', 'CM', NULL, 'The Lord''s my light and saving health...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (92, 'recWVCIntT1dTdY99', 29, '29', '1Give ye unto the Lord, ye sons
that of the mighty be,
All strength and glory to the Lord
with cheerfulness give ye.

2Unto the Lord the glory give
that to his name is due;
And in the beauty of holiness
unto JEHOVAH bow.

3The Lord''s voice on the waters is;
the God of majesty
Doth thunder, and on multitudes
of waters sitteth he.

4A pow''rful voice it is that comes
out from the Lord most high;
The voice of that great Lord is full
of glorious majesty.

5The voice of the Eternal doth
asunder cedars tear;
Yea, God the Lord doth cedars break
that Lebanon doth bear.

6He makes them like a calf to skip,
ev''n that great Lebanon,
And, like to a young unicorn,
the mountain Sirion.

7God''s voice divides the flames of fire;
8The desert it doth shake:
The Lord doth make the wilderness
of Kadesh all to quake.

9God''s voice doth make the hinds to calve,
it makes the forest bare:
And in his temple ev''ry one
his glory doth declare.

10The Lord sits on the floods; the Lord
sits King, and ever shall.
11The Lord will give his people strength,
and with peace bless them all.', '[{"index": 0, "lines": [{"text": "Give ye unto the Lord, ye sons", "bibleVerseRef": 1}, {"text": "that of the mighty be,"}, {"text": "All strength and glory to the Lord"}, {"text": "with cheerfulness give ye."}]}, {"index": 1, "lines": [{"text": "Unto the Lord the glory give", "bibleVerseRef": 2}, {"text": "that to his name is due;"}, {"text": "And in the beauty of holiness", "syllables": ["And", "in", "the", "beauty", "of", "ho-", "li-", "ness"]}, {"text": "unto JEHOVAH bow."}]}, {"index": 2, "lines": [{"text": "The Lord''s voice on the waters is;", "syllables": ["The", "Lo-", "rd''s", "voice", "on", "the", "waters", "is;"], "bibleVerseRef": 3}, {"text": "the God of majesty"}, {"text": "Doth thunder, and on multitudes"}, {"text": "of waters sitteth he.", "syllables": ["of", "wate-", "rs", "sit-", "teth", "he."]}]}, {"index": 3, "lines": [{"text": "A pow''rful voice it is that comes", "bibleVerseRef": 4}, {"text": "out from the Lord most high;"}, {"text": "The voice of that great Lord is full"}, {"text": "of glorious majesty."}]}, {"index": 4, "lines": [{"text": "The voice of the Eternal doth", "syllables": ["The", "voi-", "ce", "of", "the", "eter-", "nal", "doth"], "bibleVerseRef": 5}, {"text": "asunder cedars tear;"}, {"text": "Yea, God the Lord doth cedars break"}, {"text": "that Lebanon doth bear."}]}, {"index": 5, "lines": [{"text": "He makes them like a calf to skip,", "bibleVerseRef": 6}, {"text": "ev''n that great Lebanon,"}, {"text": "And, like to a young unicorn,"}, {"text": "the mountain Sirion.", "syllables": ["the", "mou-", "n-", "tain", "si-", "rion."]}]}, {"index": 6, "lines": [{"text": "God''s voice divides the flames of fire;", "syllables": ["God''s", "voice", "divides", "the", "fla-", "mes", "of", "fire;"], "bibleVerseRef": 7}, {"text": "The desert it doth shake:", "bibleVerseRef": 8}, {"text": "The Lord doth make the wilderness"}, {"text": "of Kadesh all to quake.", "syllables": ["of", "Kadesh", "all", "to", "qua-", "ke."]}]}, {"index": 7, "lines": [{"text": "God''s voice doth make the hinds to calve,", "syllables": ["God''s", "voice", "doth", "make", "the", "hinds", "to", "calve,"], "bibleVerseRef": 9}, {"text": "it makes the forest bare:", "syllables": ["it", "makes", "the", "fore-", "st", "bare:"]}, {"text": "And in his temple ev''ry one", "syllables": ["And", "in", "his", "te-", "mple", "ev-", "''ry", "one"]}, {"text": "his glory doth declare."}]}, {"index": 8, "lines": [{"text": "The Lord sits on the floods; the Lord", "bibleVerseRef": 10}, {"text": "sits King, and ever shall.", "syllables": ["sits", "King,", "and", "ever", "sha-", "ll."]}, {"text": "The Lord will give his people strength,", "syllables": ["The", "Lord", "will", "give", "his", "peo-", "ple", "strength,"], "bibleVerseRef": 11}, {"text": "and with peace bless them all."}]}]', 'CM', NULL, 'Give ye unto the Lord, ye sons...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (80, 'recUUEBc7EIlDHHu2', 120, '120', '1In my distress to God I cry''d,
and he gave ear to me.
2From lying lips, and guileful tongue,
O Lord, my soul set free.

3What shall be giv''n thee? or what
shall be done to thee, false tongue?
4Ev''n burning coals of juniper,
sharp arrows of the strong.

5Woe''s me that I in Mesech am
a sojourner so long;
That I in tabernacles dwell
to Kedar that belong.

6My soul with him that hateth peace
hath long a dweller been.
7I am for peace; but when I speak,
for battle they are keen.', '[{"index": 0, "lines": [{"text": "In my distress to God I cry''d,", "bibleVerseRef": 1}, {"text": "and he gave ear to me."}, {"text": "From lying lips, and guileful tongue,", "syllables": ["From", "lying", "lips,", "and", "guile-", "ful", "ton-", "gue,"], "bibleVerseRef": 2}, {"text": "O Lord, my soul set free."}]}, {"index": 1, "lines": [{"text": "What shall be giv''n thee? or what", "syllables": ["What", "sha-", "ll", "be", "giv''n", "thee?", "or", "what"], "bibleVerseRef": 3}, {"text": "shall be done to thee, false tongue?", "syllables": ["shall", "be", "done", "to", "thee,", "falsetongue?"]}, {"text": "Ev''n burning coals of juniper,", "bibleVerseRef": 4}, {"text": "sharp arrows of the strong."}]}, {"index": 2, "lines": [{"text": "Woe''s me that I in Mesech am", "bibleVerseRef": 5}, {"text": "a sojourner so long;"}, {"text": "That I in tabernacles dwell", "syllables": ["That", "I", "in", "tabe-", "r-", "nac-", "les", "dwell"]}, {"text": "to Kedar that belong."}]}, {"index": 3, "lines": [{"text": "My soul with him that hateth peace", "bibleVerseRef": 6}, {"text": "hath long a dweller been."}, {"text": "I am for peace; but when I speak,", "bibleVerseRef": 7}, {"text": "for battle they are keen."}]}]', 'CM', NULL, 'In my distress to God I cry''d...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (89, 'recW2xdYkfgmvQSeA', 74, '74', '1O God, why hast thou cast us off?
is it for evermore?
Against thy pasture-sheep why doth
thine anger smoke so sore?

2O call to thy rememberance
thy congregation,
Which thou hast purchased of old;
still think the same upon:

The rod of thine inheritance,
which thou redeemed hast,
This Sion hill, wherein thou hadst
thy dwelling in times past.

3To these long desolations
thy feet lift, do not tarry;
For all the ills thy foes have done
within thy sanctuary.

4Amidst thy congregations
thine enemies do roar:
Their ensigns they set up for signs
of triumph thee before.

5A man was famous, and was had
in estimation,
According as he lifted up
his axe thick trees upon.

6But all at once with axes now
and hammers they go to,
And down the carved work thereof
they break, and quite undo.

7They fired have thy sanctuary,
and have defil''d the same,
By casting down unto the ground
the place where dwelt thy name.

8Thus said they in their hearts, Let us
destroy them out of hand:
They burnt up all the synagogues
of God within the land.

9Our signs we do not now behold;
there is not us among
A prophet more, nor any one
that knows the time how long.

10How long, Lord, shall the enemy
thus in reproach exclaim?
And shall the adversary thus
always blaspheme thy name?

11Thy hand, ev''n thy right hand of might,
why dost thou thus draw back?
O from thy bosom pluck it out
for our deliv''rance sake.

12For certainly God is my King,
ev''n from the times of old,
Working in midst of all the earth
salvation manifold.

13The sea, by thy great pow''r, to part
asunder thou didst make;
And thou the dragons'' heads, O Lord,
within the waters brake.

14The leviathan''s head thou brak''st
in pieces, and didst give
Him to be meat unto the folk
in wilderness that live.

15Thou clav''st the fountain and the flood,
which did with streams abound:
Thou dry''dst the mighty waters up
unto the very ground.

16Thine only is the day, O Lord,
thine also is the night;
And thou alone prepared hast
the sun and shining light.

17By thee the borders of the earth
were settled ev''ry where:
The summer and the winter both
by thee created were.

18That th'' enemy reproached hath,
O keep it in record;
And that the foolish people have
blasphem''d thy name, O Lord.

19Unto the multitude do not
thy turtle''s soul deliver:
The congregation of thy poor
do not forget for ever.

20Unto thy cov''nant have respect;
for earth''s dark places be
Full of the habitations
of horrid cruelty.

21O let not those that be oppress''d
return again with shame:
Let those that poor and needy are
give praise unto thy name.

22Do thou, O God, arise and plead
the cause that is thine own:
Remember how thou art reproach''d
still by the foolish one.

23Do not forget the voice of those
that are thine enemies:
Of those the tumult ever grows
that do against thee rise.', '[{"index": 0, "lines": [{"text": "O God, why hast thou cast us off?", "bibleVerseRef": 1}, {"text": "is it for evermore?", "syllables": ["is", "it", "for", "eve-", "r-", "more?"]}, {"text": "Against thy pasture-sheep why doth", "syllables": ["against", "thy", "pas-", "tu-", "re--", "sheep", "why", "doth"]}, {"text": "thine anger smoke so sore?", "syllables": ["thine", "anger", "smo-", "ke", "so", "sore?"]}]}, {"index": 1, "lines": [{"text": "O call to thy rememberance", "syllables": ["O", "call", "to", "thy", "remem-", "be-", "ran-", "ce"], "bibleVerseRef": 2}, {"text": "thy congregation,", "syllables": ["thy", "con-", "gre-", "ga-", "tio-", "n,"]}, {"text": "Which thou hast purchased of old;"}, {"text": "still think the same upon:"}]}, {"index": 2, "lines": [{"text": "The rod of thine inheritance,", "syllables": ["The", "rod", "of", "thine", "inhe-", "ri-", "tan-", "ce,"]}, {"text": "which thou redeemed hast,"}, {"text": "This Sion hill, wherein thou hadst", "syllables": ["This", "Sion", "hill,", "wherei-", "-", "n", "thou", "hadst"]}, {"text": "thy dwelling in times past."}]}, {"index": 3, "lines": [{"text": "To these long desolations", "syllables": ["To", "the-", "se", "long", "de-", "so-", "la-", "tions"], "bibleVerseRef": 3}, {"text": "thy feet lift, do not tarry;", "syllables": ["thy", "feet", "lift,", "do", "not", "tarry;"]}, {"text": "For all the ills thy foes have done"}, {"text": "within thy sanctuary.", "syllables": ["within", "thy", "san-", "ctu-", "a-", "ry."]}]}, {"index": 4, "lines": [{"text": "Amidst thy congregations", "syllables": ["a-", "mi-", "dst", "thy", "con-", "gre-", "ga-", "tions"], "bibleVerseRef": 4}, {"text": "thine enemies do roar:", "syllables": ["thine", "ene-", "mies", "do", "ro-", "ar:"]}, {"text": "Their ensigns they set up for signs"}, {"text": "of triumph thee before.", "syllables": ["of", "triu-", "mph", "thee", "be-", "fore."]}]}, {"index": 5, "lines": [{"text": "A man was famous, and was had", "bibleVerseRef": 5}, {"text": "in estimation,", "syllables": ["in", "es-", "ti-", "ma-", "tio-", "n,"]}, {"text": "According as he lifted up"}, {"text": "his axe thick trees upon."}]}, {"index": 6, "lines": [{"text": "But all at once with axes now", "bibleVerseRef": 6}, {"text": "and hammers they go to,"}, {"text": "And down the carved work thereof"}, {"text": "they break, and quite undo.", "syllables": ["they", "break,", "and", "quite", "un-", "do."]}]}, {"index": 7, "lines": [{"text": "They fired have thy sanctuary,", "syllables": ["They", "fired", "have", "thy", "san-", "ctu-", "a-", "ry,"], "bibleVerseRef": 7}, {"text": "and have defil''d the same,"}, {"text": "By casting down unto the ground"}, {"text": "the place where dwelt thy name.", "syllables": ["the", "place", "where", "dwelt", "thy", "name."]}]}, {"index": 8, "lines": [{"text": "Thus said they in their hearts, Let us", "bibleVerseRef": 8}, {"text": "destroy them out of hand:"}, {"text": "They burnt up all the synagogues", "syllables": ["They", "burnt", "up", "all", "the", "syna-", "go-", "gues"]}, {"text": "of God within the land."}]}, {"index": 9, "lines": [{"text": "Our signs we do not now behold;", "bibleVerseRef": 9}, {"text": "there is not us among"}, {"text": "A prophet more, nor any one"}, {"text": "that knows the time how long."}]}, {"index": 10, "lines": [{"text": "How long, Lord, shall the enemy", "bibleVerseRef": 10}, {"text": "thus in reproach exclaim?", "syllables": ["thus", "in", "repro-", "ach", "ex-", "claim?"]}, {"text": "And shall the adversary thus"}, {"text": "always blaspheme thy name?"}]}, {"index": 11, "lines": [{"text": "Thy hand, ev''n thy right hand of might,", "bibleVerseRef": 11}, {"text": "why dost thou thus draw back?"}, {"text": "O from thy bosom pluck it out"}, {"text": "for our deliv''rance sake.", "syllables": ["for", "our", "deliv-", "''ran-", "ce", "sake."]}]}, {"index": 12, "lines": [{"text": "For certainly God is my King,", "bibleVerseRef": 12}, {"text": "ev''n from the times of old,"}, {"text": "Working in midst of all the earth"}, {"text": "salvation manifold."}]}, {"index": 13, "lines": [{"text": "The sea, by thy great pow''r, to part", "bibleVerseRef": 13}, {"text": "asunder thou didst make;"}, {"text": "And thou the dragons'' heads, O Lord,"}, {"text": "within the waters brake."}]}, {"index": 14, "lines": [{"text": "The leviathan''s head thou brak''st", "bibleVerseRef": 14}, {"text": "in pieces, and didst give", "syllables": ["in", "piece-", "s,", "and", "didst", "give"]}, {"text": "Him to be meat unto the folk"}, {"text": "in wilderness that live."}]}, {"index": 15, "lines": [{"text": "Thou clav''st the fountain and the flood,", "bibleVerseRef": 15}, {"text": "which did with streams abound:"}, {"text": "Thou dry''dst the mighty waters up", "syllables": ["Thou", "dry-", "''dst", "the", "mig-", "hty", "waters", "up"]}, {"text": "unto the very ground."}]}, {"index": 16, "lines": [{"text": "Thine only is the day, O Lord,", "bibleVerseRef": 16}, {"text": "thine also is the night;"}, {"text": "And thou alone prepared hast"}, {"text": "the sun and shining light."}]}, {"index": 17, "lines": [{"text": "By thee the borders of the earth", "bibleVerseRef": 17}, {"text": "were settled ev''ry where:"}, {"text": "The summer and the winter both"}, {"text": "by thee created were.", "syllables": ["by", "thee", "crea-", "-", "ted", "were."]}]}, {"index": 18, "lines": [{"text": "That th'' enemy reproached hath,", "syllables": ["That", "th''", "enemy", "rep-", "ro-", "a-", "ched", "hath,"], "bibleVerseRef": 18}, {"text": "O keep it in record;"}, {"text": "And that the foolish people have", "syllables": ["And", "that", "the", "foolish", "pe-", "o-", "ple", "have"]}, {"text": "blasphem''d thy name, O Lord."}]}, {"index": 19, "lines": [{"text": "Unto the multitude do not", "bibleVerseRef": 19}, {"text": "thy turtle''s soul deliver:"}, {"text": "The congregation of thy poor"}, {"text": "do not forget for ever."}]}, {"index": 20, "lines": [{"text": "Unto thy cov''nant have respect;", "bibleVerseRef": 20}, {"text": "for earth''s dark places be"}, {"text": "Full of the habitations", "syllables": ["Full", "of", "the", "ha-", "bi-", "ta-", "tio-", "ns"]}, {"text": "of horrid cruelty.", "syllables": ["of", "hor-", "rid", "crue-", "l-", "ty."]}]}, {"index": 21, "lines": [{"text": "O let not those that be oppress''d", "bibleVerseRef": 21}, {"text": "return again with shame:"}, {"text": "Let those that poor and needy are"}, {"text": "give praise unto thy name."}]}, {"index": 22, "lines": [{"text": "Do thou, O God, arise and plead", "bibleVerseRef": 22}, {"text": "the cause that is thine own:"}, {"text": "Remember how thou art reproach''d", "syllables": ["remem-", "ber", "how", "thou", "art", "rep-", "ro-", "ach''d"]}, {"text": "still by the foolish one."}]}, {"index": 23, "lines": [{"text": "Do not forget the voice of those", "bibleVerseRef": 23}, {"text": "that are thine enemies:"}, {"text": "Of those the tumult ever grows", "syllables": ["Of", "tho-", "se", "the", "tu-", "mult", "ever", "grows"]}, {"text": "that do against thee rise."}]}]', 'CM', NULL, 'O God, why hast thou cast us off...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (93, 'recWiaILJTmXkeW6u', 52, '52', '1Why dost thou boast, O mighty man,
of mischief and of ill?
The goodness of Almighty God
endureth ever still.

2Thy tongue mischievous calumnies
deviseth subtilely,
Like to a razor sharp to cut,
working deceitfully.

3Ill more than good, and more than truth
thou lovest to speak wrong:
4Thou lovest all-devouring words,
O thou deceitful tongue.

5So God shall thee destroy for aye,
remove thee, pluck thee out
Quite from thy house, out of the land
of life he shall thee root.

6The righteous shall it see, and fear,
and laugh at him they shall:
7Lo, this the man is that did not
make God his strength at all:

But he in his abundant wealth
his confidence did place;
And he took strength unto himself
from his own wickedness.

8But I am in the house of God
like to an olive green:
My confidence for ever hath
upon God''s mercy been.

9And I for ever will thee praise,
because thou hast done this:
I on thy name will wait; for good
before thy saints it is.', '[{"index": 0, "lines": [{"text": "Why dost thou boast, O mighty man,", "syllables": ["Why", "dost", "thou", "boast,", "O", "mig-", "hty", "man,"], "bibleVerseRef": 1}, {"text": "of mischief and of ill?"}, {"text": "The goodness of Almighty God"}, {"text": "endureth ever still.", "syllables": ["en-", "du-", "reth", "ever", "sti-", "ll."]}]}, {"index": 1, "lines": [{"text": "Thy tongue mischievous calumnies", "syllables": ["Thy", "tongue", "mis-", "chie-", "vous", "ca-", "lum-", "nies"], "bibleVerseRef": 2}, {"text": "deviseth subtilely,", "syllables": ["devi-", "seth", "sub-", "ti-", "le-", "ly,"]}, {"text": "Like to a razor sharp to cut,"}, {"text": "working deceitfully."}]}, {"index": 2, "lines": [{"text": "Ill more than good, and more than truth", "bibleVerseRef": 3}, {"text": "thou lovest to speak wrong:", "syllables": ["thou", "love-", "st", "to", "speak", "wrong:"]}, {"text": "Thou lovest all-devouring words,", "syllables": ["Thou", "love-", "st", "al-", "l-de-", "vou-", "ring", "words,"], "bibleVerseRef": 4}, {"text": "O thou deceitful tongue.", "syllables": ["O", "thou", "deceit-", "ful", "ton-", "gue."]}]}, {"index": 3, "lines": [{"text": "So God shall thee destroy for aye,", "bibleVerseRef": 5}, {"text": "remove thee, pluck thee out"}, {"text": "Quite from thy house, out of the land", "syllables": ["quite", "from", "thy", "house,", "out", "of", "the", "land"]}, {"text": "of life he shall thee root."}]}, {"index": 4, "lines": [{"text": "The righteous shall it see, and fear,", "bibleVerseRef": 6}, {"text": "and laugh at him they shall:"}, {"text": "Lo, this the man is that did not", "bibleVerseRef": 7}, {"text": "make God his strength at all:"}]}, {"index": 5, "lines": [{"text": "But he in his abundant wealth"}, {"text": "his confidence did place;", "syllables": ["his", "confiden-", "ce", "did", "pla-", "ce;"]}, {"text": "And he took strength unto himself"}, {"text": "from his own wickedness."}]}, {"index": 6, "lines": [{"text": "But I am in the house of God", "bibleVerseRef": 8}, {"text": "like to an olive green:"}, {"text": "My confidence for ever hath"}, {"text": "upon God''s mercy been."}]}, {"index": 7, "lines": [{"text": "And I for ever will thee praise,", "syllables": ["And", "I", "for", "ever", "will", "thee", "praise-", ","], "bibleVerseRef": 9}, {"text": "because thou hast done this:"}, {"text": "I on thy name will wait; for good"}, {"text": "before thy saints it is."}]}]', 'CM', NULL, 'Why dost thou boast, O mighty man...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (96, 'recYtrYGXpNk2yspQ', 125, '125', '1They in the Lord that firmly trust
shall be like Sion hill,
Which at no time can be remov''d,
but standeth ever still.

2As round about Jerusalem
the mountains stand alway,
The Lord his folk doth compass so,
from henceforth and for aye.

3For ill men''s rod upon the lot
of just men shall not lie;
Lest righteous men stretch
forth their hands unto iniquity.

4Do thou to all those that be good
thy goodness, Lord, impart;
And do thou good to those that are
upright within their heart.

5But as for such as turn aside
after their crooked way,
God shall lead forth with wicked men:
on Isr''el peace shall stay.', '[{"index": 0, "lines": [{"text": "They in the Lord that firmly trust", "bibleVerseRef": 1}, {"text": "shall be like Sion hill,", "syllables": ["sha-", "ll", "be", "like", "Sion", "hill,"]}, {"text": "Which at no time can be remov''d,"}, {"text": "but standeth ever still.", "syllables": ["but", "stan-", "deth", "ever", "sti-", "ll."]}]}, {"index": 1, "lines": [{"text": "As round about Jerusalem", "syllables": ["As", "rou-", "nd", "a-", "bout", "je-", "ru-", "salem"], "bibleVerseRef": 2}, {"text": "the mountains stand alway,"}, {"text": "The Lord his folk doth compass so,"}, {"text": "from henceforth and for aye.", "syllables": ["from", "hence-", "forth", "and", "for", "aye."]}]}, {"index": 2, "lines": [{"text": "For ill men''s rod upon the lot", "bibleVerseRef": 3}, {"text": "of just men shall not lie;"}, {"text": "Lest righteous men stretch", "syllables": ["Lest", "ri-", "gh-", "teou-", "s", "men", "stre-", "tch"]}, {"text": "forth their hands unto iniquity.", "syllables": ["forth", "their", "hands", "unto", "iniqui-", "ty."]}]}, {"index": 3, "lines": [{"text": "Do thou to all those that be good", "bibleVerseRef": 4}, {"text": "thy goodness, Lord, impart;"}, {"text": "And do thou good to those that are"}, {"text": "upright within their heart."}]}, {"index": 4, "lines": [{"text": "But as for such as turn aside", "bibleVerseRef": 5}, {"text": "after their crooked way,"}, {"text": "God shall lead forth with wicked men:"}, {"text": "on Isr''el peace shall stay."}]}]', 'CM', NULL, 'They in the Lord that firmly trust...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (100, 'recb2kLDxZYzuw4XW', 11, '11', '1I in the Lord do put my trust:
how is it then that ye
Say to my soul, Flee, as a bird,
unto your mountain high?

2For, lo, the wicked bend their bow,
their shafts on string they fit,
That those who upright are in heart
they privily may hit.

3If the foundations be destroy''d,
what hath the righteous done?
4God in his holy temple is,
in heaven is his throne:

His eyes do see, his eye-lids try
5men''s sons. The just he proves:
But his soul hates the wicked man,
and him that vi''lence loves.

6Snares, fire and brimstone, furious storms,
on sinners he shall rain:
This, as the portion of their cup,
doth unto them pertain.

7Because the Lord most righteous doth
in righteousness delight;
And with a pleasant countenance
beholdeth the upright.', '[{"index": 0, "lines": [{"text": "I in the Lord do put my trust:", "bibleVerseRef": 1}, {"text": "how is it then that ye"}, {"text": "Say to my soul, Flee, as a bird,"}, {"text": "unto your mountain high?"}]}, {"index": 1, "lines": [{"text": "For, lo, the wicked bend their bow,", "bibleVerseRef": 2}, {"text": "their shafts on string they fit,"}, {"text": "That those who upright are in heart"}, {"text": "they privily may hit."}]}, {"index": 2, "lines": [{"text": "If the foundations be destroy''d,", "bibleVerseRef": 3}, {"text": "what hath the righteous done?"}, {"text": "God in his holy temple is,", "syllables": ["God", "in", "his", "ho-", "ly", "te-", "mple", "is,"], "bibleVerseRef": 4}, {"text": "in heaven is his throne:"}]}, {"index": 3, "lines": [{"text": "His eyes do see, his eye-lids try"}, {"text": "men''s sons. The just he proves:", "syllables": ["men''s", "sons.", "The", "just", "he", "proves:"], "bibleVerseRef": 5}, {"text": "But his soul hates the wicked man,"}, {"text": "and him that vi''lence loves.", "syllables": ["and", "him", "that", "vi''len-", "ce", "loves."]}]}, {"index": 4, "lines": [{"text": "Snares, fire and brimstone, furious storms,", "syllables": ["snares,", "fire", "and", "brimsto-", "ne,", "fu-", "rious", "storms,"], "bibleVerseRef": 6}, {"text": "on sinners he shall rain:"}, {"text": "This, as the portion of their cup,"}, {"text": "doth unto them pertain."}]}, {"index": 5, "lines": [{"text": "Because the Lord most righteous doth", "bibleVerseRef": 7}, {"text": "in righteousness delight;"}, {"text": "And with a pleasant countenance", "syllables": ["And", "with", "a", "pleasant", "coun-", "te-", "nan-", "ce"]}, {"text": "beholdeth the upright."}]}]', 'CM', NULL, 'I in the Lord do put my trust...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (101, 'recbSl3LG9qvJ6Nxw', 143, '143 (Second Version, Recommended)', '1Oh, hear my prayer, Lord,
And unto my desire
To bow thine ear accord,
I humbly thee require;

And, in thy faithfulness,
Unto me answer make,
And, in thy righteousness,
Upon me pity take.

2In judgment enter not
With me thy servant poor;
For why, this well I wot,
No sinner can endure

The sight of thee, O God:
If thou his deeds shalt try,
He dare make none abode
Himself to justify.

3Behold, the cruel foe
Me persecutes with spite,
My soul to overthrow:
Yea, he my life down quite

Unto the ground hath smote,
And made me dwell full low
In darkness, as forgot,
Or men dead long ago.

4Therefore my sp''rit much vex''d,
O''erwhelm''d is me within;
My heart right sore perplex''d
And desolate hath been.

5Yet I do call to mind
What ancient days record,
Thy works of ev''ry kind
I think upon, O Lord.

6Lo, I do stretch my hands
To thee, my help alone;
For thou well understands
All my complaint and moan:

My thirsting soul desires,
And longeth after thee,
As thirsty ground requires
With rain refresh''d to be.

7Lord, let my pray''r prevail,
To answer it make speed;
For, lo, my sp''rit doth fail:
Hide not thy face in need;

Lest I be like to those
That do in darkness sit,
Or him that downward goes
Into the dreadful pit.

8Because I trust in thee,
O Lord, cause me to hear
Thy loving-kindness free,
When morning doth appear:

Cause me to know the way
Wherein my path should be;
For why, my soul on high
I do lift up to thee.

9From my fierce enemy
In safety do me guide,
Because I flee to thee,
Lord, that thou may''st me hide.

10My God alone art thou,
Teach me thy righteousness:
Thy Sp''rit''s good, lead me to
The land of uprightness.

11O Lord, for thy name''s sake,
Be pleas''d to quicken me;
And, for thy truth, forth take
My soul from misery.

12And of thy grace destroy
My foes, and put to shame
All who my soul annoy;
For I thy servant am.', NULL, '66 66 D', 'Second Version', 'Oh, hear my prayer, Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (106, 'reccCx469t0fu5TZX', 106, '106', '1Give praise and thanks unto the Lord,
for bountiful is he;
His tender mercy doth endure
unto eternity.

2God''s mighty works who can express?
or shew forth all his praise?
3Blessed are they that judgment keep,
and justly do always.

4Remember me, Lord, with that love
which thou to thine dost bear;
With thy salvation, O my God,
to visit me draw near:

5That I thy chosen''s good may see,
and in their joy rejoice;
And may with thine inheritance
triumph with cheerful voice.

6We with our fathers sinned have,
and of iniquity
Too long we have the workers been;
we have done wickedly.

7The wonders great, which thou, O Lord,
didst work in Egypt land,
Our fathers, though they saw, yet them
they did not understand:

And they thy mercies'' multitude
kept not in memory;
But at the sea, ev''n the Red sea,
provok''d him grievously.

8Nevertheless he saved them,
ev''n for his own name''s sake;
That so he might to be well known
his mighty power make.

9When he the Red sea did rebuke,
then dried up it was:
Through depths, as through the wilderness,
he safely made them pass.

10From hands of those that hated them
he did his people save;
And from the en''my''s cruel hand
to them redemption gave.

11The waters overwhelm''d their foes;
not one was left alive.
12Then they believ''d his word,
and praise to him in songs did give.

13But soon did they his mighty works
forget unthankfully,
And on his counsel and his will
did not wait patiently;

14But much did lust in wilderness,
and God in desert tempt.
15He gave them what they sought, but to
their soul he leanness sent.

16And against Moses in the camp
their envy did appear;
At Aaron they, the saint of God,
envious also were.

17Therefore the earth did open wide,
and Dathan did devour,
And all Abiram''s company
did cover in that hour.

18Likewise among their company
a fire was kindled then;
And so the hot consuming flame
burnt up these wicked men.

19Upon the hill of Horeb they
an idol-calf did frame,
A molten image they did make,
and worshipped the same.

20And thus their glory, and their God,
most vainly changed they
Into the likeness of an ox
that eateth grass or hay.

21They did forget the mighty God,
that had their saviour been,
By whom such great things brought to pass
they had in Egypt seen.

22In Ham''s land he did wondrous works,
things terrible did he,
When he his mighty hand and arm
stretch''d out at the Red sea.

23Then said he, He would them destroy,
had not, his wrath to stay,
His chosen Moses stood in breach,
that them he should not slay.

24Yea, they despis''d the pleasant land,
believed not his word:
25But in their tents they murmured,
not heark''ning to the Lord.

26Therefore in desert them to slay
he lifted up his hand:
27''Mong nations to o''erthrow their seed,
and scatter in each land.

28They unto Baal-peor did
themselves associate;
The sacrifices of the dead
they did profanely eat.

29Thus, by their lewd inventions,
they did provoke his ire;
And then upon them suddenly
the plague brake in as fire.

30Then Phin''has rose, and justice did,
and so the plague did cease;
31That to all ages counted was
to him for righteousness.

32And at the waters, where they strove,
they did him angry make,
In such sort, that it fared ill
with Moses for their sake:

33Because they there his spirit meek
provoked bitterly,
So that he utter''d with his lips
words unadvisedly.

34Nor, as the Lord commanded them,
did they the nations slay:
35But with the heathen mingled were,
and learn''d of them their way.

36And they their idols serv''d, which did
a snare unto them turn.
37Their sons and daughters they to dev''ls
in sacrifice did burn.

38In their own children''s guiltless blood
their hands they did imbrue,
Whom to Canaan''s idols they
for sacrifices slew:

So was the land defil''d with blood.
39They stain''d with their own way,
And with their own inventions
a whoring they did stray.

40Against his people kindled was
the wrath of God therefore,
Insomuch that he did his own
inheritance abhor.

41He gave them to the heathen''s hand;
their foes did them command.
42Their en''mies them oppress''d, they were
made subject to their hand.

43He many times deliver''d them;
but with their counsel so
They him provok''d, that for their sin
they were brought very low.

44Yet their affliction he beheld,
when he did hear their cry:
45And he for them his covenant
did call to memory;

After his mercies'' multitude
46he did repent: And made
Them to be pity''d of all those
who did them captive lead.

47O Lord our God, us save,
and gather the heathen from among,
That we thy holy name may praise
in a triumphant song.

48Bless''d be JEHOVAH, Isr''el''s God,
to all eternity:
Let all the people say, Amen.
Praise to the Lord give ye.', '[{"index": 0, "lines": [{"text": "Give praise and thanks unto the Lord,", "bibleVerseRef": 1}, {"text": "for bountiful is he;"}, {"text": "His tender mercy doth endure"}, {"text": "unto eternity.", "syllables": ["un-", "to", "ete-", "r-", "ni-", "ty."]}]}, {"index": 1, "lines": [{"text": "God''s mighty works who can express?", "bibleVerseRef": 2}, {"text": "or shew forth all his praise?"}, {"text": "Blessed are they that judgment keep,", "bibleVerseRef": 3}, {"text": "and justly do always."}]}, {"index": 2, "lines": [{"text": "Remember me, Lord, with that love", "bibleVerseRef": 4}, {"text": "which thou to thine dost bear;"}, {"text": "With thy salvation, O my God,"}, {"text": "to visit me draw near:"}]}, {"index": 3, "lines": [{"text": "That I thy chosen''s good may see,", "syllables": ["That", "I", "thy", "chose-", "n''s", "good", "may", "see,"], "bibleVerseRef": 5}, {"text": "and in their joy rejoice;"}, {"text": "And may with thine inheritance", "syllables": ["And", "may", "with", "thine", "inhe-", "ri-", "tan-", "ce"]}, {"text": "triumph with cheerful voice.", "syllables": ["triu-", "mph", "with", "cheer-", "ful", "voice."]}]}, {"index": 4, "lines": [{"text": "We with our fathers sinned have,", "bibleVerseRef": 6}, {"text": "and of iniquity"}, {"text": "Too long we have the workers been;"}, {"text": "we have done wickedly."}]}, {"index": 5, "lines": [{"text": "The wonders great, which thou, O Lord,", "bibleVerseRef": 7}, {"text": "didst work in Egypt land,"}, {"text": "Our fathers, though they saw, yet them"}, {"text": "they did not understand:"}]}, {"index": 6, "lines": [{"text": "And they thy mercies'' multitude"}, {"text": "kept not in memory;"}, {"text": "But at the sea, ev''n the Red sea,"}, {"text": "provok''d him grievously."}]}, {"index": 7, "lines": [{"text": "Nevertheless he saved them,", "syllables": ["ne-", "ver-", "thele-", "ss", "he", "sa-", "ved", "them,"], "bibleVerseRef": 8}, {"text": "ev''n for his own name''s sake;"}, {"text": "That so he might to be well known"}, {"text": "his mighty power make.", "syllables": ["his", "mig-", "hty", "powe-", "r", "make."]}]}, {"index": 8, "lines": [{"text": "When he the Red sea did rebuke,", "bibleVerseRef": 9}, {"text": "then dried up it was:", "syllables": ["then", "drie-", "d", "up", "it", "was:"]}, {"text": "Through depths, as through the wilderness,"}, {"text": "he safely made them pass."}]}, {"index": 9, "lines": [{"text": "From hands of those that hated them", "bibleVerseRef": 10}, {"text": "he did his people save;", "syllables": ["he", "did", "his", "peo-", "ple", "save;"]}, {"text": "And from the en''my''s cruel hand", "syllables": ["And", "from", "the", "en-", "''my-", "''s", "cruel", "hand"]}, {"text": "to them redemption gave."}]}, {"index": 10, "lines": [{"text": "The waters overwhelm''d their foes;", "syllables": ["The", "wate-", "rs", "over-", "whe-", "lm''d", "their", "foes;"], "bibleVerseRef": 11}, {"text": "not one was left alive."}, {"text": "Then they believ''d his word,", "syllables": ["Then", "they", "be-", "lie-", "v''d", "his", "wo-", "rd,"], "bibleVerseRef": 12}, {"text": "and praise to him in songs did give.", "syllables": ["and", "praise", "to", "him", "in", "songsdidgive."]}]}, {"index": 11, "lines": [{"text": "But soon did they his mighty works", "bibleVerseRef": 13}, {"text": "forget unthankfully,"}, {"text": "And on his counsel and his will"}, {"text": "did not wait patiently;"}]}, {"index": 12, "lines": [{"text": "But much did lust in wilderness,", "bibleVerseRef": 14}, {"text": "and God in desert tempt."}, {"text": "He gave them what they sought, but to", "bibleVerseRef": 15}, {"text": "their soul he leanness sent."}]}, {"index": 13, "lines": [{"text": "And against Moses in the camp", "syllables": ["And", "a-", "gai-", "nst", "Moses", "in", "the", "camp"], "bibleVerseRef": 16}, {"text": "their envy did appear;"}, {"text": "At Aaron they, the saint of God,"}, {"text": "envious also were.", "syllables": ["en-", "viou-", "s", "al-", "so", "were."]}]}, {"index": 14, "lines": [{"text": "Therefore the earth did open wide,", "syllables": ["there-", "-", "fore", "the", "earth", "did", "open", "wide,"], "bibleVerseRef": 17}, {"text": "and Dathan did devour,"}, {"text": "And all Abiram''s company"}, {"text": "did cover in that hour.", "syllables": ["did", "cove-", "r", "in", "that", "hour."]}]}, {"index": 15, "lines": [{"text": "Likewise among their company", "bibleVerseRef": 18}, {"text": "a fire was kindled then;"}, {"text": "And so the hot consuming flame", "syllables": ["And", "so", "the", "hot", "consu-", "ming", "fla-", "me"]}, {"text": "burnt up these wicked men."}]}, {"index": 16, "lines": [{"text": "Upon the hill of Horeb they", "syllables": ["u-", "pon", "the", "hill", "of", "Hore-", "b", "they"], "bibleVerseRef": 19}, {"text": "an idol-calf did frame,", "syllables": ["an", "idol-", "-calf", "did", "fra-", "me,"]}, {"text": "A molten image they did make,"}, {"text": "and worshipped the same."}]}, {"index": 17, "lines": [{"text": "And thus their glory, and their God,", "bibleVerseRef": 20}, {"text": "most vainly changed they"}, {"text": "Into the likeness of an ox"}, {"text": "that eateth grass or hay."}]}, {"index": 18, "lines": [{"text": "They did forget the mighty God,", "bibleVerseRef": 21}, {"text": "that had their saviour been,"}, {"text": "By whom such great things brought to pass"}, {"text": "they had in Egypt seen."}]}, {"index": 19, "lines": [{"text": "In Ham''s land he did wondrous works,", "bibleVerseRef": 22}, {"text": "things terrible did he,"}, {"text": "When he his mighty hand and arm"}, {"text": "stretch''d out at the Red sea."}]}, {"index": 20, "lines": [{"text": "Then said he, He would them destroy,", "bibleVerseRef": 23}, {"text": "had not, his wrath to stay,"}, {"text": "His chosen Moses stood in breach,", "syllables": ["His", "chose-", "n", "Moses", "stood", "in", "brea-", "ch,"]}, {"text": "that them he should not slay."}]}, {"index": 21, "lines": [{"text": "Yea, they despis''d the pleasant land,", "bibleVerseRef": 24}, {"text": "believed not his word:"}, {"text": "But in their tents they murmured,", "bibleVerseRef": 25}, {"text": "not heark''ning to the Lord."}]}, {"index": 22, "lines": [{"text": "Therefore in desert them to slay", "bibleVerseRef": 26}, {"text": "he lifted up his hand:"}, {"text": "''Mong nations to o''erthrow their seed,", "bibleVerseRef": 27}, {"text": "and scatter in each land."}]}, {"index": 23, "lines": [{"text": "They unto Baal-peor did", "syllables": ["They", "un-", "to", "baa-", "l-", "-pe-", "or", "did"], "bibleVerseRef": 28}, {"text": "themselves associate;", "syllables": ["themselves", "as-", "so-", "ci-", "a-", "te;"]}, {"text": "The sacrifices of the dead", "syllables": ["The", "sac-", "ri-", "fice-", "s", "of", "the", "dead"]}, {"text": "they did profanely eat.", "syllables": ["they", "did", "profa-", "ne-", "ly", "eat."]}]}, {"index": 24, "lines": [{"text": "Thus, by their lewd inventions,", "syllables": ["Thus,", "by", "their", "lewd", "in-", "ven-", "tio-", "ns,"], "bibleVerseRef": 29}, {"text": "they did provoke his ire;"}, {"text": "And then upon them suddenly"}, {"text": "the plague brake in as fire.", "syllables": ["the", "plague", "brake", "in", "as", "fire."]}]}, {"index": 25, "lines": [{"text": "Then Phin''has rose, and justice did,", "bibleVerseRef": 30}, {"text": "and so the plague did cease;", "syllables": ["and", "so", "the", "plague", "did", "cease;"]}, {"text": "That to all ages counted was", "syllables": ["That", "to", "all", "ages", "cou-", "n-", "ted", "was"], "bibleVerseRef": 31}, {"text": "to him for righteousness."}]}, {"index": 26, "lines": [{"text": "And at the waters, where they strove,", "bibleVerseRef": 32}, {"text": "they did him angry make,"}, {"text": "In such sort, that it fared ill"}, {"text": "with Moses for their sake:", "syllables": ["with", "Mose-", "s", "for", "their", "sake:"]}]}, {"index": 27, "lines": [{"text": "Because they there his spirit meek", "bibleVerseRef": 33}, {"text": "provoked bitterly,"}, {"text": "So that he utter''d with his lips"}, {"text": "words unadvisedly."}]}, {"index": 28, "lines": [{"text": "Nor, as the Lord commanded them,", "bibleVerseRef": 34}, {"text": "did they the nations slay:"}, {"text": "But with the heathen mingled were,", "bibleVerseRef": 35}, {"text": "and learn''d of them their way."}]}, {"index": 29, "lines": [{"text": "And they their idols serv''d, which did", "bibleVerseRef": 36}, {"text": "a snare unto them turn.", "syllables": ["a", "snare", "un-", "to", "them", "turn."]}, {"text": "Their sons and daughters they to dev''ls", "bibleVerseRef": 37}, {"text": "in sacrifice did burn."}]}, {"index": 30, "lines": [{"text": "In their own children''s guiltless blood", "syllables": ["In", "their", "own", "children''s", "gu-", "i-", "ltless", "blood"], "bibleVerseRef": 38}, {"text": "their hands they did imbrue,"}, {"text": "Whom to Canaan''s idols they", "syllables": ["Whom", "to", "ca-", "naa-", "n''s", "i-", "dols", "they"]}, {"text": "for sacrifices slew:", "syllables": ["for", "sac-", "ri-", "fice-", "s", "slew:"]}]}, {"index": 31, "lines": [{"text": "So was the land defil''d with blood."}, {"text": "They stain''d with their own way,", "bibleVerseRef": 39}, {"text": "And with their own inventions", "syllables": ["And", "with", "thei-", "r", "own", "in-", "ven-", "tions"]}, {"text": "a whoring they did stray."}]}, {"index": 32, "lines": [{"text": "Against his people kindled was", "syllables": ["against", "his", "pe-", "o-", "ple", "kin-", "dled", "was"], "bibleVerseRef": 40}, {"text": "the wrath of God therefore,"}, {"text": "Insomuch that he did his own"}, {"text": "inheritance abhor.", "syllables": ["inhe-", "ri-", "tan-", "ce", "a-", "bhor."]}]}, {"index": 33, "lines": [{"text": "He gave them to the heathen''s hand;", "bibleVerseRef": 41}, {"text": "their foes did them command."}, {"text": "Their en''mies them oppress''d, they were", "bibleVerseRef": 42}, {"text": "made subject to their hand."}]}, {"index": 34, "lines": [{"text": "He many times deliver''d them;", "bibleVerseRef": 43}, {"text": "but with their counsel so"}, {"text": "They him provok''d, that for their sin"}, {"text": "they were brought very low."}]}, {"index": 35, "lines": [{"text": "Yet their affliction he beheld,", "bibleVerseRef": 44}, {"text": "when he did hear their cry:"}, {"text": "And he for them his covenant", "syllables": ["And", "he", "for", "them", "his", "cove-", "-", "nant"], "bibleVerseRef": 45}, {"text": "did call to memory;"}]}, {"index": 36, "lines": [{"text": "After his mercies'' multitude"}, {"text": "he did repent: And made", "syllables": ["he", "did", "repe-", "nt:", "And", "made"], "bibleVerseRef": 46}, {"text": "Them to be pity''d of all those"}, {"text": "who did them captive lead."}]}, {"index": 37, "lines": [{"text": "O Lord our God, us save,", "syllables": ["O", "Lord", "our", "God,", "us", "save-", "-", ","], "bibleVerseRef": 47}, {"text": "and gather the heathen from among,", "syllables": ["and", "gather", "the", "heathen", "from", "among,"]}, {"text": "That we thy holy name may praise"}, {"text": "in a triumphant song.", "syllables": ["in", "a", "triu-", "m-", "phant", "song."]}]}, {"index": 38, "lines": [{"text": "Bless''d be JEHOVAH, Isr''el''s God,", "bibleVerseRef": 48}, {"text": "to all eternity:", "syllables": ["to", "all", "ete-", "r-", "ni-", "ty:"]}, {"text": "Let all the people say, Amen."}, {"text": "Praise to the Lord give ye."}]}]', 'CM', NULL, 'Give praise and thanks unto the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (108, 'reccSebllSt8Ycch9', 61, '61', '1O God, give ear unto my cry;
unto my pray''r attend.
2From th'' utmost corner of the land
my cry to thee I''ll send.

What time my heart is overwhelm''d,
and in perplexity,
Do thou me lead unto the Rock
that higher is than I.

3For thou hast for my refuge been
a shelter by thy pow''r;
And for defence against my foes
thou hast been a strong tow''r.

4Within thy tabernacle I
for ever will abide;
And under covert of thy wings
with confidence me hide.

5For thou the vows that I did make,
O Lord my God, didst hear:
Thou hast giv''n me the heritage
of those thy name that fear.

6A life prolong''d for many days
thou to the king shalt give;
Like many generations be
the years which he shall live.

7He in God''s presence his abode
for evermore shall have:
O do thou truth and mercy both
prepare, that may him save.

8And so will I perpetually
sing praise unto thy name;
That having made my vows, I may
each day perform the same.', '[{"index": 0, "lines": [{"text": "O God, give ear unto my cry;", "bibleVerseRef": 1}, {"text": "unto my pray''r attend."}, {"text": "From th'' utmost corner of the land", "syllables": ["From", "th''", "utmost", "cor-", "ner", "of", "the", "land"], "bibleVerseRef": 2}, {"text": "my cry to thee I''ll send."}]}, {"index": 1, "lines": [{"text": "What time my heart is overwhelm''d,", "syllables": ["What", "time", "my", "heart", "is", "over-", "whe-", "lm''d,"]}, {"text": "and in perplexity,"}, {"text": "Do thou me lead unto the Rock"}, {"text": "that higher is than I."}]}, {"index": 2, "lines": [{"text": "For thou hast for my refuge been", "bibleVerseRef": 3}, {"text": "a shelter by thy pow''r;"}, {"text": "And for defence against my foes"}, {"text": "thou hast been a strong tow''r."}]}, {"index": 3, "lines": [{"text": "Within thy tabernacle I", "syllables": ["wi-", "thin", "thy", "tabe-", "r-", "nac-", "le", "I"], "bibleVerseRef": 4}, {"text": "for ever will abide;", "syllables": ["for", "ever", "will", "a-", "bide-", ";"]}, {"text": "And under covert of thy wings", "syllables": ["And", "un-", "der", "cove-", "rt", "of", "thy", "wings"]}, {"text": "with confidence me hide.", "syllables": ["with", "confi-", "den-", "ce", "me", "hide."]}]}, {"index": 4, "lines": [{"text": "For thou the vows that I did make,", "bibleVerseRef": 5}, {"text": "O Lord my God, didst hear:"}, {"text": "Thou hast giv''n me the heritage"}, {"text": "of those thy name that fear."}]}, {"index": 5, "lines": [{"text": "A life prolong''d for many days", "bibleVerseRef": 6}, {"text": "thou to the king shalt give;"}, {"text": "Like many generations be"}, {"text": "the years which he shall live."}]}, {"index": 6, "lines": [{"text": "He in God''s presence his abode", "bibleVerseRef": 7}, {"text": "for evermore shall have:", "syllables": ["for", "eve-", "r-", "more", "shall", "have:"]}, {"text": "O do thou truth and mercy both"}, {"text": "prepare, that may him save."}]}, {"index": 7, "lines": [{"text": "And so will I perpetually", "syllables": ["And", "so", "will", "I", "perpe-", "tu-", "a-", "lly"], "bibleVerseRef": 8}, {"text": "sing praise unto thy name;"}, {"text": "That having made my vows, I may"}, {"text": "each day perform the same."}]}]', 'CM', NULL, 'O God, give ear unto my cry...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (109, 'reccWShN5ntvN9PIG', 18, '18', '1Thee will I love, O Lord, my strength.
2My fortress is the Lord,
My rock, and he that doth to me
deliverance afford:

My God, my strength, whom I will trust,
a buckler unto me,
The horn of my salvation,
and my high tow''r, is he.

3Upon the Lord, who worthy is
of praises, will I cry;
And then shall I preserved be
safe from mine enemy.

4Floods of ill men affrighted me,
death''s pangs about me went;
5Hell''s sorrows me environed;
death''s snares did me prevent.

6In my distress I call''d on God,
cry to my God did I;
He from his temple heard my voice,
to his ears came my cry.

7Th'' earth, as affrighted, then did shake,
trembling upon it seiz''d:
The hills'' foundations moved were,
because he was displeas''d.

8Up from his nostrils came a smoke,
and from his mouth there came
Devouring fire, and coals by it
were turned into flame.

9He also bowed down the heav''ns,
and thence he did descend;
And thickest clouds of darkness did
under his feet attend.

10And he upon a cherub rode,
and thereon he did fly;
Yea, on the swift wings of the wind
his flight was from on high.

11He darkness made his secret place:
about him, for his tent,
Dark waters were, and thickest clouds
of th'' airy firmament.

12And at the brightness of that light,
which was before his eye,
His thick clouds pass''d away, hailstones
and coals of fire did fly.

13The Lord God also in the heav''ns
did thunder in his ire;
And there the Highest gave his voice,
hailstones and coals of fire.

14Yea, he his arrows sent abroad,
and them he scattered;
His lightnings also he shot out,
and them discomfited.

15The waters'' channels then were seen,
the world''s foundations vast
At thy rebuke discover''d were,
and at thy nostrils'' blast.

16And from above the Lord sent down,
and took me from below;
From many waters he me drew,
which would me overflow.

17He me reliev''d from my strong foes,
and such as did me hate;
Because he saw that they for me
too strong were, and too great.

18They me prevented in the day
of my calamity;
But even then the Lord himself
a stay was unto me.

19He to a place where liberty
and room was hath me brought;
Because he took delight in me,
he my deliv''rance wrought.

20According to my righteousness
he did me recompense,
He me repaid according to
my hands'' pure innocence.

21For I God''s ways kept, from my God
did not turn wickedly.
22His judgments were before me, I
his laws put not from me.

23Sincere before him was my heart;
with him upright was I;
And watchfully I kept myself
from mine iniquity.

24After my righteousness the Lord
hath recompensed me,
After the cleanness of my hands
appearing in his eye.

25Thou gracious to the gracious art,
to upright men upright:
26Pure to the pure, froward thou kyth''st
unto the froward wight.

27For thou wilt the afflicted save
in grief that low do lie:
But wilt bring down the countenance
of them whose looks are high.

28The Lord will light my candle so,
that it shall shine full bright:
The Lord my God will also make
my darkness to be light.

29By thee through troops of men I break,
and them discomfit all;
And, by my God assisting me,
I overleap a wall.

30As for God, perfect is his way:
the Lord his word is try''d;
He is a buckler to all those
who do in him confide.

31Who but the Lord is God? but he
who is a rock and stay?
32''Tis God that girdeth me with strength,
and perfect makes my way.

33He made my feet swift as the hinds,
set me on my high places.
34Mine hands to war he taught, mine arms
brake bows of steel in pieces.

35The shield of thy salvation
thou didst on me bestow:
Thy right hand held me up, and great
thy kindness made me grow.

36And in my way my steps thou hast
enlarged under me,
That I go safely, and my feet
are kept from sliding free.

37Mine en''mies I pursued have,
and did them overtake;
Nor did I turn again till I
an end of them did make.

38I wounded them, they could not rise;
they at my feet did fall.
39Thou girdedst me with strength for war;
my foes thou brought''st down all:

40And thou hast giv''n to me the necks
of all mine enemies;
That I might them destroy and slay,
who did against me rise.

41They cried out, but there was none
that would or could them save;
Yea, they did cry unto the Lord,
but he no answer gave.

42Then did I beat them small as dust
before the wind that flies;
And I did cast them out like dirt
upon the street that lies.

43Thou mad''st me free from people''s strife,
and heathen''s head to be:
A people whom I have not known
shall service do to me.

44At hearing they shall me obey,
to me they shall submit.
45Strangers for fear shall fade away,
who in close places sit.

46God lives, bless''d be my Rock; the God
of my health praised be.
47God doth avenge me, and subdues
the people under me.

48He saves me from mine enemies;
yea, thou hast lifted me
Above my foes; and from the man
of vi''lence set me free.

49Therefore to thee will I give thanks
the heathen folk among;
And to thy name, O Lord, I will
sing praises in a song.

50He great deliv''rance gives his king:
he mercy doth extend
To David, his anointed one,
and his seed without end.', '[{"index": 0, "lines": [{"text": "Thee will I love, O Lord, my strength.", "bibleVerseRef": 1}, {"text": "My fortress is the Lord,", "bibleVerseRef": 2}, {"text": "My rock, and he that doth to me"}, {"text": "deliverance afford:", "syllables": ["deli-", "ve-", "ran-", "ce", "af-", "ford:"]}]}, {"index": 1, "lines": [{"text": "My God, my strength, whom I will trust,"}, {"text": "a buckler unto me,"}, {"text": "The horn of my salvation,", "syllables": ["The", "horn", "of", "my", "sal-", "va-", "tio-", "n,"]}, {"text": "and my high tow''r, is he."}]}, {"index": 2, "lines": [{"text": "Upon the Lord, who worthy is", "bibleVerseRef": 3}, {"text": "of praises, will I cry;", "syllables": ["of", "praise-", "s,", "will", "I", "cry;"]}, {"text": "And then shall I preserved be"}, {"text": "safe from mine enemy."}]}, {"index": 3, "lines": [{"text": "Floods of ill men affrighted me,", "bibleVerseRef": 4}, {"text": "death''s pangs about me went;"}, {"text": "Hell''s sorrows me environed;", "bibleVerseRef": 5}, {"text": "death''s snares did me prevent."}]}, {"index": 4, "lines": [{"text": "In my distress I call''d on God,", "bibleVerseRef": 6}, {"text": "cry to my God did I;"}, {"text": "He from his temple heard my voice,", "syllables": ["He", "from", "his", "te-", "mple", "heard", "my", "voice,"]}, {"text": "to his ears came my cry."}]}, {"index": 5, "lines": [{"text": "Th'' earth, as affrighted, then did shake,", "syllables": ["Th''", "earth,", "as", "affrig-", "hted,", "then", "did", "shake,"], "bibleVerseRef": 7}, {"text": "trembling upon it seiz''d:"}, {"text": "The hills'' foundations moved were,"}, {"text": "because he was displeas''d."}]}, {"index": 6, "lines": [{"text": "Up from his nostrils came a smoke,", "syllables": ["Up", "from", "his", "nostrils", "came", "a", "smo-", "ke,"], "bibleVerseRef": 8}, {"text": "and from his mouth there came"}, {"text": "Devouring fire, and coals by it", "syllables": ["devou-", "ring", "fire,", "and", "co-", "als", "by", "it"]}, {"text": "were turned into flame.", "syllables": ["were", "turned", "in-", "to", "fla-", "me."]}]}, {"index": 7, "lines": [{"text": "He also bowed down the heav''ns,", "bibleVerseRef": 9}, {"text": "and thence he did descend;"}, {"text": "And thickest clouds of darkness did"}, {"text": "under his feet attend."}]}, {"index": 8, "lines": [{"text": "And he upon a cherub rode,", "bibleVerseRef": 10}, {"text": "and thereon he did fly;"}, {"text": "Yea, on the swift wings of the wind"}, {"text": "his flight was from on high."}]}, {"index": 9, "lines": [{"text": "He darkness made his secret place:", "syllables": ["He", "darkness", "made", "his", "sec-", "ret", "pla-", "ce:"], "bibleVerseRef": 11}, {"text": "about him, for his tent,"}, {"text": "Dark waters were, and thickest clouds", "syllables": ["Dark", "wate-", "rs", "were,", "and", "thic-", "kest", "clouds"]}, {"text": "of th'' airy firmament.", "syllables": ["of", "th''", "airy", "fir-", "ma-", "ment."]}]}, {"index": 10, "lines": [{"text": "And at the brightness of that light,", "bibleVerseRef": 12}, {"text": "which was before his eye,"}, {"text": "His thick clouds pass''d away, hailstones", "syllables": ["His", "thick", "clouds", "pass''d", "away,", "hail-", "sto-", "nes"]}, {"text": "and coals of fire did fly.", "syllables": ["and", "coals", "of", "fire", "did", "fly."]}]}, {"index": 11, "lines": [{"text": "The Lord God also in the heav''ns", "bibleVerseRef": 13}, {"text": "did thunder in his ire;"}, {"text": "And there the Highest gave his voice,"}, {"text": "hailstones and coals of fire.", "syllables": ["hailstones", "and", "co-", "als", "of", "fire."]}]}, {"index": 12, "lines": [{"text": "Yea, he his arrows sent abroad,", "syllables": ["Yea,", "he", "his", "arrows", "sent", "ab-", "ro-", "ad,"], "bibleVerseRef": 14}, {"text": "and them he scattered;"}, {"text": "His lightnings also he shot out,"}, {"text": "and them discomfited."}]}, {"index": 13, "lines": [{"text": "The waters'' channels then were seen,", "syllables": ["The", "wate-", "rs''", "chan-", "nels", "then", "were", "seen,"], "bibleVerseRef": 15}, {"text": "the world''s foundations vast"}, {"text": "At thy rebuke discover''d were,"}, {"text": "and at thy nostrils'' blast."}]}, {"index": 14, "lines": [{"text": "And from above the Lord sent down,", "bibleVerseRef": 16}, {"text": "and took me from below;"}, {"text": "From many waters he me drew,", "syllables": ["From", "ma-", "ny", "wate-", "rs", "he", "me", "drew,"]}, {"text": "which would me overflow.", "syllables": ["whi-", "ch", "would", "me", "over-", "flow."]}]}, {"index": 15, "lines": [{"text": "He me reliev''d from my strong foes,", "bibleVerseRef": 17}, {"text": "and such as did me hate;"}, {"text": "Because he saw that they for me"}, {"text": "too strong were, and too great."}]}, {"index": 16, "lines": [{"text": "They me prevented in the day", "bibleVerseRef": 18}, {"text": "of my calamity;"}, {"text": "But even then the Lord himself", "syllables": ["But", "eve-", "n", "then", "the", "Lord", "him-", "self"]}, {"text": "a stay was unto me."}]}, {"index": 17, "lines": [{"text": "He to a place where liberty", "bibleVerseRef": 19}, {"text": "and room was hath me brought;"}, {"text": "Because he took delight in me,"}, {"text": "he my deliv''rance wrought.", "syllables": ["he", "my", "deliv-", "''ran-", "ce", "wrought."]}]}, {"index": 18, "lines": [{"text": "According to my righteousness", "bibleVerseRef": 20}, {"text": "he did me recompense,", "syllables": ["he", "did", "me", "recom-", "pen-", "se,"]}, {"text": "He me repaid according to"}, {"text": "my hands'' pure innocence.", "syllables": ["my", "hands''", "pure", "inno-", "cen-", "ce."]}]}, {"index": 19, "lines": [{"text": "For I God''s ways kept, from my God", "bibleVerseRef": 21}, {"text": "did not turn wickedly."}, {"text": "His judgments were before me, I", "bibleVerseRef": 22}, {"text": "his laws put not from me."}]}, {"index": 20, "lines": [{"text": "Sincere before him was my heart;", "syllables": ["since-", "re", "be-", "fore", "him", "was", "my", "heart;"], "bibleVerseRef": 23}, {"text": "with him upright was I;"}, {"text": "And watchfully I kept myself", "syllables": ["And", "wat-", "chfu-", "l-", "ly", "I", "kept", "myself"]}, {"text": "from mine iniquity."}]}, {"index": 21, "lines": [{"text": "After my righteousness the Lord", "bibleVerseRef": 24}, {"text": "hath recompensed me,"}, {"text": "After the cleanness of my hands"}, {"text": "appearing in his eye."}]}, {"index": 22, "lines": [{"text": "Thou gracious to the gracious art,", "bibleVerseRef": 25}, {"text": "to upright men upright:"}, {"text": "Pure to the pure, froward thou kyth''st", "bibleVerseRef": 26}, {"text": "unto the froward wight."}]}, {"index": 23, "lines": [{"text": "For thou wilt the afflicted save", "bibleVerseRef": 27}, {"text": "in grief that low do lie:"}, {"text": "But wilt bring down the countenance", "syllables": ["But", "wilt", "bring", "down", "the", "counte-", "nan-", "ce"]}, {"text": "of them whose looks are high."}]}, {"index": 24, "lines": [{"text": "The Lord will light my candle so,", "bibleVerseRef": 28}, {"text": "that it shall shine full bright:"}, {"text": "The Lord my God will also make"}, {"text": "my darkness to be light."}]}, {"index": 25, "lines": [{"text": "By thee through troops of men I break,", "bibleVerseRef": 29}, {"text": "and them discomfit all;"}, {"text": "And, by my God assisting me,"}, {"text": "I overleap a wall.", "syllables": ["I", "ove-", "r-", "leap", "a", "wall."]}]}, {"index": 26, "lines": [{"text": "As for God, perfect is his way:", "bibleVerseRef": 30}, {"text": "the Lord his word is try''d;"}, {"text": "He is a buckler to all those"}, {"text": "who do in him confide."}]}, {"index": 27, "lines": [{"text": "Who but the Lord is God? but he", "bibleVerseRef": 31}, {"text": "who is a rock and stay?"}, {"text": "''Tis God that girdeth me with strength,", "bibleVerseRef": 32}, {"text": "and perfect makes my way."}]}, {"index": 28, "lines": [{"text": "He made my feet swift as the hinds,", "bibleVerseRef": 33}, {"text": "set me on my high places.", "syllables": ["set", "me", "on", "my", "high", "places."]}, {"text": "Mine hands to war he taught, mine arms", "bibleVerseRef": 34}, {"text": "brake bows of steel in pieces.", "syllables": ["brake", "bows", "of", "steel", "in", "pieces."]}]}, {"index": 29, "lines": [{"text": "The shield of thy salvation", "syllables": ["The", "shie-", "ld", "of", "thy", "sal-", "va-", "tion"], "bibleVerseRef": 35}, {"text": "thou didst on me bestow:"}, {"text": "Thy right hand held me up, and great"}, {"text": "thy kindness made me grow."}]}, {"index": 30, "lines": [{"text": "And in my way my steps thou hast", "bibleVerseRef": 36}, {"text": "enlarged under me,"}, {"text": "That I go safely, and my feet"}, {"text": "are kept from sliding free."}]}, {"index": 31, "lines": [{"text": "Mine en''mies I pursued have,", "syllables": ["Mine", "en-", "''mie-", "s", "I", "pur-", "sued", "have,"], "bibleVerseRef": 37}, {"text": "and did them overtake;", "syllables": ["and", "did", "them", "ove-", "r-", "take;"]}, {"text": "Nor did I turn again till I"}, {"text": "an end of them did make."}]}, {"index": 32, "lines": [{"text": "I wounded them, they could not rise;", "bibleVerseRef": 38}, {"text": "they at my feet did fall."}, {"text": "Thou girdedst me with strength for war;", "bibleVerseRef": 39}, {"text": "my foes thou brought''st down all:"}]}, {"index": 33, "lines": [{"text": "And thou hast giv''n to me the necks", "bibleVerseRef": 40}, {"text": "of all mine enemies;"}, {"text": "That I might them destroy and slay,"}, {"text": "who did against me rise."}]}, {"index": 34, "lines": [{"text": "They cried out, but there was none", "bibleVerseRef": 41}, {"text": "that would or could them save;"}, {"text": "Yea, they did cry unto the Lord,"}, {"text": "but he no answer gave."}]}, {"index": 35, "lines": [{"text": "Then did I beat them small as dust", "bibleVerseRef": 42}, {"text": "before the wind that flies;"}, {"text": "And I did cast them out like dirt"}, {"text": "upon the street that lies."}]}, {"index": 36, "lines": [{"text": "Thou mad''st me free from people''s strife,", "syllables": ["Thou", "mad''st", "me", "free", "from", "people''s", "stri-", "fe,"], "bibleVerseRef": 43}, {"text": "and heathen''s head to be:"}, {"text": "A people whom I have not known", "syllables": ["A", "peo-", "ple", "whom", "I", "have", "not", "known"]}, {"text": "shall service do to me."}]}, {"index": 37, "lines": [{"text": "At hearing they shall me obey,", "syllables": ["At", "hea-", "ring", "they", "sha-", "ll", "me", "obey,"], "bibleVerseRef": 44}, {"text": "to me they shall submit."}, {"text": "Strangers for fear shall fade away,", "bibleVerseRef": 45}, {"text": "who in close places sit.", "syllables": ["who", "in", "close", "pla-", "ces", "sit."]}]}, {"index": 38, "lines": [{"text": "God lives, bless''d be my Rock; the God", "bibleVerseRef": 46}, {"text": "of my health praised be.", "syllables": ["of", "my", "health", "praise-", "d", "be."]}, {"text": "God doth avenge me, and subdues", "bibleVerseRef": 47}, {"text": "the people under me.", "syllables": ["the", "peo-", "ple", "un-", "der", "me."]}]}, {"index": 39, "lines": [{"text": "He saves me from mine enemies;", "bibleVerseRef": 48}, {"text": "yea, thou hast lifted me"}, {"text": "Above my foes; and from the man"}, {"text": "of vi''lence set me free.", "syllables": ["of", "vi''len-", "ce", "set", "me", "free."]}]}, {"index": 40, "lines": [{"text": "Therefore to thee will I give thanks", "bibleVerseRef": 49}, {"text": "the heathen folk among;"}, {"text": "And to thy name, O Lord, I will"}, {"text": "sing praises in a song.", "syllables": ["sing", "praise-", "s", "in", "a", "song."]}]}, {"index": 41, "lines": [{"text": "He great deliv''rance gives his king:", "syllables": ["He", "great", "deliv-", "''ran-", "ce", "gives", "his", "king:"], "bibleVerseRef": 50}, {"text": "he mercy doth extend"}, {"text": "To David, his anointed one,"}, {"text": "and his seed without end."}]}]', 'CM', NULL, 'Thee will I love, O Lord, my strength...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (115, 'recfJeUi09RkKcCWr', 80, '80', '1Hear, Isr''el''s Shepherd! like a flock
thou that dost Joseph guide;
Shine forth, O thou that dost between
the cherubims abide.

2In Ephraim''s, and Benjamin''s
and in Manasseh''s sight,
O come for our salvation;
stir up thy strength and might.

3Turn us again, O Lord our God,
and upon us vouchsafe
To make thy countenance to shine,
and so we shall be safe.

4O Lord of hosts, almighty God,
how long shall kindled be
Thy wrath against the prayer made
by thine own folk to thee?

5Thou tears of sorrow giv''st to them
instead of bread to eat;
Yea, tears instead of drink thou giv''st
to them in measure great.

6Thou makest us a strife unto
our neighbours round about;
Our enemies among themselves
at us do laugh and flout.

7Turn us again, O God of hosts,
and upon us vouchsafe
To make thy countenance to shine,
and so we shall be safe.

8A vine from Egypt brought thou hast,
by thine outstretched hand;
And thou the heathen out didst cast,
to plant it in their land.

9Before it thou a room didst make,
where it might grow and stand;
Thou causedst it deep root to take,
and it did fill the land.

10The mountains vail''d were with its shade,
as with a covering;
Like goodly cedars were the boughs
which out from it did spring.

11Upon the one hand to the sea
her boughs she did out send;
On th'' other side unto the flood
her branches did extend.

12Why hast thou then thus broken down,
and ta''en her hedge away?
So that all passengers do pluck,
and make of her a prey.

13The boar who from the forest comes
doth waste it at his pleasure;
The wild beast of the field also
devours it out of measure.

14O God of hosts, we thee beseech,
return now unto thine;
Look down from heav''n in love, behold,
and visit this thy vine:

15This vineyard, which thine own right hand
hath planted us among;
And that same branch, which for thyself
thou hast made to be strong.

16Burnt up it is with flaming fire,
it also is cut down:
They utterly are perished,
when as thy face doth frown.

17O let thy hand be still upon
the Man of thy right hand,
The Son of man, whom for thyself
thou madest strong to stand.

18So henceforth we will not go back,
nor turn from thee at all:
O do thou quicken us,
and we upon thy name will call.

19Turn us again, Lord God of hosts,
and upon us vouchsafe
To make thy countenance to shine,
and so we shall be safe.', '[{"index": 0, "lines": [{"text": "Hear, Isr''el''s Shepherd! like a flock", "bibleVerseRef": 1}, {"text": "thou that dost Joseph guide;", "syllables": ["thou", "that", "dost", "Joseph", "gui-", "de;"]}, {"text": "Shine forth, O thou that dost between"}, {"text": "the cherubims abide."}]}, {"index": 1, "lines": [{"text": "In Ephraim''s, and Benjamin''s", "syllables": ["In", "ep-", "hrai-", "m''s,", "and", "ben-", "ja-", "min''s"], "bibleVerseRef": 2}, {"text": "and in Manasseh''s sight,"}, {"text": "O come for our salvation;", "syllables": ["O", "come", "for", "our", "sal-", "va-", "tio-", "n;"]}, {"text": "stir up thy strength and might."}]}, {"index": 2, "lines": [{"text": "Turn us again, O Lord our God,", "bibleVerseRef": 3}, {"text": "and upon us vouchsafe", "syllables": ["and", "upon", "us", "vouc-", "hsa-", "fe"]}, {"text": "To make thy countenance to shine,", "syllables": ["To", "make", "thy", "counte-", "nan-", "ce", "to", "shine,"]}, {"text": "and so we shall be safe."}]}, {"index": 3, "lines": [{"text": "O Lord of hosts, almighty God,", "bibleVerseRef": 4}, {"text": "how long shall kindled be"}, {"text": "Thy wrath against the prayer made"}, {"text": "by thine own folk to thee?"}]}, {"index": 4, "lines": [{"text": "Thou tears of sorrow giv''st to them", "bibleVerseRef": 5}, {"text": "instead of bread to eat;"}, {"text": "Yea, tears instead of drink thou giv''st"}, {"text": "to them in measure great."}]}, {"index": 5, "lines": [{"text": "Thou makest us a strife unto", "bibleVerseRef": 6}, {"text": "our neighbours round about;"}, {"text": "Our enemies among themselves", "syllables": ["Our", "ene-", "mies", "a-", "mong", "them-", "sel-", "ves"]}, {"text": "at us do laugh and flout."}]}, {"index": 6, "lines": [{"text": "Turn us again, O God of hosts,", "bibleVerseRef": 7}, {"text": "and upon us vouchsafe", "syllables": ["and", "upon", "us", "vouc-", "hsa-", "fe"]}, {"text": "To make thy countenance to shine,", "syllables": ["To", "make", "thy", "counte-", "nan-", "ce", "to", "shine,"]}, {"text": "and so we shall be safe."}]}, {"index": 7, "lines": [{"text": "A vine from Egypt brought thou hast,", "bibleVerseRef": 8}, {"text": "by thine outstretched hand;"}, {"text": "And thou the heathen out didst cast,"}, {"text": "to plant it in their land."}]}, {"index": 8, "lines": [{"text": "Before it thou a room didst make,", "bibleVerseRef": 9}, {"text": "where it might grow and stand;"}, {"text": "Thou causedst it deep root to take,"}, {"text": "and it did fill the land."}]}, {"index": 9, "lines": [{"text": "The mountains vail''d were with its shade,", "bibleVerseRef": 10}, {"text": "as with a covering;", "syllables": ["as", "with", "a", "cove-", "-", "ring;"]}, {"text": "Like goodly cedars were the boughs"}, {"text": "which out from it did spring."}]}, {"index": 10, "lines": [{"text": "Upon the one hand to the sea", "bibleVerseRef": 11}, {"text": "her boughs she did out send;"}, {"text": "On th'' other side unto the flood", "syllables": ["On", "th''", "other", "side", "un-", "to", "the", "flood"]}, {"text": "her branches did extend."}]}, {"index": 11, "lines": [{"text": "Why hast thou then thus broken down,", "bibleVerseRef": 12}, {"text": "and ta''en her hedge away?"}, {"text": "So that all passengers do pluck,"}, {"text": "and make of her a prey."}]}, {"index": 12, "lines": [{"text": "The boar who from the forest comes", "bibleVerseRef": 13}, {"text": "doth waste it at his pleasure;", "syllables": ["doth", "waste", "it", "at", "his", "pleasure;"]}, {"text": "The wild beast of the field also"}, {"text": "devours it out of measure.", "syllables": ["devours", "it", "out", "of", "mea-", "sure."]}]}, {"index": 13, "lines": [{"text": "O God of hosts, we thee beseech,", "bibleVerseRef": 14}, {"text": "return now unto thine;"}, {"text": "Look down from heav''n in love, behold,"}, {"text": "and visit this thy vine:"}]}, {"index": 14, "lines": [{"text": "This vineyard, which thine own right hand", "syllables":