INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (111, 'recdWcd4A0IzhSfIQ', 119, '119:105-112 (14)', '105Thy word is to my feet a lamp,
and to my path a light.
106I sworn have, and I will perform,
to keep thy judgments right.

107I am with sore affliction
ev''n overwhelm''d, O Lord:
In mercy raise and quicken me,
according to thy word.

108The free-will-off ''rings of my mouth
accept, I thee beseech:
And unto me thy servant, Lord,
thy judgments clearly teach.

109Though still my soul be in my hand,
thy laws I''ll not forget.
110I err''d not from them, though for me
the wicked snares did set.

111I of thy testimonies have
above all things made choice,
To be my heritage for aye;
for they my heart rejoice.

112I carefully inclined have
my heart still to attend;
That I thy statutes may perform
alway unto the end.
', '[{"index": 0, "lines": [{"text": "Thy word is to my feet a lamp,", "bibleVerseRef": 105}, {"text": "and to my path a light."}, {"text": "I sworn have, and I will perform,", "bibleVerseRef": 106}, {"text": "to keep thy judgments right."}]}, {"index": 1, "lines": [{"text": "I am with sore affliction", "syllables": ["I", "am", "with", "sore", "af-", "fli-", "c-", "tion"], "bibleVerseRef": 107}, {"text": "ev''n overwhelm''d, O Lord:", "syllables": ["ev''n", "over-", "whe-", "lm''d,", "O", "Lord:"]}, {"text": "In mercy raise and quicken me,", "syllables": ["In", "mercy", "raise", "and", "qu-", "i-", "cken", "me,"]}, {"text": "according to thy word."}]}, {"index": 2, "lines": [{"text": "The free-will-off ''rings of my mouth", "bibleVerseRef": 108}, {"text": "accept, I thee beseech:"}, {"text": "And unto me thy servant, Lord,"}, {"text": "thy judgments clearly teach."}]}, {"index": 3, "lines": [{"text": "Though still my soul be in my hand,", "bibleVerseRef": 109}, {"text": "thy laws I''ll not forget."}, {"text": "I err''d not from them, though for me", "bibleVerseRef": 110}, {"text": "the wicked snares did set.", "syllables": ["the", "wicked", "sna-", "res", "did", "set."]}]}, {"index": 4, "lines": [{"text": "I of thy testimonies have", "bibleVerseRef": 111}, {"text": "above all things made choice,"}, {"text": "To be my heritage for aye;"}, {"text": "for they my heart rejoice."}]}, {"index": 5, "lines": [{"text": "I carefully inclined have", "bibleVerseRef": 112}, {"text": "my heart still to attend;"}, {"text": "That I thy statutes may perform", "syllables": ["That", "I", "thy", "statu-", "tes", "may", "per-", "form"]}, {"text": "alway unto the end."}]}]', 'CM', 'Part 14', 'Thy word is to my feet a lamp...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (118, 'recgDINwXaCl7FdVT', 21, '21', '1The king in thy great strength, O Lord,
shall very joyful be:
In thy salvation rejoice
