INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (120, 'recgZUjJYiBhbfs8e', 108, '108', '1My heart is fix''d, Lord; I will sing,
and with my glory praise.
2Awake up psaltery and harp;
myself I''ll early raise.

3I''ll praise thee ''mong the people, Lord;
''mong nations sing will I:
4For above heav''n thy mercy''s great,
thy truth doth reach the sky.

5Be thou above the heavens, Lord,
exalted gloriously;
Thy glory all the earth above
be lifted up on high.

6That those who thy beloved are
delivered may be,
O do thou save with thy right hand,
and answer give to me.

7God in his holiness hath said,
Herein I will take pleasure;
Shechem I will divide, and forth
will Succoth''s valley measure.

8Gilead I claim as mine by right;
Manasseh mine shall be;
Ephraim is of my head the strength;
Judah gives laws for me;

9Moab''s my washing-pot; my shoe
I''ll over Edom throw;
Over the land of Palestine
I will in triumph go.

10O who is he will bring me to
the city fortify''d?
O who is he that to the land
of Edom will me guide?

11O God, thou who hadst cast us off,
this thing wilt thou not do?
And wilt not thou, ev''n thou, O God,
forth with our armies go?

12Do thou from trouble give us help,
for helpless is man''s aid.
13Through God we shall do valiantly;
our foes he shall down tread.', '[{"index": 0, "lines": [{"text": "My heart is fix''d, Lord; I will sing,", "bibleVerseRef": 1}, {"text": "and with my glory praise."}, {"text": "Awake up psaltery and harp;", "bibleVerseRef": 2}, {"text": "myself I''ll early raise.", "syllables": ["myse-", "lf", "I''ll", "ear-", "ly", "raise."]}]}, {"index": 1, "lines": [{"text": "I''ll praise thee ''mong the people, Lord;", "syllables": ["I''ll", "praise", "thee", "''mong", "the", "peo-", "ple,", "Lord;"], "bibleVerseRef": 3}, {"text": "''mong nations sing will I:"}, {"text": "For above heav''n thy mercy''s great,", "bibleVerseRef": 4}, {"text": "thy truth doth reach the sky."}]}, {"index": 2, "lines": [{"text": "Be thou above the heavens, Lord,", "syllables": ["Be", "thou", "a-", "bove", "the", "heave-", "ns,", "Lord,"], "bibleVerseRef": 5}, {"text": "exalted gloriously;"}, {"text": "Thy glory all the earth above"}, {"text": "be lifted up on high."}]}, {"index": 3, "lines": [{"text": "That those who thy beloved are", "bibleVerseRef": 6}, {"text": "delivered may be,"}, {"text": "O do thou save with thy right hand,"}, {"text": "and answer give to me."}]}, {"index": 4, "lines": [{"text": "God in his holiness hath said,", "bibleVerseRef": 7}, {"text": "Herein I will take pleasure;", "syllables": ["herein", "I", "will", "take", "plea-", "sure;"]}, {"text": "Shechem I will divide, and forth"}, {"text": "will Succoth''s valley measure.", "syllables": ["will", "succoth''s", "val-", "ley", "mea-", "sure."]}]}, {"index": 5, "lines": [{"text": "Gilead I claim as mine by right;", "syllables": ["Gilea-", "d", "I", "claim", "as", "mine", "by", "right;"], "bibleVerseRef": 8}, {"text": "Manasseh mine shall be;"}, {"text": "Ephraim is of my head the strength;"}, {"text": "Judah gives laws for me;"}]}, {"index": 6, "lines": [{"text": "Moab''s my washing-pot; my shoe", "bibleVerseRef": 9}, {"text": "I''ll over Edom throw;", "syllables": ["I''ll", "over", "e-", "dom", "thro-", "w;"]}, {"text": "Over the land of Palestine", "syllables": ["Over", "the", "land", "of", "pale-", "-", "s-", "tine"]}, {"text": "I will in triumph go.", "syllables": ["I", "will", "in", "triu-", "mph", "go."]}]}, {"index": 7, "lines": [{"text": "O who is he will bring me to", "bibleVerseRef": 10}, {"text": "the city fortify''d?"}, {"text": "O who is he that to the land"}, {"text": "of Edom will me guide?", "syllables": ["of", "edom", "will", "me", "gui-", "de?"]}]}, {"index": 8, "lines": [{"text": "O God, thou who hadst cast us off,", "bibleVerseRef": 11}, {"text": "this thing wilt thou not do?"}, {"text": "And wilt not thou, ev''n thou, O God,"}, {"text": "forth with our armies go?"}]}, {"index": 9, "lines": [{"text": "Do thou from trouble give us help,", "bibleVerseRef": 12}, {"text": "for helpless is man''s aid."}, {"text": "Through God we shall do valiantly;", "syllables": ["Through", "God", "we", "shall", "do", "vali-", "a-", "ntly;"], "bibleVerseRef": 13}, {"text": "our foes he shall down tread."}]}]', 'CM', NULL, 'My heart is fix''d, Lord; I will sing...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (125, 'rechh13aDWXvnNQdV', 51, '51', '1After thy loving-kindness, Lord,
have mercy upon me:
For thy compassions great, blot out
all mine iniquity.

2Me cleanse from sin, and throughly wash
from mine iniquity:
3For my transgressions I confess;
my sin I ever see.

4''Gainst thee, thee only, have I sinn''d,
in thy sight done this ill;
That when thou speak''st thou may''st be just,
and clear in judging still.

5Behold, I in iniquity
was form''d the womb within;
My mother also me conceiv''d
in guiltiness and sin.

6Behold, thou in the inward parts
with truth delighted art;
And wisdom thou shalt make me know
within the hidden part.

7Do thou with hyssop sprinkle me,
I shall be cleansed so;
Yea, wash thou me, and then I shall
be whiter than the snow.

8Of gladness and of joyfulness
make me to hear the voice;
That so these very bones which thou
hast broken may rejoice.

9All mine iniquities blot out,
thy face hide from my sin.
10Create a clean heart, Lord, renew
a right sp''rit me within.

11Cast me not from thy sight, nor take
thy Holy Sp''rit away.
12Restore me thy salvation''s joy;
with thy free Sp''rit me stay.

13Then will I teach thy ways unto
those that transgressors be;
And those that sinners are shall then
be turned unto thee.

14O God, of my salvation God,
me from blood-guiltiness
Set free; then shall my tongue aloud
sing of thy righteousness.

15My closed lips, O Lord, by thee
let them be opened;
Then shall thy praises by my mouth
abroad be published.

16For thou desir''st not sacrifice,
else would I give it thee;
Nor wilt thou with burnt-offering
at all delighted be.

17A broken spirit is to God
a pleasing sacrifice:
A broken and a contrite heart,
Lord, thou wilt not despise.

18Shew kindness, and do good, O Lord,
to Sion, thine own hill:
The walls of thy Jerusalem
build up of thy good will.

19Then righteous off ''rings shall thee please,
and off ''rings burnt, which they
With whole burnt-off ''rings,
and with calves, shall on thine altar lay.', '[{"index": 0, "lines": [{"text": "After thy loving-kindness, Lord,", "bibleVerseRef": 1}, {"text": "have mercy upon me:"}, {"text": "For thy compassions great, blot out"}, {"text": "all mine iniquity."}]}, {"index": 1, "lines": [{"text": "Me cleanse from sin, and throughly wash", "syllables": ["Me", "cleanse", "from", "sin,", "and", "throug-", "hly", "wash"], "bibleVerseRef": 2}, {"text": "from mine iniquity:"}, {"text": "For my transgressions I confess;", "bibleVerseRef": 3}, {"text": "my sin I ever see.", "syllables": ["my", "sin", "I", "eve-", "r", "see."]}]}, {"index": 2, "lines": [{"text": "''Gainst thee, thee only, have I sinn''d,", "bibleVerseRef": 4}, {"text": "in thy sight done this ill;"}, {"text": "That when thou speak''st thou may''st be just,"}, {"text": "and clear in judging still."}]}, {"index": 3, "lines": [{"text": "Behold, I in iniquity", "bibleVerseRef": 5}, {"text": "was form''d the womb within;"}, {"text": "My mother also me conceiv''d"}, {"text": "in guiltiness and sin.", "syllables": ["in", "gui-", "lti-", "ness", "and", "sin."]}]}, {"index": 4, "lines": [{"text": "Behold, thou in the inward parts", "bibleVerseRef": 6}, {"text": "with truth delighted art;"}, {"text": "And wisdom thou shalt make me know"}, {"text": "within the hidden part."}]}, {"index": 5, "lines": [{"text": "Do thou with hyssop sprinkle me,", "bibleVerseRef": 7}, {"text": "I shall be cleansed so;"}, {"text": "Yea, wash thou me, and then I shall"}, {"text": "be whiter than the snow.", "syllables": ["be", "white-", "r", "than", "the", "snow."]}]}, {"index": 6, "lines": [{"text": "Of gladness and of joyfulness", "bibleVerseRef": 8}, {"text": "make me to hear the voice;"}, {"text": "That so these very bones which thou"}, {"text": "hast broken may rejoice."}]}, {"index": 7, "lines": [{"text": "All mine iniquities blot out,", "bibleVerseRef": 9}, {"text": "thy face hide from my sin."}, {"text": "Create a clean heart, Lord, renew", "syll