INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (137, 'reclT7JRxhaFDVQiR', 7, '7', '1O Lord my God, in thee do I
my confidence repose:
Save and deliver me from all
my persecuting foes;

2Lest that the enemy my soul
should, like a lion, tear,
In pieces rending it, while there
is no deliverer.

3O Lord my God, if it be so
that I committed this;
If it be so that in my hands
iniquity there is:

4If I rewarded ill to him
that was at peace with me;
(Yea, ev''n the man that without cause
my foe was I did free;)

5Then let the foe pursue and take
my soul, and my life thrust
Down to the earth,
and let him lay mine honour in the dust.

6Rise in thy wrath, Lord, raise thyself,
for my foes raging be;
And, to the judgment which thou hast
commanded, wake for me.

7So shall th'' assembly of thy folk
about encompass thee:
Thou, therefore, for their sakes, return
unto thy place on high.

8The Lord he shall the people judge:
my judge, JEHOVAH, be,
After my righteousness, and mine
integrity in me.

9O let the wicked''s malice end;
but stablish stedfastly
The righteous: for the righteous God
the hearts and reins doth try.

10In God, who saves th'' upright in heart,
is my defence and stay.
11God just men judgeth, God is wroth
with ill men ev''ry day.

12If he do not return again,
then he his sword will whet;
His bow he hath already bent,
and hath it ready set:

13He also hath for him prepar''d
the instruments of death;
Against the persecutors he
his shafts ordained hath.

14Behold, he with iniquity
doth travail, as in birth;
A mischief he conceived hath,
and falsehood shall bring forth.

15He made a pit and digg''d it deep,
another there to take;
But he is fall''n into the ditch
which he himself did make.

16Upon his own head his mischief
shall be returned home;
His vi''lent dealing also down
on his own pate shall come.

17According to his righteousness
the Lord I''ll magnify;
And will sing praise unto the name
of God that is most high.', '[{"index": 0, "lines": [{"text": "O Lord my God, in thee do I", "bibleVerseRef": 1}, {"text": "my confidence repose:", "syllables": ["my", "confi-", "den-", "ce", "re-", "pose:"]}, {"text": "Save and deliver me from all", "syllables": ["Save", "and", "de-", "live-", "r", "me", "from", "all"]}, {"text": "my persecuting foes;"}]}, {"index": 1, "lines": [{"text": "Lest that the enemy my soul", "bibleVerseRef": 2}, {"text": "should, like a lion, tear,", "syllables": ["shou-", "ld,", "like", "a", "lion,", "tear,"]}, {"text": "In pieces rending it, while there", "syllables": ["In", "piece-", "s", "ren-", "ding", "it,", "while", "there"]}, {"text": "is no deliverer."}]}, {"index": 2, "lines": [{"text": "O Lord my God, if it be so", "bibleVerseRef": 3}, {"text": "that I committed this;"}, {"text": "If it be so that in my hands"}, {"text": "iniquity there is:"}]}, {"index": 3, "lines": [{"text": "If I rewarded ill to him", "bibleVerseRef": 4}, {"text": "that was at peace with me;"}, {"text": "(Yea, ev''n the man that without cause"}, {"text": "my foe was I did free;)"}]}, {"index": 4, "lines": [{"text": "Then let the foe pursue and take", "bibleVerseRef": 5}, {"text": "my soul, and my life thrust"}, {"text": "Down to the earth,", "syllables": ["Do-", "-", "-", "wn", "to", "the", "ea-", "rth,"]}, {"text": "and let him lay mine honour in the dust.", "syllables": ["and", "let", "him", "lay", "mine", "honourinthedust."]}]}, {"index": 5, "lines": [{"text": "Rise in thy wrath, Lord, raise thyself,", "syllables": ["Rise", "in", "thy", "wrath,", "Lord,", "raise", "thyse-", "lf,"], "bibleVerseRef": 6}, {"text": "for my foes raging be;"}, {"text": "And, to the judgment which thou hast"}, {"text": "commanded, wake for me."}]}, {"index": 6, "lines": [{"text": "So shall th'' assembly of thy folk", "syllables": ["So", "shall", "th''", "assem-", "bly", "of", "thy", "folk"], "bibleVerseRef": 7}, {"text": "about encompass thee:"}, {"text": "Thou, therefore, for their sakes, return"}, {"text": "unto thy place on high.", "syllables": ["unto", "thy", "pla-", "ce", "on", "high."]}]}, {"index": 7, "lines": [{"text": "The Lord he shall the people judge:", "syllables": ["The", "Lord", "he", "shall", "the", "people", "jud-", "ge:"], "bibleVerseRef": 8}, {"text": "my judge, JEHOVAH, be,", "syllables": ["my", "judge,", "je-", "ho-", "vah,", "be,"]}, {"text": "After my righteousness, and mine"}, {"text": "integrity in me."}]}, {"index": 8, "lines": [{"text": "O let the wicked''s malice end;", "bibleVerseRef": 9}, {"text": "but stablish stedfastly"}, {"text": "The righteous: for the righteous God"}, {"text": "the hearts and reins doth try."}]}, {"index": 9, "lines": [{"text": "In God, who saves th'' upright in heart,", "syllables": ["In", "God,", "who", "saves", "th''", "upright", "in", "heart,"], "bibleVerseRef": 10}, {"text": "is my defence and stay."}, {"text": "God just men judgeth, God is wroth", "bibleVerseRef": 11}, {"text": "with ill men ev''ry day."}]}, {"index": 10, "lines": [{"text": "If he do not return again,", "bibleVerseRef": 12}, {"text": "then he his sword will whet;"}, {"text": "His bow he hath already bent,"}, {"text": "and hath it ready set:"}]}, {"index": 11, "lines": [{"text": "He also hath for him prepar''d", "bibleVerseRef": 13}, {"text": "the instruments of death;"}, {"text": "Against the persecutors he"}, {"text": "his shafts ordained hath."}]}, {"index": 12, "lines": [{"text": "Behold, he with iniquity", "bibleVerseRef": 14}, {"text": "doth travail, as in birth;"}, {"text": "A mischief he conceived hath,"}, {"text": "and falsehood shall bring forth.", "syllables": ["and", "false-", "hood", "shall", "bring", "forth."]}]}, {"index": 13, "lines": [{"text": "He made a pit and digg''d it deep,", "bibleVerseRef": 15}, {"text": "another there to take;"}, {"text": "But he is fall''n into the ditch"}, {"text": "which he himself did make."}]}, {"index": 14, "lines": [{"text": "Upon his own head his mischief", "bibleVer