INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (135, 'recl3X1MDY9TO6JAO', 110, '110', '1The Lord did say unto my Lord,
Sit thou at my right hand,
Until I make thy foes a stool,
whereon thy feet may stand.

2The Lord shall out of Sion send
the rod of thy great pow''r:
In midst of all thine enemies
be thou the governor.

3A willing people in thy day
of pow''r shall come to thee,
In holy beauties from morn''s womb;
thy youth like dew shall be.

4The Lord himself hath made an oath,
and will repent him never,
Of th'' order of Melchisedec
thou art a priest for ever.

5The glorious and mighty Lord,
that sits at thy right hand,
Shall, in his day of wrath, strike through
kings that do him withstand.

6He shall among the heathen judge,
he shall with bodies dead
The places fill: o''er many lands
he wound shall ev''ry head.

7The brook that runneth in the way
with drink shall him supply;
And, for this cause, in triumph he
shall lift his head on high.', '[{"index": 0, "lines": [{"text": "The Lord did say unto my Lord,", "bibleVerseRef": 1}, {"text": "Sit thou at my right hand,"}, {"text": "Until I make thy foes a stool,"}, {"text": "whereon thy feet may stand."}]}, {"index": 1, "lines": [{"text": "The Lord shall out of Sion send", "syllables": ["The", "Lord", "sha-", "ll", "out", "of", "Sion", "send"], "bibleVerseRef": 2}, {"text": "the rod of thy great pow''r:"}, {"text": "In midst of all thine enemies"}, {"text": "be thou the governor.", "syllables": ["be", "thou", "the", "gove-", "r-", "nor."]}]}, {"index": 2, "lines": [{"text": "A willing people in thy day", "syllables": ["A", "willing", "pe-", "o-", "ple", "in", "thy", "day"], "bibleVerseRef": 3}, {"text": "of pow''r shall come to thee,"}, {"text": "In holy beauties from morn''s womb;"}, {"text": "thy youth like dew shall be."}]}, {"index": 3, "lines": [{"text": "The Lord himself hath made an oath,", "syllables": ["The", "Lord", "himself", "hath", "made", "an", "o-", "ath,"], "bibleVerseRef": 4}, {"text": "and will repent him never,"}, {"text": "Of th'' order of Melchisedec", "syllables": ["Of", "th''", "order", "of", "mel-", "chi-", "se-", "dec"]}, {"text": "thou art a priest for ever."}]}, {"index": 4, "lines": [{"text": "The glorious and mighty Lord,", "syllables": ["The", "glo-", "riou-", "s", "and", "mig-", "hty", "Lord,"], "bibleVerseRef": 5}, {"text": "that sits at thy right hand,"}, {"text": "Shall, in his day of wrath, strike through", "syllables": ["Shall,", "in", "his", "day", "of", "wrath,", "strike", "through"]}, {"text": "kings that do him withstand."}]}, {"index": 5, "lines": [{"text": "He shall among the heathen judge,", "syllables": ["He", "shall", "among", "the", "hea-", "then", "jud-", "ge,"], "bibleVerseRef": 6}, {"text": "he shall with bodies dead"}, {"text": "The places fill: o''er many lands"}, {"text": "he wound shall ev''ry head."}]}, {"index": 6, "lines": [{"text": "The brook that runneth in the way", "b