INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (142, 'recmQZXWAT9oh93lO', 117, '117', '1O give ye praise unto the Lord,
all nations that be;
Likewise, ye people all, accord
his name to magnify.

2For great to us-ward ever are
his loving-kindnesses:
His truth endures for evermore.
The Lord O do ye bless.', '[{"index": 0, "lines": [{"text": "O give ye praise unto the Lord,", "bibleVerseRef": 1}, {"text": "all nations that be;", "syllables": ["all", "na-", "tio-", "ns", "that", "be;"]}, {"text": "Likewise, ye people all, accord", "syllables": ["likewise,", "ye", "pe-", "o-", "ple", "all,", "ac-", "cord"]}, {"text": "his name to magnify."}]}, {"index": 1, "lines": [{"text": "For great to us-ward ever are", "syllables": ["For", "grea-", "t", "to", "us-", "-ward", "ever", "are"], "bibleVerseRef": 2}, {"text": "his loving-kindnesses:"}, {"text": "His truth endures for evermore.", "syllables": ["His", "tru-", "th", "en-", "dures", "for", "ever-", "more."]}, {"text": "The Lord O do ye bless."}]}]', 'CM', NULL, 'O give ye praise unto the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (140, 'recm1DvD2BzGSPEgg', 119, '119:121-128 (16)', '121To all men I have judgment done,
performing justice right;
Then let me not be left unto
my fierce oppressors'' might.

122For good unto thy servant, Lord,
thy servant''s surety be:
From the oppression of the proud
do thou deliver me.

123Mine eyes do fail with looking long
for thy salvation,
The word of thy pure righteousness
while I do wait upon.

124In mercy with thy servant deal,
thy laws me teach and show.
125I am thy servant, wisdom give,
that I thy laws may know.

126''Tis time thou work, Lord; for they have
made void thy law divine.
127Therefore thy precepts more I love
than gold, yea, gold most fine.

128Concerning all things thy commands
all right I judge therefore;
And ev''ry false and wicked way
I perfectly abhor.
', '[{"index": 0, "lines": [{"text": "To all men I have judgment done,", "bibleVerseRef": 121}, {"text": "performing justice right;"}, {"text": "Then let me not be left unto"}, {"text": "my fierce oppressors'' might.", "syllables": ["my", "fierce", "op-", "pres-", "sors''", "might."]}]}, {"index": 1, "lines": [{"text": "For good unto thy servant, Lord,", "bibleVerseRef": 122}, {"text": "thy servant''s surety be:"}, {"text": "From the oppression of the proud"}, {"text": "do thou deliver me.", "syllables": ["do", "thou", "de-", "live-", "r", "me."]}]}, {"index": 2, "lines": [{"text": "Mine eyes do fail with looking long", "bibleVerseRef": 123}, {"text": "for thy salvation,", "syllables": ["for", "thy", "sal-", "va-", "tio-", "n,"]}, {"text": "The word of thy pure righteousness"}, {"text": "while I do wait upon."}]}, {"index": 3, "lines": [{"text": "In mercy with thy servant deal,", "bibleVerseRef": 124}, {"text": "thy laws me teach and show."}, {"text": "I am thy servant, wisdom give,", "bibleVerseRef": 125}, {"text": "that I thy laws may know."}]}, {"index": 4, "lines": [{"text": "''Tis time thou work, Lord; for they have", "bibleVerseRef": 126}, {"text": "made void thy law divine."}, {"text": "Therefore thy precepts more I love", "bibleVerseRef": 127}, {"text": "than gold, yea, gold most fine."}]}, {"index": 5, "lines": [{"text": "Concerning all things thy commands", "bibleVerseRef": 128}, {"text": "all right I judge therefore;", "syllables": ["all", "right", "I", "judge", "there-", "fore;"]}, {"text": "And ev''ry false and wicked way", "syllables": ["And", "ev''ry", "fal-", "se", "and", "wic-", "ked", "way"]}, {"text": "I perfectly abhor."}]}]', 'CM', 'Part 16', 'To all men I have judgment done...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (147, 'recnc71K2gKMHqoAi', 119, '119:97-104 (13)', '97O how love I thy law! it is
my study all the day:
98It makes me wiser than my foes;
for it doth with me stay.

99Than all my teachers now I have
more understanding far;
Because my meditation
thy testimonies are.

100In understanding I excel
those that are ancients;
For I endeavoured to keep
all thy commandements.

101My feet from each ill way I stay''d,
that I may keep thy word.
102I from thy judgments have not swerv''d;
for thou hast taught me, Lord.

103How sweet unto my taste, O Lord,
are all thy words of truth!
Yea, I do find them sweeter far
than honey to my mouth.

104I through thy precepts, that are pure,
do understanding get;
I therefore ev''ry way that''s false
with all my heart do hate.
', '[{"index": 0, "lines": [{"text": "O how love I thy law! it is", "bibleVerseRef": 97}, {"text": "my study all the day:"}, {"text": "It makes me wiser than my foes;", "syllables": ["It", "make-", "s", "me", "wiser", "than", "my", "foes;"], "bibleVerseRef": 98}, {"text": "for it doth with me stay."}]}, {"index": 1, "lines": [{"text": "Than all my teachers now I have", "bibleVerseRef": 99}, {"text": "more understanding far;"}, {"text": "Because my meditation", "syllables": ["be-", "cau-", "se", "my", "me-", "di-", "ta-", "tion"]}, {"text": "thy testimonies are."}]}, {"index": 2, "lines": [{"text": "In understanding I excel", "bibleVerseRef": 100}, {"text": "those that are ancients;", "syllables": ["those", "that", "are", "an-", "cie-", "nts;"]}, {"text": "For I endeavoured to keep"}, {"text": "all thy commandements."}]}, {"index": 3, "lines": [{"text": "My feet from each ill way I stay''d,", "bibleVerseRef": 101}, {"text": "that I may keep thy word."}, {"text": "I from thy judgments have not swerv''d;", "bibleVerseRef": 102}, {"text": "for thou hast taught me, Lord."}]}, {"index": 4, "lines": [{"text": "How sweet unto my taste, O Lord,", "syllables": ["How", "sweet", "unto", "my", "tas-", "te,", "O", "Lord,"], "bibleVerseRef": 103}, {"text": "are all thy words of truth!"}, {"text": "Yea, I do find them sweeter far"}, {"text": "than honey to my mouth.", "syllables": ["than", "honey", "to", "my", "mou-", "th."]}]}, {"index": 5, "lines": [{"text": "I through thy precepts, that are pure,", "bibleVerseRef": 104}, {"text": "do understanding get;"}, {"text": "I therefore ev''ry way that''s false", "syllables": ["I", "therefore", "ev-", "''ry", "way", "that''s", "fal-", "se"]}, {"text": "with all my heart do hate."}]}]', 'CM', 'Part 13', 'O how love I thy law! it is...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (144, 'recmWeXNZVLnOOgyF', 6, '6 (First Version, Recommended)', '1Lord, in thy wrath rebuke me not;
Nor in thy hot rage chasten me.
2Lord, pity me, for I am weak:
Heal me, for my bones vexed be.

3My soul is also vexed sore;
But, Lord, how long stay wilt thou make?
4Return, O Lord, my soul set free;
O save me, for thy mercies'' sake.

5Because those that deceased are
Of thee shall no remembrance have;
And who is he that will to thee
Give praises lying in the grave?

6I with my groaning weary am,
I also all the night my bed
Have caused for to swim; and I
With tears my couch have watered.

7Mine eye, consum''d with grief, grows old,
Because of all mine enemies.
8Hence from me, wicked workers all;
For God hath heard my weeping cries.

9God hath my supplication heard,
My pray''r received graciously
10Sham''d and sore vex''d be all my foes,
Sham''d and back turned suddenly.', '[{"index": 0, "lines": [{"text": "Lord, in thy wrath rebuke me not;", "bibleVerseRef": 1}, {"text": "Nor in thy hot rage chasten me."}, {"text": "Lord, pity me, for I am weak:", "bibleVerseRef": 2}, {"text": "Heal me, for my bones vexed be."}]}, {"index": 1, "lines": [{"text": "My soul is also vexed sore;", "bibleVerseRef": 3}, {"text": "But, Lord, how long stay wilt thou make?"}, {"text": "Return, O Lord, my soul set free;", "bibleVerseRef": 4}, {"text": "O save me, for thy mercies'' sake."}]}, {"index": 2, "lines": [{"text": "Because those that deceased are", "bibleVerseRef": 5}, {"text": "Of thee shall no remembrance have;", "syllables": ["Of", "thee", "shall", "no", "remem-", "bran-", "ce", "have;"]}, {"text": "And who is he that will to thee"}, {"text": "Give praises lying in the grave?", "syllables": ["Give", "praise-", "s", "lying", "in", "the", "gra-", "ve?"]}]}, {"index": 3, "lines": [{"text": "I with my groaning weary am,", "syllables": ["I", "with", "my", "groa-", "ning", "wea-", "ry", "am,"], "bibleVerseRef": 6}, {"text": "I also all the night my bed"}, {"text": "Have caused for to swim; and I"}, {"text": "With tears my couch have watered.", "syllables": ["With", "tea-", "rs", "my", "couch", "have", "wate-", "red."]}]}, {"index": 4, "lines": [{"text": "Mine eye, consum''d with grief, grows old,", "bibleVerseRef": 7}, {"text": "Because of all mine enemies."}, {"text": "Hence from me, wicked workers all;", "bibleVerseRef": 8}, {"text": "For God hath heard my weeping cries."}]}, {"index": 5, "lines": [{"text": "God hath my supplication heard,", "bibleVerseRef": 9}, {"text": "My pray''r received graciously"}, {"text": "Sham''d and sore vex''d be all my foes,", "bibleVerseRef": 10}, {"text": "Sham''d and back turned suddenly."}]}]', 'LM (long meter, 88 88)', 'First Version', 'Lord, in thy wrath rebuke me not...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (152, 'recpGZYqQqh5UbEWP', 53, '53', '1That there is not a God, the fool
doth in his heart conclude:
They are corrupt, their works are vile,
not one of them doth good.

2The Lord upon the sons of men
from heav''n did cast his eyes,
To see if any one there was
that sought God, and was wise.

3They altogether filthy are,
they all are backward gone;
And there is none that doeth good,
no, not so much as one.

4These workers of iniquity,
do they not know at all,
That they my people eat as bread,
and on God do not call?

5Ev''n there they were afraid, and stood
with trembling, all dismay''d,
Whereas there was no cause at all
why they should be afraid:

For God his bones that thee besieg''d
hath scatter''d all abroad;
Thou hast confounded them, for they
despised are of God.

6Let Isr''el''s help from Sion come:
when back the Lord shall bring
His captives, Jacob shall rejoice,
and Israel shall sing.', '[{"index": 0, "lines": [{"text": "That there is not a God, the fool", "bibleVerseRef": 1}, {"text": "doth in his heart conclude:", "syllables": ["doth", "in", "his", "heart", "conclu-", "de:"]}, {"text": "They are corrupt, their works are vile,"}, {"text": "not one of them doth good."}]}, {"index": 1, "lines": [{"text": "The Lord upon the sons of men", "bibleVerseRef": 2}, {"text": "from heav''n did cast his eyes,"}, {"text": "To see if any one there was"}, {"text": "that sought God, and was wise."}]}, {"index": 2, "lines": [{"text": "They altogether filthy are,", "bibleVerseRef": 3}, {"text": "they all are backward gone;"}, {"text": "And there is none that doeth good,", "syllables": ["And", "there", "is", "none", "that", "do-", "eth", "good,"]}, {"text": "no, not so much as one."}]}, {"index": 3, "lines": [{"text": "These workers of iniquity,", "bibleVerseRef": 4}, {"text": "do they not know at all,"}, {"text": "That they my people eat as bread,", "syllables": ["That", "they", "my", "peo-", "ple", "eat", "as", "bread,"]}, {"text": "and on God do not call?"}]}, {"index": 4, "lines": [{"text": "Ev''n there they were afraid, and stood", "bibleVerseRef": 5}, {"text": "with trembling, all dismay''d,"}, {"text": "Whereas there was no cause at all", "syllables": ["Wherea-", "s", "there", "was", "no", "cause", "at", "all"]}, {"text": "why they should be afraid:"}]}, {"index": 5, "lines": [{"text": "For God his bones that thee besieg''d"}, {"text": "hath scatter''d all abroad;", "syllables": ["hath", "scatter''d", "all", "ab-", "ro-", "ad;"]}, {"text": "Thou hast confounded them, for they"}, {"text": "despised are of God.", "syllables": ["des-", "pise-", "d", "are", "of", "God."]}]}, {"index": 6, "lines": [{"text": "Let Isr''el''s help from Sion come:", "syllables": ["Let", "is-", "r''e-", "l''s", "help", "from", "Sion", "come:"], "bibleVerseRef": 6}, {"text": "when back the Lord shall bring"}, {"text": "His captives, Jacob shall rejoice,"}, {"text": "and Israel shall sing.", "syllables": ["and", "is-", "rael", "sha-", "ll", "sing."]}]}]', 'CM', NULL, 'That there is not a God, the fool...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (153, 'recpiTSX6CjB2Rro1', 97, '97', '1God reigneth, let the earth be glad,
and isles rejoice each one.
2Dark clouds him compass; and in right
with judgment dwells his throne.

3Fire goes before him,
and his foes it burns up round about:
4His lightnings lighten did the world; earth saw,
and shook throughout.

5Hills at the presence of the Lord,
like wax, did melt away;
Ev''n at the presence of the Lord
of all the earth, I say.

6The heav''ns declare his righteousness,
all men his glory see.
7All who serve graven images,
confounded let them be.

Who do of idols boast themselves,
let shame upon them fall:
Ye that are called gods, see that
ye do him worship all.

8Sion did hear, and joyful was,
glad Judah''s daughters were;
They much rejoic''d, O Lord, because
thy judgments did appear.

9For thou, O Lord, art high above
all things on earth that are;
Above all other gods thou art
exalted very far.

10Hate ill, all ye that love the Lord:
his saints'' souls keepeth he;
And from the hands of wicked men
he sets them safe and free.

11For all those that be righteous
sown is a joyful light,
And gladness sown is for all those
that are in heart upright.

12Ye righteous, in the Lord rejoice;
express your thankfulness,
When ye into your memory
do call his holiness.', '[{"index": 0, "lines": [{"text": "God reigneth, let the earth be glad,", "bibleVerseRef": 1}, {"text": "and isles rejoice each one.", "syllables": ["and", "isles", "re-", "joice", "each", "one."]}, {"text": "Dark clouds him compass; and in right", "bibleVerseRef": 2}, {"text": "with judgment dwells his throne.", "syllables": ["with", "judgment", "dwells", "his", "thro-", "ne."]}]}, {"index": 1, "lines": [{"text": "Fire goes before him,", "syllables": ["Fi-", "re", "goe-", "-", "s", "be-", "fore", "him,"], "bibleVerseRef": 3}, {"text": "and his foes it burns up round about:", "syllables": ["and", "his", "foes", "it", "burns", "uproundabout:"]}, {"text": "His lightnings lighten did the world; earth saw,", "syllables": ["His", "lightnings", "lighten", "did", "the", "world;", "earth", "saw,"], "bibleVerseRef": 4}, {"text": "and shook throughout.", "syllables": ["and", "shook", "throu-", "-", "-", "ghout."]}]}, {"index": 2, "lines": [{"text": "Hills at the presence of the Lord,", "bibleVerseRef": 5}, {"text": "like wax, did melt away;"}, {"text": "Ev''n at the presence of the Lord"}, {"text": "of all the earth, I say."}]}, {"index": 3, "lines": [{"text": "The heav''ns declare his righteousness,", "bibleVerseRef": 6}, {"text": "all men his glory see."}, {"text": "All who serve graven images,", "syllables": ["All", "who", "serve", "gra-", "ven", "i-", "mage-", "s,"], "bibleVerseRef": 7}, {"text": "confounded let them be."}]}, {"index": 4, "lines": [{"text": "Who do of idols boast themselves,", "syllables": ["Who", "do", "of", "idols", "boast", "them-", "sel-", "ves,"]}, {"text": "let shame upon them fall:"}, {"text": "Ye that are called gods, see that"}, {"text": "ye do him worship all."}]}, {"index": 5, "lines": [{"text": "Sion did hear, and joyful was,", "syllables": ["Sion", "did", "hea-", "r,", "and", "joy-", "ful", "was,"], "bibleVerseRef": 8}, {"text": "glad Judah''s daughters were;"}, {"text": "They much rejoic''d, O Lord, because"}, {"text": "thy judgments did appear."}]}, {"index": 6, "lines": [{"text": "For thou, O Lord, art high above", "bibleVerseRef": 9}, {"text": "all things on earth that are;"}, {"text": "Above all other gods thou art"}, {"text": "exalted very far."}]}, {"index": 7, "lines": [{"text": "Hate ill, all ye that love the Lord:", "bibleVerseRef": 10}, {"text": "his saints'' souls keepeth he;"}, {"text": "And from the hands of wicked men"}, {"text": "he sets them safe and free."}]}, {"index": 8, "lines": [{"text": "For all those that be righteous", "syllables": ["For", "all", "tho-", "se", "that", "be", "righ-", "teous"], "bibleVerseRef": 11}, {"text": "sown is a joyful light,"}, {"text": "And gladness sown is for all those"}, {"text": "that are in heart upright."}]}, {"index": 9, "lines": [{"text": "Ye righteous, in the Lord rejoice;", "bibleVerseRef": 12}, {"text": "express your thankfulness,"}, {"text": "When ye into your memory"}, {"text": "do call his holiness."}]}]', 'CM', NULL, 'God reigneth, let the earth be glad...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (154, 'recprdJdgkueyrIxv', 73, '73', '1Yet God is good to Israel,
to each pure-hearted one.
2But as for me, my steps near slipp''d,
my feet were almost gone.

3For I envious was, and grudg''d
the foolish folk to see,
When I perceiv''d the wicked sort
enjoy prosperity.

4For still their strength continueth firm;
their death of bands is free.
5They are not toil''d like other men,
nor plagu''d, as others be.

6Therefore their pride, like to a chain,
them compasseth about;
And, as a garment, violence
doth cover them throughout.

7Their eyes stand out with fat; they have
more than their hearts could wish.
8They are corrupt; their talk of wrong
both lewd and lofty is.

9They set their mouth against the heav''ns
in their blasphemous talk;
And their reproaching tongue throughout
the earth at large doth walk.

10His people oftentimes for this
look back, and turn about;
Sith waters of so full a cup
to these are poured out.

11And thus they say, How can it be
that God these things doth know?
Or, Can there in the Highest be
knowledge of things below?

12Behold, these are the wicked ones,
yet prosper at their will
In worldly things; they do increase
in wealth and riches still.

13I verily have done in vain
my heart to purify;
To no effect in innocence
washed my hands have I.

14For daily, and all day throughout,
great plagues I suffer''d have;
Yea, ev''ry morning I of new
did chastisement receive.

15If in this manner foolishly
to speak I would intend,
Thy children''s generation,
behold, I should offend.

16When I this thought to know, it was
too hard a thing for me;
17Till to God''s sanctuary I went,
then I their end did see.

18Assuredly thou didst them set
a slipp''ry place upon;
Them suddenly thou castedst down
into destruction.

19How in a moment suddenly
to ruin brought are they!
With fearful terrors utterly
they are consum''d away.

20Ev''n like unto a dream, when one
from sleeping doth arise;
So thou, O Lord, when thou awak''st,
their image shalt despise.

21Thus grieved was my heart in me,
and me my reins opprest:
22So rude was I, and ignorant,
and in thy sight a beast.

23Nevertheless continually,
O Lord, I am with thee:
Thou dost me hold by my right hand,
and still upholdest me.

24Thou, with thy counsel, while I live,
wilt me conduct and guide;
And to thy glory afterward
receive me to abide.

25Whom have I in the heavens high
but thee, O Lord, alone?
And in the earth whom I desire
besides thee there is none.

26My flesh and heart doth faint and fail,
but God doth fail me never:
For of my heart God is the strength
and portion for ever.

27For, lo, they that are far from thee
for ever perish shall;
Them that a whoring from thee go
thou hast destroyed all.

28But surely it is good for me
that I draw near to God:
In God I trust, that all thy works
I may declare abroad.', '[{"index": 0, "lines": [{"text": "Yet God is good to Israel,", "syllables": ["Yet", "God", "is", "good", "to", "is-", "rae-", "l,"], "bibleVerseRef": 1}, {"text": "to each pure-hearted one."}, {"text": "But as for me, my steps near slipp''d,", "bibleVerseRef": 2}, {"text": "my feet were almost gone."}]}, {"index": 1, "lines": [{"text": "For I envious was, and grudg''d", "syllables": ["For", "I", "en-", "vious", "was,", "and", "gru-", "dg''d"], "bibleVerseRef": 3}, {"text": "the foolish folk to see,"}, {"text": "When I perceiv''d the wicked sort"}, {"text": "enjoy prosperity."}]}, {"index": 2, "lines": [{"text": "For still their strength continueth firm;", "bibleVerseRef": 4}, {"text": "their death of bands is free."}, {"text": "They are not toil''d like other men,", "bibleVerseRef": 5}, {"text": "nor plagu''d, as others be.", "syllables": ["nor", "plagu''d,", "as", "o-", "thers", "be."]}]}, {"index": 3, "lines": [{"text": "Therefore their pride, like to a chain,", "syllables": ["therefore", "their", "pri-", "de,", "like", "to", "a", "chain,"], "bibleVerseRef": 6}, {"text": "them compasseth about;"}, {"text": "And, as a garment, violence", "syllables": ["And,", "as", "a", "gar-", "ment,", "viole-", "n-", "ce"]}, {"text": "doth cover them throughout.", "syllables": ["doth", "cover", "them", "throu-", "-", "ghout."]}]}, {"index": 4, "lines": [{"text": "Their eyes stand out with fat; they have", "bibleVerseRef": 7}, {"text": "more than their hearts could wish."}, {"text": "They are corrupt; their talk of wrong", "bibleVerseRef": 8}, {"text": "both lewd and lofty is."}]}, {"index": 5, "lines": [{"text": "They set their mouth against the heav''ns", "bibleVerseRef": 9}, {"text": "in their blasphemous talk;"}, {"text": "And their reproaching tongue throughout", "syllables": ["And", "their", "reproa-", "ching", "ton-", "gue", "throu-", "ghout"]}, {"text": "the earth at large doth walk.", "syllables": ["the", "earth", "at", "large", "doth", "walk."]}]}, {"index": 6, "lines": [{"text": "His people oftentimes for this", "syllables": ["His", "peo-", "ple", "of-", "ten-", "times", "for", "this"], "bibleVerseRef": 10}, {"text": "look back, and turn about;"}, {"text": "Sith waters of so full a cup", "syllables": ["Sith", "wate-", "rs", "of", "so", "full", "a", "cup"]}, {"text": "to these are poured out."}]}, {"index": 7, "lines": [{"text": "And thus they say, How can it be", "bibleVerseRef": 11}, {"text": "that God these things doth know?"}, {"text": "Or, Can there in the Highest be"}, {"text": "knowledge of things below?", "syllables": ["knowled-", "ge", "of", "things", "be-", "low?"]}]}, {"index": 8, "lines": [{"text": "Behold, these are the wicked ones,", "bibleVerseRef": 12}, {"text": "yet prosper at their will"}, {"text": "In worldly things; they do increase", "syllables": ["In", "worldly", "things;", "they", "do", "in-", "crea-", "se"]}, {"text": "in wealth and riches still."}]}, {"index": 9, "lines": [{"text": "I verily have done in vain", "bibleVerseRef": 13}, {"text": "my heart to purify;"}, {"text": "To no effect in innocence", "syllables": ["To", "no", "effect", "in", "in-", "no-", "cen-", "ce"]}, {"text": "washed my hands have I."}]}, {"index": 10, "lines": [{"text": "For daily, and all day throughout,", "bibleVerseRef": 14}, {"text": "great plagues I suffer''d have;", "syllables": ["great", "plagues", "I", "suf-", "fer''d", "have;"]}, {"text": "Yea, ev''ry morning I of new"}, {"text": "did chastisement receive.", "syllables": ["did", "chasti-", "se-", "ment", "re-", "ceive."]}]}, {"index": 11, "lines": [{"text": "If in this manner foolishly", "bibleVerseRef": 15}, {"text": "to speak I would intend,"}, {"text": "Thy children''s generation,", "syllables": ["Thy", "chil-", "dre-", "n''s", "ge-", "ne-", "ra-", "tion,"]}, {"text": "behold, I should offend."}]}, {"index": 12, "lines": [{"text": "When I this thought to know, it was", "bibleVerseRef": 16}, {"text": "too hard a thing for me;"}, {"text": "Till to God''s sanctuary I went,", "syllables": ["Till", "to", "God''s", "sanctu-", "a-", "ry", "I", "went,"], "bibleVerseRef": 17}, {"text": "then I their end did see."}]}, {"index": 13, "lines": [{"text": "Assuredly thou didst them set", "bibleVerseRef": 18}, {"text": "a slipp''ry place upon;", "syllables": ["a", "slipp''ry", "pla-", "ce", "u-", "pon;"]}, {"text": "Them suddenly thou castedst down"}, {"text": "into destruction.", "syllables": ["in-", "to", "des-", "tru-", "c-", "tion."]}]}, {"index": 14, "lines": [{"text": "How in a moment suddenly", "bibleVerseRef": 19}, {"text": "to ruin brought are they!"}, {"text": "With fearful terrors utterly"}, {"text": "they are consum''d away."}]}, {"index": 15, "lines": [{"text": "Ev''n like unto a dream, when one", "bibleVerseRef": 20}, {"text": "from sleeping doth arise;"}, {"text": "So thou, O Lord, when thou awak''st,"}, {"text": "their image shalt despise."}]}, {"index": 16, "lines": [{"text": "Thus grieved was my heart in me,", "bibleVerseRef": 21}, {"text": "and me my reins opprest:"}, {"text": "So rude was I, and ignorant,", "bibleVerseRef": 22}, {"text": "and in thy sight a beast."}]}, {"index": 17, "lines": [{"text": "Nevertheless continually,", "bibleVerseRef": 23}, {"text": "O Lord, I am with thee:"}, {"text": "Thou dost me hold by my right hand,"}, {"text": "and still upholdest me."}]}, {"index": 18, "lines": [{"text": "Thou, with thy counsel, while I live,", "bibleVerseRef": 24}, {"text": "wilt me conduct and guide;", "syllables": ["wilt", "me", "conduct", "and", "gui-", "de;"]}, {"text": "And to thy glory afterward"}, {"text": "receive me to abide."}]}, {"index": 19, "lines": [{"text": "Whom have I in the heavens high", "syllables": ["Whom", "have", "I", "in", "the", "heave-", "ns", "high"], "bibleVerseRef": 25}, {"text": "but thee, O Lord, alone?"}, {"text": "And in the earth whom I desire"}, {"text": "besides thee there is none.", "syllables": ["besides", "thee", "there", "is", "no-", "ne."]}]}, {"index": 20, "lines": [{"text": "My flesh and heart doth faint and fail,", "bibleVerseRef": 26}, {"text": "but God doth fail me never:", "syllables": ["but", "God", "doth", "fail", "me", "never:"]}, {"text": "For of my heart God is the strength"}, {"text": "and portion for ever.", "syllables": ["and", "por-", "tion", "for", "eve-", "r."]}]}, {"index": 21, "lines": [{"text": "For, lo, they that are far from thee", "bibleVerseRef": 27}, {"text": "for ever perish shall;", "syllables": ["for", "ever", "pe-", "rish", "sha-", "ll;"]}, {"text": "Them that a whoring from thee go"}, {"text": "thou hast destroyed all.", "syllables": ["thou", "hast", "des-", "troye-", "d", "all."]}]}, {"index": 22, "lines": [{"text": "But surely it is good for me", "bibleVerseRef": 28}, {"text": "that I draw near to God:"}, {"text": "In God I trust, that all thy works"}, {"text": "I may declare abroad.", "syllables": ["I", "may", "declare", "ab-", "ro-", "ad."]}]}]', 'CM', NULL, 'Yet God is good to Israel...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (13, 'rec4JJh50FyRIQ4it', 56, '56', '1Shew mercy, Lord, to me, for man
would swallow me outright;
He me oppresseth, while he doth
against me daily fight.

2They daily would me swallow up
that hate me spitefully;
For they be many that do fight
against me, O most High.

3When I''m afraid I''ll trust in thee:
4In God I''ll praise his word;
I will not fear what flesh can do,
my trust is in the Lord.

5Each day they wrest my words; their thoughts
''gainst me are all for ill.
6They meet, they lurk, they mark my steps,
waiting my soul to kill.

7But shall they by iniquity
escape thy judgments so?
O God, with indignation down
do thou the people throw.

8My wand''rings all what they have been
thou know''st, their number took;
Into thy bottle put my tears:
are they not in thy book?

9My foes shall, when I cry, turn back;
I know''t, God is for me.
10In God his word I''ll praise; his word
in God shall praised be.

11In God I trust; I will not fear
what man can do to me.
12Thy vows upon me are, O God:
I''ll render praise to thee.

13Wilt thou not, who from death me sav''d,
my feet from falls keep free,
To walk before God in the light
of those that living be?', '[{"index": 0, "lines": [{"text": "Shew mercy, Lord, to me, for man", "bibleVerseRef": 1}, {"text": "would swallow me outright;"}, {"text": "He me oppresseth, while he doth"}, {"text": "against me daily fight."}]}, {"index": 1, "lines": [{"text": "They daily would me swallow up", "bibleVerseRef": 2}, {"text": "that hate me spitefully;", "syllables": ["that", "hate", "me", "spite-", "ful-", "ly;"]}, {"text": "For they be many that do fight"}, {"text": "against me, O most High."}]}, {"index": 2, "lines": [{"text": "When I''m afraid I''ll trust in thee:", "bibleVerseRef": 3}, {"text": "In God I''ll praise his word;", "bibleVerseRef": 4}, {"text": "I will not fear what flesh can do,"}, {"text": "my trust is in the Lord."}]}, {"index": 3, "lines": [{"text": "Each day they wrest my words; their thoughts", "bibleVerseRef": 5}, {"text": "''gainst me are all for ill."}, {"text": "They meet, they lurk, they mark my steps,", "bibleVerseRef": 6}, {"text": "waiting my soul to kill."}]}, {"index": 4, "lines": [{"text": "But shall they by iniquity", "bibleVerseRef": 7}, {"text": "escape thy judgments so?"}, {"text": "O God, with indignation down"}, {"text": "do thou the people throw.", "syllables": ["do", "thou", "the", "peo-", "ple", "throw."]}]}, {"index": 5, "lines": [{"text": "My wand''rings all what they have been", "bibleVerseRef": 8}, {"text": "thou know''st, their number took;"}, {"text": "Into thy bottle put my tears:"}, {"text": "are they not in thy book?"}]}, {"index": 6, "lines": [{"text": "My foes shall, when I cry, turn back;", "bibleVerseRef": 9}, {"text": "I know''t, God is for me."}, {"text": "In God his word I''ll praise; his word", "bibleVerseRef": 10}, {"text": "in God shall praised be.", "syllables": ["in", "God", "shall", "praise-", "d", "be."]}]}, {"index": 7, "lines": [{"text": "In God I trust; I will not fear", "bibleVerseRef": 11}, {"text": "what man can do to me."}, {"text": "Thy vows upon me are, O God:", "bibleVerseRef": 12}, {"text": "I''ll render praise to thee."}]}, {"index": 8, "lines": [{"text": "Wilt thou not, who from death me sav''d,", "bibleVerseRef": 13}, {"text": "my feet from falls keep free,"}, {"text": "To walk before God in the light"}, {"text": "of those that living be?"}]}]', 'CM', NULL, 'Shew mercy, Lord, to me, for man...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (34, 'rec9Nk6LabA6zk3Jo', 131, '131', '1My heart not haughty is, O Lord,
mine eyes not lofty be;
Nor do I deal in matters great,
or things too high for me.

2I surely have myself behav''d
with quiet sp''rit and mild,
As child of mother wean''d: my soul
is like a weaned child.

3Upon the Lord let all the hope
of Israel rely,
Ev''n from the time that present is
unto eternity.', '[{"index": 0, "lines": [{"text": "My heart not haughty is, O Lord,", "bibleVerseRef": 1}, {"text": "mine eyes not lofty be;"}, {"text": "Nor do I deal in matters great,"}, {"text": "or things too high for me."}]}, {"index": 1, "lines": [{"text": "I surely have myself behav''d", "syllables": ["I", "sure-", "ly", "have", "myse-", "lf", "be-", "hav''d"], "bibleVerseRef": 2}, {"text": "with quiet sp''rit and mild,", "syllables": ["with", "qui-", "et", "sp''rit", "and", "mild,"]}, {"text": "As child of mother wean''d: my soul"}, {"text": "is like a weaned child."}]}, {"index": 2, "lines": [{"text": "Upon the Lord let all the hope", "bibleVerseRef": 3}, {"text": "of Israel rely,", "syllables": ["of", "is-", "rae-", "l", "re-", "ly,"]}, {"text": "Ev''n from the time that present is", "syllables": ["Ev''n", "from", "the", "time", "that", "prese-", "nt", "is"]}, {"text": "unto eternity.", "syllables": ["un-", "to", "ete-", "r-", "ni-", "ty."]}]}]', 'CM', NULL, 'My heart not haughty is, O Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (156, 'recq9MfbeZrGeAyN4', 38, '38', '1In thy great indignation,
O Lord, rebuke me not;
Nor on me lay thy chast''ning hand,
in thy displeasure hot.

2For in me fast thine arrows stick,
thine hand doth press me sore:
3And in my flesh there is no health,
nor soundness any more.

This grief I have, because thy wrath
is forth against me gone;
And in my bones there is no rest,
for sin that I have done.

4Because gone up above mine head
my great transgressions be;
And, as a weighty burden, they
too heavy are for me.

5My wounds do stink, and are corrupt;
my folly makes it so.
6I troubled am, and much bow''d down;
all day I mourning go.

7For a disease that loathsome is
so fills my loins with pain,
That in my weak and weary flesh
no soundness doth remain.

8So feeble and infirm am I,
and broken am so sore,
That, through disquiet of my heart,
I have been made to roar.

9O Lord, all that I do desire
is still before thine eye;
And of my heart the secret groans
not hidden are from thee.

10My heart doth pant incessantly,
my strength doth quite decay;
As for mine eyes, their wonted light
is from me gone away.

11My lovers and my friends do stand
at distance from my sore;
And those do stand aloof that were
kinsmen and kind before.

12Yea, they that seek my life lay snares:
who seek to do me wrong
Speak things mischievous, and deceits
imagine all day long.

13But, as one deaf, that heareth not,
I suffer''d all to pass;
I as a dumb man did become,
whose mouth not open''d was:

14As one that hears not, in whose mouth
are no reproofs at all.
15For, Lord, I hope in thee; my God,
thou''lt hear me when I call.

16For I said, Hear me, lest they should
rejoice o''er me with pride;
And o''er me magnify themselves,
when as my foot doth slide.

17For I am near to halt, my grief
is still before mine eye:
18For I''ll declare my sin, and grieve
for mine iniquity.

19But yet mine en''mies lively are,
and strong are they beside;
And they that hate me wrongfully
are greatly multiply''d.

20And they for good that render ill,
as en''mies me withstood;
Yea, ev''n for this, because that I
do follow what is good.

21Forsake me not, O Lord; my God,
far from me never be.
22O Lord, thou my salvation art,
haste to give help to me.', '[{"index": 0, "lines": [{"text": "In thy great indignation,", "syllables": ["In", "thy", "grea-", "t", "in-", "dig-", "na-", "tion,"], "bibleVerseRef": 1}, {"text": "O Lord, rebuke me not;"}, {"text": "Nor on me lay thy chast''ning hand,"}, {"text": "in thy displeasure hot."}]}, {"index": 1, "lines": [{"text": "For in me fast thine arrows stick,", "bibleVerseRef": 2}, {"text": "thine hand doth press me sore:"}, {"text": "And in my flesh there is no health,", "bibleVerseRef": 3}, {"text": "nor soundness any more."}]}, {"index": 2, "lines": [{"text": "This grief I have, because thy wrath"}, {"text": "is forth against me gone;"}, {"text": "And in my bones there is no rest,"}, {"text": "for sin that I have done."}]}, {"index": 3, "lines": [{"text": "Because gone up above mine head", "bibleVerseRef": 4}, {"text": "my great transgressions be;"}, {"text": "And, as a weighty burden, they"}, {"text": "too heavy are for me."}]}, {"index": 4, "lines": [{"text": "My wounds do stink, and are corrupt;", "bibleVerseRef": 5}, {"text": "my folly makes it so."}, {"text": "I troubled am, and much bow''d down;", "bibleVerseRef": 6}, {"text": "all day I mourning go."}]}, {"index": 5, "lines": [{"text": "For a disease that loathsome is", "syllables": ["For", "a", "disease", "that", "loa-", "thso-", "me", "is"], "bibleVerseRef": 7}, {"text": "so fills my loins with pain,"}, {"text": "That in my weak and weary flesh"}, {"text": "no soundness doth remain."}]}, {"index": 6, "lines": [{"text": "So feeble and infirm am I,", "syllables": ["So", "fee-", "ble", "and", "in-", "firm", "am", "I,"], "bibleVerseRef": 8}, {"text": "and broken am so sore,"}, {"text": "That, through disquiet of my heart,", "syllables": ["That,", "through", "disqu-", "i-", "et", "of", "my", "heart,"]}, {"text": "I have been made to roar.", "syllables": ["I", "have", "been", "made", "to", "roar."]}]}, {"index": 7, "lines": [{"text": "O Lord, all that I do desire", "bibleVerseRef": 9}, {"text": "is still before thine eye;"}, {"text": "And of my heart the secret groans", "syllables": ["And", "of", "my", "heart", "the", "secret", "gro-", "ans"]}, {"text": "not hidden are from thee."}]}, {"index": 8, "lines": [{"text": "My heart doth pant incessantly,", "bibleVerseRef": 10}, {"text": "my strength doth quite decay;", "syllables": ["my", "strength", "doth", "quite", "de-", "cay;"]}, {"text": "As for mine eyes, their wonted light"}, {"text": "is from me gone away."}]}, {"index": 9, "lines": [{"text": "My lovers and my friends do stand", "syllables": ["My", "lovers", "and", "my", "frie-", "nds", "do", "stand"], "bibleVerseRef": 11}, {"text": "at distance from my sore;", "syllables": ["at", "distan-", "ce", "from", "my", "sore;"]}, {"text": "And those do stand aloof that were"}, {"text": "kinsmen and kind before."}]}, {"index": 10, "lines": [{"text": "Yea, they that seek my life lay snares:", "syllables": ["Yea,", "they", "that", "seek", "my", "life", "lay", "snares:"], "bibleVerseRef": 12}, {"text": "who seek to do me wrong"}, {"text": "Speak things mischievous, and deceits"}, {"text": "imagine all day long."}]}, {"index": 11, "lines": [{"text": "But, as one deaf, that heareth not,", "bibleVerseRef": 13}, {"text": "I suffer''d all to pass;"}, {"text": "I as a dumb man did become,"}, {"text": "whose mouth not open''d was:", "syllables": ["whose", "mouth", "not", "ope-", "n''d", "was:"]}]}, {"index": 12, "lines": [{"text": "As one that hears not, in whose mouth", "bibleVerseRef": 14}, {"text": "are no reproofs at all."}, {"text": "For, Lord, I hope in thee; my God,", "bibleVerseRef": 15}, {"text": "thou''lt hear me when I call."}]}, {"index": 13, "lines": [{"text": "For I said, Hear me, lest they should", "bibleVerseRef": 16}, {"text": "rejoice o''er me with pride;", "syllables": ["rejoice", "o''er", "me", "with", "pri-", "de;"]}, {"text": "And o''er me magnify themselves,", "syllables": ["And", "o''er", "me", "magni-", "fy", "them-", "sel-", "ves,"]}, {"text": "wh