INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (161, 'recrOTrFwpPGE9l8j', 101, '101', '1I mercy will and judgment sing,
Lord, I will sing to thee.
2With wisdom in a perfect way
shall my behaviour be.

O when, in kindness unto me,
wilt thou be pleas''d to come?
I with a perfect heart will walk
within my house at home.

3I will endure no wicked thing
before mine eyes to be:
I hate their work that turn aside,
it shall not cleave to me.

4A stubborn and a froward heart
depart quite from me shall;
A person giv''n to wickedness
I will not know at all.

5I''ll cut him off that slandereth
his neighbour privily:
The haughty heart I will not bear,
nor him that looketh high.

6Upon the faithful of the land
mine eyes shall be, that they
May dwell with me: he shall me serve
that walks in perfect way.

7Who of deceit a worker is
in my house shall not dwell;
And in my presence shall he not
remain that lies doth tell.

8Yea, all the wicked of the land
early destroy will I;
All from God''s city to cut off
that work iniquity.', '[{"index": 0, "lines": [{"text": "I mercy will and judgment sing,", "bibleVerseRef": 1}, {"text": "Lord, I will sing to thee."}, {"text": "With wisdom in a perfect way", "bibleVerseRef": 2}, {"text": "shall my behaviour be."}]}, {"index": 1, "lines": [{"text": "O when, in kindness unto me,"}, {"text": "wilt thou be pleas''d to come?"}, {"text": "I with a perfect heart will walk"}, {"text": "within my house at home."}]}, {"index": 2, "lines": [{"text": "I will endure no wicked thing", "bibleVerseRef": 3}, {"text": "before mine eyes to be:"}, {"text": "I hate their work that turn aside,"}, {"text": "it shall not cleave to me.", "syllables": ["it", "shall", "not", "cleave", "to", "me."]}]}, {"index": 3, "lines": [{"text": "A stubborn and a froward heart", "bibleVerseRef": 4}, {"text": "depart quite from me shall;", "syllables": ["depart", "qui-", "te", "from", "me", "shall;"]}, {"text": "A person giv''n to wickedness"}, {"text": "I will not know at all."}]}, {"index": 4, "lines": [{"text": "I''ll cut him off that slandereth", "bibleVerseRef": 5}, {"text": "his neighbour privily:"}, {"text": "The haughty heart I will not bear,"}, {"text": "nor him that looketh high."}]}, {"index": 5, "lines": [{"text": "Upon the faithful of the land", "bibleVerseRef": 6}, {"text": "mine eyes shall be, that they"}, {"text": "May dwell with me: he shall me serve"}, {"text": "that walks in perfect way."}]}, {"index": 6, "lines": [{"text": "Who of deceit a worker is", "bibleVerseRef": 7}, {"text": "in my house shall not dwell;"}, {"text": "And in my presence shall he not"}, {"text": "remain that lies doth tell."}]}, {"index": 7, "lines": [{"text": "Yea, all the wicked of the land", "bibleVerseRef": 8}, {"text": "early destroy will I;"}, {"text": "All from God''s city to cut off"}, {"text": "that work iniquity."}]}]', 'CM', NULL, 'I mercy will and judgment sing...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (157, 'recqLa1Yq0jcNcgTS', 6, '6 (Second Version)', '1In thy great indignation,
O Lord, rebuke me not;
Nor on me lay thy chast ''ning hand,
in thy displeasure hot.

2Lord, I am weak, therefore on me
have mercy, and me spare:
Heal me, O Lord, because thou know''st
my bones much vexed are.

3My soul is vexed sore:
but, Lord, how long stay wilt thou make?
4Return, Lord, free my soul; and save
me, for thy mercies'' sake.

5Because of thee in death there shall
no more remembrance be:
Of those that in the grave do lie,
who shall give thanks to thee?

6I with my groaning weary am,
and all the night my bed
I caused for to swim;
with tears my couch I watered.

7By reason of my vexing grief,
mine eye consumed is;
It waxeth old, because of all
that be mine enemies.

8But now, depart from me all ye
that work iniquity:
For why? the Lord hath heard my voice,
when I did mourn and cry.

9Unto my supplication
the Lord did hearing give:
When I to him my prayer make,
the Lord will it receive.

10Let all be sham''d and troubled sore,
That en''mies are to me;
Let them turn back, and suddenly
ashamed let them be.', '[{"index": 0, "lines": [{"text": "In thy great indignation,", "syllables": ["In", "thy", "grea-", "t", "in-", "dig-", "na-", "tion,"], "bibleVerseRef": 1}, {"text": "O Lord, rebuke me not;"}, {"text": "Nor on me lay thy chast ''ning hand,"}, {"text": "in thy displeasure hot."}]}, {"index": 1, "lines": [{"text": "Lord, I am weak, therefore on me", "bibleVerseRef": 2}, {"text": "have mercy, and me spare:", "syllables": ["have", "mercy,", "and", "me", "spa-", "re:"]}, {"text": "Heal me, O Lord, because thou know''st"}, {"text": "my bones much vexed are."}]}, {"index": 2, "lines": [{"text": "My soul is vexed sore:", "syllables": ["My", "soul", "is", "ve-", "xed", "sore-", "-", ":"], "bibleVerseRef": 3}, {"text": "but, Lord, how long stay wilt thou make?", "syllables": ["but,", "Lord,", "how", "long", "stay", "wiltthoumake?"]}, {"text": "Return, Lord, free my soul; and save", "bibleVerseRef": 4}, {"text": "me, for thy mercies'' sake."}]}, {"index": 3, "lines": [{"text": "Because of thee in death there shall", "bibleVerseRef": 5}, {"text": "no more remembrance be:", "syllables": ["no", "more", "remem-", "bran-", "ce", "be:"]}, {"text": "Of those that in the grave do lie,", "syllables": ["Of", "those", "that", "in", "the", "grave", "do", "lie,"]}, {"text": "who shall give thanks to thee?"}]}, {"index": 4, "lines": [{"text": "I with my groaning weary am,", "syllables": ["I", "with", "my", "groa-", "ning", "wea-", "ry", "am,"], "bibleVerseRef": 6}, {"text": "and all the night my bed"}, {"text": "I caused for to swim;", "syllables": ["I", "cau-", "-", "sed", "for", "to", "swi-", "m;"]}, {"text": "with tears my couch I watered.", "syllables": ["with", "tears", "my", "couch", "I", "watered."]}]}, {"index": 5, "lines": [{"text": "By reason of my vexing grief,", "bibleVerseRef": 7}, {"text": "mine eye consumed is;"}, {"text": "It waxeth old, because of all"}, {"text": "that be mine enemies."}]}, {"index": 6, "lines": [{"text": "But now, depart from me all ye", "bibleVerseRef": 8}, {"text": "that work iniquity:"}, {"text": "For why? the Lord hath heard my voice,"}, {"text": "when I did mourn and cry."}]}, {"index": 7, "lines": [{"text": "Unto my supplication", "syllables": ["un-", "to", "my", "su-", "p-", "pli-", "ca-", "tion"], "bibleVerseRef": 9}, {"text": "the Lord did hearing give:"}, {"text": "When I to him my prayer make,"}, {"text": "the Lord will it receive."}]}, {"index": 8, "lines": [{"text": "Let all be sham''d and troubled sore,", "bibleVerseRef": 10}, {"text": "That en''mies are to me;"}, {"text": "Let them turn back, and suddenly"}, {"text": "ashamed let them be."}]}]', 'CM', 'Second Version', 'In thy great indignation...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (164, 'rectCzhigRgHyDBFb', 68, '68', '1Let God arise, and scatterèd
let all his en''mies be;
And let all those that do him hate
before his presence flee.

2As smoke is driv''n, so drive thou them;
as fire melts wax away,
Before God''s face let wicked men
so perish and decay.

3But let the righteous be glad:
let them before God''s sight
Be very joyful; yea, let them
rejoice with all their might.

4To God sing, to his name sing praise;
extol him with your voice,
That rides on heav''n, by his name Jah,
before his face rejoice.

5Because the Lord a father is
unto the fatherless;
God is the widow''s judge, within
his place of holiness.

6God doth the solitary set
in fam''lies: and from bands
The chain''d doth free; but rebels do
inhabit parched lands.

7O God, what time thou didst go forth
before thy people''s face;
And when through the great wilderness
thy glorious marching was;

8Then at God''s presence shook the earth,
then drops from heaven fell;
This Sinai shook before the Lord,
the God of Israel.

9O God, thou to thine heritage
didst send a plenteous rain,
Whereby thou, when it weary was,
didst it refresh again.

10Thy congregation then did make
their habitation there:
Of thine own goodness for the poor,
O God, thou didst prepare.

11The Lord himself did give the word,
the word abroad did spread;
Great was the company of them
the same who published.

12Kings of great armies foiled were,
and forced to flee away;
And women, who remained at home,
did distribute the prey.

13Though ye have lien among the pots,
like doves ye shall appear,
Whose wings with silver, and with gold
whose feathers covered are.

14When there th'' Almighty scatter''d kings,
like Salmon''s snow ''twas white.
15God''s hill is like to Bashan hill,
like Bashan hill for height.

16Why do ye leap, ye mountains high?
this is the hill where God
Desires to dwell; yea, God in it
for aye will make abode.

17God''s chariots twenty thousand are,
thousands of angels strong;
In''s holy place God is, as in
mount Sinai, them among.

18Thou hast, O Lord, most glorious,
ascended up on high;
And in triumph victorious led
captive captivity:

Thou hast received gifts for men,
for such as did rebel;
Yea, ev''n for them, that God the Lord
in midst of them might dwell.

19Blessed be the Lord, who is to us
of our salvation God;
Who daily with his benefits
us plenteously doth load.

20He of salvation is the God,
who is our God most strong;
And unto God the Lord from death
the issues do belong.

21But surely God shall wound the head
of those that are his foes;
The hairy scalp of him that still
on in his trespass goes.

22God said, My people I will bring
again from Bashan hill;
Yea, from the sea''s devouring depths
them bring again I will;

23That in the blood of enemies
thy foot imbrued may be,
And of thy dogs dipped in the same
the tongues thou mayest see.

24Thy goings they have seen, O God;
the steps of majesty
Of my God, and my mighty King,
within the sanctuary.

25Before went singers, players next
on instruments took way;
And them among the damsels were
that did on timbrels play.

26Within the congregations
bless God with one accord:
From Isr''el''s fountain do ye bless
and praise the mighty Lord.

27With their prince, little Benjamin,
princes and council there
Of Judah were, there Zabulon''s
and Napht''li''s princes were.

28Thy God commands thy strength; make strong
what thou wrought''st for us, Lord.
29For thy house at Jerusalem
kings shall thee gifts afford.

30The spearmen''s host, the multitude
of bulls, which fiercely look,
Those calves which people have forth sent,
O Lord our God, rebuke,

Till ev''ry one submit himself,
and silver pieces bring:
The people that delight in war
disperse, O God and King.

31Those that be princes great shall then
come out of Egypt lands;
And Ethiopia to God
shall soon stretch out her hands.

32O all ye kingdoms of the earth,
sing praises to this King;
For he is Lord that ruleth all,
unto him praises sing.

33To him that rides on heav''ns of heav''ns,
which he of old did found;
Lo, he sends out his voice, a voice
in might that doth abound.

34Strength unto God do ye ascribe;
for his excellency
Is over Israel, his strength
is in the clouds most high.

35Thou''rt from thy temple dreadful, Lord;
Isr''el''s own God is he,
Who gives his people strength and pow''r:
O let God blessed be.', '[{"index": 0, "lines": [{"text": "Let God arise, and scatterèd", "syllables": ["Let", "God", "a-", "rise-", ",", "and", "scat-", "terèd"], "bibleVerseRef": 1}, {"text": "let all his en''mies be;"}, {"text": "And let all those that do him hate"}, {"text": "before his presence flee."}]}, {"index": 1, "lines": [{"text": "As smoke is driv''n, so drive thou them;", "syllables": ["As", "smoke", "is", "driv''n,", "so", "drive", "thou", "them;"], "bibleVerseRef": 2}, {"text": "as fire melts wax away,"}, {"text": "Before God''s face let wicked men"}, {"text": "so perish and decay."}]}, {"index": 2, "lines": [{"text": "But let the righteous be glad:", "syllables": ["But", "let", "the", "ri-", "gh-", "teous", "be", "glad:"], "bibleVerseRef": 3}, {"text": "let them before God''s sight"}, {"text": "Be very joyful; yea, let them"}, {"text": "rejoice with all their might."}]}, {"index": 3, "lines": [{"text": "To God sing, to his name sing praise;", "bibleVerseRef": 4}, {"text": "extol him with your voice,"}, {"text": "That rides on heav''n, by his name Jah,"}, {"text": "before his face rejoice."}]}, {"index": 4, "lines": [{"text": "Because the Lord a father is", "bibleVerseRef": 5}, {"text": "unto the fatherless;"}, {"text": "God is the widow''s judge, within", "syllables": ["God", "is", "the", "widow''s", "jud-", "ge,", "wi-", "thin"]}, {"text": "his place of holiness.", "syllables": ["his", "place", "of", "ho-", "li-", "ness."]}]}, {"index": 5, "lines": [{"text": "God doth the solitary set", "bibleVerseRef": 6}, {"text": "in fam''lies: and from bands"}, {"text": "The chain''d doth free; but rebels do"}, {"text": "inhabit parched lands."}]}, {"index": 6, "lines": [{"text": "O God, what time thou didst go forth", "bibleVerseRef": 7}, {"text": "before thy people''s face;", "syllables": ["before", "thy", "pe-", "o-", "ple''s", "face;"]}, {"text": "And when through the great wilderness"}, {"text": "thy glorious marching was;"}]}, {"index": 7, "lines": [{"text": "Then at God''s presence shook the earth,", "bibleVerseRef": 8}, {"text": "then drops from heaven fell;", "syllables": ["then", "drops", "from", "heave-", "n", "fell;"]}, {"text": "This Sinai shook before the Lord,"}, {"text": "the God of Israel.", "syllables": ["the", "God", "of", "is-", "rae-", "l."]}]}, {"index": 8, "lines": [{"text": "O God, thou to thine heritage", "bibleVerseRef": 9}, {"text": "didst send a plenteous rain,", "syllables": ["didst", "send", "a", "plenteo-", "us", "rain,"]}, {"text": "Whereby thou, when it weary was,"}, {"text": "didst it refresh again."}]}, {"index": 9, "lines": [{"text": "Thy congregation then did make", "bibleVerseRef": 10}, {"text": "their habitation there:"}, {"text": "Of thine own goodness for the poor,"}, {"text": "O God, thou didst prepare."}]}, {"index": 10, "lines": [{"text": "The Lord himself did give the word,", "bibleVerseRef": 11}, {"text": "the word abroad did spread;", "syllables": ["the", "word", "abro-", "ad", "did", "spread;"]}, {"text": "Great was the company of them"}, {"text": "the same who published."}]}, {"index": 11, "lines": [{"text": "Kings of great armies foiled were,", "bibleVerseRef": 12}, {"text": "and forced to flee away;", "syllables": ["and", "forced", "to", "flee", "a-", "way;"]}, {"text": "And women, who remained at home,"}, {"text": "did distribute the prey."}]}, {"index": 12, "lines": [{"text": "Though ye have lien among the pots,", "bibleVerseRef": 13}, {"text": "like doves ye shall appear,"}, {"text": "Whose wings with silver, and with gold"}, {"text": "whose feathers covered are."}]}, {"index": 13, "lines": [{"text": "When there th'' Almighty scatter''d kings,", "syllables": ["When", "there", "th''", "almig-", "hty", "scat-", "ter''d", "kings,"], "bibleVerseRef": 14}, {"text": "like Salmon''s snow ''twas white."}, {"text": "God''s hill is like to Bashan hill,", "bibleVerseRef": 15}, {"text": "like Bashan hill for height."}]}, {"index": 14, "lines": [{"text": "Why do ye leap, ye mountains high?", "bibleVerseRef": 16}, {"text": "this is the hill where God"}, {"text": "Desires to dwell; yea, God in it"}, {"text": "for aye will make abode."}]}, {"index": 15, "lines": [{"text": "God''s chariots twenty thousand are,", "bibleVerseRef": 17}, {"text": "thousands of angels strong;"}, {"text": "In''s holy place God is, as in", "syllables": ["In''s", "holy", "pla-", "ce", "God", "is,", "as", "in"]}, {"text": "mount Sinai, them among."}]}, {"index": 16, "lines": [{"text": "Thou hast, O Lord, most glorious,", "syllables": ["Thou", "hast,", "O", "Lord,", "most", "glo-", "riou-", "s,"], "bibleVerseRef": 18}, {"text": "ascended up on high;"}, {"text": "And in triumph victorious led", "syllables": ["And", "in", "triu-", "mph", "vic-", "to-", "rious", "led"]}, {"text": "captive captivity:"}]}, {"index": 17, "lines": [{"text": "Thou hast received gifts for men,"}, {"text": "for such as did rebel;"}, {"text": "Yea, ev''n for them, that God the Lord"}, {"text": "in midst of them might dwell."}]}, {"index": 18, "lines": [{"text": "Blessed be the Lord, who is to us", "syllables": ["blessed", "be", "the", "Lord,", "who", "is", "to", "us"], "bibleVerseRef": 19}, {"text": "of our salvation God;"}, {"text": "Who daily with his benefits"}, {"text": "us plenteously doth load.", "syllables": ["us", "plenteous-", "ly", "doth", "lo-", "ad."]}]}, {"index": 19, "lines": [{"text": "He of salvation is the God,", "bibleVerseRef": 20}, {"text": "who is our God most strong;"}, {"text": "And unto God the Lord from death"}, {"text": "the issues do belong."}]}, {"index": 20, "lines": [{"text": "But surely God shall wound the head", "bibleVerseRef": 21}, {"text": "of those that are his foes;"}, {"text": "The hairy scalp of him that still"}, {"text": "on in his trespass goes."}]}, {"index": 21, "lines": [{"text": "God said, My people I will bring", "syllables": ["God", "said,", "My", "peo-", "ple", "I", "will", "bring"], "bibleVerseRef": 22}, {"text": "again from Bashan hill;"}, {"text": "Yea, from the sea''s devouring depths"}, {"text": "them bring again I will;"}]}, {"index": 22, "lines": [{"text": "That in the blood of enemies", "bibleVerseRef": 23}, {"text": "thy foot imbrued may be,"}, {"text": "And of thy dogs dipped in the same", "syllables": ["And", "of", "thy", "dogs", "dipped", "in", "the", "same"]}, {"text": "the tongues thou mayest see.", "syllables": ["the", "tongue-", "s", "thou", "mayest", "see."]}]}, {"index": 23, "lines": [{"text": "Thy goings they have seen, O God;", "syllables": ["Thy", "goi-", "ngs", "they", "have", "seen,", "O", "God;"], "bibleVerseRef": 24}, {"text": "the steps of majesty"}, {"text": "Of my God, and my mighty King,"}, {"text": "within the sanctuary.", "syllables": ["within", "the", "san-", "ctu-", "a-", "ry."]}]}, {"index": 24, "lines": [{"text": "Before went singers, players next", "syllables": ["be-", "fore", "went", "sin-", "gers,", "playe-", "rs", "next"], "bibleVerseRef": 25}, {"text": "on instruments took way;"}, {"text": "And them among the damsels were"}, {"text": "that did on timbrels play."}]}, {"index": 25, "lines": [{"text": "Within the congregations", "syllables": ["wi-", "thin", "the", "con-", "gre-", "ga-", "tio-", "ns"], "bibleVerseRef": 26}, {"text": "bless God with one accord:"}, {"text": "From Isr''el''s fountain do ye bless"}, {"text": "and praise the mighty Lord."}]}, {"index": 26, "lines": [{"text": "With their prince, little Benjamin,", "syllables": ["With", "their", "prince,", "lit-", "tle", "ben-", "ja-", "min,"], "bibleVerseRef": 27}, {"text": "princes and council there"}, {"text": "Of Judah were, there Zabulon''s"}, {"text": "and Napht''li''s princes were."}]}, {"index": 27, "lines": [{"text": "Thy God commands thy strength; make strong", "bibleVerseRef": 28}, {"text": "what thou wrought''st for us, Lord."}, {"text": "For thy house at Jerusalem", "syllables": ["For", "thy", "hou-", "se", "at", "je-", "ru-", "salem"], "bibleVerseRef": 29}, {"text": "kings shall thee gifts afford."}]}, {"index": 28, "lines": [{"text": "The spearmen''s host, the multitude", "bibleVerseRef": 30}, {"text": "of bulls, which fiercely look,", "syllables": ["of", "bulls,", "which", "fierce-", "ly", "look,"]}, {"text": "Those calves which people have forth sent,", "syllables": ["Those", "calves", "which", "peo-", "ple", "have", "forth", "sent,"]}, {"text": "O Lord our God, rebuke,"}]}, {"index": 29, "lines": [{"text": "Till ev''ry one submit himself,"}, {"text": "and silver pieces bring:", "syllables": ["and", "sil-", "ver", "piece-", "s", "bring:"]}, {"text": "The people that delight in war", "syllables": ["The", "peo-", "ple", "that", "de-", "light", "in", "war"]}, {"text": "disperse, O God and King.", "syllables": ["disper-", "se,", "O", "God", "and", "King."]}]}, {"index": 30, "lines": [{"text": "Those that be princes great shall then", "bibleVerseRef": 31}, {"text": "come out of Egypt lands;"}, {"text": "And Ethiopia to God", "syllables": ["And", "e-", "thio-", "-", "pi-", "a", "to", "God"]}, {"text": "shall soon stretch out her hands."}]}, {"index": 31, "lines": [{"text": "O all ye kingdoms of the earth,", "bibleVerseRef": 32}, {"text": "sing praises to this King;", "syllables": ["sing", "praise-", "s", "to", "this", "King;"]}, {"text": "For he is Lord that ruleth all,"}, {"text": "unto him praises sing.", "syllables": ["un-", "to", "him", "praise-", "s", "sing."]}]}, {"index": 32, "lines": [{"text": "To him that rides on heav''ns of heav''ns,", "bibleVerseRef": 33}, {"text": "which he of old did found;"}, {"text": "Lo, he sends out his voice, a voice"}, {"text": "in might that doth abound."}]}, {"index": 33, "lines": [{"text": "Strength unto God do ye ascribe;", "syllables": ["Strength", "unto", "God", "do", "ye", "as-", "cri-", "be;"], "bibleVerseRef": 34}, {"text": "for his excellency"}, {"text": "Is over Israel, his strength", "syllables": ["Is", "over", "is-", "rae-", "l,", "his", "stre-", "ngth"]}, {"text": "is in the clouds most high."}]}, {"index": 34, "lines": [{"text": "Thou''rt from thy temple dreadful, Lord;", "syllables": ["Thou-", "''rt", "from", "thy", "temple", "dread-", "ful,", "Lord;"], "bibleVerseRef": 35}, {"text": "Isr''el''s own God is he,"}, {"text": "Who gives his people strength and pow''r:", "syllables": ["Who", "gives", "his", "peo-", "ple", "strength", "and", "pow''r:"]}, {"text": "O let God blessed be."}]}]', 'CM', NULL, 'Let God arise, and scatterèd...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (160, 'recrHxwxEbTnLsHlz', 45, '45 (Second Version, Recommended)', '1My heart inditing is
good matter in a song:
I speak the things that I have made,
which to the King belong:

My tongue shall be as quick,
his honour to indite,
As is the pen of any scribe
that useth fast to write.

2Thou''rt fairest of all men;
grace in thy lips doth flow:
And therefore blessings evermore
on thee doth God bestow.

3Thy sword gird on thy thigh,
thou that art most of might:
Appear in dreadful majesty,
and in thy glory bright.

4For meekness, truth, and right,
ride prosp''rously in state;
And thy right hand shall teach to thee
things terrible and great.

5Thy shafts shall pierce their hearts
that foes are to the King;
Whereby into subjection
the people thou shalt bring.

6Thy royal seat, O Lord,
for ever shall remain:
The sceptre of thy kingdom doth
all righteousness maintain.

7Thou lov''st right, and hat''st ill;
for God, thy God, most high,
Above thy fellows hath with th'' oil
of joy anointed thee.

8Of myrrh and spices sweet
a smell thy garments had,
Out of the iv''ry palaces,
whereby they made thee glad.

9And in thy glorious train
kings'' daughters waiting stand;
And thy fair queen, in Ophir gold,
doth stand at thy right hand.

10O daughter, take good heed,
incline, and give good ear;
Thou must forget thy kindred all,
and father''s house most dear.

11Thy beauty to the King
shall then delightful be:
And do thou humbly worship him,
because thy Lord is he.

12The daughter then of Tyre
there with a gift shall be,
And all the wealthy of the land
shall make their suit to thee.

13The daughter of the King
all glorious is within;
And with embroideries of gold
her garments wrought have been.

14She cometh to the King
in robes with needle wrought;
The virgins that do follow her
shall unto thee be brought.

15They shall be brought with joy,
and mirth on ev''ry side,
Into the palace of the King,
and there they shall abide.

16And in thy fathers'' stead,
thy children thou may''st take,
And in all places of the earth
them noble princes make.

17I will shew forth thy name
to generations all:
Therefore the people evermore
to thee give praises shall.', '[{"index": 0, "lines": [{"text": "My heart inditing is", "bibleVerseRef": 1}, {"text": "good matter in a song:"}, {"text": "I speak the things that I have made,"}, {"text": "which to the King belong:"}]}, {"index": 1, "lines": [{"text": "My tongue shall be as quick,", "syllables": ["My", "tongue", "shall", "be", "as", "quick,"]}, {"text": "his honour to indite,"}, {"text": "As is the pen of any scribe", "syllables": ["As", "is", "the", "pen", "of", "any", "scri-", "be"]}, {"text": "that useth fast to write.", "syllables": ["that", "useeth", "fast", "to", "wri-", "te."]}]}, {"index": 2, "lines": [{"text": "Thou''rt fairest of all men;", "syllables": ["Thou-", "''rt", "fairest", "of", "all", "men;"], "bibleVerseRef": 2}, {"text": "grace in thy lips doth flow:", "syllables": ["grace", "in", "thy", "lips", "doth", "flow:"]}, {"text": "And therefore blessings evermore", "syllables": ["And", "there-", "-", "fore", "bles-", "sings", "ever-", "more"]}, {"text": "on thee doth God bestow."}]}, {"index": 3, "lines": [{"text": "Thy sword gird on thy thigh,", "bibleVerseRef": 3}, {"text": "thou that art most of might:"}, {"text": "Appear in dreadful majesty,"}, {"text": "and in thy glory bright."}]}, {"index": 4, "lines": [{"text": "For meekness, truth, and right,", "bibleVerseRef": 4}, {"text": "ride prosp''rously in state;"}, {"text": "And thy right hand shall teach to thee"}, {"text": "things terrible and great."}]}, {"index": 5, "lines": [{"text": "Thy shafts shall pierce their hearts", "syllables": ["Thy", "shafts", "shall", "pierce", "their", "hearts"], "bibleVerseRef": 5}, {"text": "that foes are to the King;"}, {"text": "Whereby into subjection", "syllables": ["where-", "-", "by", "in-", "to", "sub-", "jec-", "tion"]}, {"text": "the people thou shalt bring.", "syllables": ["the", "peo-", "ple", "thou", "shalt", "bring."]}]}, {"index": 6, "lines": [{"text": "Thy royal seat, O Lord,", "syllables": ["Thy", "roya-", "l", "seat,", "O", "Lord,"], "bibleVerseRef": 6}, {"text": "for ever shall remain:", "syllables": ["for", "ever", "sha-", "ll", "re-", "main:"]}, {"text": "The sceptre of thy kingdom doth", "syllables": ["The", "sce-", "ptre", "of", "thy", "kin-", "gdom", "doth"]}, {"text": "all righteousness maintain."}]}, {"index": 7, "lines": [{"text": "Thou lov''st right, and hat''st ill;", "bibleVerseRef": 7}, {"text": "for God, thy God, most high,"}, {"text": "Above thy fellows hath with th'' oil", "syllables": ["above", "thy", "fel-", "lows", "hath", "with", "th''", "oil"]}, {"text": "of joy anointed thee."}]}, {"index": 8, "lines": [{"text": "Of myrrh and spices sweet", "bibleVerseRef": 8}, {"text": "a smell thy garments had,"}, {"text": "Out of the iv''ry palaces,", "syllables": ["Out", "of", "the", "iv-", "''ry", "pa-", "lace-", "s,"]}, {"text": "whereby they made thee glad."}]}, {"index": 9, "lines": [{"text": "And in thy glorious train", "bibleVerseRef": 9}, {"text": "kings'' daughters waiting stand;"}, {"text": "And thy fair queen, in Ophir gold,"}, {"text": "doth stand at thy right hand."}]}, {"index": 10, "lines": [{"text": "O daughter, take good heed,", "bibleVerseRef": 10}, {"text": "incline, and give good ear;", "syllables": ["incli-", "ne,", "and", "give", "good", "ear;"]}, {"text": "Thou must forget thy kindred all,"}, {"text": "and father''s house most dear."}]}, {"index": 11, "lines": [{"text": "Thy beauty to the King", "bibleVerseRef": 11}, {"text": "shall then delightful be:"}, {"text": "And do thou humbly worship him,"}, {"text": "because thy Lord is he."}]}, {"index": 12, "lines": [{"text": "The daughter then of Tyre", "bibleVerseRef": 12}, {"text": "there with a gift shall be,"}, {"text": "And all the wealthy of the land"}, {"text": "shall make their suit to thee.", "syllables": ["shall", "make", "their", "suit", "to", "thee."]}]}, {"index": 13, "lines": [{"text": "The daughter of the King", "bibleVerseRef": 13}, {"text": "all glorious is within;"}, {"text": "And with embroideries of gold"}, {"text": "her garments wrought have been."}]}, {"index": 14, "lines": [{"text": "She cometh to the King", "bibleVerseRef": 14}, {"text": "in robes with needle wrought;", "syllables": ["in", "robes", "with", "needle", "wrou-", "ght;"]}, {"text": "The virgins that do follow her"}, {"text": "shall unto thee be brought."}]}, {"index": 15, "lines": [{"text": "They shall be brought with joy,", "bibleVerseRef": 15}, {"text": "and mirth on ev''ry side,"}, {"text": "Into the palace of the King,"}, {"text": "and there they shall abide."}]}, {"index": 16, "lines": [{"text": "And in thy fathers'' stead,", "bibleVerseRef": 16}, {"text": "thy children thou may''st take,"}, {"text": "And in all places of the earth"}, {"text": "them noble princes make."}]}, {"index": 17, "lines": [{"text": "I will shew forth thy name", "bibleVerseRef": 17}, {"text": "to generations all:"}, {"text": "Therefore the people evermore"}, {"text": "to thee give praises shall.", "syllables": ["to", "thee", "give", "praise-", "s", "shall."]}]}]', 'SM', 'Second Version', 'My heart inditing is...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (167, 'recuVXIKZCbSVgb43', 136, '136 (Second Version)', '1Praise God, for he is kind:
His mercy lasts for aye
2Give thanks with heart and mind
To God of gods alway:

For certainly
His mercies dure
Most firm and sure
Eternally.

3The Lord of lords praise ye,
Whose mercies still endure.
4Great wonders only he
Doth work by his great pow''r

For certainly
His mercies dure
Most firm and sure
Eternally.

5Which God omnipotent,
By might and wisdom high,
The heav''n and firmament
Did frame, as we may see:

For certainly
His mercies dure
Most firm and sure
Eternally.

6To him who did outstretch
This earth so great and wide,
Above the waters'' reach
Making it to abide:

For certainly
His mercies dure
Most firm and sure
Eternally.

7Great lights he made to be;
For his grace lasteth aye:
8Such as the sun we see,
To rule the lightsome day:

For certainly
His mercies dure
Most firm and sure
Eternally.

9Also the moon so clear,
Which shineth in our sight;
The stars that do appear,
To guide the darksome night:

For certainly
His mercies dure
Most firm and sure
Eternally.

10To him that Egypt smote,
Who did his message scorn;
And in his anger hot
Did kill all their first-born:

For certainly
His mercies dure
Most firm and sure
Eternally.

11Thence Isr''el out he brought;
For his grace lasteth ever.
12With a strong hand he wrought,
And stretch''d-out arm deliver:

For certainly
His mercies dure
Most firm and sure
Eternally.

13The sea he cut in two;
For his grace lasteth still.
14And through its midst to go
Made his own Israel:

For certainly
His mercies dure
Most firm and sure
Eternally.

15But overwhelm''d and lost
Was proud king Pharaoh,
With all his mighty host,
And chariots there also:

For certainly
His mercies dure
Most firm and sure
Eternally.

16To him who pow''rfully
His chosen people led,
Ev''n through the desert dry,
And in that place them fed:

For certainly
His mercies dure
Most firm and sure
Eternally.

17To him great kings who smote;
For his grace hath no bound.
18Who slew, and spared not
Kings famous and renown''d:

For certainly
His mercies dure
Most firm and sure
Eternally.

19Sihon the Am''rites'' king;
For his grace lasteth ever:
20Og also, who did reign
The land of Bashan over:

For certainly
His mercies dure
Most firm and sure
Eternally.

21Their land by lot he gave;
For his grace faileth never,
22That Isr''el might it have
In heritage for ever:

For certainly
His mercies dure
Most firm and sure
Eternally.

23Who hath remembered
Us in our low estate;
24And us delivered
From foes which did us hate:

For certainly
His mercies dure
Most firm and sure
Eternally.

25Who to all flesh gives food;
For his grace faileth never
26Give thanks to God most good,
The God of heav''n, for ever:

For certainly
His mercies dure
Most firm and sure
Eternally.', NULL, '66 66 88', 'Second Version', 'Praise God, for he is kind...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (169, 'recv1knOCLFj1vkBZ', 102, '102 (First Version)', '1O Lord, unto my pray''r give ear,
my cry let come to thee;
2And in the day of my distress
hide not thy face from me.

Give ear to me; what time I call,
to answer me make haste:
3For, as an hearth, my bones are burnt,
my days, like smoke, do waste.

4My heart within me smitten is,
and it is withered
Like very grass; so that I do
forget to eat my bread.

5By reason of my groaning voice
my bones cleave to my skin.
6Like pelican in wilderness
forsaken I have been:

I like an owl in desert am,
that nightly there doth moan;
7I watch, and like a sparrow am
on the house-top alone.

8My bitter en''mies all the day
reproaches cast on me;
And, being mad at me, with rage
against me sworn they be.

9For why? I ashes eaten have
like bread, in sorrows deep;
My drink I also mingled have
with tears that I did weep.

10Thy wrath and indignation
did cause this grief and pain;
For thou hast lift me up on high,
and cast me down again.

11My days are like unto a shade,
which doth declining pass;
And I am dry''d and withered,
ev''n like unto the grass.

12But thou, Lord, everlasting art,
and thy remembrance shall
Continually endure,
and be to generations all.

13Thou shalt arise, and mercy have
upon thy Sion yet;
The time to favour her is come,
the time that thou hast set.

14For in her rubbish and her stones
thy servants pleasure take;
Yea, they the very dust thereof
do favour for her sake.

15So shall the heathen people fear
the Lord''s most holy name;
And all the kings on earth shall dread
thy glory and thy fame.

16When Sion by the mighty Lord
built up again shall be,
In glory then and majesty
to men appear shall he.

17The prayer of the destitute
he surely will regard;
Their prayer will he not despise,
by him it shall be heard.

18For generations yet to come
this shall be on record:
So shall the people that shall be
created praise the Lord.

19He from his sanctuary''s height
hath downward cast his eye;
And from his glorious throne in heav''n
the Lord the earth did spy;

20That of the mournful prisoner
the groanings he might hear,
To set them free that unto death
by men appointed are:

21That they in Sion may declare
the Lord''s most holy name,
And publish in Jerusalem
the praises of the same;

22When as the people gather shall
in troops with one accord,
When kingdoms shall assembled be
to serve the highest Lord.

23My wonted strength and force he hath
abated in the way,
And he my days hath shortened:
24Thus therefore did I say,

My God, in mid-time of my days
take thou me not away:
From age to age eternally
thy years endure and stay.

25The firm foundation of the earth
of old time thou hast laid;
The heavens also are the work
which thine own hands have made.

26Thou shalt for evermore endure,
but they shall perish all;
Yea, ev''ry one of them wax old,
like to a garment, shall:

Thou, as a vesture, shalt them change,
and they shall changed be:
27But thou the same art,
and thy years are to eternity.

28The children of thy servants shall
continually endure;
And in thy sight, O Lord, their seed
shall be establish''d sure.', '[{"index": 0, "lines": [{"text": "O Lord, unto my pray''r give ear,", "bibleVerseRef": 1}, {"text": "my cry let come to thee;"}, {"text": "And in the day of my distress", "bibleVerseRef": 2}, {"text": "hide not thy face from me."}]}, {"index": 1, "lines": [{"text": "Give ear to me; what time I call,"}, {"text": "to answer me make haste:", "syllables": ["to", "answer", "me", "make", "has-", "te:"]}, {"text": "For, as an hearth, my bones are burnt,", "bibleVerseRef": 3}, {"text": "my days, like smoke, do waste.", "syllables": ["my", "days,", "like", "smoke,", "do", "waste."]}]}, {"index": 2, "lines": [{"text": "My heart within me smitten is,", "bibleVerseRef": 4}, {"text": "and it is withered"}, {"text": "Like very grass; so that I do"}, {"text": "forget to eat my bread."}]}, {"index": 3, "lines": [{"text": "By reason of my groaning voice", "syllables": ["By", "reason", "of", "my", "gro-", "a-", "ning", "voice"], "bibleVerseRef": 5}, {"text": "my bones cleave to my skin.", "syllables": ["my", "bones", "cleave", "to", "my", "skin."]}, {"text": "Like pelican in wilderness", "bibleVerseRef": 6}, {"text": "forsaken I have been:", "syllables": ["for-", "sake-", "n", "I", "have", "been:"]}]}, {"index": 4, "lines": [{"text": "I like an owl in desert am,"}, {"text": "that nightly there doth moan;", "syllables": ["that", "nightly", "there", "doth", "mo-", "an;"]}, {"text": "I watch, and like a sparrow am", "bibleVerseRef": 7}, {"text": "on the house-top alone."}]}, {"index": 5, "lines": [{"text": "My bitter en''mies all the day", "bibleVerseRef": 8}, {"text": "reproaches cast on me;", "syllables": ["repro-", "a-", "ches", "cast", "on", "me;"]}, {"text": "And, being mad at me, with rage", "syllables": ["And,", "bei-", "ng", "mad", "at", "me,", "with", "rage"]}, {"text": "against me sworn they be."}]}, {"index": 6, "lines": [{"text": "For why? I ashes eaten have", "bibleVerseRef": 9}, {"text": "like bread, in sorrows deep;"}, {"text": "My drink I also mingled have"}, {"text": "with tears that I did weep."}]}, {"index": 7, "lines": [{"text": "Thy wrath and indignation", "syllables": ["Thy", "wra-", "th", "and", "in-", "dig-", "na-", "tion"], "bibleVerseRef": 10}, {"text": "did cause this grief and pain;"}, {"text": "For thou hast lift me up on high,"}, {"text": "and cast me down again."}]}, {"index": 8, "lines": [{"text": "My days are like unto a shade,", "bibleVerseRef": 11}, {"text": "which doth declining pass;"}, {"text": "And I am dry''d and withered,"}, {"text": "ev''n like unto the grass."}]}, {"index": 9, "lines": [{"text": "But thou, Lord, everlasting art,", "syllables": ["But", "thou-", ",", "Lord,", "ever-", "las-", "ting", "art,"], "bibleVerseRef": 12}, {"text": "and thy remembrance shall", "syllables": ["and", "thy", "remem-", "bran-", "ce", "shall"]}, {"text": "Continually endure,", "syllables": ["con-", "ti-", "nu-", "a-", "lly", "en-", "dure-", ","]}, {"text": "and be to generations all.", "syllables": ["and", "be", "to", "genera-", "tions", "all."]}]}, {"index": 10, "lines": [{"text": "Thou shalt arise, and mercy have", "bibleVerseRef": 13}, {"text": "upon thy Sion yet;", "syllables": ["u-", "pon", "thy", "Sio-", "n", "yet;"]}, {"text": "The time to favour her is come,"}, {"text": "the time that thou hast set."}]}, {"index": 11, "lines": [{"text": "For in her rubbish and her stones", "syllables": ["For", "in", "her", "rubbish", "and", "her", "sto-", "nes"], "bibleVerseRef": 14}, {"text": "thy servants pleasure take;"}, {"text": "Yea, they the very dust thereof"}, {"text": "do favour for her sake."}]}, {"index": 12, "lines": [{"text": "So shall the heathen people fear", "syllables": ["So", "shall", "the", "heathen", "pe-", "o-", "ple", "fear"], "bibleVerseRef": 15}, {"text": "the Lord''s most holy name;"}, {"text": "And all the kings on earth shall dread"}, {"text": "thy glory and thy fame."}]}, {"index": 13, "lines": [{"text": "When Sion by the mighty Lord", "syllables": ["Whe-", "n", "Sion", "by", "the", "mig-", "hty", "Lord"], "bibleVerseRef": 16}, {"text": "built up again shall be,", "syllables": ["built", "up", "a-", "gain", "shall", "be,"]}, {"text": "In glory then and majesty"}, {"text": "to men appear shall he."}]}, {"index": 14, "lines": [{"text": "The prayer of the destitute", "syllables": ["The", "prayer", "of", "the", "des-", "ti-", "tu-", "te"], "bibleVerseRef": 17}, {"text": "he surely will regard;"}, {"text": "Their prayer will he not despise,"}, {"text": "by him it shall be heard."}]}, {"index": 15, "lines": [{"text": "For generations yet to come", "bibleVerseRef": 18}, {"text": "this shall be on record:"}, {"text": "So shall the people that shall be", "syllables": ["So", "shall", "the", "peo-", "ple", "that", "shall", "be"]}, {"text": "created praise the Lord.", "syllables": ["crea-", "ted", "prai-", "se", "the", "Lord."]}]}, {"index": 16, "lines": [{"text": "He from his sanctuary''s height", "bibleVerseRef": 19}, {"text": "hath downward cast his eye;"}, {"text": "And from his glorious throne in heav''n", "syllables": ["And", "from", "his", "glorious", "thro-", "ne", "in", "heav''n"]}, {"text": "the Lord the earth did spy;"}]}, {"index": 17, "lines": [{"text": "That of the mournful prisoner", "syllables": ["That", "of", "the", "mou-", "r-", "nful", "pri-", "soner"], "bibleVerseRef": 20}, {"text": "the groanings he might hear,", "syllables": ["the", "groa-", "nings", "he", "might", "hear,"]}, {"text": "To set them free that unto death"}, {"text": "by men appointed are:"}]}, {"index": 18, "lines": [{"text": "That they in Sion may declare", "syllables": ["Tha-", "t", "they", "in", "Sion", "may", "dec-", "lare"], "bibleVerseRef": 21}, {"text": "the Lord''s most holy name,"}, {"text": "And publish in Jerusalem", "syllables": ["And", "pub-", "lish", "in", "je-", "ru-", "sale-", "m"]}, {"text": "the praises of the same;", "syllables": ["the", "praise-", "s", "of", "the", "same;"]}]}, {"index": 19, "lines": [{"text": "When as the people gather shall", "syllables": ["When", "as", "the", "peo-", "ple", "ga-", "ther", "shall"], "bibleVerseRef": 22}, {"text": "in troops with one accord,"}, {"text": "When kingdoms shall assembled be"}, {"text": "to serve the highest Lord."}]}, {"index": 20, "lines": [{"text": "My wonted strength and force he hath", "syllables": ["My", "wonted", "strength", "and", "for-", "ce", "he", "hath"], "bibleVerseRef": 23}, {"text": "abated in the way,"}, {"text": "And he my days hath shortened:"}, {"text": "Thus therefore did I say,", "bibleVerseRef": 24}]}, {"index": 21, "lines": [{"text": "My God, in mid-time of my days", "syllables": ["My", "God,", "in", "mid-ti-", "me", "of", "my", "days"]}, {"text": "take thou me not away:"}, {"text": "From age to age eternally", "syllables": ["From", "age", "to", "age", "ete-", "r-", "nal-", "ly"]}, {"text": "thy years endure and stay."}]}, {"index": 22, "lines": [{"text": "The firm foundation of the earth", "bibleVerseRef": 25}, {"text": "of old time thou hast laid;"}, {"text": "The heavens also are the work", "syllables": ["The", "heave-", "ns", "al-", "so", "are", "the", "work"]}, {"text": "which thine own hands have made."}]}, {"index": 23, "lines": [{"text": "Thou shalt for evermore endure,", "syllables": ["Thou", "sha-", "lt", "for", "ever-", "more", "en-", "dure,"], "bibleVerseRef": 26}, {"text": "but they shall perish all;"}, {"text": "Yea, ev''ry one of them wax old,"}, {"text": "like to a garment, shall:"}]}, {"index": 24, "lines": [{"text": "Thou, as a vesture, shalt them change,", "syllables": ["Thou,", "as", "a", "vesture,", "shalt", "them", "chan-", "ge,"]}, {"text": "and they shall changed be:"}, {"text": "But thou the same art,", "syllables": ["But", "tho-", "-", "-", "u", "the", "same", "art,"], "bibleVerseRef": 27}, {"text": "and thy years are to eternity.", "syllables": ["and", "thy", "years", "are", "to", "eternity."]}]}, {"index": 25, "lines": [{"text": "The children of thy servants shall", "bibleVerseRef": 28}, {"text": "continually endure;", "syllables": ["conti-", "nu-", "a-", "lly", "en-", "dure;"]}, {"text": "And in thy sight, O Lord, their seed"}, {"text": "shall be establish''d sure."}]}]', 'CM', 'First Version', 'O Lord, unto my pray''r give ear...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (159, 'recqWLM1Jp206BAC9', 79, '79', '1O God, the heathen enter''d have
thine heritage; by them
Defiled is thy house: on heaps
they laid Jerusalem.

2The bodies of thy servants they
have cast forth to be meat
To rav''nous fowls; thy dear saints'' flesh
they gave to beasts to eat.

3Their blood about Jerusalem
like water they have shed;
And there was none to bury them
when they were slain and dead.

4Unto our neighbours a reproach
most base become are we;
A scorn and laughingstock to them
that round about us be.

5How long, Lord, shall thine anger last?
wilt thou still keep the same?
And shall thy fervent jealousy
burn like unto a flame?

6On heathen pour thy fury forth,
that have thee never known,
And on those kingdoms which thy name
have never call''d upon.

7For these are they who Jacob have
devoured cruelly;
And they his habitation
have caused waste to lie.

8Against us mind not former sins;
thy tender mercies show;
Let them prevent us speedily,
for we''re brought very low.

9For thy name''s glory help us, Lord,
who hast our Saviour been:
Deliver us; for thy name''s sake,
O purge away our sin.

10Why say the heathen, Where''s their God?
let him to them be known;
When those who shed thy servants'' blood
are in our sight o''erthrown.

11O let the pris''ner''s sighs ascend
before thy sight on high;
Preserve those in thy mighty pow''r
that are design''d to die.

12And to our neighbours'' bosom cause
it sev''n-fold render''d be,
Ev''n the reproach wherewith they have,
O Lord, reproached thee.

13So we thy folk, and pasture-sheep,
shall give thee thanks always;
And unto generations all
we will shew forth thy praise.', '[{"index": 0, "lines": [{"text": "O God, the heathen enter''d have", "bibleVerseRef": 1}, {"text": "thine heritage; by them"}, {"text": "Defiled is thy house: on heaps", "syllables": ["de-", "filed", "is", "thy", "house-", ":", "on", "heaps"]}, {"text": "they laid Jerusalem.", "syllables": ["they", "laid", "je-", "ru-", "sale-", "m."]}]}, {"index": 1, "lines": [{"text": "The bodies of thy servants they", "bibleVerseRef": 2}, {"text": "have cast forth to be meat"}, {"text": "To rav''nous fowls; thy dear saints'' flesh"}, {"text": "they gave to beasts to eat."}]}, {"index": 2, "lines": [{"text": "Their blood about Jerusalem", "syllables": ["Thei-", "r", "blood", "a-", "bout", "je-", "ru-", "salem"], "bibleVerseRef": 3}, {"text": "like water they have shed;", "syllables": ["like", "wate-", "r", "they", "have", "shed;"]}, {"text": "And there was none to bury them", "syllables": ["And", "there", "was", "none", "to", "bu-", "ry", "them"]}, {"text": "when they were slain and dead."}]}, {"index": 3, "lines": [{"text": "Unto our neighbours a reproach", "syllables": ["unto", "our", "neig-", "hbours", "a", "rep-", "ro-", "ach"], "bibleVerseRef": 4}, {"text": "most base become are we;"}, {"text": "A scorn and laughingstock to them"}, {"text": "that round about us be."}]}, {"index": 4, "lines": [{"text": "How long, Lord, shall thine anger last?", "bibleVerseRef": 5}, {"text": "wilt thou still keep the same?"}, {"text": "And shall thy fervent jealousy", "syllables": ["And", "shall", "thy", "ferve-", "nt", "jea-", "lou-", "sy"]}, {"text": "burn like unto a flame?", "syllables": ["burn", "like", "unto", "a", "fla-", "me?"]}]}, {"index": 5, "lines": [{"text": "On heathen pour thy fury forth,", "bibleVerseRef": 6}, {"text": "that have thee never known,"}, {"text": "And on those kingdoms which thy name"}, {"text": "have never call''d upon."}]}, {"index": 6, "lines": [{"text": "For these are they who Jacob have", "bibleVerseRef": 7}, {"text": "devoured