INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (72, 'recRg5EhjIEhd2u41', 116, '116', '1I love the Lord, because my voice
and prayers he did hear.
2I, while I live, will call on him,
who bow''d to me his ear.

3Of death the cords and sorrows did
about me compass round;
The pains of hell took hold on me,
I grief and trouble found.

4Upon the name of God the Lord
then did I call, and say,
Deliver thou my soul, O Lord,
I do thee humbly pray.

5God merciful and righteous is,
yea, gracious is our Lord.
6God saves the meek: I was brought low,
he did me help afford.

7O thou my soul, do thou return
unto thy quiet rest;
For largely, lo, the Lord to thee
his bounty hath exprest.

8For my distressed soul from death
deliver''d was by thee:
Thou didst my mourning eyes from tears,
my feet from falling, free.

9I in the land of those that live
will walk the Lord before.
10I did believe, therefore I spake:
I was afflicted sore.

11I said, when I was in my haste,
that all men liars be.
12What shall I render to the Lord
for all his gifts to me?

13I''ll of salvation take the cup,
on God''s name will I call:
14I''ll pay my vows now to the Lord
before his people all.

15Dear in God''s sight is his saints'' death.
16Thy servant, Lord, am I;
Thy servant sure, thine handmaid''s son:
my bands thou didst untie.

17Thank-off ''rings I to thee will give,
and on God''s name will call.
18I''ll pay my vows now to the Lord
before his people all;

19Within the courts of God''s own house,
within the midst of thee,
O city of Jerusalem.
Praise to the Lord give ye.', '[{"index": 0, "lines": [{"text": "I love the Lord, because my voice", "bibleVerseRef": 1}, {"text": "and prayers he did hear."}, {"text": "I, while I live, will call on him,", "bibleVerseRef": 2}, {"text": "who bow''d to me his ear."}]}, {"index": 1, "lines": [{"text": "Of death the cords and sorrows did", "bibleVerseRef": 3}, {"text": "about me compass round;"}, {"text": "The pains of hell took hold on me,"}, {"text": "I grief and trouble found."}]}, {"index": 2, "lines": [{"text": "Upon the name of God the Lord", "bibleVerseRef": 4}, {"text": "then did I call, and say,"}, {"text": "Deliver thou my soul, O Lord,", "syllables": ["de-", "live-", "r", "thou", "my", "soul,", "O", "Lord,"]}, {"text": "I do thee humbly pray."}]}, {"index": 3, "lines": [{"text": "God merciful and righteous is,", "bibleVerseRef": 5}, {"text": "yea, gracious is our Lord."}, {"text": "God saves the meek: I was brought low,", "bibleVerseRef": 6}, {"text": "he did me help afford."}]}, {"index": 4, "lines": [{"text": "O thou my soul, do thou return", "bibleVerseRef": 7}, {"text": "unto thy quiet rest;", "syllables": ["unto", "thy", "qu-", "i-", "et", "rest;"]}, {"text": "For largely, lo, the Lord to thee", "syllables": ["For", "large-", "ly,", "lo,", "the", "Lord", "to", "thee"]}, {"text": "his bounty hath exprest."}]}, {"index": 5, "lines": [{"text": "For my distressed soul from death", "bibleVerseRef": 8}, {"text": "deliver''d was by thee:"}, {"text": "Thou didst my mourning eyes from tears,"}, {"text": "my feet from falling, free."}]}, {"index": 6, "lines": [{"text": "I in the land of those that live", "bibleVerseRef": 9}, {"text": "will walk the Lord before."}, {"text": "I did believe, therefore I spake:", "syllables": ["I", "did", "believe,", "there-", "fore", "I", "spa-", "ke:"], "bibleVerseRef": 10}, {"text": "I was afflicted sore."}]}, {"index": 7, "lines": [{"text": "I said, when I was in my haste,", "syllables": ["I", "said,", "when", "I", "was", "in", "