INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (173, 'recwUxXE9VPRCs99z', 50, '50 (Second Version)', '1The mighty God, the Lord, hath spoke,
and call''d the earth upon,
Ev''n from the rising of the sun
unto his going down.

2From out of Sion, his own hill,
where the perfection high
Of beauty is, from thence the Lord
hath shined gloriously.

3Our God shall come, and shall no more
be silent, but speak out;
Before him fire shall waste, great storms
shall compass him about.

4He to the heavens from above,
and to the earth below,
Shall call, that he his judgments may
before his people show.

5Let all my saints together be
unto me gathered;
Those that by sacrifice with me
a covenant have made.

6And then the heavens shall declare
his righteousness abroad;
Because the Lord himself doth come;
none else is judge but God.

7Hear, O my people, and I''ll speak;
O Israel by name,
Against thee I will testify;
God, ev''n thy God, I am.

8I for thy sacrifices few
reprove thee never will,
Nor for burnt-off ''rings to have been
before me offer''d still.

9I''ll take no bullock nor he-goats
from house nor folds of thine:
10For beasts of forests, cattle all
on thousand hills, are mine.

11The fowls are all to me well known
that mountains high do yield;
And I do challenge as mine own
the wild beasts of the field.

12If I were hungry, I would not
to thee for need complain;
For earth, and all its fulness, doth
to me of right pertain.

13That I to eat the flesh of bulls
take pleasure dost thou think?
Or that I need, to quench my thirst,
the blood of goats to drink?

14Nay, rather unto me, thy God,
thanksgiving offer thou:
To the most High perform thy word,
and fully pay thy vow:

15And in the day of trouble great
see that thou call on me;
I will deliver thee, and thou
my name shalt glorify.

16But God unto the wicked saith,
Why should''st thou mention make
Of my commands? how dar''st thou in
thy mouth my cov''nant take?

17Sith it is so that thou dost hate
all good instruction;
And sith thou cast''st behind thy back,
and slight''st my words each one.

18When thou a thief didst see, then straight
thou join''dst with him in sin,
And with the vile adulterers
thou hast partaker been.

19Thy mouth to evil thou dost give,
thy tongue deceit doth frame
20Thou sitt''st, and ''gainst thy brother speak''st,
thy mother''s son to shame.

21These things thou wickedly hast done,
and I have silent been:
Thou thought''st that I was like thyself,
and did approve thy sin;

But I will sharply thee reprove,
and I will order right
Thy sins and thy transgressions
in presence of thy sight.

22Consider this, and be afraid,
ye that forget the Lord,
Lest I in pieces tear you all,
when none can help afford.

23Who off''reth praise me glorifies:
I will shew God''s salvation
To him that ordereth aright
his life and conversation.', '[{"index": 0, "lines": [{"text": "The mighty God, the Lord, hath spoke,", "syllables": ["The", "mighty", "God,", "the", "Lord,", "hath", "spo-", "ke,"], "bibleVerseRef": 1}, {"text": "and call''d the earth upon,"}, {"text": "Ev''n from the rising of the sun"}, {"text": "unto his going down.", "syllables": ["un-", "to", "his", "goi-", "ng", "down."]}]}, {"index": 1, "lines": [{"text": "From out of Sion, his own hill,", "syllables": ["From", "out", "of", "Sio-", "n,", "his", "own", "hill,"], "bibleVerseRef": 2}, {"text": "where the perfection high"}, {"text": "Of beauty is, from thence the Lord"}, {"text": "hath shined gloriously."}]}, {"index": 2, "lines": [{"text": "Our God shall come, and shall no more", "bibleVerseRef": 3}, {"text": "be silent, but speak out;", "syllables": ["be", "sile-", "nt,", "but", "speak", "out;"]}, {"text": "Before him fire shall waste, great storms", "syllables": ["before", "him", "fire", "shall", "was-", "te,", "great", "storms"]}, {"text": "shall compass him about."}]}, {"index": 3, "lines": [{"text": "He to the heavens from above,", "syllables": ["He", "to", "the", "heave-", "ns", "from", "a-", "bove,"], "bibleVerseRef": 4}, {"text": "and to the earth below,"}, {"text": "Shall call, that he his judgments may"}, {"text": "before his people show.", "syllables": ["before", "his", "pe-", "o-", "ple", "show."]}]}, {"index": 4, "lines": [{"text": "Let all my saints together be", "bibleVerseRef": 5}, {"text": "unto me gathered;"}, {"text": "Those that by sacrifice with me"}, {"text": "a covenant have made.", "syllables": ["a", "cove-", "-", "nant", "have", "made."]}]}, {"index": 5, "lines": [{"text": "And then the heavens shall declare", "syllables": ["And", "then", "the", "heave-", "ns", "shall", "dec-", "lare"], "bibleVerseRef": 6}, {"text": "his righteousness abroad;", "syllables": ["his", "righteous-", "ness", "ab-", "ro-", "ad;"]}, {"text": "Because the Lord himself doth come;"}, {"text": "none else is judge but God.", "syllables": ["none", "else", "is", "judge", "but", "God."]}]}, {"index": 6, "lines": [{"text": "Hear, O my people, and I''ll speak;", "syllables": ["Hear,", "O", "my", "peo-", "ple,", "and", "I''ll", "speak;"], "bibleVerseRef": 7}, {"text": "O Israel by name,", "syllables": ["O", "is-", "rael", "by", "name-", ","]}, {"text": "Against thee I will testify;"}, {"text": "God, ev''n thy God, I am."}]}, {"index": 7, "lines": [{"text": "I for thy sacrifices few", "syllables": ["I", "for", "thy", "sac-", "ri-", "fice-", "s", "few"], "bibleVerseRef": 8}, {"text": "reprove thee never will,"}, {"text": "Nor for burnt-off ''rings to have been"}, {"text": "before me offer''d still."}]}, {"index": 8, "lines": [{"text": "I''ll take no bullock nor he-goats", "syllables": ["I''ll", "take", "no", "bullock", "nor", "he--", "go-", "ats"], "bibleVerseRef": 9}, {"text": "from house nor folds of thine:"}, {"text": "For beasts of forests, cattle all", "syllables": ["For", "beasts", "of", "fore-", "sts,", "cat-", "tle", "all"], "bibleVerseRef": 10}, {"text": "on thousand hills, are mine."}]}, {"index": 9, "lines": [{"text": "The fowls are all to me well known", "bibleVerseRef": 11}, {"text": "that mountains high do yield;"}, {"text": "And I do challenge as mine own", "syllables": ["And", "I", "do", "challen-", "ge", "as", "mine", "own"]}, {"text": "the wild beasts of the field."}]}, {"index": 10, "lines": [{"text": "If I were hungry, I would not", "bibleVerseRef": 12}, {"text": "to thee for need complain;"}, {"text": "For earth, and all its fulness, doth"}, {"text": "to me of right pertain."}]}, {"index": 11, "lines": [{"text": "That I to eat the flesh of bulls", "bibleVerseRef": 13}, {"text": "take pleasure dost thou think?"}, {"text": "Or that I need, to quench my thirst,"}, {"text": "the blood of goats to drink?", "syllables": ["the", "blood", "of", "goats", "to", "drink?"]}]}, {"index": 12, "lines": [{"text": "Nay, rather unto me, thy God,", "bibleVerseRef": 14}, {"text": "thanksgiving offer thou:"}, {"text": "To the most High perform thy word,"}, {"text": "and fully pay thy vow:"}]}, {"index": 13, "lines": [{"text": "And in the day of trouble great", "bibleVerseRef": 15}, {"text": "see that thou call on me;"}, {"text": "I will deliver thee, and thou", "syllables": ["I", "will", "de-", "live-", "r", "thee,", "and", "thou"]}, {"text": "my name shalt glorify."}]}, {"index": 14, "lines": [{"text": "But God unto the wicked saith,", "bibleVerseRef": 16}, {"text": "Why should''st thou mention make"}, {"text": "Of my commands? how dar''st thou in"}, {"text": "thy mouth my cov''nant take?"}]}, {"index": 15, "lines": [{"text": "Sith it is so that thou dost hate", "bibleVerseRef": 17}, {"text": "all good instruction;", "syllables": ["all", "good", "in-", "stru-", "c-", "tion;"]}, {"text": "And sith thou cast''st behind thy back,"}, {"text": "and slight''st my words each one."}]}, {"index": 16, "lines": [{"text": "When thou a thief didst see, then straight", "bibleVerseRef": 18}, {"text": "thou join''dst with him in sin,"}, {"text": "And with the vile adulterers"}, {"text": "thou hast partaker been.", "syllables": ["thou", "hast", "par-", "take-", "r", "been."]}]}, {"index": 17, "lines": [{"text": "Thy mouth to evil thou dost give,", "bibleVerseRef": 19}, {"text": "thy tongue deceit doth frame", "syllables": ["thy", "tongue", "deceit", "doth", "fra-", "me"]}, {"text": "Thou sitt''st, and ''gainst thy brother speak''st,", "bibleVerseRef": 20}, {"text": "thy mother''s son to shame."}]}, {"index": 18, "lines": [{"text": "These things thou wickedly hast done,", "bibleVerseRef": 21}, {"text": "and I have silent been:", "syllables": ["and", "I", "have", "sile-", "nt", "been:"]}, {"text": "Thou thought''st that I was like thyself,", "syllables": ["Thou", "thou-", "ght''st", "that", "I", "was", "like", "thyself,"]}, {"text": "and did approve thy sin;", "syllables": ["and", "did", "appro-", "ve", "thy", "sin;"]}]}, {"index": 19, "lines": [{"text": "But I will sharply thee reprove,"}, {"text": "and I will order right"}, {"text": "Thy sins and thy transgressions", "syllables": ["Thy", "sins", "and", "thy", "tran-", "sgre-", "s-", "sions"]}, {"text": "in presence of thy sight."}]}, {"index": 20, "lines": [{"text": "Consider this, and be afraid,", "syllables": ["con-", "side-", "r", "this,", "and", "be", "af-", "raid,"], "bibleVerseRef": 22}, {"text": "ye that forget the Lord,"}, {"text": "Lest I in pieces tear you all,", "syllables": ["Lest", "I", "in", "piece-", "s", "tear", "you", "all,"]}, {"text": "when none can help afford.", "syllables": ["when", "none", "can", "help", "af-", "ford."]}]}, {"index": 21, "lines": [{"text": "Who off''reth praise me glorifies:", "bibleVerseRef": 23}, {"text": "I will shew God''s salvation", "syllables": ["I", "will", "shew", "God''s", "salva-", "tion"]}, {"text": "To him that ordereth aright"}, {"text": "his life and conversation.", "syllables": ["his", "life", "and", "conver-", "sa-", "tion."]}]}]', 'CM', 'First Version', 'The mighty God, the Lord, hath spoke...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (171, 'recvmXXJCkEffpFXp', 105, '105', '1Give thanks to God, call on his name;
to men his deeds make known.
2Sing ye to him, sing psalms; proclaim
his wondrous works each one.

3See that ye in his holy name
to glory do accord;
And let the heart of ev''ry one
rejoice that seeks the Lord.

4The Lord Almighty, and his strength,
with stedfast hearts seek ye:
His blessed and his gracious face
seek ye continually.

5Think on the works that he hath done,
which admiration breed;
His wonders, and the judgments all
which from his mouth proceed;

6O ye that are of Abr''ham''s race,
his servant well approv''n;
And ye that Jacob''s children are,
whom he chose for his own.

7Because he, and he only, is
the mighty Lord our God;
And his most righteous judgments are
in all the earth abroad.

8His cov''nant he remember''d hath,
that it may ever stand:
To thousand generations
the word he did command.

9Which covenant he firmly made
with faithful Abraham,
And unto Isaac, by his oath,
he did renew the same:

10And unto Jacob, for a law,
he made it firm and sure,
A covenant to Israel,
which ever should endure.

11He said, I''ll give Canaan''s land
for heritage to you;
12While they were strangers there,
and few, in number very few:

13While yet they went from land to land
without a sure abode;
And while through sundry kingdoms they
did wander far abroad;

14Yet, notwithstanding suffer''d he
no man to do them wrong:
Yea, for their sakes, he did reprove
kings, who were great and strong.

15Thus did he say, Touch ye not those
that mine anointed be,
Nor do the prophets any harm
that do pertain to me.

16He call''d for famine on the land,
he brake the staff of bread:
17But yet he sent a man before,
by whom they should be fed;

Ev''n Joseph, whom unnat''rally
sell for a slave did they;
18Whose feet with fetters they did hurt,
and he in irons lay;

19Until the time that his word came
to give him liberty;
The word and purpose of the Lord
did him in prison try.

20Then sent the king, and did command
that he enlarg''d should be:
He that the people''s ruler was
did send to set him free.

21A lord to rule his family
he rais''d him, as most fit;
To him of all that he possess''d
he did the charge commit:

22That he might at his pleasure bind
the princes of the land;
And he might teach his senators
wisdom to understand.

23The people then of Israel
down into Egypt came;
And Jacob also sojourned
within the land of Ham.

24And he did greatly by his pow''r
increase his people there;
And stronger than their enemies
they by his blessing were.

25Their heart he turned to envy
his folk maliciously,
With those that his own servants were
to deal in subtilty.

26His servant Moses he did send,
Aaron his chosen one.
27By these his signs and wonders great
in Ham''s land were made known.

28Darkness he sent, and made it dark;
his word they did obey.
29He turn''d their waters into blood,
and he their fish did slay.

30The land in plenty brought forth frogs
in chambers of their kings.
31His word all sorts of flies and lice
in all their borders brings.

32He hail for rain, and flaming fire
into their land he sent:
33And he their vines and fig-trees smote:
trees of their coasts he rent.

34He spake, and caterpillars came,
locusts did much abound;
35Which in their land all herbs consum''d,
and all fruits of their ground.

36He smote all first-born in their land,
chief of their strength each one.
37With gold and silver brought them forth,
weak in their tribes were none.

38Egypt was glad when forth they went,
their fear on them did light.
39He spread a cloud for covering,
and fire to shine by night.

40They ask''d, and he brought quails:
with bread of heav''n he filled them.
41He open''d rocks, floods gush''d,
and ran in deserts like a stream.

42For on his holy promise he,
and servant Abr''ham, thought.
43With joy his people, his elect
with gladness, forth he brought.

44And unto them the pleasant lands
he of the heathen gave;
That of the people''s labour they
inheritance might have.

45That they his statutes might observe
according to his word;
And that they might his laws obey.
