INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (45, 'recEWle38UGV1shlY', 126, '126', '1When Sion''s bondage God turn''d back,
as men that dream''d were we.
2Then fill''d with laughter was our mouth,
our tongue with melody:

They ''mong the heathen said, The Lord
great things for them hath wrought.
3The Lord hath done great things for us,
whence joy to us is brought.

4As streams of water in the south,
our bondage, Lord, recall.
5Who sow in tears, a reaping time
of joy enjoy they shall.

6That man who, bearing precious seed,
in going forth doth mourn,
He doubtless, bringing back his sheaves,
rejoicing shall return.', '[{"index": 0, "lines": [{"text": "When Sion''s bondage God turn''d back,", "syllables": ["When", "Sio-", "n''s", "bon-", "dage", "God", "turn''d", "back,"], "bibleVerseRef": 1}, {"text": "as men that dream''d were we."}, {"text": "Then fill''d with laughter was our mouth,", "bibleVerseRef": 2}, {"text": "our tongue with melody:", "syllables": ["our", "tongue", "with", "me-", "lo-", "dy:"]}]}, {"index": 1, "lines": [{"text": "They ''mong the heathen said, The Lord"}, {"text": "great things for them hath wrought."}, {"text": "The Lord hath done great things for us,", "bibleVerseRef": 3}, {"text": "whence joy to us is brought."}]}, {"index": 2, "lines": [{"text": "As streams of water in the south,", "syllables": ["As", "strea-", "ms", "of", "water", "in", "the", "south,"], "bibleVerseRef": 4}, {"text": "our bondage, Lord, recall."}, {"text": "Who sow in tears, a reaping time", "bibleVerseRef": 5}, {"text": "of joy enjoy they shall."}]}, {"index": 3, "lines": [{"text": "That man who, bearing precious seed,", "bibleVerseRef": 6}, {"text": "in going forth doth mourn,", "syllables": ["in", "going", "forth", "doth", "mou-", "rn,"]}, {"text": "He doubtless, bringing back his sheaves,"}, {"text": "rejoicing shall return."}]}]', 'CM', NULL, 'When Sion''s bondage God turn''d back...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (49, 'recGDPYl7p8ykRRq4', 85, '85', '1O Lord, thou hast been favourable
to thy beloved land:
Jacob''s captivity thou hast
recall''d with mighty hand.

2Thou pardoned thy people hast
all their iniquities;
Thou all their trespasses and sins
hast cover''d from thine eyes.

3Thou took''st off all thine ire, and turn''dst
from thy wrath''s furiousness.
4Turn us, God of our health, and cause
thy wrath ''gainst us to cease.

5Shall thy displeasure thus endure
against us without end?
Wilt thou to generations all
thine anger forth extend?

6That in thee may thy people joy,
wilt thou not us revive?
7Shew us thy mercy, Lord, to us
do thy salvation give.

8I''ll hear what God the Lord will speak:
to his folk he''ll speak peace,
And to his saints; but let them not
return to foolishness.

9To them that fear him surely near
is his salvation;
That glory in our land may have
her habitation.

10Truth met with mercy, righteousness
and peace kiss''d mutually:
11Truth springs from earth, and righteousness
looks down from heaven high.

12Yea, what is good the Lord shall give;
our land shall yield increase:
13Justice, to set us in his steps,
shall go before his face.', '[{"index": 0, "lines": [{"text": "O Lord, thou hast been favourable", "syllables": ["O", "Lord,", "thou", "hast", "been", "favou-", "rab-", "le"], "bibleVerseRef": 1}, {"text": "to thy beloved land:"}, {"text": "Jacob''s captivity thou hast"}, {"text": "recall''d with mighty hand."}]}, {"index": 1, "lines": [{"text": "Thou pardoned thy people hast", "syllables": ["Thou", "pardo-", "ned", "thy", "pe-", "o-", "ple", "hast"], "bibleVerseRef": 2}, {"text": "all their iniquities;"}, {"text": "Thou all their trespasses and sins"}, {"text": "hast cover''d from thine eyes.", "syllables": ["hast", "cove-", "r''d", "from", "thine", "eyes."]}]}, {"index": 2, "lines": [{"text": "Thou took''st off all thine ire, and turn''dst", "bibleVerseRef": 3}, {"text": "from thy wrath''s furiousness."}, {"text": "Turn us, God of our health, and cause", "bibleVerseRef": 4}, {"text": "thy wrath ''gainst us to cease."}]}, {"index": 3, "lines": [{"text": "Shall thy displeasure thus endure", "bibleVerseRef": 5}, {"text": "against us without end?"}, {"text": "Wilt thou to generations all"}, {"text": "thine anger forth extend?"}]}, {"index": 4, "lines": [{"text": "That in thee may thy people joy,", "syllables": ["That", "in", "thee", "may", "thy", "peo-", "ple", "joy,"], "bibleVerseRef": 6}, {"text": "wilt thou not us revive?", "syllables": ["wilt", "thou", "not", "us", "revi-", "ve?"]}, {"text": "Shew us thy mercy, Lord, to us", "bibleVerseRef": 7}, {"text": "do thy salvation give."}]}, {"index": 5, "lines": [{"text": "I''ll hear what God the Lord will speak:", "bibleVerseRef": 8}, {"text": "to his folk he''ll speak peace,"}, {"text": "And to his saints; but let them not"}, {"text": "return to foolishness."}]}, {"index": 6, "lines": [{"text": "To them that fear him surely near", "bibleVerseRef": 9}, {"text": "is his salvation;", "syllables": ["is", "his", "sal-", "va-", "tio-", "n;"]}, {"text": "That glory in our land may have"}, {"text": "her habitation.", "syllables": ["her", "ha-", "bi-", "ta-", "tio-", "n."]}]}, {"index": 7, "lines": [{"text": "Truth met with mercy, righteousness", "bibleVerseRef": 10}, {"text": "and peace kiss''d mutually:", "syllables": ["and", "peace", "kiss''d", "mutu-", "a-", "lly:"]}, {"text": "Truth springs from earth, and righteousness", "bibleVerseRef": 11}, {"text": "looks down from heaven high.", "syllables": ["looks", "down", "from", "heave-", "n", "high."]}]}, {"index": 8, "lines": [{"text": "Yea, what is good the Lord shall give;", "bibleVerseRef": 12}, {"text": "our land shall yield increase:", "syllables": ["our", "land", "shall", "yield", "increa-", "se:"]}, {"text": "Justice, to set us in his steps,", "bibleVerseRef": 13}, {"text": "shall go before his face."}]}]', 'CM', NULL, 'O Lord, thou hast been favourable...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (50, 'recGEuCilj3yoGTxM', 76, '76', '1In Judah''s land God is well known,
his name''s in Isr''el great:
2In Salem is his tabernacle,
in Sion is his seat.

3There arrows of the bow he brake,
the shield, the sword, the war.
4More glorious thou than hills of prey,
more excellent art far.

5Those that were stout of heart are spoil''d,
they slept their sleep outright;
And none of those their hands did find,
that were the men of might.

6When thy rebuke, O Jacob''s God,
had forth against them past,
Their horses and their chariots both
were in a dead sleep cast.

7Thou, Lord, ev''n thou art he that should
be fear''d; and who is he
That may stand up before thy sight,
if once thou angry be?

8From heav''n thou judgment caus''d be heard;
the earth was still with fear,
9When God to judgment rose, to save
all meek on earth that were.

10Surely the very wrath of man
unto thy praise redounds:
Thou to the remnant of his wrath
wilt set restraining bounds.

11Vow to the Lord your God,
and pay: all ye that near him be,
Bring gifts and presents unto him;
for to be fear''d is he.

12By him the sp''rits shall be cut off
of those that princes are:
Unto the kings that are on earth
he fearful doth appear.', '[{"index": 0, "lines": [{"text": "In Judah''s land God is well known,", "bibleVerseRef": 1}, {"text": "his name''s in Isr''el great:"}, {"text": "In Salem is his tabernacle,", "syllables": ["In", "Salem", "is", "his", "tabe-", "r-", "nac-", "le,"], "bibleVerseRef": 2}, {"text": "in Sion is his seat.", "syllables": ["in", "Sion", "is", "his", "sea-", "t."]}]}, {"index": 1, "lines": [{"text": "There arrows of the bow he brake,", "syllables": ["There", "arrows", "of", "the", "bow", "he", "bra-", "ke,"], "bibleVerseRef": 3}, {"text": "the shield, the sword, the war."}, {"text": "More glorious thou than hills of prey,", "bibleVerseRef": 4}, {"text": "more excellent art far.", "syllables": ["more", "ex-", "celle-", "nt", "art", "far."]}]}, {"index": 2, "lines": [{"text": "Those that were stout of heart are spoil''d,", "bibleVerseRef": 5}, {"text": "they slept their sleep outright;"}, {"text": "And none of those their hands did find,", "syllables": ["And", "none", "of", "those", "their", "hands", "did", "find,"]}, {"text": "that were the men of might."}]}, {"index": 3, "lines": [{"text": "When thy rebuke, O Jacob''s God,", "bibleVerseRef": 6}, {"text": "had forth against them past,"}, {"text": "Their horses and their chariots both"}, {"text": "were in a dead sleep cast."}]}, {"index": 4, "lines": [{"text": "Thou, Lord, ev''n thou art he that should", "bibleVerseRef": 7}, {"text": "be fear''d; and who is he"}, {"text": "That may stand up before thy sight,"}, {"text": "if once thou angry be?", "syllables": ["if", "once", "thou", "an-", "gry", "be?"]}]}, {"index": 5, "lines": [{"text": "From heav''n thou judgment caus''d be heard;", "bibleVerseRef": 8}, {"text": "the earth was still with fear,"}, {"text": "When God to judgment rose, to save", "bibleVerseRef": 9}, {"text": "all meek on earth that were."}]}, {"index": 6, "lines": [{"text": "Surely the very wrath of man", "bibleVerseRef": 10}, {"text": "unto thy praise redounds:"}, {"text": "Thou to the remnant of his wrath"}, {"text": "wilt set restraining bounds."}]}, {"index": 7, "lines": [{"text": "Vow to the Lord your God,", "syllables": ["Vow", "to", "the", "Lo-", "rd", "you-", "r", "God,"], "bibleVerseRef": 11}, {"text": "and pay: all ye that near him be,", "syllables": ["and", "pay:", "all", "ye", "that", "nearhimbe,"]}, {"text": "Bring gifts and presents unto him;"}, {"text": "for to be fear''d is he."}]}, {"index": 8, "lines": [{"text": "By him the sp''rits shall be cut off", "bibleVerseRef": 12}, {"text": "of those that princes are:"}, {"text": "Unto the kings that are on earth"}, {"text": "he fearful doth appear."}]}]', 'CM', NULL, 'In Judah''s land God is well known...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (94, 'recXy5qr8Qqn2rbTE', 141, '141', '1O Lord, I unto thee do cry,
do thou make haste to me,
And give an ear unto my voice,
when I cry unto thee.

2As incense let my prayer be
directed in thine eyes;
And the uplifting of my hands
as th'' ev ''ning sacrifice.

3Set, Lord, a watch before my mouth,
keep of my lips the door.
4My heart incline thou not unto
the ills I should abhor,

To practise wicked works with men
that work iniquity;
And with their delicates my taste
let me not satisfy.

5Let him that righteous is me smite,
it shall a kindness be;
Let him reprove, I shall it count
a precious oil to me:

Such smiting shall not break my head;
for yet the time shall fall,
When I in their calamities
to God pray for them shall.

6When as their judges down shall be
in stony places cast,
Then shall they hear my words; for they
shall sweet be to their taste.

7About the grave''s devouring mouth
our bones are scatter''d round,
As wood which men do cut and cleave
lies scatter''d on the ground.

8But unto thee, O God the Lord,
mine eyes uplifted be:
My soul do not leave destitute;
my trust is set on thee.

9Lord, keep me safely from the snares
which they for me prepare;
And from the subtile gins of them
that wicked workers are.

10Let workers of iniquity
into their own nets fall,
Whilst I do, by thine help, escape
the danger of them all.', '[{"index": 0, "lines": [{"text": "O Lord, I unto thee do cry,", "bibleVerseRef": 1}, {"text": "do thou make haste to me,", "syllables": ["do", "thou", "make", "haste", "to", "me,"]}, {"text": "And give an ear unto my voice,"}, {"text": "when I cry unto thee."}]}, {"index": 1, "lines": [{"text": "As incense let my prayer be", "syllables": ["As", "incen-", "se", "let", "my", "pray-", "er", "be"], "bibleVerseRef": 2}, {"text": "directed in thine eyes;", "syllables": ["dire-", "c-", "ted", "in", "thine", "eyes;"]}, {"text": "And the uplifting of my hands"}, {"text": "as th'' ev ''ning sacrifice.", "syllables": ["as", "th''", "ev", "''ning", "sacri-", "fice."]}]}, {"index": 2, "lines": [{"text": "Set, Lord, a watch before my mouth,", "bibleVerseRef": 3}, {"text": "keep of my lips the door."}, {"text": "My heart incline thou not unto", "syllables": ["My", "heart", "incli-", "ne", "thou", "not", "un-", "to"], "bibleVerseRef": 4}, {"text": "the ills I should abhor,"}]}, {"index": 3, "lines": [{"text": "To practise wicked works with men"}, {"text": "that work iniquity;"}, {"text": "And with their delicates my taste", "syllables": ["And", "with", "their", "deli-", "cates", "my", "tas-", "te"]}, {"text": "let me not satisfy."}]}, {"index": 4, "lines": [{"text": "Let him that righteous is me smite,", "syllables": ["Let", "him", "that", "righteous", "is", "me", "smi-", "te,"], "bibleVerseRef": 5}, {"text": "it shall a kindness be;"}, {"text": "Let him reprove, I shall it count"}, {"text": "a precious oil to me:"}]}, {"index": 5, "lines": [{"text": "Such smiting shall not break my head;"}, {"text": "for yet the time shall fall,"}, {"text": "When I in their calamities"}, {"text": "to God pray for them shall."}]}, {"index": 6, "lines": [{"text": "When as their judges down shall be", "bibleVerseRef": 6}, {"text": "in stony places cast,"}, {"text": "Then shall they hear my words; for they"}, {"text": "shall sweet be to their taste.", "syllables": ["shall", "sweet", "be", "to", "their", "taste."]}]}, {"index": 7, "lines": [{"text": "About the grave''s devouring mouth", "syllables": ["about", "the", "gra-", "ve''s", "de-", "vou-", "ring", "mouth"], "bibleVerseRef": 7}, {"text": "our bones are scatter''d round,"}, {"text": "As wood which men do cut and cleave", "syllables": ["As", "wood", "which", "men", "do", "cut", "and", "cleave"]}, {"text": "lies scatter''d on the ground."}]}, {"index": 8, "lines": [{"text": "But unto thee, O God the Lord,", "bibleVerseRef": 8}, {"text": "mine eyes uplifted be:"}, {"text": "My soul do not leave destitute;", "syllables": ["My", "soul", "do", "not", "leave", "desti-", "tu-", "te;"]}, {"text": "my trust is set on thee."}]}, {"index": 9, "lines": [{"text": "Lord, keep me safely from the snares", "syllables": ["Lord,", "keep", "me", "safely", "from", "the", "sna-", "res"], "bibleVerseRef": 9}, {"text": "which they for me prepare;"}, {"text": "And from the subtile gins of them"}, {"text": "that wicked workers are."}]}, {"index": 10, "lines": [{"text": "Let workers of iniquity", "bibleVerseRef": 10}, {"text": "into their own nets fall,"}, {"text": "Whilst I do, by thine help, escape"}, {"text": "the danger of them all."}]}]', 'CM', NULL, 'O Lord, I unto thee do cry...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (63, 'recLm4xqDyVPUAKk8', 92, '92', '1To render thanks unto the Lord
it is a comely thing,
And to thy name, O thou most High,
due praise aloud to sing.

2Thy loving-kindness to shew forth
when shines the morning light;
And to declare thy faithfulness
with pleasure ev''ry night.

3On a ten-stringed instrument,
upon the psaltery,
And on the harp with solemn sound,
and grave sweet melody.

4For thou, Lord, by thy mighty works
hast made my heart right glad;
And I will triumph in the works
which by thine hands were made.

5How great, Lord, are thy works! each thought
of thine a deep it is:
6A brutish man it knoweth not;
fools understand not this.

7When those that lewd and wicked are
spring quickly up like grass,
And workers of iniquity
do flourish all apace;

It is that they for ever may
destroyed be and slain;
8But thou, O Lord, art the most High,
for ever to remain.

9For, lo, thine enemies, O Lord,
thine en''mies perish shall;
The workers of iniquity
shall be dispersed all.

10But thou shalt, like unto the horn
of th'' unicorn, exalt
My horn on high: thou with fresh oil
anoint me also shalt.

11Mine eyes shall also my desire
see on mine enemies;
Mine ears shall of the wicked hear
that do against me rise.

12But like the palm-tree flourishing
shall be the righteous one;
He shall like to the cedar grow
that is in Lebanon.

13Those that within the house of God
are planted by his grace,
They shall grow up, and flourish all
in our God''s holy place.

14And in old age, when others fade,
they fruit still forth shall bring;
They shall be fat, and full of sap,
and aye be flourishing;

15To shew that upright is the Lord:
he is a rock to me;
And he from all unrighteousness
is altogether free.', '[{"index": 0, "lines": [{"text": "To render thanks unto the Lord", "bibleVerseRef": 1}, {"text": "it is a comely thing,"}, {"text": "And to thy name, O thou most High,"}, {"text": "due praise aloud to sing."}]}, {"index": 1, "lines": [{"text": "Thy loving-kindness to shew forth", "bibleVerseRef": 2}, {"text": "when shines the morning light;"}, {"text": "And to declare thy faithfulness"}, {"text": "with pleasure ev''ry night."}]}, {"index": 2, "lines": [{"text": "On a ten-stringed instrument,", "bibleVerseRef": 3}, {"text": "upon the psaltery,"}, {"text": "And on the harp with solemn sound,", "syllables": ["And", "on", "the", "harp", "with", "sole-", "mn", "sound,"]}, {"text": "and grave sweet melody.", "syllables": ["and", "grave", "sweet", "me-", "lo-", "dy."]}]}, {"index": 3, "lines": [{"text": "For thou, Lord, by thy mighty works", "bibleVerseRef": 4}, {"text": "hast made my heart right glad;"}, {"text": "And I will triumph in the works", "syllables": ["And", "I", "will", "triu-", "mph", "in", "the", "works"]}, {"text": "which by thine hands were made."}]}, {"index": 4, "lines": [{"text": "How great, Lord, are thy works! each thought", "bibleVerseRef": 5}, {"text": "of thine a deep it is:"}, {"text": "A brutish man it knoweth not;", "bibleVerseRef": 6}, {"text": "fools understand not this."}]}, {"index": 5, "lines": [{"text": "When those that lewd and wicked are", "bibleVerseRef": 7}, {"text": "spring quickly up like grass,", "syllables": ["spring", "qui-", "ckly", "up", "like", "grass,"]}, {"text": "And workers of iniquity"}, {"text": "do flourish all apace;"}]}, {"index": 6, "lines": [{"text": "It is that they for ever may", "syllables": ["It", "is", "tha-", "t", "they", "for", "ever", "may"]}, {"text": "destroyed be and slain;", "syllables": ["des-", "troye-", "d", "be", "and", "slain;"]}, {"text": "But thou, O Lord, art the most High,", "bibleVerseRef": 8}, {"text": "for ever to remain.", "syllables": ["for", "ever", "to", "re-", "mai-", "n."]}]}, {"index": 7, "lines": [{"text": "For, lo, thine enemies, O Lord,", "bibleVerseRef": 9}, {"text": "thine en''mies perish shall;"}, {"text": "The workers of iniquity"}, {"text": "shall be dispersed all."}]}, {"index": 8, "lines": [{"text": "But thou shalt, like unto the horn", "bibleVerseRef": 10}, {"text": "of th'' unicorn, exalt", "syllables": ["of", "th''", "uni-", "corn,", "e-", "xalt"]}, {"text": "My horn on high: thou with fresh oil"}, {"text": "anoint me also shalt."}]}, {"index": 9, "lines": [{"text": "Mine eyes shall also my desire", "bibleVerseRef": 11}, {"text": "see on mine enemies;"}, {"text": "Mine ears shall of the wicked hear"}, {"text": "that do against me rise."}]}, {"index": 10, "lines": [{"text": "But like the palm-tree flourishing", "bibleVerseRef": 12}, {"text": "shall be the righteous one;"}, {"text": "He shall like to the cedar grow"}, {"text": "that is in Lebanon."}]}, {"index": 11, "lines": [{"text": "Those that within the house of God", "bibleVerseRef": 13}, {"text": "are planted by his grace,", "syllables": ["are", "planted", "by", "his", "gra-", "ce,"]}, {"text": "They shall grow up, and flourish all"}, {"text": "in our God''s holy place.", "syllables": ["in", "our", "God''s", "holy", "pla-", "ce."]}]}, {"index": 12, "lines": [{"text": "And in old age, when others fade,", "bibleVerseRef": 14}, {"text": "they fruit still forth shall bring;", "syllables": ["they", "fruit", "still", "forth", "shall", "bring;"]}, {"text": "They shall be fat, and full of sap,"}, {"text": "and aye be flourishing;"}]}, {"index": 13, "lines": [{"text": "To shew that upright is the Lord:", "bibleVerseRef": 15}, {"text": "he is a rock to me;"}, {"text": "And he from all unrighteousness"}, {"text": "is altogether free."}]}]', 'CM', NULL, 'To render thanks unto the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (65, 'recN6PZYvaekx7HsB', 138, '138', '1Thee will I praise with all my heart,
I will sing praise to thee
2Before the gods: And worship will
toward thy sanctuary.

I''ll praise thy name, ev''n for thy truth,
and kindness of thy love;
For thou thy word hast magnify''d
all thy great name above.

3Thou didst me answer in the day
when I to thee did cry;
And thou my fainting soul with strength
didst strengthen inwardly.

4All kings upon the earth that are
shall give thee praise, O Lord,
When as they from thy mouth shall hear
thy true and faithful word.

5Yea, in the righteous ways of God
with gladness they shall sing:
For great''s the glory of the Lord;
who doth for ever reign.

6Though God be high, yet he respects
all those that lowly be;
Whereas the proud and lofty ones
afar off knoweth he.

7Though I in midst of trouble walk,
I life from thee shall have:
''Gainst my foes'' wrath thou''lt stretch thine hand;
thy right hand shall me save.

8Surely that which concerneth me
the Lord will perfect make:
Lord, still thy mercy lasts; do not
thine own hands'' works forsake.', '[{"index": 0, "lines": [{"text": "Thee will I praise with all my heart,", "bibleVerseRef": 1}, {"text": "I will sing praise to thee"}, {"text": "Before the gods: And worship will", "bibleVerseRef": 2}, {"text": "toward thy sanctuary.", "syllables": ["toward", "thy", "san-", "ctu-", "a-", "ry."]}]}, {"index": 1, "lines": [{"text": "I''ll praise thy name, ev''n for thy truth,"}, {"text": "and kindness of thy love;"}, {"text": "For thou thy word hast magnify''d"}, {"text": "all thy great name above."}]}, {"index": 2, "lines": [{"text": "Thou didst me answer in the day", "bibleVerseRef": 3}, {"text": "when I to thee did cry;"}, {"text": "And thou my fainting soul with strength"}, {"text": "didst strengthen inwardly."}]}, {"index": 3, "lines": [{"text": "All kings upon the earth that are", "bibleVerseRef": 4}, {"text": "shall give thee praise, O Lord,"}, {"text": "When as they from thy mouth shall hear"}, {"text": "thy true and faithful word."}]}, {"index": 4, "lines": [{"text": "Yea, in the righteous ways of God", "bibleVerseRef": 5}, {"text": "with gladness they shall sing:"}, {"text": "For great''s the glory of the Lord;"}, {"text": "who doth for ever reign.", "syllables": ["who", "doth", "for", "ever", "rei-", "gn."]}]}, {"index": 5, "lines": [{"text": "Though God be high, yet he respects", "bibleVerseRef": 6}, {"text": "all those that lowly be;"}, {"text": "Whereas the proud and lofty ones", "syllables": ["Wherea-", "s", "the", "proud", "and", "lof-", "ty", "ones"]}, {"text": "afar off knoweth he."}]}, {"index": 6, "lines": [{"text": "Though I in midst of trouble walk,", "bibleVerseRef": 7}, {"text": "I life from thee shall have:"}, {"text": "''Gainst my foes'' wrath thou''lt stretch thine hand;"}, {"text": "thy right hand shall me save."}]}, {"index": 7, "lines": [{"text": "Surely that which concerneth me", "bibleVerseRef": 8}, {"text": "the Lord will perfect make:"}, {"text": "Lord, still thy mercy lasts; do not"}, {"text": "thine own hands'' works forsake."}]}]', 'CM', NULL, 'Thee will I praise with all my heart...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (70, 'recQI4pSzd6nTffsm', 134, '134', '1Behold, bless ye the Lord, all ye
that his attendants are,
Ev''n you that in God''s temple be,
and praise him nightly there.

2Your hands within God''s holy place
lift up, and praise his name.
3From Sion'' hill the Lord thee bless,
that heav''n and earth did frame.', '[{"index": 0, "lines": [{"text": "Behold, bless ye the Lord, all ye", "bibleVerseRef": 1}, {"text": "that his attendants are,"}, {"text": "Ev''n you that in God''s temple be,", "syllables": ["Ev''n", "you", "that", "in", "God''s", "te-", "mple", "be,"]}, {"text": "and praise him nightly there."}]}, {"index": 1, "lines": [{"text": "Your hands within God''s holy place", "syllables": ["Your", "hands", "within", "God''s", "ho-", "ly", "pla-", "ce"], "bibleVerseRef": 2}, {"text": "lift up, and praise his name."}, {"text": "From Sion'' hill the Lord thee bless,", "syllables": ["From", "Sion''", "hill", "the", "Lord", "thee", "ble-", "ss,"], "bibleVerseRef": 3}, {"text": "that heav''n and earth did frame.", "syllables": ["that", "heav''n", "and", "earth", "did", "frame."]}]}]', 'CM', NULL, 'Behold, bless ye the Lord, all ye...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (79, 'recUHZlS3eWRln5HS', 119, '119:41-48 (6)', '41Let thy sweet mercies also come
and visit me, O Lord;
Ev''n thy benign salvation,
according to thy word.

42So shall I have wherewith I may
give him an answer just,
Who spitefully reproacheth me;
for in thy word I trust.

43The word of truth out of my mouth
take thou not utterly;
For on thy judgments righteous
my hope doth still rely.

44So shall I keep for evermore
thy law continually.
45And, sith that I thy precepts seek,
I''ll walk at liberty.

46I''ll speak thy word to kings,
and I with shame shall not be mov''d;
47And will delight myself always
in thy laws, which I lov''d.

48To thy commandments, which I lov''d,
my hands lift up I will;
And I will also meditate
upon thy statutes still.
', '[{"index": 0, "lines": [{"text": "Let thy sweet mercies also come", "bibleVerseRef": 41}, {"text": "and visit me, O Lord;"}, {"text": "Ev''n thy benign salvation,", "syllables": ["Ev''n", "thy", "be-", "nign", "sal-", "va-", "tio-", "n,"]}, {"text": "according to thy word."}]}, {"index": 1, "lines": [{"text": "So shall I have wherewith I may", "bibleVerseRef": 42}, {"text": "give him an answer just,"}, {"text": "Who spitefully reproacheth me;", "syllables": ["Who", "spiteful-", "ly", "rep-", "ro-", "a-", "cheth", "me;"]}, {"text": "for in thy word I trust."}]}, {"index": 2, "lines": [{"text": "The word of truth out of my mouth", "bibleVerseRef": 43}, {"text": "take thou not utterly;"}, {"text": "For on thy judgments righteous", "syllables": ["For", "on", "thy", "jud-", "gme-", "nts", "righ-", "teous"]}, {"text": "my hope doth still rely."}]}, {"index": 3, "lines": [{"text": "So shall I keep for evermore", "syllables": ["So", "sha-", "ll", "I", "keep", "for", "ever-", "more"], "bibleVerseRef": 44}, {"text": "thy law continually.", "syllables": ["thy", "law", "conti-", "nu-", "a-", "lly."]}, {"text": "And, sith that I thy precepts seek,", "bibleVerseRef": 45}, {"text": "I''ll walk at liberty.", "syllables": ["I''ll", "walk", "at", "libe-", "r-", "ty."]}]}, {"index": 4, "lines": [{"text": "I''ll speak thy word to kings,", "syllables": ["I''ll", "spea-", "k", "thy", "word", "to", "ki-", "ngs,"], "bibleVerseRef": 46}, {"text": "and I with shame shall not be mov''d;", "syllables": ["and", "I", "with", "shame", "shall", "notbemov''d;"]}, {"text": "And will delight myself always", "syllables": ["And", "will", "de-", "light", "myse-", "lf", "al-", "ways"], "bibleVerseRef": 47}, {"text": "in thy laws, which I lov''d."}]}, {"index": 5, "lines": [{"text": "To thy commandments, which I lov''d,", "bibleVerseRef": 48}, {"text": "my hands lift up I will;"}, {"text": "And I will also meditate"}, {"text": "upon thy statutes still.", "syllables": ["upon", "thy", "sta-", "tu-", "tes", "still."]}]}]', 'CM', 'Part 6', 'Let thy sweet mercies also come...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (88, 'recVk99xheW6YNjU1', 81, '81', '1Sing loud to God our strength; with joy
to Jacob''s God do sing.
2Take up a psalm, the pleasant harp,
timbrel and psalt''ry bring.

3Blow trumpets at new-moon, what day
our feast appointed is:
4For charge to Isr''el,
and a law of Jacob''s God was this.

5To Joseph this a testimony
he made, when Egypt land
He travell''d through, where speech I heard
I did not understand.

6His shoulder I from burdens took,
his hands from pots did free.
7Thou didst in trouble on me call,
and I deliver''d thee:

In secret place of thundering
I did thee answer make;
And at the streams of Meribah
of thee a proof did take.

8O thou, my people, give an ear,
I''ll testify to thee;
To thee, O Isr''el, if thou wilt
but hearken unto me.

9In midst of thee there shall not be
any strange god at all;
Nor unto any god unknown
thou bowing down shalt fall.

10I am the Lord thy God, which did
from Egypt land thee guide;
I''ll fill thy mouth abundantly,
do thou it open wide.

11But yet my people to my voice
would not attentive be;
And ev''n my chosen Israel
he would have none of me.

12So to the lust of their own hearts
I them delivered;
And then in counsels of their own
they vainly wandered.

13O that my people had me heard,
Isr''el my ways had chose!
14I had their en''mies soon subdu''d,
my hand turn''d on their foes.

15The haters of the Lord to him
submission should have feign''d;
But as for them, their time should have
for evermore remain''d.

16He should have also fed them with
the finest of the wheat;
Of honey from the rock thy fill
I should have made thee eat.', '[{"index": 0, "lines": [{"text": "Sing loud to God our strength; with joy", "bibleVerseRef": 1}, {"text": "to Jacob''s God do sing."}, {"text": "Take up a psalm, the pleasant harp,", "bibleVerseRef": 2}, {"text": "timbrel and psalt''ry bring."}]}, {"index": 1, "lines": [{"text": "Blow trumpets at new-moon, what day", "bibleVerseRef": 3}, {"text": "our feast appointed is:"}, {"text": "For charge to Isr''el,", "syllables": ["For", "cha-", "r-", "ge", "to", "is-", "r''e-", "l,"], "bibleVerseRef": 4}, {"text": "and a law of Jacob''s God was this.", "syllables": ["and", "a", "law", "of", "jacob''s", "Godwasthis."]}]}, {"index": 2, "lines": [{"text": "To Joseph this a testimony", "bibleVerseRef": 5}, {"text": "he made, when Egypt land"}, {"text": "He travell''d through, where speech I heard"}, {"text": "I did not understand."}]}, {"index": 3, "lines": [{"text": "His shoulder I from burdens took,", "bibleVerseRef": 6}, {"text": "his hands from pots did free."}, {"text": "Thou didst in trouble on me call,", "bibleVerseRef": 7}, {"text": "and I deliver''d thee:"}]}, {"index": 4, "lines": [{"text": "In secret place of thundering", "syllables": ["In", "secret", "pla-", "ce", "of", "thun-", "de-", "ring"]}, {"text": "I did thee answer make;"}, {"text": "And at the streams of Meribah"}, {"text": "of thee a proof did take."}]}, {"index": 5, "lines": [{"text": "O thou, my people, give an ear,", "syllables": ["O", "thou,", "my", "peo-", "ple,", "give", "an", "ear,"], "bibleVerseRef": 8}, {"text": "I''ll testify to thee;"}, {"text": "To thee, O Isr''el, if thou wilt"}, {"text": "but hearken unto me."}]}, {"index": 6, "lines": [{"text": "In midst of thee there shall not be", "bibleVerseRef": 9}, {"text": "any strange god at all;", "syllables": ["any", "stran-", "ge", "god", "at", "all;"]}, {"text": "Nor unto any god unknown"}, {"text": "thou bowing down shalt fall."}]}, {"index": 7, "lines": [{"text": "I am the Lord thy God, which did", "bibleVerseRef"