INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (87, 'recVciSA7bwktYQcK', 14, '14', '1That there is not a God, the fool
doth in his heart conclude:
They are corrupt, their works are vile;
not one of them doth good.

2Upon men''s sons the Lord from heav''n
did cast his eyes abroad,
To see if any understood,
and did seek after God.

3They altogether filthy are,
they all aside are gone;
And there is none that doeth good,
yea, sure there is not one.

4These workers of iniquity
do they not know at all,
That they my people eat as bread,
and on God do not call?

5There fear''d they much; for God is with
the whole race of the just.
6You shame the counsel of the poor,
because God is his trust.

7Let Isr''el''s help from Sion come:
when back the Lord shall bring
His captives, Jacob shall rejoice,
and Israel shall sing.', '[{"index": 0, "lines": [{"text": "That there is not a God, the fool", "bibleVerseRef": 1}, {"text": "doth in his heart conclude:", "syllables": ["doth", "in", "his", "heart", "conclu-", "de:"]}, {"text": "They are corrupt, their works are vile;"}, {"text": "not one of them doth good."}]}, {"index": 1, "lines": [{"text": "Upon men''s sons the Lord from heav''n", "bibleVerseRef": 2}, {"text": "did cast his eyes abroad,", "syllables": ["did", "cast", "his", "eyes", "abro-", "ad,"]}, {"text": "To see if any understood,"}, {"text": "and did seek after God."}]}, {"index": 2, "lines": [{"text": "They altogether filthy are,", "bibleVerseRef": 3}, {"text": "they all aside are gone;"}, {"text": "And there is none that doeth good,", "syllables": ["And", "there", "is", "none", "that", "do-", "eth", "good,"]}, {"text": "yea, sure there is not one."}]}, {"index": 3, "lines": [{"text": "These workers of iniquity", "bibleVerseRef": 4}, {"text": "do they not know at all,"}, {"text": "That they my people eat as bread,", "syllables": ["That", "they", "my", "peo-", "ple", "eat", "as", "bread,"]}, {"text": "and on God do not call?"}]}, {"index": 4, "lines": [{"text": "There fear''d they much; for God is with", "bibleVerseRef": 5}, {"text": "the whole race of the just."}, {"text": "You shame the counsel of the poor,", "bibleVerseRef": 6}, {"text": "because God is his trust."}]}, {"index": 5, "lines": [{"text": "Let Isr''el''s help from Sion come:", "syllables": ["Let", "is-", "r''e-", "l''s", "help", "from", "Sion", "come:"], "bibleVerseRef": 7}, {"text": "when back the Lord shall bring"}, {"text": "His captives, Jacob shall rejoice,"}, {"text": "and Israel shall sing.", "syllables": ["and", "is-", "rael", "sha-", "ll", "sing."]}]}]', 'CM', NULL, 'That there is not a God, the fool...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (95, 'recYoVtp6IcuFBP1E', 20, '20', '1 JEHOVAH hear thee in the day
when trouble he doth send:
And let the name of Jacob''s God
thee from all ill defend.

2O let him help send from above,
out of his sanctuary:
From Sion, his own holy hill,
let him give strength to thee.

3Let him remember all thy gifts,
accept thy sacrifice:
4Grant thee thine heart''s wish, and fulfil
thy thoughts and counsel wise.

5In thy salvation we will joy;
in our God''s name we will
Display our banners: and the Lord
thy prayers all fulfil.

6Now know I God his king doth save:
he from his holy heav''n
Will hear him, with the saving strength
by his own right hand giv''n.

7In chariots some put confidence,
some horses trust upon:
But we remember will the name
of our Lord God alone.

8We rise, and upright stand, when they
are bowed down, and fall.
9Deliver, Lord; and let the King
us hear, when we do call.', '[{"index": 0, "lines": [{"text": "JEHOVAH hear thee in the day", "bibleVerseRef": 1}, {"text": "when trouble he doth send:"}, {"text": "And let the name of Jacob''s God"}, {"text": "thee from all ill defend."}]}, {"index": 1, "lines": [{"text": "O let him help send from above,", "bibleVerseRef": 2}, {"text": "out of his sanctuary:", "syllables": ["out", "of", "his", "sanctu-", "a-", "ry:"]}, {"text": "From Sion, his own holy hill,", "syllables": ["From", "Sio-", "n,", "his", "own", "ho-", "ly", "hill,"]}, {"text": "let him give strength to thee."}]}, {"index": 2, "lines": [{"text": "Let him remember all thy gifts,", "bibleVerseRef": 3}, {"text": "accept thy sacrifice:"}, {"text": "Grant thee thine heart''s wish, and fulfil", "bibleVerseRef": 4}, {"text": "thy thoughts and counsel wise."}]}, {"index": 3, "lines": [{"text": "In thy salvation we will joy;", "bibleVerseRef": 5}, {"text": "in our God''s name we will"}, {"text": "Display our banners: and the Lord"}, {"text": "thy prayers all fulfil."}]}, {"index": 4, "lines": [{"text": "Now know I God his king doth save:", "bibleVerseRef": 6}, {"text": "he from his holy heav''n"}, {"text": "Will hear him, with the saving strength"}, {"text": "by his own right hand giv''n."}]}, {"index": 5, "lines": [{"text": "In chariots some put confidence,", "syllables": ["In", "chariots", "some", "put", "con-", "fi-", "den-", "ce,"], "bibleVerseRef": 7}, {"text": "some horses trust upon:"}, {"text": "But we remember will the name"}, {"text": "of our Lord God alone."}]}, {"index": 6, "lines": [{"text": "We rise, and upright stand, when they", "bibleVerseRef": 8}, {"text": "are bowed down, and fall."}, {"text": "Deliver, Lord; and let the King", "syllables": ["de-", "live-", "r,", "Lord;", "and", "let", "the", "King"], "bibleVerseRef": 9}, {"text": "us hear, when we do call."}]}]', 'CM', NULL, 'JEHOVAH hear thee in the day...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (99, 'recanAeaj9rivo2dA', 77, '77', '1Unto the Lord I with my voice,
I unto God did cry;
Ev''n with my voice,
and unto me his ear he did apply.

2I in my trouble sought the Lord,
my sore by night did run,
And ceased not; my grieved soul
did consolation shun.

3I to remembrance God did call,
yet trouble did remain;
And overwhelm''d my spirit was,
whilst I did sore complain.

4Mine eyes, debarr''d from rest and sleep,
thou makest still to wake;
My trouble is so great that I
unable am to speak.

5The days of old to mind I call''d,
and oft did think upon
The times and ages that are past
full many years agone.

6By night my song I call to mind,
and commune with my heart;
My sp''rit did carefully enquire
how I might ease my smart.

7For ever will the Lord cast off,
and gracious be no more?
8For ever is his mercy gone?
fails his word evermore?

9Is''t true that to be gracious
the Lord forgotten hath?
And that his tender mercies he
hath shut up in his wrath?

10Then did I say, That surely this
is mine infirmity:
I''ll mind the years of the right hand
of him that is most High.

11Yea, I remember will the works
performed by the Lord:
The wonders done of old by thee
I surely will record.

12I also will of all thy works
my meditation make;
And of thy doings to discourse
great pleasure I will take.

13O God, thy way most holy is
within thy sanctuary;
And what god is so great in pow''r
as is our God most high?

14Thou art the God that wonders do''st
by thy right hand most strong:
Thy mighty pow''r thou hast declar''d
the nations among.

15To thine own people with thine arm
thou didst redemption bring;
To Jacob''s sons,
and to the tribes of Joseph that do spring.

16The waters, Lord, perceived thee,
the waters saw thee well;
And they for fear aside did flee;
the depths on trembling fell.

17The clouds in water forth were pour''d,
sound loudly did the sky;
And swiftly through the world abroad
thine arrows fierce did fly.

18Thy thunder''s voice alongst the heav''n
a mighty noise did make;
By lightnings lighten''d was the world,
th'' earth tremble did and shake.

19Thy way is in the sea, and in
the waters great thy path;
Yet are thy footsteps hid, O Lord;
none knowledge thereof hath.

20Thy people thou didst safely lead,
like to a flock of sheep;
By Moses'' hand and Aaron''s thou
didst them conduct and keep.', '[{"index": 0, "lines": [{"text": "Unto the Lord I with my voice,", "bibleVerseRef": 1}, {"text": "I unto God did cry;"}, {"text": "Ev''n with my voice,", "syllables": ["Ev''n", "with", "my", "voice-", "-", "-", "-", ","]}, {"text": "and unto me his ear he did apply.", "syllables": ["and", "unto", "me", "his", "ear", "hedidapply."]}]}, {"index": 1, "lines": [{"text": "I in my trouble sought the Lord,", "bibleVerseRef": 2}, {"text": "my sore by night did run,"}, {"text": "And ceased not; my grieved soul"}, {"text": "did consolation shun."}]}, {"index": 2, "lines": [{"text": "I to remembrance God did call,", "syllables": ["I", "to", "remem-", "bran-", "ce", "God", "did", "call,"], "bibleVerseRef": 3}, {"text": "yet trouble did remain;"}, {"text": "And overwhelm''d my spirit was,", "syllables": ["And", "over-", "whe-", "lm''d", "my", "spi-", "rit", "was,"]}, {"text": "whilst I did sore complain."}]}, {"index": 3, "lines": [{"text": "Mine eyes, debarr''d from rest and sleep,", "bibleVerseRef": 4}, {"text": "thou makest still to wake;", "syllables": ["thou", "make-", "st", "still", "to", "wake;"]}, {"text": "My trouble is so great that I"}, {"text": "unable am to speak."}]}, {"index": 4, "lines": [{"text": "The days of old to mind I call''d,", "bibleVerseRef": 5}, {"text": "and oft did think upon"}, {"text": "The times and ages that are past", "syllables": ["The", "time-", "s", "and", "ages", "that", "are", "past"]}, {"text": "full many years agone."}]}, {"index": 5, "lines": [{"text": "By night my song I call to mind,", "bibleVerseRef": 6}, {"text": "and commune with my heart;"}, {"text": "My sp''rit did carefully enquire", "syllables": ["My", "sp''rit", "did", "carefully", "en-", "qu-", "i-", "re"]}, {"text": "how I might ease my smart.", "syllables": ["how", "I", "might", "ease", "my", "smart."]}]}, {"index": 6, "lines": [{"text": "For ever will the Lord cast off,", "syllables": ["For", "eve-", "r", "will", "the", "Lord", "cast", "off,"], "bibleVerseRef": 7}, {"text": "and gracious be no more?"}, {"text": "For ever is his mercy gone?", "syllables": ["For", "ever", "is", "his", "mer-", "cy", "gone-", "?"], "bibleVerseRef": 8}, {"text": "fails his word evermore?", "syllables": ["fai-", "ls", "his", "word", "ever-", "more?"]}]}, {"index": 7, "lines": [{"text": "Is''t true that to be gracious", "syllables": ["Is''t", "true", "that", "to", "be", "gra-", "ciou-", "s"], "bibleVerseRef": 9}, {"text": "the Lord forgotten hath?"}, {"text": "And that his tender mercies he"}, {"text": "hath shut up in his wrath?"}]}, {"index": 8, "lines": [{"text": "Then did I say, That surely this", "bibleVerseRef": 10}, {"text": "is mine infirmity:"}, {"text": "I''ll mind the years of the right hand"}, {"text": "of him that is most High."}]}, {"index": 9, "lines": [{"text": "Yea, I remember will the works", "bibleVerseRef": 11}, {"text": "performed by the Lord:"}, {"text": "The wonders done of old by thee"}, {"text": "I surely will record."}]}, {"index": 10, "lines": [{"text": "I also will of all thy works", "bibleVerseRef": 12}, {"text": "my meditation make;"}, {"text": "And of thy doings to discourse"}, {"text": "great pleasure I will take."}]}, {"index": 11, "lines": [{"text": "O God, thy way most holy is", "bibleVerseRef": 13}, {"text": "within thy sanctuary;", "syllables": ["within", "thy", "san-", "ctu-", "a-", "ry;"]}, {"text": "And what god is so great in pow''r"}, {"text": "as is our God most high?"}]}, {"index": 12, "lines": [{"text": "Thou art the God that wonders do''st", "bibleVerseRef": 14}, {"text": "by thy right hand most strong:"}, {"text": "Thy mighty pow''r thou hast declar''d"}, {"text": "the nations among.", "syllables": ["the", "na-", "tio-", "ns", "a-", "mong."]}]}, {"index": 13, "lines": [{"text": "To thine own people with thine arm", "syllables": ["To", "thine", "own", "peo-", "ple", "with", "thine", "arm"], "bibleVerseRef": 15}, {"text": "thou didst redemption bring;"}, {"text": "To Jacob''s sons,", "syllables": ["To", "ja-", "-", "-", "co-", "b''s", "so-", "ns,"]}, {"text": "and to the tribes of Joseph that do spring.", "syllables": ["and", "to", "the", "tribes", "of", "Josephthatdospring."]}]}, {"index": 14, "lines": [{"text": "The waters, Lord, perceived thee,", "syllables": ["The", "wate-", "rs,", "Lord,", "per-", "cei-", "ved", "thee,"], "bibleVerseRef": 16}, {"text": "the waters saw thee well;", "syllables": ["the", "wate-", "rs", "saw", "thee", "well;"]}, {"text": "And they for fear aside did flee;"}, {"text": "the depths on trembling fell."}]}, {"index": 15, "lines": [{"text": "The clouds in water forth were pour''d,", "syllables": ["The", "clouds", "in", "water", "forth", "were", "pou-", "r''d,"], "bibleVerseRef": 17}, {"text": "sound loudly did the sky;"}, {"text": "And swiftly through the world abroad", "syllables": ["And", "swiftly", "through", "the", "world", "ab-", "ro-", "ad"]}, {"text": "thine arrows fierce did fly.", "syllables": ["thine", "arrows", "fier-", "ce", "did", "fly."]}]}, {"index": 16, "lines": [{"text": "Thy thunder''s voice alongst the heav''n", "bibleVerseRef": 18}, {"text": "a mighty noise did make;"}, {"text": "By lightnings lighten''d was the world,"}, {"text": "th'' earth tremble did and shake."}]}, {"index": 17, "lines": [{"text": "Thy way is in the sea, and in", "bibleVerseRef": 19}, {"text": "the waters great thy path;", "syllables": ["the", "wate-", "rs", "great", "thy", "path;"]}, {"text": "Yet are thy footsteps hid, O Lord;"}, {"text": "none knowledge thereof hath.", "syllables": ["none", "knowled-", "ge", "there-", "of", "hath."]}]}, {"index": 18, "lines": [{"text": "Thy people thou didst safely lead,", "syllables": ["Thy", "peo-", "ple", "thou", "didst", "safe-", "ly", "lead,"], "bibleVerseRef": 20}, {"text": "like to a flock of sheep;"}, {"text": "By Moses'' hand and Aaron''s thou", "syllables": ["By", "Mose-", "s''", "hand", "and", "aa-", "ron''s", "thou"]}, {"text": "didst them conduct and keep."}]}]', 'CM', NULL, 'Unto the Lord I with my voice...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (104, 'recbwXkqcB2EVvruC', 65, '65', '1Praise waits for thee in Sion, Lord:
to thee vows paid shall be.
2O thou that hearer art of pray''r,
all flesh shall come to thee.

3Iniquities, I must confess,
prevail against me do:
But as for our transgressions,
them purge away shalt thou.

4Bless''d is the man whom thou dost chuse,
and mak''st approach to thee,
That he within thy courts, O Lord,
may still a dweller be:

We surely shall be satisfy''d
with thy abundant grace,
And with the goodness of thy house,
ev''n of thy holy place.

5O God of our salvation,
thou, in thy righteousness,
By fearful works unto our pray''rs
thine answer dost express:

Therefore the ends of all the earth,
and those afar that be
Upon the sea, their confidence,
O Lord, will place in thee.

6Who, being girt with pow''r, sets fast
by his great strength the hills.
7Who noise of seas, noise of their waves,
and people''s tumult, stills.

8Those in the utmost parts that dwell
are at thy signs afraid:
Th'' outgoings of the morn and ev''n
by thee are joyful made.

9The earth thou visit''st, wat''ring it;
thou mak''st it rich to grow
With God''s full flood; thou corn prepar''st,
when thou provid''st it so.

10Her rigs thou wat''rest plenteously,
her furrows settelest:
With show''rs thou dost her mollify,
her spring by thee is blest.

11So thou the year most lib''rally
dost with thy goodness crown;
And all thy paths abundantly
on us drop fatness down.

12They drop upon the pastures wide,
that do in deserts lie;
The little hills on ev''ry side
rejoice right pleasantly.

13With flocks the pastures clothed be,
the vales with corn are clad;
And now they shout and sing to thee,
for thou hast made them glad.', '[{"index": 0, "lines": [{"text": "Praise waits for thee in Sion, Lord:", "syllables": ["Prai-", "se", "waits", "for", "thee", "in", "Sion,", "Lord:"], "bibleVerseRef": 1}, {"text": "to thee vows paid shall be."}, {"text": "O thou that hearer art of pray''r,", "syllables": ["O", "thou", "that", "hearer", "art", "of", "pray-", "''r,"], "bibleVerseRef": 2}, {"text": "all flesh shall come to thee."}]}, {"index": 1, "lines": [{"text": "Iniquities, I must confess,", "bibleVerseRef": 3}, {"text": "prevail against me do:"}, {"text": "But as for our transgressions,", "syllables": ["But", "as", "for", "our", "tran-", "sgre-", "s-", "sions,"]}, {"text": "them purge away shalt thou.", "syllables": ["them", "purge", "a-", "way", "shalt", "thou."]}]}, {"index": 2, "lines": [{"text": "Bless''d is the man whom thou dost chuse,", "bibleVerseRef": 4}, {"text": "and mak''st approach to thee,", "syllables": ["and", "mak''st", "appro-", "ach", "to", "thee,"]}, {"text": "That he within thy courts, O Lord,"}, {"text": "may still a dweller be:"}]}, {"index": 3, "lines": [{"text": "We surely shall be satisfy''d"}, {"text": "with thy abundant grace,", "syllables": ["with", "thy", "abun-", "dant", "gra-", "ce,"]}, {"text": "And with the goodness of thy house,"}, {"text": "ev''n of thy holy place.", "syllables": ["ev''n", "of", "thy", "holy", "pla-", "ce."]}]}, {"index": 4, "lines": [{"text": "O God of our salvation,", "syllables": ["O", "God", "of", "our", "sal-", "va-", "tio-", "n,"], "bibleVerseRef": 5}, {"text": "thou, in thy righteousness,"}, {"text": "By fearful works unto our pray''rs"}, {"text": "thine answer dost express:"}]}, {"index": 5, "lines": [{"text": "Therefore the ends of all the earth,"}, {"text": "and those afar that be"}, {"text": "Upon the sea, their confidence,", "syllables": ["upon", "the", "sea,", "their", "con-", "fi-", "den-", "ce,"]}, {"text": "O Lord, will place in thee.", "syllables": ["O", "Lord,", "will", "place", "in", "thee."]}]}, {"index": 6, "lines": [{"text": "Who, being girt with pow''r, sets fast", "syllables": ["Who,", "being", "girt", "with", "po-", "w''r,", "sets", "fast"], "bibleVerseRef": 6}, {"text": "by his great strength the hills."}, {"text": "Who noise of seas, noise of their waves,", "bibleVerseRef": 7}, {"text": "and people''s tumult, stills.", "syllables": ["and", "peo-", "ple''s", "tu-", "mult,", "stills."]}]}, {"index": 7, "lines": [{"text": "Those in the utmost parts that dwell", "bibleVerseRef": 8}, {"text": "are at thy signs afraid:"}, {"text": "Th'' outgoings of the morn and ev''n"}, {"text": "by thee are joyful made."}]}, {"index": 8, "lines": [{"text": "The earth thou visit''st, wat''ring it;", "bibleVerseRef": 9}, {"text": "thou mak''st it rich to grow"}, {"text": "With God''s full flood; thou corn prepar''st,"}, {"text": "when thou provid''st it so."}]}, {"index": 9, "lines": [{"text": "Her rigs thou wat''rest plenteously,", "syllables": ["Her", "rigs", "thou", "wat''rest", "plente-", "o-", "us-", "ly,"], "bibleVerseRef": 10}, {"text": "her furrows settelest:"}, {"text": "With show''rs thou dost her mollify,"}, {"text": "her spring by thee is blest."}]}, {"index": 10, "lines": [{"text": "So thou the year most lib''rally", "bibleVerseRef": 11}, {"text": "dost with thy goodness crown;"}, {"text": "And all thy paths abundantly"}, {"text": "on us drop fatness down."}]}, {"index": 11, "lines": [{"text": "They drop upon the pastures wide,", "bibleVerseRef": 12}, {"text": "that do in deserts lie;"}, {"text": "The little hills on ev''ry side"}, {"text": "rejoice right pleasantly."}]}, {"index": 12, "lines": [{"text": "With flocks the pastures clothed be,", "bibleVerseRef": 13}, {"text": "the vales with corn are clad;"}, {"text": "And now they shout and sing to thee,"}, {"text": "for thou hast made them glad."}]}]', 'CM', NULL, 'Praise waits for thee in Sion, Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (107, 'reccOKfSlD4fxOkbk', 119, '119:65-72 (9)', '65Well hast thou with thy servant dealt,
as thou didst promise give.
66Good judgment me, and knowledge teach,
for I thy word believe.

67Ere I afflicted was I stray''d;
but now I keep thy word.
68Both good thou art, and good thou do''st:
teach me thy statutes, Lord.

69The men that are puff ''d up with pride
against me forg''d a lie;
Yet thy commandements observe
with my whole heart will I.

70Their hearts, through worldly ease and wealth,
as fat as grease they be:
But in thy holy law I take
delight continually.

71It hath been very good for me
that I afflicted was,
That I might well instructed be,
and learn thy holy laws.

72The word that cometh from thy mouth
is better unto me
Than many thousands and great sums
of gold and silver be.
', '[{"index": 0, "lines": [{"text": "Well hast thou with thy servant dealt,", "bibleVerseRef": 65}, {"text": "as thou didst promise give."}, {"text": "Good judgment me, and knowledge teach,", "syllables": ["Good", "judgment", "me,", "and", "know-", "led-", "ge", "teach,"], "bibleVerseRef": 66}, {"text": "for I thy word believe."}]}, {"index": 1, "lines": [{"text": "Ere I afflicted was I stray''d;", "bibleVerseRef": 67}, {"text": "but now I keep thy word."}, {"text": "Both good thou art, and good thou do''st:", "bibleVerseRef": 68}, {"text": "teach me thy statutes, Lord.", "syllables": ["teach", "me", "thy", "statu-", "tes,", "Lord."]}]}, {"index": 2, "lines": [{"text": "The men that are puff ''d up with pride", "syllables": ["The", "men", "that", "are", "puff", "''d", "up", "withpride"], "bibleVerseRef": 69}, {"text": "against me forg''d a lie;"}, {"text": "Yet thy commandements observe", "syllables": ["Yet", "thy", "comman-", "de-", "ments", "ob-", "ser-", "ve"]}, {"text": "with my whole heart will I."}]}, {"index": 3, "lines": [{"text": "Their hearts, through worldly ease and wealth,", "syllables": ["Their", "hearts,", "through", "worldly", "ea-", "se", "and", "wealth,"], "bibleVerseRef": 70}, {"text": "as fat as grease they be:", "syllables": ["as", "fat", "as", "grease", "they", "be:"]}, {"text": "But in thy holy law I take"}, {"text": "delight continually.", "syllables": ["delight", "con-", "ti-", "nu-", "a-", "lly."]}]}, {"index": 4, "lines": [{"text": "It hath been very good for me", "bibleVerseRef": 71}, {"text": "that I afflicted was,"}, {"text": "That I might well instructed be,"}, {"text": "and learn thy holy laws."}]}, {"index": 5, "lines": [{"text": "The word that cometh from thy mouth", "bibleVerseRef": 72}, {"text": "is better unto me"}, {"text": "Than many thousands and great sums"}, {"text": "of gold and silver be."}]}]', 'CM', 'Part 9', 'Well hast thou with thy servant dealt...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (112, 'recdkiaZmBcoQLFXt', 128, '128', '1Bless''d is each one that fears the Lord,
and walketh in his ways;
2For of thy labour thou shalt eat,
and happy be always.

3Thy wife shall as a fruitful vine
by thy house'' sides be found:
Thy children like to olive-plants
about thy table round.

4Behold, the man that fears the Lord,
thus blessed shall he be.
5The Lord shall out of Sion give
his blessing unto thee:

Thou shalt Jerus''lem''s good behold
whilst thou on earth dost dwell.
6Thou shalt thy children''s children see,
and peace on Israel.', '[{"index": 0, "lines": [{"text": "Bless''d is each one that fears the Lord,", "bibleVerseRef": 1}, {"text": "and walketh in his ways;"}, {"text": "For of thy labour thou shalt eat,", "bibleVerseRef": 2}, {"text": "and happy be always."}]}, {"index": 1, "lines": [{"text": "Thy wife shall as a fruitful vine", "syllables": ["Thy", "wife", "shall", "as", "a", "frui-", "tful", "vine"], "bibleVerseRef": 3}, {"text": "by thy house'' sides be found:"}, {"text": "Thy children like to olive-plants", "syllables": ["Thy", "children", "like", "to", "o-", "li-", "ve--", "plants"]}, {"text": "about thy table round."}]}, {"index": 2, "lines": [{"text": "Behold, the man that fears the Lord,", "bibleVerseRef": 4}, {"text": "thus blessed shall he be."}, {"text": "The Lord shall out of Sion give", "syllables": ["The", "Lord", "sha-", "ll", "out", "of", "Sion", "give"], "bibleVerseRef": 5}, {"text": "his blessing unto thee:"}]}, {"index": 3, "lines": [{"text": "Thou shalt Jerus''lem''s good behold"}, {"text": "whilst thou on earth dost dwell."}, {"text": "Thou shalt thy children''s children see,", "bibleVerseRef": 6}, {"text": "and peace on Israel.", "syllables": ["and", "pea-", "ce", "on", "is-", "rael."]}]}]', 'CM', NULL, 'Bless''d is each one that fears the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (116, 'recfXiPIiZmzyImCI', 16, '16', '1Lord, keep me; for I trust in thee.
2To God thus was my speech,
Thou art my Lord; and unto thee
my goodness doth not reach:

3To saints on earth, to th'' excellent,
where my delight''s all plac''d.
4Their sorrows shall be multiply''d
to other gods that haste:

Of their drink-offerings of blood
I will no off ''ring make;
Yea, neither I their very names
up in my lips will take.

5God is of mine inheritance
and cup the portion;
The lot that fallen is to me
thou dost maintain alone.

6Unto me happily the lines
in pleasant places fell;
Yea, the inheritance I got
in beauty doth excel.

7I bless the Lord, because he doth
by counsel me conduct;
And in the seasons of the night
my reins do me instruct.

8Before me still the Lord I set:
sith it is so that he
Doth ever stand at my right hand,
I shall not moved be.

9Because of this my heart is glad,
and joy shall be exprest
Ev''n by my glory; and my flesh
in confidence shall rest.

10Because my soul in grave to dwell
shall not be left by thee;
Nor wilt thou give thine Holy One
corruption to see.

11Thou wilt me shew the path of life:
of joys there is full store
Before thy face; at thy right hand
are pleasures evermore.', '[{"index": 0, "lines": [{"text": "Lord, keep me; for I trust in thee.", "bibleVerseRef": 1}, {"text": "To God thus was my speech,", "bibleVerseRef": 2}, {"text": "Thou art my Lord; and unto thee"}, {"text": "my goodness doth not reach:"}]}, {"index": 1, "lines": [{"text": "To saints on earth, to th'' excellent,", "bibleVerseRef": 3}, {"text": "where my delight''s all plac''d."}, {"text": "Their sorrows shall be multiply''d", "bibleVerseRef": 4}, {"text": "to other gods that haste:", "syllables": ["to", "other", "gods", "that", "has-", "te:"]}]}, {"index": 2, "lines": [{"text": "Of their drink-offerings of blood"}, {"text": "I will no off ''ring make;"}, {"text": "Yea, neither I their very names"}, {"text": "up in my lips will take."}]}, {"index": 3, "lines": [{"text": "God is of mine inheritance", "syllables": ["God", "is", "of", "mine", "inhe-", "ri-", "tan-", "ce"], "bibleVerseRef": 5}, {"text": "and cup the portion;", "syllables": ["and", "cup", "the", "por-", "tio-", "n;"]}, {"text": "The lot that fallen is to me"}, {"text": "thou dost maintain alone."}]}, {"index": 4, "lines": [{"text": "Unto me happily the lines", "bibleVerseRef": 6}, {"text": "in pleasant places fell;"}, {"text": "Yea, the inheritance I got", "syllables": ["Yea,", "the", "inhe-", "ri-", "tan-", "ce", "I", "got"]}, {"text": "in beauty doth excel."}]}, {"index": 5, "lines": [{"text": "I bless the Lord, because he doth", "bibleVerseRef": 7}, {"text": "by counsel me conduct;"}, {"text": "And in the seasons of the night"}, {"text": "my reins do me instruct."}]}, {"index": 6, "lines": [{"text": "Before me still the Lord I set:", "bibleVerseRef": 8}, {"text": "sith it is so that he"}, {"text": "Doth ever stand at my right hand,", "syllables": ["Doth", "ever", "sta-", "nd", "at", "my", "right", "hand,"]}, {"text": "I shall not moved be."}]}, {"index": 7, "lines": [{"text": "Because of this my heart is glad,", "bibleVerseRef": 9}, {"text": "and joy shall be exprest"}, {"text": "Ev''n by my glory; and my flesh"}, {"text": "in confidence shall rest.", "syllables": ["in", "confi-", "den-", "ce", "shall", "rest."]}]}, {"index": 8, "lines": [{"text": "Because my soul in grave to dwell", "syllables": ["because", "my", "soul", "in", "gra-", "ve", "to", "dwell"], "bibleVerseRef": 10}, {"text": "shall not be left by thee;"}, {"text": "Nor wilt thou give thine Holy One"}, {"text": "corruption to see.", "syllables": ["co-", "r-", "rup-", "tion", "to", "see."]}]}, {"index": 9, "lines": [{"text": "Thou wilt me shew the path of life:", "bibleVerseRef": 11}, {"text": "of joys there is full store", "syllables": ["of", "joys", "there", "is", "full", "store"]}, {"text": "Before thy face; at thy right hand"}, {"text": "are pleasures evermore.", "syllables": ["are", "plea-", "-", "sures", "ever-", "more."]}]}]', 'CM', NULL, 'Lord, keep me; for I trust in thee...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (174, 'recwfPlX6VR66NF5H', 75, '75', '1To thee, O God, do we give thanks,
we do give thanks to thee;
Because thy wondrous works declare
thy great name near to be.

2I purpose, when I shall receive
the congregation,
That I shall judgment uprightly
render to ev''ry one.

3Dissolved is the land, with all
that in the same do dwell;
But I the pillars thereof do
Bear up, and stablish well.

4I to the foolish people said,
Do not deal foolishly;
And unto those that wicked are,
Lift not your horn on high.

5Lift not your horn on high, nor speak
6with stubborn neck. But know,
That not from east, nor west, nor south,
promotion doth flow.

7But God is judge; he puts down one,
and sets another up.
8For in the hand of God most high
of red wine is a cup:

''Tis full of mixture, he pours forth,
and makes the wicked all
Wring out the bitter dregs thereof; yea,
and they drink them shall.

9But I for ever will declare,
I Jacob''s God will praise.
10All horns of lewd men I''ll cut off;
but just men''s horns will raise.', '[{"index": 0, "lines": [{"text": "To thee, O God, do we give thanks,", "bibleVerseRef": 1}, {"text": "we do give thanks to thee;"}, {"text": "Because thy wondrous works declare"}, {"text": "thy great name near to be."}]}, {"index": 1, "lines": [{"text": "I purpose, when I shall receive", "bibleVerseRef": 2}, {"text": "the congregation,", "syllables": ["the", "con-", "gre-", "ga-", "tio-", "n,"]}, {"text": "That I shall judgment uprightly"}, {"text": "render to ev''ry one."}]}, {"index": 2, "lines": [{"text": "Dissolved is the land, with all", "bibleVerseRef": 3}, {"text": "that in the same do dwell;"}, {"text": "But I the pillars thereof do"}, {"text": "Bear up, and stablish well."}]}, {"index": 3, "lines": [{"text": "I to the foolish people said,", "syllables": ["I", "to", "the", "foolish", "pe-", "o-", "ple", "said,"], "bibleVerseRef": 4}, {"text": "Do not deal foolishly;"}, {"text": "And unto those that wicked are,"}, {"text": "Lift not your horn on high."}]}, {"index": 4, "lines": [{"text": "Lift not your horn on high, nor speak", "bibleVerseRef": 5}, {"text": "with stubborn neck. But know,", "bibleVerseRef": 6}, {"text": "That not from east, nor west, nor south,"}, {"text": "promotion doth flow.", "syllables": ["pro-", "mo-", "tion", "doth", "flo-", "w."]}]}, {"index": 5, "lines": [{"text": "But God is judge; he puts down one,", "syllables": ["But", "God", "is", "judge;", "he", "puts", "down", "one,"], "bibleVerseRef": 7}, {"text": "and sets another up."}, {"text": "For in the hand of God most high", "bibleVerseRef": 8}, {"text": "of red wine is a cup:"}]}, {"index": 6, "lines": [{"text": "''Tis full of mixture, he pours forth,"}, {"text": "and makes the wicked all"}, {"text": "Wring out the bitter dregs thereof; yea,", "syllables": ["Wring", "out", "the", "bitter", "dregs", "there-", "of;", "yea,"]}, {"text": "and they drink them shall.", "syllables": ["and", "they", "drink", "them", "sha-", "ll."]}]}, {"index": 7, "lines": [{"text": "But I for ever will declare,", "syllables": ["But", "I", "for", "ever", "will", "dec-", "lare-", ","], "bibleVerseRef": 9}, {"text": "I Jacob''s God will praise."}, {"text": "All horns of lewd men I''ll cut off;", "bibleVerseRef": 10}, {"text": "but just men''s horns will raise."}]}]', 'CM', NULL, 'To thee, O God, do we give thanks...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (128, 'reciq5VH2TlIywaHM', 119, '119:49-56 (7)', '49Remember, Lord, thy gracious word
thou to thy servant spake,
Which, for a ground of my sure hope,
thou causedst me to take.

50This word of thine my comfort is
in mine affliction:
For in my straits I am reviv''d
by this thy word alone.

51The men whose hearts with pride are stuff''d
did greatly me deride;
Yet from thy straight commandements
I have not turn''d aside.

52Thy judgments righteous, O Lord,
which thou of old forth gave,
I did remember, and myself
by them comforted have.

53Horror took hold on me, because
ill men thy law forsake.
54I in my house of pilgrimage
thy laws my songs do make.

55Thy name by night, Lord, I did mind,
and I have kept thy law.
56And this I had, because thy word
I kept, and stood in awe.
', '[{"index": 0, "lines": [{"text": "Remember, Lord, thy gracious word", "bibleVerseRef": 49}, {"text": "thou to thy servant spake,", "syllables": ["thou", "to", "thy", "servant", "spa-", "ke,"]}, {"text": "Which, for a ground of my sure hope,"}, {"text": "thou causedst me to take."}]}, {"index": 1, "lines": [{"text": "This word of thine my comfort is", "bibleVerseRef": 50}, {"text": "in mine affliction:", "syllables": ["in", "mine", "af-", "fli-", "c-", "tion:"]}, {"text": "For in my straits I am reviv''d"}, {"text": "by this thy word alone."}]}, {"index": 2, "lines": [{"text": "The men whose hearts with pride are stuff''d", "syllables": ["The", "men", "whose", "hearts", "with", "pride", "are", "stuff''d"], "bibleVerseRef": 51}, {"text": "did greatly me deride;"}, {"text": "Yet from thy straight commandements"}, {"text": "I have not turn''d aside."}]}, {"index": 3, "lines": [{"text": "Thy judgments righteous, O Lord,", "syllables": ["Thy", "jud-", "gme-", "nts", "righ-", "teous,", "O", "Lord,"], "bibleVerseRef": 52}, {"text": "which thou of old forth gave,"}, {"text": "I did remember, and myself", "syllables": ["I", "did", "re-", "mem-", "ber,", "and", "myse-", "lf"]}, {"text": "by them comforted have."}]}, {"index": 4, "lines": [{"text": "Horror took hold on me, because", "bibleVerseRef": 53}, {"text": "ill men thy law forsake."}, {"text": "I in my house of pilgrimage", "bibleVerseRef": 54}, {"text": "thy laws my songs do make."}]}, {"index": 5, "lines": [{"text": "Thy name by night, Lord, I did mind,", "bibleVerseRef": 55}, {"text": "and I have kept thy law."}, {"text": "And this I had, because thy word", "bibleVerseRef": 56}, {"text": "I kept, and stood in awe."}]}]', 'CM', 'Part 7', 'Remember, Lord, thy gracious word...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (175, 'recxB2C7gOHv0dbZU', 95, '95', '1O come, let us sing to the Lord:
come, let us ev''ry one
A joyful noise make to the Rock
of our salvation.

2Let us before his presence come
with praise and thankful voice;
Let us sing psalms to him with grace,
and make a joyful noise.

3For God, a great God, and great King,
above all gods he is.
4Depths of the earth are in his hand,
the strength of hills is his.

5To him the spacious sea belongs,
for he the same did make;
The dry land also from his hands
its form at first did take.

6O come, and let us worship him,
let us bow down withal,
And on our knees before the Lord
our Maker let us fall.

7For he''s our God, the people we
of his own pasture are,
And of his hand the sheep; to-day,
if ye his voice will hear,

8Then harden not your hearts, as in
the provocation,
As in the desert, on the day
of the tentation:

9When me your fathers tempt''d and prov''d,
and did my working see;
10Ev''n for the space of forty years
this race hath grieved me.

I said, This people errs in heart,
my ways they do not know:
11To whom I sware in wrath, that to
my rest they should not go.', '[{"index": 0, "lines": [{"text": "O come, let us sing to the Lord:", "bibleVerseRef": 1}, {"text": "come, let us ev''ry one"}, {"text": "A joyful noise make to the Rock"}, {"text": "of our salvation.", "syllables": ["of", "our", "sal-", "va-", "tio-", "n."]}]}, {"index": 1, "lines": [{"text": "Let us before his presence come", "bibleVerseRef": 2}, {"text": "with praise and thankful voice;"}, {"text": "Let us sing psalms to him with grace,", "syllables": ["Let", "us", "sing", "psalms", "to", "him", "with", "grace,"]}, {"text": "and make a joyful noise."}]}, {"index": 2, "lines": [{"text": "For God, a great God, and great King,", "bibleVerseRef": 3}, {"text": "above all gods he is."}, {"text": "Depths of the earth are in his hand,", "bibleVerseRef": 4}, {"text": "the strength of hills is his."}]}, {"index": 3, "lines": [{"text": "To him the spacious sea belongs,", "bibleVerseRef": 5}, {"text": "for he the same did make;"}, {"text": "The dry land also from his hands"}, {"text": "its form at first did take."}]}, {"index": 4, "lines": [{"text": "O come, and let us worship him,", "bibleVerseRef": 6}, {"text": "let us bow down withal,"}, {"text": "And on our knees before the Lord"}, {"text": "our Maker let us fall.", "syllables": ["our", "Make-", "r", "let", "us", "fall."]}]}, {"index": 5, "lines": [{"text": "For he''s our God, the people we", "syllables": ["For", "he''s", "our", "God,", "the", "peo-", "ple", "we"], "bibleVerseRef": 7}, {"text": "of his own pasture are,"}, {"text": "And of his hand the sheep; to-day,"}, {"text": "if ye his voice will hear,"}]}, {"index": 6, "lines": [{"text": "Then harden not your hearts, as in", "bibleVerseRef": 8}, {"text": "the provocation,", "syllables": ["the", "pro-", "vo-", "ca-", "tio-", "n,"]}, {"text": "As in the desert, on the day"}, {"text": "of the tentation:", "syllables": ["of", "the", "ten-", "ta-", "tio-", "n:"]}]}, {"index": 7, "lines": [{"text": "When me your fathers tempt''d and prov''d,", "bibleVerseRef": 9}, {"text": "and did my working see;"}, {"text": "Ev''n for the space of forty years", "syllables": ["Ev''n", "for", "the", "space", "of", "for-", "ty", "years"], "bibleVerseRef": 10}, {"text": "this race hath grieved me."}]}, {"index": 8, "lines": [{"text": "I said, This people errs in heart,", "syllables": ["I", "said,", "This", "peo-", "ple", "errs", "in", "heart,"]}, {"text": "my ways they do not know:"}, {"text": "To whom I sware in wrath, that to", "syllables": ["To", "whom", "I", "sware", "in", "wrath,", "that", "to"], "bibleVerseRef": 11}, {"text": "my rest they should not go."}]}]', 'CM', NULL, 'O come, let us sing to the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (141, 'recm22NRE1WaFlmwm', 41, '41', '1Blessed is he that wisely doth
the poor man''s case consider;
For when the time of trouble is,
the Lord will him deliver.

2God will him keep, yea, save alive;
on earth he bless''d shall live;
And to his enemies'' desire
thou wilt him not up give.

3God will give strength when he on bed
of languishing doth mourn;
And in his sickness sore, O Lord,
thou all his bed wilt turn.

4I said, O Lord, do thou extend
thy mercy unto me;
O do thou heal my soul; for why?
I have offended thee.

5Those that to me are enemies,
of me do evil say,
When shall he die, that so his name
may perish quite away?

6To see me if he comes, he speaks
vain words: but then his heart
Heaps mischief to it, which he tells,
when forth he doth depart.

7My haters jointly whispering,
''gainst me my hurt devise.
8Mischief, say they, cleaves fast to him;
he li''th, and shall not rise.

9Yea, ev''n mine own familiar friend,
on whom I did rely,
Who ate my bread, ev''n he his heel
against me lifted high.

10But, Lord, be merciful to me,
and up again me raise,
That I may justly them requite
according to their ways.

11By this I know that certainly
I favour''d am by thee;
Because my hateful enemy
triumphs not over me.

12But as for me, thou me uphold''st
in mine integrity;
And me before thy countenance
thou sett''st continually.

13The Lord, the God of Israel,
be bless''d for ever then,
From age to age eternally.
Amen, yea, and amen.', '[{"index": 0, "lines": [{"text": "Blessed is he that wisely doth", "bibleVerseRef": 1}, {"text": "the poor man''s case consider;"}, {"text": "For when the time of trouble is,"}, {"text": "the Lord will him deliver."}]}, {"index": 1, "lines": [{"text": "God will him keep, yea, save alive;", "bibleVerseRef": 2}, {"text": "on earth he bless''d shall live;"}, {"text": "And to his enemies'' desire", "syllables": ["And", "to", "his", "ene-", "mie-", "s''", "de-", "sire"]}, {"text": "thou wilt him not up give."}]}, {"index": 2, "lines": [{"text": "God will give strength when he on bed", "bibleVerseRef": 3}, {"text": "of languishing doth mourn;", "syllables": ["of", "langu-", "i-", "shing", "doth", "mourn;"]}, {"text": "And in his sickness sore, O Lord,"}, {"text": "thou all his bed wilt turn."}]}, {"index": 3, "lines": [{"text": "I said, O Lord, do thou extend", "bibleVerseRef": 4}, {"text": "thy mercy unto me;"}, {"text": "O do thou heal my soul; for why?"}, {"text": "I have offended thee."}]}, {"index": 4, "lines": [{"text": "Those that to me are enemies,", "bibleVerseRef": 5}, {"text": "of me do evil say,"}, {"text": "When shall he die, that so his name"}, {"text": "may perish quite away?", "syllables": ["may", "perish", "qui-", "te", "a-", "way?"]}]}, {"index": 5, "lines": [{"text": "To see me if he comes, he speaks", "bibleVerseRef": 6}, {"text": "vain words: but then his heart"}, {"text": "Heaps mischief to it, which he tells,"}, {"text": "when forth he doth depart."}]}, {"index": 6, "lines": [{"text": "My haters jointly whispering,", "syllables": ["My", "hate-", "rs", "join-", "tly", "whis-", "pe-", "ring,"], "bibleVerseRef": 7}, {"text": "''gainst me my hurt devise."}, {"text": "Mischief, say they, cleaves fast to him;", "syllables": ["mischief,", "say", "they,", "clea-", "ves", "fast", "to", "him;"], "bibleVerseRef": 8}, {"text": "he li''th, and shall not rise."}]}, {"index": 7, "lines": [{"text": "Yea, ev''n mine own familiar friend,", "syllables": ["Yea,", "ev''n", "mine", "own", "fami-", "li-", "ar", "friend,"], "bibleVerseRef": 9}, {"text": "on whom I did rely,"}, {"text": "Who ate my bread, ev''n he his heel"}, {"text": "against me lifted high."}]}, {"index": 8, "lines": [{"text": "But, Lord, be merciful to me,", "bibleVerseRef": 10}, {"text": "and up again me raise,"}, {"text": "That I may justly them requite", "syllables": ["That", "I", "may", "justly", "them", "requ-", "i-", "te"]}, {"text": "according to their ways."}]}, {"index": 9, "lines": [{"text": "By this I know that certainly", "bibleVerseRef": 11}, {"text": "I favour''d am by thee;"}, {"text": "Because my hateful enemy"}, {"text": "triumphs not over me.", "syllables": ["triu-", "-", "mphs", "not", "over", "me."]}]}, {"index": 10, "lines": [{"text": "But as for me, thou me uphold''st", "bibleVerseRef": 12}, {"text": "in mine integrity;"}, {"text": "And me before thy countenance", "syllables": ["And", "me", "before", "thy", "coun-", "te-", "nan-", "ce"]}, {"text": "thou sett''st continually.", "syllables": ["thou", "sett''st", "conti-", "nu-", "a-", "lly."]}]}, {"index": 11, "lines": [{"text": "The Lord, the God of Israel,", "syllables": ["The", "Lo-", "rd,", "the", "God", "of", "is-", "rael,"], "bibleVerseRef": 13}, {"text": "be bless''d for ever then,", "syllables": ["be", "ble-", "ss''d", "for", "ever", "then,"]}, {"text": "From age to age eternally.", "syllables": ["From", "age", "to", "age", "ete-", "r-", "nal-", "ly."]}, {"text": "Amen, yea, and amen.", "syllables": ["Ame-", "n,", "yea,", "and", "ame-", "n."]}]}]', 'CM', NULL, 'Blessed is he that wisely doth...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (134, 'reckdw98zSgFDzN8i', 99, '99', '1Th'' eternal Lord doth reign as king,
let all the people quake;
He sits between the cherubims,
let th'' earth be mov''d and shake.

2The Lord in Sion great and high
above all people is;
3Thy great and dreadful name (for it
is holy) let them bless.

4The king''s strength also judgment loves;
thou settlest equity:
Just judgment thou dost execute
in Jacob righteously.

5The Lord our God exalt on high,
and rev''rently do ye
Before his footstool worship him:
the Holy One is he.

6Moses and Aaron ''mong his priests,
Samuel, with them that call
Upon his name: these call''d on God,
and he them answer''d all.

7Within the pillar of the cloud
he unto them did speak:
The testimonies he them taught,
and laws, they did not break.

8Thou answer''dst them, O Lord our God;
thou wast a God that gave
Pardon to them, though on their deeds
thou wouldest vengeance have.

9Do ye exalt the Lord our God,
and at his holy hill
Do ye him worship: for the Lord
our God is holy still.', '[{"index": 0, "lines": [{"text": "Th'' eternal Lord doth reign as king,", "bibleVerseRef": 1}, {"text": "let all the people quake;", "syllables": ["let", "all", "the", "people", "qua-", "ke;"]}, {"text": "He sits between the cherubims,"}, {"text": "let th'' earth be mov''d and shake.", "syllables": ["let", "th''", "earth", "be", "mov''d", "andshake."]}]}, {"index": 1, "lines": [{"text": "The Lord in Sion great and high", "syllables": ["The", "Lord", "in", "Sion", "grea-", "t", "and", "high"], "bibleVerseRef": 2}, {"text": "above all people is;", "syllables": ["above", "all", "pe-", "o-", "ple", "is;"]}, {"text": "Thy great and dreadful name (for it", "bibleVerseRef": 3}, {"text": "is holy) let them bless."}]}, {"index": 2, "lines": [{"text": "The king''s strength also judgment loves;", "bibleVerseRef": 4}, {"text": "thou settlest equity:", "syllables": ["thou", "settlest", "e-", "qu-", "i-", "ty:"]}, {"text": "Just judgment thou dost execute", "syllables": ["Just", "jud-", "gme-", "nt", "thou", "dost", "exe-", "cute"]}, {"text": "in Jacob righteously.", "syllables": ["in", "jacob", "righte-", "o-", "us-", "ly."]}]}, {"index": 3, "lines": [{"text": "The Lord our God exalt on high,", "bibleVerseRef": 5}, {"text": "and rev''rently do ye"}, {"text": "Before his footstool worship him:"}, {"text": "the Holy One is he."}]}, {"index": 4, "lines": [{"text": "Moses and Aaron ''mong his priests,", "syllables": ["Moses", "and", "aa-", "ron", "''mong", "his", "prie-", "sts,"], "bibleVerseRef": 6}, {"text": "Samuel, with them that call"}, {"text": "Upon his name: these call''d on God,"}, {"text": "and he them answer''d all."}]}, {"index": 5, "lines": [{"text": "Within the pillar of the cloud", "bibleVerseRef": 7}, {"text": "he unto them did speak:"}, {"text": "The testimonies he them taught,"}, {"text": "and laws, they did not break."}]}, {"index": 6, "lines": [{"text": "Thou answer''dst them, O Lord our God;", "bibleVerseRef": 8}, {"text": "thou wast a God that gave"}, {"text": "Pardon to them, though on their deeds"}, {"text": "thou wouldest vengeance have.", "syllables": ["thou", "wouldest", "ven-", "gean-", "ce", "have."]}]}, {"index": 7, "lines": [{"text": "Do ye exalt the Lord our God,", "bibleVerseRef": 9}, {"text": "and at his holy hill"}, {"text": "Do ye him worship: for the Lord"}, {"text": "our God is holy still."}]}]', 'CM', NULL, 'Th'' eternal Lord doth reign as king...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (139, 'reclw3hos5WCtqeSU', 91, '91', '1He that doth in the secret place
of the most High reside,
Under the shade of him that is
th'' Almighty shall abide.

2I of the Lord my God will say,
He is my refuge still,
He is my fortress, and my God,
and in him trust I will.

3Assuredly he shall thee save,
and give deliverance
From subtile fowler''s snare,
and from the noisome pestilence.

4His feathers shall thee hide; thy trust
under his wings shall be:
His faithfulness shall be a shield
and buckler unto thee.

5Thou shalt not need to be afraid
for terrors of the night;
Nor for the arrow that doth fly
by day, while it is light;

6Nor for the pestilence, that walks
in darkness secretly;
Nor for destruction, that doth waste
at noon-day openly.

7A thousand at thy side shall fall,
on thy right hand shall lie
Ten thousand dead; yet unto thee
it shall not once come nigh.

8Only thou with thine eyes shalt look,
and a beholder be;
And thou therein the just reward
of wicked men shalt see.

9Because the Lord, who constantly
my refuge is alone,
Ev''n the most High, is made by thee
thy habitation;

10No plague shall near thy dwelling come;
no ill shall thee befall:
11For thee to keep in all thy ways
his angels charge he shall.

12They in their hands shall bear thee up,
still waiting thee upon;
Lest thou at any time should''st dash
thy foot against a stone.

13Upon the adder thou shalt tread,
and on the lion strong;
Thy feet on dragons trample shall,
and on the lions young.

14Because on me he set his love,
I''ll save and set him free;
Because my great name he hath known,
I will him set on high.

15He''ll call on me, I''ll answer him;
I will be with him still
In trouble, to deliver him,
and honour him I will.

16With length of days unto his mind
I will him satisfy;
I also my salvation
will cause his eyes to see.', '[{"index": 0, "lines": [{"text": "He that doth in the secret place", "syllables": ["He", "that", "doth", "in", "the", "secret", "pla-", "ce"], "bibleVerseRef": 1}, {"text": "of the most High reside,"}, {"text": "Under the shade of him that is"}, {"text": "th'' Almighty shall abide.", "syllables": ["th''", "almig-", "hty", "shall", "a-", "bide."]}]}, {"index": 1, "lines": [{"text": "I of the Lord my God will say,", "bibleVerseRef": 2}, {"text": "He is my refuge still,"}, {"text": "He is my fortress, and my God,"}, {"text": "and in him trust I will."}]}, {"index": 2, "lines": [{"text": "Assuredly he shall thee save,", "bibleVerseRef": 3}, {"text": "and give deliverance", "syllables": ["and", "give", "deli-", "ve-", "ran-", "ce"]}, {"text": "From subtile fowler''s snare,", "syllables": ["From", "sub-", "tile", "fow-", "le-", "r''s", "sna-", "re,"]}, {"text": "and from the noisome pestilence.", "syllables": ["and", "from", "the", "noisome", "pestilen-", "ce."]}]}, {"index": 3, "lines": [{"text": "His feathers shall thee hide; thy trust", "bibleVerseRef": 4}, {"text": "under his wings shall be:"}, {"text": "His faithfulness shall be a shield"}, {"text": "and buckler unto thee."}]}, {"index": 4, "lines": [{"text": "Thou shalt not need to be afraid", "bibleVerseRef": 5}, {"text": "for terrors of the night;"}, {"text": "Nor for the arrow that doth fly"}, {"text": "by day, while it is light;"}]}, {"index": 5, "lines": [{"text": "Nor for the pestilence, that walks", "syllables": ["Nor", "for", "the", "pesti-", "len-", "ce,", "that", "walks"], "bibleVerseRef": 6}, {"text": "in darkness secretly;"}, {"text": "Nor for destruction, that doth waste", "syllables": ["Nor", "for", "destruc-", "tion,", "that", "doth", "was-", "te"]}, {"text": "at noon-day openly.", "syllables": ["at", "noo-", "n-", "-day", "open-", "ly."]}]}, {"index": 6, "lines": [{"text": "A thousand at thy side shall fall,", "bibleVerseRef": 7}, {"text": "on thy right hand shall lie"}, {"text": "Ten thousand dead; yet unto thee"}, {"text": "it shall not once come nigh.", "syllables": ["it", "shall", "not", "once", "come", "nigh."]}]}, {"index": 7, "lines": [{"text": "Only thou with thine eyes shalt look,", "bibleVerseRef": 8}, {"text": "and a beholder be;"}, {"text": "And thou therein the just reward", "syllables": ["And", "thou", "therei-", "n", "the", "just", "re-", "ward"]}, {"text": "of wicked men shalt see."}]}, {"index": 8, "lines": [{"text": "Because the Lord, who constantly", "bibleVerseRef": 9}, {"text": "my refuge is alone,"}, {"text": "Ev''n the most High, is made by thee"}, {"text": "thy habitation;", "syllables": ["thy", "ha-", "bi-", "ta-", "tio-", "n;"]}]}, {"index": 9, "lines": [{"text": "No plague shall near thy dwelling come;", "syllables": ["No", "plague", "shall", "near", "thy", "dwel-", "ling", "come;"], "bibleVerseRef": 10}, {"text": "no ill shall thee befall:"}, {"text": "For thee to keep in all thy ways", "bibleVerseRef": 11}, {"text": "his angels charge he shall.", "syllables": ["his", "angels", "char-", "ge", "he", "shall."]}]}, {"index": 10, "lines": [{"text": "They in their hands shall bear thee up,", "bibleVerseRef": 12}, {"text": "still waiting thee upon;"}, {"text": "Lest thou at any time should''st dash"}, {"text": "thy foot against a stone.", "syllables": ["thy", "foot", "against", "a", "sto-", "ne."]}]}, {"index": 11, "lines": [{"text": "Upon the adder thou shalt tread,", "bibleVerseRef": 13}, {"text": "and on the lion strong;", "syllables": ["and", "on", "the", "lion", "stro-", "ng;"]}, {"text": "Thy feet on dragons trample shall,"}, {"text": "and on the lions young.", "syllables": ["and", "on", "the", "lions", "you-", "ng."]}]}, {"index": 12, "lines": [{"text": "Because on me he set his love,", "bibleVerseRef": 14}, {"text": "I''ll save and set him free;"}, {"text": "Because my great name he hath known,"}, {"text": "I will him set on high."}]}, {"index": 13, "lines": [{"text": "He''ll call on me, I''ll answer him;", "bibleVerseRef": 15}, {"text": "I will be with him still"}, {"text": "In trouble, to deliver him,", "syllables": ["In", "trou-", "b-", "le,", "to", "de-", "liver", "him,"]}, {"text": "and honour him I will."}]}, {"index": 14, "lines": [{"text": "With length of days unto his mind", "bibleVerseRef": 16}, {"text": "I will him satisfy;"}, {"text": "I also my salvation", "syllables": ["I", "al-", "so", "my", "sa-", "l-", "va-", "tion"]}, {"text": "will cause his eyes to see."}]}]', 'CM', NULL, 'He that doth in the secret place...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (145, 'recmhLPMWOXgGhFeY', 119, '119:57-64 (8)', '57Thou my sure portion art alone,
which I did chuse, O Lord:
I have resolv''d, and said, that I
would keep thy holy word.

58With my whole heart I did entreat
thy face and favour free:
According to thy gracious word
be merciful to me.

59I thought upon my former ways,
and did my life well try;
And to thy testimonies pure
my feet then turned I.

60I did not stay, nor linger long,
as those that slothful are;
But hastily thy laws to keep
myself I did prepare.

61Bands of ill men me robb''d; yet I
thy precepts did not slight.
62I''ll rise at midnight thee to praise,
ev''n for thy judgments right.

63I am companion to all those
who fear, and thee obey.
64O Lord, thy mercy fills the earth:
teach me thy laws, I pray.
', '[{"index": 0, "lines": [{"text": "Thou my sure portion art alone,", "bibleVerseRef": 57}, {"text": "which I did chuse, O Lord:"}, {"text": "I have resolv''d, and said, that I"}, {"text": "would keep thy holy word."}]}, {"index": 1, "lines": [{"text": "With my whole heart I did entreat", "bibleVerseRef": 58}, {"text": "thy face and favour free:"}, {"text": "According to thy gracious word"}, {"text": "be merciful to me."}]}, {"index": 2, "lines": [{"text": "I thought upon my former ways,", "bibleVerseRef": 59}, {"text": "and did my life well try;"}, {"text": "And to thy testimonies pure"}, {"text": "my feet then turned I."}]}, {"index": 3, "lines": [{"text": "I did not stay, nor linger long,", "bibleVerseRef": 60}, {"text": "as those that slothful are;"}, {"text": "But hastily thy laws to keep"}, {"text": "myself I did prepare.", "syllables": ["myse-", "lf", "I", "did", "pre-", "pare."]}]}, {"index": 4, "lines": [{"text": "Bands of ill men me robb''d; yet I", "bibleVerseRef": 61}, {"text": "thy precepts did not slight."}, {"text": "I''ll rise at midnight thee to praise,", "bibleVerseRef": 62}, {"text": "ev''n for thy judgments right."}]}, {"index": 5, "lines": [{"text": "I am companion to all those", "bibleVerseRef": 63}, {"text": "who fear, and thee obey.", "syllables": ["who", "fea-", "r,", "and", "thee", "obey."]}, {"text": "O Lord, thy mercy fills the earth:", "bibleVerseRef": 64}, {"text": "teach me thy laws, I pray."}]}]', 'CM', 'Part 8', 'Thou my sure portion art alone...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (150, 'recour4ik3OYmYVAX', 119, '119:9-16 (2)', '9By what means shall a young man learn
his way to purify?
If he according to thy word
thereto attentive be.

10Unfeignedly thee have I sought
with all my soul and heart:
O let me not from the right path
of thy commands depart.

11Thy word I in my heart have hid,
that I offend not thee.
12O Lord, thou ever blessed art,
thy statutes teach thou me.

13The judgments of thy mouth each one
my lips declared have:
14More joy thy testimonies'' way
than riches all me gave.

15I will thy holy precepts make
my meditation;
And carefully I''ll have respect
unto thy ways each one.

16Upon thy statutes my delight
shall constantly be set:
And, by thy grace, I never will
thy holy word forget.
', '[{"index": 0, "lines": [{"text": "By what means shall a young man learn", "bibleVerseRef": 9}, {"text": "his way to purify?"}, {"text": "If he according to thy word"}, {"text": "thereto attentive be."}]}, {"index": 1, "lines": [{"text": "Unfeignedly thee have I sought", "bibleVerseRef": 10}, {"text": "with all my soul and heart:"}, {"text": "O let me not from the right path"}, {"text": "of thy commands depart."}]}, {"index": 2, "lines": [{"text": "Thy word I in my heart have hid,", "bibleVerseRef": 11}, {"text": "that I offend not thee."}, {"text": "O Lord, thou ever blessed art,", "syllables": ["O", "Lo-", "rd,", "thou", "ever", "bles-", "sed", "art,"], "bibleVerseRef": 12}, {"text": "thy statutes teach thou me.", "syllables": ["thy", "statu-", "tes", "teach", "thou", "me."]}]}, {"index": 3, "lines": [{"text": "The judgments of thy mouth each one", "bibleVerseRef": 13}, {"text": "my lips declared have:"}, {"text": "More joy thy testimonies'' way", "bibleVerseRef": 14}, {"text": "than riches all me gave."}]}, {"index": 4, "lines": [{"text": "I will thy holy precepts make", "bibleVerseRef": 15}, {"text": "my meditation;", "syllables": ["my", "me-", "di-", "ta-", "tio-", "n;"]}, {"text": "And carefully I''ll have respect"}, {"text": "unto thy ways each one."}]}, {"index": 5, "lines": [{"text": "Upon thy statutes my delight", "syllables": ["upon", "thy", "sta-", "tu-", "tes", "my", "de-", "light"], "bibleVerseRef": 16}, {"text": "shall constantly be set:"}, {"text": "And, by thy grace, I never will", "syllables": ["And,", "by", "thy", "grace,", "I", "ne-", "ver", "will"]}, {"text": "thy holy word forget."}]}]', 'CM', 'Part 2', 'By what means shall a young man learn...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (155, 'recq7g2NcwVB7gFhJ', 142, '142', '1I with my voice cry''d to the Lord,
with it made my request:
2Pour''d out to him my plaint, to him
my trouble I exprest.

3When in me was o''erwhelm''d my sp''rit,
then well thou knew''st my way;
Where I did walk a snare for me
they privily did lay.

4I look''d on my right hand, and view''d,
but none to know me were;
All refuge failed me, no man
did for my soul take care.

5I cry''d to thee; I said, Thou art
my refuge, Lord, alone;
And in the land of those that live
thou art my portion.

6Because I am brought very low,
attend unto my cry:
Me from my persecutors save,
who stronger are than I.

7From prison bring my soul, that I
thy name may glorify:
The just shall compass me, when thou
with me deal''st bounteously.', '[{"index": 0, "lines": [{"text": "I with my voice cry''d to the Lord,", "bibleVerseRef": 1}, {"text": "with it made my request:"}, {"text": "Pour''d out to him my plaint, to him", "bibleVerseRef": 2}, {"text": "my trouble I exprest."}]}, {"index": 1, "lines": [{"text": "When in me was o''erwhelm''d my sp''rit,", "bibleVerseRef": 3}, {"text": "then well thou knew''st my way;"}, {"text": "Where I did walk a snare for me", "syllables": ["Where", "I", "did", "walk", "a", "snare", "for", "me"]}, {"text": "they privily did lay."}]}, {"index": 2, "lines": [{"text": "I look''d on my right hand, and view''d,", "bibleVerseRef": 4}, {"text": "but none to know me were;", "syllables": ["but", "none", "to", "know", "me", "were;"]}, {"text": "All refuge failed me, no man"}, {"text": "did for my soul take care."}]}, {"index": 3, "lines": [{"text": "I cry''d to thee; I said, Thou art", "bibleVerseRef": 5}, {"text": "my refuge, Lord, alone;"}, {"text": "And in the land of those that live"}, {"text": "thou art my portion.", "syllables": ["thou", "art", "my", "por-", "tio-", "n."]}]}, {"index": 4, "lines": [{"text": "Because I am brought very low,", "bibleVerseRef": 6}, {"text": "attend unto my cry:"}, {"text": "Me from my persecutors save,"}, {"text": "who stronger are than I."}]}, {"index": 5, "lines": [{"text": "From prison bring my soul, that I", "bibleVerseRef": 7}, {"text": "thy name may glorify:"}, {"text": "The just shall compass me, when thou"}, {"text": "with me deal''st bounteously.", "syllables": ["with", "me", "deal''st", "bounteo-", "us-", "ly."]}]}]', 'CM', NULL, 'I with my voice cry''d to the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (166, 'rectyAcH0XvEcnmLK', 63, '63', '1Lord, thee my God, I''ll early seek:
my soul doth thirst for thee;
My flesh longs in a dry parch''d land,
wherein no waters be:

2That I thy power may behold,
and brightness of thy face,
As I have seen thee heretofore
within thy holy place.

3Since better is thy love than life,
my lips thee praise shall give.
4I in thy name will lift my hands,
and bless thee while I live.

5Ev''n as with marrow and with fat
my soul shall filled be;
Then shall my mouth with joyful lips
sing praises unto thee:

6When I do thee upon my bed
remember with delight,
And when on thee I meditate
in watches of the night.

7In shadow of thy wings I''ll joy;
for thou mine help hast been.
8My soul thee follows hard; and me
thy right hand doth sustain.

9Who seek my soul to spill shall sink
down to earth''s lowest room.
10They by the sword shall be cut off,
and foxes'' prey become.

11Yet shall the king in God rejoice,
and each one glory shall
That swear by him: but stopp''d shall be
the mouth of liars all.', '[{"index": 0, "lines": [{"text": "Lord, thee my God, I''ll early seek:", "bibleVerseRef": 1}, {"text": "my soul doth thirst for thee;"}, {"text": "My flesh longs in a dry parch''d land,"}, {"text": "wherein no waters be:", "syllables": ["wherei-", "-", "n", "no", "waters", "be:"]}]}, {"index": 1, "lines": [{"text": "That I thy power may behold,", "syllables": ["That", "I", "thy", "powe-", "r", "may", "be-", "hold,"], "bibleVerseRef": 2}, {"text": "and brightness of thy face,"}, {"text": "As I have seen thee heretofore", "syllables": ["As", "I", "have", "seen", "thee", "here-", "to-", "fore"]}, {"text": "within thy holy place.", "syllables": ["within", "thy", "ho-", "ly", "pla-", "ce."]}]}, {"index": 2, "lines": [{"text": "Since better is thy love than life,", "syllables": ["since", "bet-", "ter", "is", "thy", "love", "than", "life,"], "bibleVerseRef": 3}, {"text": "my lips thee praise shall give."}, {"text": "I in thy name will lift my hands,", "bibleVerseRef": 4}, {"text": "and bless thee while I live."}]}, {"index": 3, "lines": [{"text": "Ev''n as with marrow and with fat", "bibleVerseRef": 5}, {"text": "my soul shall filled be;"}, {"text": "Then shall my mouth with joyful lips"}, {"text": "sing praises unto thee:", "syllables": ["sing", "praise-", "s", "un-", "to", "thee:"]}]}, {"index": 4, "lines": [{"text": "When I do thee upon my bed", "bibleVerseRef": 6}, {"text": "remember with delight,"}, {"text": "And when on thee I meditate"}, {"text": "in watches of the night."}]}, {"index": 5, "lines": [{"text": "In shadow of thy wings I''ll joy;", "bibleVerseRef": 7}, {"text": "for thou mine help hast been."}, {"text": "My soul thee follows hard; and me", "bibleVerseRef": 8}, {"text": "thy right hand doth sustain."}]}, {"index": 6, "lines": [{"text": "Who seek my soul to spill shall sink", "bibleVerseRef": 9}, {"text": "down to earth''s lowest room.", "syllables": ["down", "to", "ea-", "rth''s", "lowest", "room."]}, {"text": "They by the sword shall be cut off,", "bibleVerseRef": 10}, {"text": "and foxes'' prey become.", "syllables": ["and", "foxe-", "s''", "prey", "be-", "come."]}]}, {"index": 7, "lines": [{"text": "Yet shall the king in God rejoice,", "bibleVerseRef": 11}, {"text": "and each one glory shall"}, {"text": "That swear by him: but stopp''d shall be"}, {"text": "the mouth of liars all."}]}]', 'CM', NULL, 'Lord, thee my God, I''ll early seek...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (165, 'rectirbqRKt4cWFPj', 87, '87', '1Upon the hills of holiness
he his foundation sets.
2God, more than Jacob''s dwellings all,
delights in Sion''s gates.

3Things glorious are said of thee,
thou city of the Lord.
4Rahab and Babel I, to those
that know me, will record:

Behold ev''n Tyrus, and with it
the land of Palestine,
And likewise Ethiopia;
this man was born therein.

5And it of Sion shall be said,
This man and that man there
Was born; and he that is most High
himself shall stablish her.

6When God the people writes, he''ll count
that this man born was there.
7There be that sing and play; and all
my well-springs in thee are.', '[{"index": 0, "lines": [{"text": "Upon the hills of holiness", "bibleVerseRef": 1}, {"text": "he his foundation sets."}, {"text": "God, more than Jacob''s dwellings all,", "bibleVerseRef": 2}, {"text": "delights in Sion''s gates."}]}, {"index": 1, "lines": [{"text": "Things glorious are said of thee,", "syllables": ["Thi-", "ngs", "glo-", "rious", "are", "said", "of", "thee,"], "bibleVerseRef": 3}, {"text": "thou city of the Lord."}, {"text": "Rahab and Babel I, to those", "bibleVerseRef": 4}, {"text": "that know me, will record:"}]}, {"index": 2, "lines": [{"text": "Behold ev''n Tyrus, and with it"}, {"text": "the land of Palestine,", "syllables": ["the", "land", "of", "pale-", "s-", "tine,"]}, {"text": "And likewise Ethiopia;", "syllables": ["And", "like-", "-", "wise", "e-", "thio-", "pi-", "a;"]}, {"text": "this man was born therein.", "syllables": ["this", "man", "was", "born", "therei-", "n."]}]}, {"index": 3, "lines": [{"text": "And it of Sion shall be said,", "syllables": ["And", "it", "of", "Sion", "sha-", "ll", "be", "said,"], "bibleVerseRef": 5}, {"text": "This man and that man there"}, {"text": "Was born; and he that is most High"}, {"text": "himself shall stablish her."}]}, {"index": 4, "lines": [{"text": "When God the people writes, he''ll count", "syllables": ["When", "God", "the", "people", "wri-", "tes,", "he''ll", "count"], "bibleVerseRef": 6}, {"text": "that this man born was there."}, {"text": "There be that sing and play; and all", "bibleVerseRef": 7}, {"text": "my well-springs in thee are."}]}]', 'CM', NULL, 'Upon the hills of holiness...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (162, 'recsFtrIhlAZO3GnQ', 119, '119:25-32 (4)', '25My soul to dust cleaves: quicken me,
according to thy word.
26My ways I shew''d, and me thou heard''st:
teach me thy statutes, Lord.

27The way of thy commandements
make me aright to know;
So all thy works that wondrous are
I shall to others show.

28My soul doth melt, and drop away,
for heaviness and grief:
To me, according to thy word,
give strength, and send relief.

29From me the wicked way of lies
let far removed be;
And graciously thy holy law
do thou grant unto me.

30I chosen have the perfect way
of truth and verity:
Thy judgments that most righteous are
before me laid have I.

31I to thy testimonies cleave;
shame do not on me cast.
32I''ll run thy precepts'' way, when thou
my heart enlarged hast.
', '[{"index": 0, "lines": [{"text": "My soul to dust cleaves: quicken me,", "syllables": ["My", "soul", "to", "dust", "cleaves:", "qui-", "cken", "me,"], "bibleVerseRef": 25}, {"text": "according to thy word."}, {"text": "My ways I shew''d, and me thou heard''st:", "bibleVerseRef": 26}, {"text": "teach me thy statutes, Lord.", "syllables": ["teach", "me", "thy", "statu-", "tes,", "Lord."]}]}, {"index": 1, "lines": [{"text": "The way of thy commandements", "bibleVerseRef": 27}, {"text": "make me aright to know;"}, {"text": "So all thy works that wondrous are"}, {"text": "I shall to others show."}]}, {"index": 2, "lines": [{"text": "My soul doth melt, and drop away,", "bibleVerseRef": 28}, {"text": "for heaviness and grief:"}, {"text": "To me, according to thy word,"}, {"text": "give strength, and send relief."}]}, {"index": 3, "lines": [{"text": "From me the wicked way of lies", "bibleVerseRef": 29}, {"text": "let far removed be;"}, {"text": "And graciously thy holy law"}, {"text": "do thou grant unto me."}]}, {"index": 4, "lines": [{"text": "I chosen have the perfect way", "syllables": ["I", "chose-", "n", "have", "the", "per-", "fect", "way"], "bibleVerseRef": 30}, {"text": "of truth and verity:"}, {"text": "Thy judgments that most righteous are"}, {"text": "before me laid have I."}]}, {"index": 5, "lines": [{"text": "I to thy testimonies cleave;", "syllables": ["I", "to", "thy", "testi-", "mo-", "nies", "clea-", "ve;"], "bibleVerseRef": 31}, {"text": "shame do not on me cast."}, {"text": "I''ll run thy precepts'' way, when thou", "bibleVerseRef": 32}, {"text": "my heart enlarged hast."}]}]', 'CM', 'Part 4', 'My soul to dust cleaves: quicken me...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (178, 'recxOv3ynKpAR9xTI', 119, '119:81-88 (11)', '81My soul for thy salvation faints;
yet I thy word believe.
82Mine eyes fail for thy word: I say,
When wilt thou comfort give?

83For like a bottle I''m become,
that in the smoke is set:
I''m black, and parch''d with grief; yet I
thy statutes not forget.

84How many are thy servant''s days?
when wilt thou execute
Just judgment on these wicked men
that do me persecute?

85The proud have digged pits for me,
which is against thy laws.
86Thy words all faithful are: help me,
pursu''d without a cause.

87They so consum''d me, that on earth
my life they scarce did leave:
Thy precepts yet forsook I not,
but close to them did cleave.

88After thy loving-kindness, Lord,
me quicken, and preserve:
The testimony of thy mouth
so shall I still observe.
', '[{"index": 0, "lines": [{"text": "My soul for thy salvation faints;", "bibleVerseRef": 81}, {"text": "yet I thy word believe."}, {"text": "Mine eyes fail for thy word: I say,", "bibleVerseRef": 82}, {"text": "When wilt thou comfort give?"}]}, {"index": 1, "lines": [{"text": "For like a bottle I''m become,", "bibleVerseRef": 83}, {"text": "that in the smoke is set:", "syllables": ["that", "in", "the", "smoke", "is", "set:"]}, {"text": "I''m black, and parch''d with grief; yet I"}, {"text": "thy statutes not forget.", "syllables": ["thy", "statu-", "tes", "not", "for-", "get."]}]}, {"index": 2, "lines": [{"text": "How many are thy servant''s days?", "bibleVerseRef": 84}, {"text": "when wilt thou execute", "syllables": ["whe-", "n", "wilt", "thou", "exe-", "cute"]}, {"text": "Just judgment on these wicked men"}, {"text": "that do me persecute?"}]}, {"index": 3, "lines": [{"text": "The proud have digged pits for me,", "bibleVerseRef": 85}, {"text": "which is against thy laws."}, {"text": "Thy words all faithful are: help me,", "bibleVerseRef": 86}, {"text": "pursu''d without a cause."}]}, {"index": 4, "lines": [{"text": "They so consum''d me, that on earth", "bibleVerseRef": 87}, {"text": "my life they scarce did leave:", "syllables": ["my", "life", "they", "scarce", "did", "leave:"]}, {"text": "Thy precepts yet forsook I not,"}, {"text": "but close to them did cleave.", "syllables": ["but", "close", "to", "them", "did", "cleave."]}]}, {"index": 5, "lines": [{"text": "After thy loving-kindness, Lord,", "bibleVerseRef": 88}, {"text": "me quicken, and preserve:", "syllables": ["me", "qui-", "cken,", "and", "pre-", "serve:"]}, {"text": "The testimony of thy mouth"}, {"text": "so shall I still observe.", "syllables": ["so", "shall", "I", "still", "obser-", "ve."]}]}]', 'CM', 'Part 11', 'My soul for thy salvation faints...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (184, 'reczEzZGCm7DcPfMd', 119, '119:153-160 (20)', '153Consider mine affliction,
in safety do me set:
Deliver me, O Lord, for I
thy law do not forget.

154After thy word revive thou me: save me,
and plead my cause.
155Salvation is from sinners far;
for they seek not thy laws.

156O Lord, both great and manifold
thy tender mercies be:
According to thy judgments just,
revive and quicken me.

157My persecutors many are,
and foes that do combine;
Yet from thy testimonies pure
my heart doth not decline.

158I saw transgressors, and was griev''d;
for they keep not thy word.
159See how I love thy law! as thou
art kind, me quicken, Lord.

160From the beginning all thy word
hath been most true and sure:
Thy righteous judgments ev''ry one
for evermore endure.', '[{"index": 0, "lines": [{"text": "Consider mine affliction,", "syllables": ["con-", "side-", "-", "r", "mine", "af-", "flic-", "tion,"], "bibleVerseRef": 153}, {"text": "in safety do me set:"}, {"text": "Deliver me, O Lord, for I", "syllables": ["de-", "live-", "r", "me,", "O", "Lord,", "for", "I"]}, {"text": "thy law do not forget."}]}, {"index": 1, "lines": [{"text": "After thy word revive thou me: save me,", "syllables": ["after", "thy", "word", "revive", "thou", "me:", "save", "me,"], "bibleVerseRef": 154}, {"text": "and plead my cause.", "syllables": ["and", "plead", "my", "cause-", "-", "."]}, {"text": "Salvation is from sinners far;", "bibleVerseRef": 155}, {"text": "for they seek not thy laws."}]}, {"index": 2, "lines": [{"text": "O Lord, both great and manifold", "bibleVerseRef": 156}, {"text": "thy tender mercies be:"}, {"text": "According to thy judgments just,"}, {"text": "revive and quicken me.", "syllables": ["revive", "and", "qu-", "i-", "cken", "me."]}]}, {"index": 3, "lines": [{"text": "My persecutors many are,", "bibleVerseRef": 157}, {"text": "and foes that do combine;"}, {"text": "Yet from thy testimonies pure"}, {"text": "my heart doth not decline."}]}, {"index": 4, "lines": [{"text": "I saw transgressors, and was griev''d;", "bibleVerseRef": 158}, {"text": "for they keep not thy word."}, {"text": "See how I love thy law! as thou", "bibleVerseRef": 159}, {"text": "art kind, me quicken, Lord.", "syllables": ["art", "kind,", "me", "qui-", "cken,", "Lord."]}]}, {"index": 5, "lines": [{"text": "From the beginning all thy word", "bibleVerseRef": 160}, {"text": "hath been most true and sure:"}, {"text": "Thy righteous judgments ev''ry one"}, {"text": "for evermore endure.", "syllables": ["for", "eve-", "r-", "more", "en-", "dure."]}]}]', 'CM', NULL, 'Consider mine affliction...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (18, 'rec5QGUHSapKjwQfD', 39, '39', '1I said, I will look to my ways,
lest with my tongue I sin:
In sight of wicked men my mouth
with bridle I''ll keep in.

2With silence I as dumb became,
I did myself restrain
From speaking good; but then the more
increased was my pain.

3My heart within me waxed hot;
and, while I musing was,
The fire did burn; and from my tongue
these words I did let pass:

4Mine end, and measure of my days,
O Lord, unto me show
What is the same; that I thereby
my frailty well may know.

5Lo, thou my days an handbreadth mad''st;
mine age is in thine eye
As nothing: sure each man at best
is wholly vanity.

6Sure each man walks in a vain show;
they vex themselves in vain:
He heaps up wealth, and doth not know
to whom it shall pertain.

7And now, O Lord, what wait I for?
my hope is fix''d on thee.
8Free me from all my trespasses,
the fool''s scorn make not me.

9Dumb was I, op''ning not my mouth,
because this work was thine.
10Thy stroke take from me; by the blow
of thine hand I do pine.

11When with rebukes thou dost correct
man for iniquity,
Thou wastes his beauty like a moth:
sure each man''s vanity.

12Attend my cry, Lord, at my tears
and pray''rs not silent be:
I sojourn as my fathers all,
and stranger am with thee.

13O spare thou me, that I my strength
recover may again,
Before from hence I do depart,
and here no more remain.', '[{"index": 0, "lines": [{"text": "I said, I will look to my ways,", "bibleVerseRef": 1}, {"text": "lest with my tongue I sin:", "syllables": ["lest", "with", "my", "tongue", "I", "sin:"]}, {"text": "In sight of wicked men my mouth"}, {"text": "with bridle I''ll keep in."}]}, {"index": 1, "lines": [{"text": "With silence I as dumb became,", "bibleVerseRef": 2}, {"text": "I did myself restrain", "syllables": ["I", "did", "myse-", "lf", "res-", "train"]}, {"text": "From speaking good; but then the more"}, {"text": "increased was my pain."}]}, {"index": 2, "lines": [{"text": "My heart within me waxed hot;", "bibleVerseRef": 3}, {"text": "and, while I musing was,"}, {"text": "The fire did burn; and from my tongue", "syllables": ["The", "fire", "did", "burn;", "and", "from", "my", "tongue"]}, {"text": "these words I did let pass:"}]}, {"index": 3, "lines": [{"text": "Mine end, and measure of my days,", "bibleVerseRef": 4}, {"text": "O Lord, unto me show"}, {"text": "What is the same; that I thereby"}, {"text": "my frailty well may know."}]}, {"index": 4, "lines": [{"text": "Lo, thou my days an handbreadth mad''st;", "bibleVerseRef": 5}, {"text": "mine age is in thine eye"}, {"text": "As nothing: sure each man at best"}, {"text": "is wholly vanity."}]}, {"index": 5, "lines": [{"text": "Sure each man walks in a vain show;", "bibleVerseRef": 6}, {"text": "they vex themselves in vain:", "syllables": ["they", "vex", "themsel-", "ves", "in", "vain:"]}, {"text": "He heaps up wealth, and doth not know"}, {"text": "to whom it shall pertain."}]}, {"index": 6, "lines": [{"text": "And now, O Lord, what wait I for?", "bibleVerseRef": 7}, {"text": "my hope is fix''d on thee."}, {"text": "Free me from all my trespasses,", "bibleVerseRef": 8}, {"text": "the fool''s scorn make not me."}]}, {"index": 7, "lines": [{"text": "Dumb was I, op''ning not my mouth,", "bibleVerseRef": 9}, {"text": "because this work was thine."}, {"text": "Thy stroke take from me; by the blow", "syllables": ["Thy", "stroke", "take", "from", "me;", "by", "the", "blow"], "bibleVerseRef": 10}, {"text": "of thine hand I do pine."}]}, {"index": 8, "lines": [{"text": "When with rebukes thou dost correct", "bibleVerseRef": 11}, {"text": "man for iniquity,"}, {"text": "Thou wastes his beauty like a moth:", "syllables": ["Thou", "wastes", "his", "beau-", "ty", "like", "a", "moth:"]}, {"text": "sure each man''s vanity."}]}, {"index": 9, "lines": [{"text": "Attend my cry, Lord, at my tears", "bibleVerseRef": 12}, {"text": "and pray''rs not silent be:", "syllables": ["and", "pray-", "''rs", "not", "silent", "be:"]}, {"text": "I sojourn as my fathers all,"}, {"text": "and stranger am with thee."}]}, {"index": 10, "lines": [{"text": "O spare thou me, that I my strength", "syllables": ["O", "spare", "thou", "me,", "that", "I", "my", "strength"], "bibleVerseRef": 13}, {"text": "recover may again,", "syllables": ["re-", "cove-", "r", "may", "a-", "gain,"]}, {"text": "Before from hence I do depart,"}, {"text": "and here no more remain."}]}]', 'CM', NULL, 'I said, I will look to my ways...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (27, 'rec7LJp3UjAjm8nbF', 32, '32', '1O blessed is the man to whom
is freely pardoned
All the transgression he hath done,
whose sin is covered.

2Bless''d is the man to whom the Lord
imputeth not his sin,
And in whose sp''rit there is no guile,
nor fraud is found therein.

3When as I did refrain my speech,
and silent was my tongue,
My bones then waxed old, because
I roared all day long.

4For upon me both day and night
thine hand did heavy lie,
So that my moisture turned is
in summer''s drought thereby.

5I thereupon have unto thee
my sin acknowledged,
And likewise mine iniquity
I have not covered:

I will confess unto the Lord
my trespasses, said I;
And of my sin thou freely didst
forgive th'' iniquity.

6For this shall ev''ry godly one
his prayer make to thee;
In such a time he shall thee seek,
as found thou mayest be.

Surely, when floods of waters great
do swell up to the brim,
They shall not overwhelm his soul,
nor once come near to him.

7Thou art my hiding-place, thou shalt
from trouble keep me free:
Thou with songs of deliverance
about shalt compass me.

8I will instruct thee, and thee teach
the way that thou shalt go;
And, with mine eye upon thee set,
I will direction show.

9Then be not like the horse or mule,
which do not understand;
Whose mouth, lest they come near to thee,
a bridle must command.

10Unto the man that wicked is
his sorrows shall abound;
But him that trusteth in the Lord
mercy shall compass round.

11Ye righteous, in the Lord be glad,
in him do ye rejoice:
All ye that upright are in heart,
for joy lift up your voice.', '[{"index": 0, "lines": [{"text": "O blessed is the man to whom", "bibleVerseRef": 1}, {"text": "is freely pardoned"}, {"text": "All the transgression he hath done,"}, {"text": "whose sin is covered.", "syllables": ["who-", "se", "sin", "is", "cove-", "red."]}]}, {"index": 1, "lines": [{"text": "Bless''d is the man to whom the Lord", "bibleVerseRef": 2}, {"text": "imputeth not his sin,"}, {"text": "And in whose sp''rit there is no guile,", "syllables": ["And", "in", "whose", "sp''rit", "there", "is", "no", "guile,"]}, {"text": "nor fraud is found therein.", "syllables": ["nor", "fraud", "is", "found", "therei-", "n."]}]}, {"index": 2, "lines": [{"text": "When as I did refrain my speech,", "bibleVerseRef": 3}, {"text": "and silent was my tongue,"}, {"text": "My bones then waxed old, because"}, {"text": "I roared all day long.", "syllables": ["I", "roa-", "red", "all", "day", "long."]}]}, {"index": 3, "lines": [{"text": "For upon me both day and night", "bibleVerseRef": 4}, {"text": "thine hand did heavy lie,"}, {"text": "So that my moisture turned is"}, {"text": "in summer''s drought thereby."}]}, {"index": 4, "lines": [{"text": "I thereupon have unto thee", "bibleVerseRef": 5}, {"text": "my sin acknowledged,"}, {"text": "And likewise mine iniquity"}, {"text": "I have not covered:", "syllables": ["I", "have", "not", "cove-", "-", "red:"]}]}, {"index": 5, "lines": [{"text": "I will confess unto the Lord"}, {"text": "my trespasses, said I;"}, {"text": "And of my sin thou freely didst"}, {"text": "forgive th'' iniquity.", "syllables": ["forgive", "th''", "in-", "iq-", "ui-", "ty."]}]}, {"index": 6, "lines": [{"text": "For this shall ev''ry godly one", "bibleVerseRef": 6}, {"text": "his prayer make to thee;"}, {"text": "In such a time he shall thee seek,"}, {"text": "as found thou mayest be.", "syllables": ["as", "found", "thou", "maye-", "st", "be."]}]}, {"index": 7, "lines": [{"text": "Surely, when floods of waters great", "syllables": ["sure-", "ly,", "when", "floo-", "ds", "of", "waters", "great"]}, {"text": "do swell up to the brim,"}, {"text": "They shall not overwhelm his soul,", "syllables": ["They", "sha-", "ll", "not", "over-", "whelm", "his", "soul,"]}, {"text": "nor once come near to him.", "syllables": ["nor", "once", "come", "near", "to", "him."]}]}, {"index": 8, "lines": [{"text": "Thou art my hiding-place, thou shalt", "syllables": ["Thou", "art", "my", "hidin-", "g-pla-", "ce,", "thou", "shalt"], "bibleVerseRef": 7}, {"text": "from trouble keep me free:"}, {"text": "Thou with songs of deliverance", "syllables": ["Thou", "with", "songs", "of", "deli-", "ve-", "ran-", "ce"]}, {"text": "about shalt compass me."}]}, {"index": 9, "lines": [{"text": "I will instruct thee, and thee teach", "bibleVerseRef": 8}, {"text": "the way that thou shalt go;"}, {"text": "And, with mine eye upon thee set,"}, {"text": "I will direction show.", "syllables": ["I", "will", "dire-", "c-", "tion", "show."]}]}, {"index": 10, "lines": [{"text": "Then be not like the horse or mule,", "syllables": ["Then", "be", "not", "like", "the", "horse", "or", "mule,"], "bibleVerseRef": 9}, {"text": "which do not understand;"}, {"text": "Whose mouth, lest they come near to thee,"}, {"text": "a bridle must command."}]}, {"index": 11, "lines": [{"text": "Unto the man that wicked is", "bibleVerseRef": 10}, {"text": "his sorrows shall abound;"}, {"text": "But him that trusteth in the Lord"}, {"text": "mercy shall compass round."}]}, {"index": 12, "lines": [{"text": "Ye righteous, in the Lord be glad,", "bibleVerseRef": 11}, {"text": "in him do ye rejoice:"}, {"text": "All ye that upright are in heart,"}, {"text": "for joy lift up your voice."}]}]', 'CM', NULL, 'O blessed is the man to whom...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (32, 'rec8jNeNPgyXtHsLl', 13, '13', '1How long wilt thou forget me, Lord?
shall it for ever be?
O how long shall it be that thou
wilt hide thy face from me?

2How long take counsel in my soul,
still sad in heart, shall I?
How long exalted over me
Shall be mine enemy?

3O Lord my God, consider well,
and answer to me make:
Mine eyes enlighten, lest the sleep
of death me overtake:

4Lest that mine enemy should say,
Against him I prevail''d;
And those that trouble me rejoice,
when I am mov''d and fail''d.

5But I have all my confidence
thy mercy set upon;
My heart within me shall rejoice
in thy salvation.

6I will unto the Lord my God
sing praises cheerfully,
Because he hath his bounty shown
to me abundantly.', '[{"index": 0, "lines": [{"text": "How long wilt thou forget me, Lord?", "bibleVerseRef": 1}, {"text": "shall it for ever be?", "syllables": ["sha-", "ll", "it", "for", "ever", "be?"]}, {"text": "O how long shall it be that thou"}, {"text": "wilt hide thy face from me?"}]}, {"index": 1, "lines": [{"text": "How long take counsel in my soul,", "bibleVerseRef": 2}, {"text": "still sad in heart, shall I?"}, {"text": "How long exalted over me", "syllables": ["How", "lo-", "ng", "e-", "xal-", "ted", "over", "me"]}, {"text": "Shall be mine enemy?"}]}, {"index": 2, "lines": [{"text": "O Lord my God, consider well,", "syllables": ["O", "Lord", "my", "God,", "con-", "side-", "r", "well,"], "bibleVerseRef": 3}, {"text": "and answer to me make:"}, {"text": "Mine eyes enlighten, lest the sleep"}, {"text": "of death me overtake:", "syllables": ["of", "dea-", "th", "me", "over-", "take:"]}]}, {"index": 3, "lines": [{"text": "Lest that mine enemy should say,", "bibleVerseRef": 4}, {"text": "Against him I prevail''d;"}, {"text": "And those that trouble me rejoice,"}, {"text": "when I am mov''d and fail''d."}]}, {"index": 4, "lines": [{"text": "But I have all my confidence", "syllables": ["But", "I", "have", "all", "my", "confi-", "den-", "ce"], "bibleVerseRef": 5}, {"text": "thy mercy set upon;"}, {"text": "My heart within me shall rejoice"}, {"text": "in thy salvation.", "syllables": ["in", "thy", "sal-", "va-", "tio-", "n."]}]}, {"index": 5, "lines": [{"text": "I will unto the Lord my God", "bibleVerseRef": 6}, {"text": "sing praises cheerfully,", "syllables": ["sing", "praise-", "s", "cheer-", "ful-", "ly,"]}, {"text": "Because he hath his bounty shown"}, {"text": "to me abundantly."}]}]', 'CM', NULL, 'How long wilt thou forget me, Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (48, 'recEvFbgnJCVILz5d', 34, '34', '1God will I bless all times; his praise
my mouth shall still express.
2My soul shall boast in God: the meek
shall hear with joyfulness.

3Extol the Lord with me, let us
exalt his name together.
4I sought the Lord, he heard, and did
me from all fears deliver.

5They look''d to him, and lighten''d were:
not shamed were their faces.
6This poor man cry''d, God heard, and sav''d
him from all his distresses.

7The angel of the Lord encamps,
and round encompasseth
All those about that do him fear,
and them delivereth.

8O taste and see that God is good:
who trusts in him is bless''d.
9Fear God his saints: none that him fear
shall be with want oppress''d.

10The lions young may hungry be,
and they may lack their food:
But they that truly seek the Lord
shall not lack any good.

11O children, hither do ye come,
and unto me give ear;
I shall you teach to understand
how ye the Lord should fear.

12What man is he that life desires,
to see good would live long?
13Thy lips refrain from speaking guile,
and from ill words thy tongue.

14Depart from ill, do good, seek peace,
pursue it earnestly.
15God''s eyes are on the just; his ears
are open to their cry.

16The face of God is set against
those that do wickedly,
That he may quite out from the earth
cut off their memory.

17The righteous cry unto the Lord,
he unto them gives ear;
And they out of their troubles all
by him deliver''d are.

18The Lord is ever nigh to them
that be of broken sp''rit;
To them he safety doth afford
that are in heart contrite.

19The troubles that afflict the just
in number many be;
But yet at length out of them all
the Lord doth set him free.

20He carefully his bones doth keep,
whatever can befall;
That not so much as one of them
can broken be at all.

21Ill shall the wicked slay; laid waste
shall be who hate the just.
22The Lord redeems his servants'' souls;
none perish that him trust.', '[{"index": 0, "lines": [{"text": "God will I bless all times; his praise", "bibleVerseRef": 1}, {"text": "my mouth shall still express."}, {"text": "My soul shall boast in God: the meek", "syllables": ["My", "soul", "shall", "boast", "in", "God:", "the", "meek"], "bibleVerseRef": 2}, {"text": "shall hear with joyfulness."}]}, {"index": 1, "lines": [{"text": "Extol the Lord with me, let us", "bibleVerseRef": 3}, {"text": "exalt his name together.", "syllables": ["exalt", "his", "name", "to-", "ge-", "ther."]}, {"text": "I sought the Lord, he heard, and did", "bibleVerseRef": 4}, {"text": "me from all fears deliver."}]}, {"index": 2, "lines": [{"text": "They look''d to him, and lighten''d were:", "bibleVerseRef": 5}, {"text": "not shamed were their faces."}, {"text": "This poor man cry''d, God heard, and sav''d", "bibleVerseRef": 6}, {"text": "him from all his distresses.", "syllables": ["him", "from", "all", "his", "distres-", "ses."]}]}, {"index": 3, "lines": [{"text": "The angel of the Lord encamps,", "bibleVerseRef": 7}, {"text": "and round encompasseth"}, {"text": "All those about that do him fear,"}, {"text": "and them delivereth."}]}, {"index": 4, "lines": [{"text": "O taste and see that God is good:", "syllables": ["O", "taste", "and", "see", "that", "God", "is", "good:"], "bibleVerseRef": 8}, {"text": "who trusts in him is bless''d."}, {"text": "Fear God his saints: none that him fear", "syllables": ["Fear", "God", "his", "saints:", "none", "that", "him", "fear"], "bibleVerseRef": 9}, {"text": "shall be with want oppress''d."}]}, {"index": 5, "lines": [{"text": "The lions young may hungry be,", "syllables": ["The", "lio-", "ns", "young", "may", "hun-", "gry", "be,"], "bibleVerseRef": 10}, {"text": "and they may lack their food:"}, {"text": "But they that truly seek the Lord"}, {"text": "shall not lack any good."}]}, {"index": 6, "lines": [{"text": "O children, hither do ye come,", "bibleVerseRef": 11}, {"text": "and unto me give ear;"}, {"text": "I shall you teach to understand"}, {"text": "how ye the Lord should fear."}]}, {"index": 7, "lines": [{"text": "What man is he that life desires,", "bibleVerseRef": 12}, {"text": "to see good would live long?"}, {"text": "Thy lips refrain from speaking guile,", "syllables": ["Thy", "lips", "refrain", "from", "speaking", "gu-", "i-", "le,"], "bibleVerseRef": 13}, {"text": "and from ill words thy tongue.", "syllables": ["and", "from", "ill", "words", "thy", "tongue."]}]}, {"index": 8, "lines": [{"text": "Depart from ill, do good, seek peace,", "bibleVerseRef": 14}, {"text": "pursue it earnestly."}, {"text": "God''s eyes are on the just; his ears", "bibleVerseRef": 15}, {"text": "are open to their cry.", "syllables": ["are", "open", "to", "thei-", "r", "cry."]}]}, {"index": 9, "lines": [{"text": "The face of God is set against", "bibleVerseRef": 16}, {"text": "those that do wickedly,"}, {"text": "That he may quite out from the earth", "syllables": ["That", "he", "may", "quite", "out", "from", "the", "earth"]}, {"text": "cut off their memory."}]}, {"index": 10, "lines": [{"text": "The righteous cry unto the Lord,", "bibleVerseRef": 17}, {"text": "he unto them gives ear;"}, {"text": "And they out of their troubles all"}, {"text": "by him deliver''d are."}]}, {"index": 11, "lines": [{"text": "The Lord is ever nigh to them", "syllables": ["The", "Lo-", "rd", "is", "ever", "nigh", "to", "them"], "bibleVerseRef": 18}, {"text": "that be of broken sp''rit;"}, {"text": "To them he safety doth afford"}, {"text": "that are in heart contrite.", "syllables": ["that", "are", "in", "heart", "contri-", "te."]}]}, {"index": 12, "lines": [{"text": "The troubles that afflict the just", "bibleVerseRef": 19}, {"text": "in number many be;"}, {"text": "But yet at length out of them all"}, {"text": "the Lord doth set him free."}]}, {"index": 13, "lines": [{"text": "He carefully his bones doth keep,", "bibleVerseRef": 20}, {"text": "whatever can befall;", "syllables": ["whateve-", "-", "r", "can", "be-", "fall;"]}, {"text": "That not so much as one of them"}, {"text": "can broken be at all."}]}, {"index": 14, "lines": [{"text": "Ill shall the wicked slay; laid waste", "syllables": ["Ill", "shall", "the", "wicked", "slay;", "laid", "was-", "te"], "bibleVerseRef": 21}, {"text": "shall be who hate the just."}, {"text": "The Lord redeems his servants'' souls;", "bibleVerseRef": 22}, {"text": "none perish that him trust.", "syllables": ["none", "pe-", "rish", "that", "him", "trust."]}]}]', 'CM', NULL, 'God will I bless all times; his praise...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (84, 'recV6m7hHloRpOeE2', 119, '119:1-8 (1)', '1Blessed are they that undefil''d,
and straight are in the way;
Who in the Lord''s most holy law do walk,
and do not stray.

2Blessed are they who to observe
his statutes are inclin''d;
And who do seek the living God
with their whole heart and mind.

3Such in his ways do walk,
and they do no iniquity.
4Thou hast commanded us to keep
thy precepts carefully.

5O that thy statutes to observe
thou would''st my ways direct!
6Then shall I not be sham''d, when I
thy precepts all respect.

7Then with integrity of heart
thee will I praise and bless,
When I the judgments all have learn''d
of thy pure righteousness.

8That I will keep thy statutes all
firmly resolv''d have I:
O do not then, most gracious God,
forsake me utterly.
', '[{"index": 0, "lines": [{"text": "Blessed are they that undefil''d,", "bibleVerseRef": 1}, {"text": "and straight are in the way;"}, {"text": "Who in the Lord''s most holy law do walk,", "syllables": ["Who", "in", "the", "Lord''s", "most", "holy", "law", "dowalk,"]}, {"text": "and do not stray.", "syllables": ["and", "do", "not", "stray-", "-", "."]}]}, {"index": 1, "lines": [{"text": "Blessed are they who to observe", "syllables": ["blessed", "are", "they", "who", "to", "ob-", "ser-", "ve"], "bibleVerseRef": 2}, {"text": "his statutes are inclin''d;", "syllables": ["his", "statu-", "tes", "are", "in-", "clin''d;"]}, {"text": "And who do seek the living God"}, {"text": "with their whole heart and mind."}]}, {"index": 2, "lines": [{"text": "Such in his ways do walk,", "syllables": ["Su-", "ch", "in", "his", "ways", "do", "wa-", "lk,"], "bibleVerseRef": 3}, {"text": "and they do no iniquity.", "syllables": ["and", "they", "do", "no", "iniqui-", "ty."]}, {"text": "Thou hast commanded us to keep", "bibleVerseRef": 4}, {"text": "thy precepts carefully."}]}, {"index": 3, "lines": [{"text": "O that thy statutes to observe", "syllables": ["O", "that", "thy", "statutes", "to", "ob-", "ser-", "ve"], "bibleVerseRef": 5}, {"text": "thou would''st my ways direct!", "syllables": ["thou", "wou-", "ld''st", "my", "ways", "direct!"]}, {"text": "Then shall I not be sham''d, when I", "bibleVerseRef": 6}, {"text": "thy precepts all respect."}]}, {"index": 4, "lines": [{"text": "Then with integrity of heart", "bibleVerseRef": 7}, {"text": "thee will I praise and bless,"}, {"text": "When I the judgments all have learn''d"}, {"text": "of thy pure righteousness."}]}, {"index": 5, "lines": [{"text": "That I will keep thy statutes all", "syllables": ["That", "I", "will", "keep", "thy", "statu-", "tes", "all"], "bibleVerseRef": 8}, {"text": "firmly resolv''d have I:"}, {"text": "O do not then, most gracious God,"}, {"text": "forsake me utterly."}]}]', 'CM', 'Part 1', 'Blessed are they that undefil''d...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (97, 'reca18RUoigTnmW7B', 42, '42', '1Like as the hart for water-brooks
in thirst doth pant and bray;
So pants my longing soul, O God,
that come to thee I may.

2My soul for God, the living God,
doth thirst: when shall I near
Unto thy countenance approach,
and in God''s sight appear?

3My tears have unto me been meat,
both in the night and day,
While unto me continually,
Where is thy God? they say.

4My soul is poured out in me,
when this I think upon;
Because that with the multitude
I heretofore had gone:

With them into God''s house I went,
with voice of joy and praise;
Yea, with the multitude that kept
the solemn holy days.

5O why art thou cast down, my soul?
why in me so dismay''d?
Trust God, for I shall praise him yet,
his count''nance is mine aid.

6My God, my soul''s cast down in me;
thee therefore mind I will
From Jordan''s land, the Hermonites,
and ev''n from Mizar hill.

7At the noise of thy water-spouts
deep unto deep doth call;
Thy breaking waves pass over me,
yea, and thy billows all.

8His loving-kindness yet the Lord
command will in the day,
His song''s with me by night; to God,
by whom I live, I''ll pray:

9And I will say to God my rock,
Why me forgett''st thou so?
Why, for my foes'' oppression,
thus mourning do I go?

10''Tis as a sword within my bones,
when my foes me upbraid;
Ev''n when by them, Where is thy God?
''tis daily to me said.

11O why art thou cast down, my soul?
why, thus with grief opprest,
Art thou disquieted in me?
in God still hope and rest:

For yet I know I shall him praise,
who graciously to me
The health is of my countenance,
yea, mine own God is he.', '[{"index": 0, "lines": [{"text": "Like as the hart for water-brooks", "syllables": ["Like", "as", "the", "hart", "for", "water-", "-broo-", "ks"], "bibleVerseRef": 1}, {"text": "in thirst doth pant and bray;"}, {"text": "So pants my longing soul, O God,"}, {"text": "that come to thee I may."}]}, {"index": 1, "lines": [{"text": "My soul for God, the living God,", "bibleVerseRef": 2}, {"text": "doth thirst: when shall I near"}, {"text": "Unto thy countenance approach,", "syllables": ["unto", "thy", "counte-", "nan-", "ce", "ap-", "pro-", "ach,"]}, {"text": "and in God''s sight appear?"}]}, {"index": 2, "lines": [{"text": "My tears have unto me been meat,", "bibleVerseRef": 3}, {"text": "both in the night and day,"}, {"text": "While unto me continually,", "syllables": ["While", "unto", "me", "con-", "ti-", "nu-", "a-", "lly,"]}, {"text": "Where is thy God? they say."}]}, {"index": 3, "lines": [{"text": "My soul is poured out in me,", "bibleVerseRef": 4}, {"text": "when this I think upon;"}, {"text": "Because that with the multitude"}, {"text": "I heretofore had gone:", "syllables": ["I", "here-", "to-", "fore", "had", "gone:"]}]}, {"index": 4, "lines": [{"text": "With them into God''s house I went,"}, {"text": "with voice of joy and praise;"}, {"text": "Yea, with the multitude that kept"}, {"text": "the solemn holy days.", "syllables": ["the", "sole-", "mn", "ho-", "ly", "days."]}]}, {"index": 5, "lines": [{"text": "O why art thou cast down, my soul?", "bibleVerseRef": 5}, {"text": "why in me so dismay''d?"}, {"text": "Trust God, for I shall praise him yet,"}, {"text": "his count''nance is mine aid.", "syllables": ["his", "count''nan-", "ce", "is", "mine", "aid."]}]}, {"index": 6, "lines": [{"text": "My God, my soul''s cast down in me;", "bibleVerseRef": 6}, {"text": "thee therefore mind I will"}, {"text": "From Jordan''s land, the Hermonites,"}, {"text": "and ev''n from Mizar hill."}]}, {"index": 7, "lines": [{"text": "At the noise of thy water-spouts", "syllables": ["At", "the", "noise", "of", "thy", "water-", "-spou-", "ts"], "bibleVerseRef": 7}, {"text": "deep unto deep doth call;"}, {"text": "Thy breaking waves pass over me,", "syllables": ["Thy", "brea-", "-", "king", "waves", "pass", "over", "me,"]}, {"text": "yea, and thy billows all."}]}, {"index": 8, "lines": [{"text": "His loving-kindness yet the Lord", "bibleVerseRef": 8}, {"text": "command will in the day,"}, {"text": "His song''s with me by night; to God,"}, {"text": "by whom I live, I''ll pray:"}]}, {"index": 9, "lines": [{"text": "And I will say to God my rock,", "bibleVerseRef": 9}, {"text": "Why me forgett''st thou so?"}, {"text": "Why, for my foes'' oppression,", "syllables": ["Why,", "for", "my", "foe-", "s''", "op-", "pres-", "sion,"]}, {"text": "thus mourning do I go?"}]}, {"index": 10, "lines": [{"text": "''Tis as a sword within my bones,", "bibleVerseRef": 10}, {"text": "when my foes me upbraid;"}, {"text": "Ev''n when by them, Where is thy God?"}, {"text": "''tis daily to me said."}]}, {"index": 11, "lines": [{"text": "O why art thou cast down, my soul?", "bibleVerseRef": 11}, {"text": "why, thus with grief opprest,"}, {"text": "Art thou disquieted in me?", "syllables": ["Art", "thou", "disqu-", "i-", "e-", "ted", "in", "me?"]}, {"text": "in God still hope and rest:"}]}, {"index": 12, "lines": [{"text": "For yet I know I shall him praise,"}, {"text": "who graciously to me"}, {"text": "The health is of my countenance,", "syllables": ["The", "health", "is", "of", "my", "counte-", "nan-", "ce,"]}, {"text": "yea, mine own God is he."}]}]', 'CM', NULL, 'Like as the hart for water-brooks...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (103, 'recbpBQUyKOscdcGN', 114, '114', '1When Isr''el out of Egypt went,
and did his dwelling change,
When Jacob''s house went out from those
that were of language strange,

2He Judah did his sanctuary,
his kingdom Isr''el make:
3The sea it saw, and quickly fled,
Jordan was driven back.

4Like rams the mountains, and like lambs
the hills skipp''d to and fro.
5O sea, why fledd''st thou? Jordan, back
why wast thou driven so?

6Ye mountains great, wherefore was it
that ye did skip like rams?
And wherefore was it, little hills,
that ye did leap like lambs?

7O at the presence of the Lord,
earth, tremble thou for fear,
While as the presence of the God
of Jacob doth appear:

8Who from the hard and stony rock
did standing water bring;
And by his pow''r did turn the flint
into a water-spring.', '[{"index": 0, "lines": [{"text": "When Isr''el out of Egypt went,", "bibleVerseRef": 1}, {"text": "and did his dwelling change,", "syllables": ["and", "did", "his", "dwelling", "chan-", "ge,"]}, {"text": "When Jacob''s house went out from those"}, {"text": "that were of language strange,", "syllables": ["that", "were", "of", "language", "stran-", "ge,"]}]}, {"index": 1, "lines": [{"text": "He Judah did his sanctuary,", "syllables": ["He", "judah", "did", "his", "san-", "ctu-", "a-", "ry,"], "bibleVerseRef": 2}, {"text": "his kingdom Isr''el make:"}, {"text": "The sea it saw, and quickly fled,", "syllables": ["The", "sea", "it", "saw,", "and", "qui-", "ckly", "fled,"], "bibleVerseRef": 3}, {"text": "Jordan was driven back."}]}, {"index": 2, "lines": [{"text": "Like rams the mountains, and like lambs", "bibleVerseRef": 4}, {"text": "the hills skipp''d to and fro."}, {"text": "O sea, why fledd''st thou? Jordan, back", "bibleVerseRef": 5}, {"text": "why wast thou driven so?"}]}, {"index": 3, "lines": [{"text": "Ye mountains great, wherefore was it", "bibleVerseRef": 6}, {"text": "that ye did skip like rams?"}, {"text": "And wherefore was it, little hills,"}, {"text": "that ye did leap like lambs?"}]}, {"index": 4, "lines": [{"text": "O at the presence of the Lord,", "bibleVerseRef": 7}, {"text": "earth, tremble thou for fear,", "syllables": ["earth,", "tre-", "mble", "thou", "for", "fear,"]}, {"text": "While as the presence of the God"}, {"text": "of Jacob doth appear:"}]}, {"index": 5, "lines": [{"text": "Who from the hard and stony rock", "bibleVerseRef": 8}, {"text": "did standing water bring;", "syllables": ["did", "stan-", "ding", "water", "bri-", "ng;"]}, {"text": "And by his pow''r did turn the flint"}, {"text": "into a water-spring.", "syllables": ["in-", "to", "a", "water-", "-spri-", "ng."]}]}]', 'CM', NULL, 'When Isr''el out of Egypt went...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (121, 'recgjWGFvLuATezM8', 119, '119:33-40 (5)', '33Teach me, O Lord, the perfect way
of thy precepts divine,
And to observe it to the end
I shall my heart incline.

34Give understanding unto me,
so keep thy law shall I;
Yea, ev''n with my whole heart I shall
observe it carefully.

35In thy law''s path make me to go;
for I delight therein.
36My heart unto thy testimonies,
and not to greed, incline.

37Turn thou away my sight and eyes
from viewing vanity;
And in thy good and holy way
be pleas''d to quicken me.

38Confirm to me thy gracious word,
which I did gladly hear,
Ev''n to thy servant, Lord, who is
devoted to thy fear.

39Turn thou away my fear''d reproach;
for good thy judgments be.
40Lo, for thy precepts I have long''d;
in thy truth quicken me.
', '[{"index": 0, "lines": [{"text": "Teach me, O Lord, the perfect way", "bibleVerseRef": 33}, {"text": "of thy precepts divine,"}, {"text": "And to observe it to the end", "syllables": ["And", "to", "obser-", "ve", "it", "to", "the", "end"]}, {"text": "I shall my heart incline.", "syllables": ["I", "shall", "my", "heart", "incli-", "ne."]}]}, {"index": 1, "lines": [{"text": "Give understanding unto me,", "bibleVerseRef": 34}, {"text": "so keep thy law shall I;"}, {"text": "Yea, ev''n with my whole heart I shall"}, {"text": "observe it carefully.", "syllables": ["obser-", "ve", "it", "care-", "ful-", "ly."]}]}, {"index": 2, "lines": [{"text": "In thy law''s path make me to go;", "bibleVerseRef": 35}, {"text": "for I delight therein.", "syllables": ["for", "I", "de-", "light", "therei-", "n."]}, {"text": "My heart unto thy testimonies,", "syllables": ["My", "heart", "unto", "thy", "tes-", "ti-", "mo-", "nies,"], "bibleVerseRef": 36}, {"text": "and not to greed, incline.", "syllables": ["and", "not", "to", "greed,", "incli-", "ne."]}]}, {"index": 3, "lines": [{"text": "Turn thou away my sight and eyes", "bibleVerseRef": 37}, {"text": "from viewing vanity;"}, {"text": "And in thy good and holy way"}, {"text": "be pleas''d to quicken me.", "syllables": ["be", "pleas''d", "to", "qui-", "cken", "me."]}]}, {"index": 4, "lines": [{"text": "Confirm to me thy gracious word,", "bibleVerseRef": 38}, {"text": "which I did gladly hear,"}, {"text": "Ev''n to thy servant, Lord, who is"}, {"text": "devoted to thy fear."}]}, {"index": 5, "lines": [{"text": "Turn thou away my fear''d reproach;", "syllables": ["Turn", "thou", "away", "my", "fear''d", "rep-", "ro-", "ach;"], "bibleVerseRef": 39}, {"text": "for good thy judgments be."}, {"text": "Lo, for thy precepts I have long''d;", "bibleVerseRef": 40}, {"text": "in thy truth quicken me.", "syllables": ["in", "thy", "truth", "qui-", "cken", "me."]}]}]', 'CM', 'Part 5', 'Teach me, O Lord, the perfect way...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (133, 'reck0HyBsxnf4OJeX', 19, '19', '1The heav''ns God''s glory do declare,
the skies his hand-works preach:
2Day utters speech to day, and night
to night doth knowledge teach.

3There is no speech nor tongue to which
their voice doth not extend:
4Their line is gone through all the earth,
their words to the world''s end.

In them he set the sun a tent;
5Who, bridegroom-like, forth goes
From''s chamber, as a strong man doth
to run his race rejoice.

6From heav''n''s end is his going forth,
circling to th'' end again;
And there is nothing from his heat
that hidden doth remain.

7God''s law is perfect, and converts
the soul in sin that lies:
God''s testimony is most sure,
and makes the simple wise.

8The statutes of the Lord are right,
and do rejoice the heart:
The Lord''s command is pure, and doth
light to the eyes impart.

9Unspotted is the fear of God,
and doth endure for ever:
The judgments of the Lord are true
and righteous altogether.

10They more than gold, yea, much fine gold,
to be desired are:
Than honey, honey from the comb
that droppeth, sweeter far.

11Moreover, they thy servant warn
how he his life should frame:
A great reward provided is
for them that keep the same.

12Who can his errors understand?
O cleanse thou me within
13From secret faults. Thy servant keep
from all presumptuous sin:

And do not suffer them to have
dominion over me:
Then, righteous and innocent,
I from much sin shall be.

14The words which from my mouth proceed,
the thoughts sent from my heart,
Accept, O Lord, for thou my strength
and my Redeemer art.', '[{"index": 0, "lines": [{"text": "The heav''ns God''s glory do declare,", "bibleVerseRef": 1}, {"text": "the skies his hand-works preach:"}, {"text": "Day utters speech to day, and night", "bibleVerseRef": 2}, {"text": "to night doth knowledge teach.", "syllables": ["to", "night", "doth", "knowled-", "ge", "teach."]}]}, {"index": 1, "lines": [{"text": "There is no speech nor tongue to which", "syllables": ["There", "is", "no", "speech", "nor", "tongue", "to", "which"], "bibleVerseRef": 3}, {"text": "their voice doth not extend:"}, {"text": "Their line is gone through all the earth,", "bibleVerseRef": 4}, {"text": "their words to the world''s end."}]}, {"index": 2, "lines": [{"text": "In them he set the sun a tent;"}, {"text": "Who, bridegroom-like, forth goes", "syllables": ["Who,", "bridegroom-", "-li-", "ke,", "forth", "goes"], "bibleVerseRef": 5}, {"text": "From''s chamber, as a strong man doth"}, {"text": "to run his race rejoice."}]}, {"index": 3, "lines": [{"text": "From heav''n''s end is his going forth,", "syllables": ["From", "hea-", "v''n''s", "end", "is", "his", "going", "forth,"], "bibleVerseRef": 6}, {"text": "circling to th'' end again;", "syllables": ["circling", "to", "th''", "end", "a-", "gain;"]}, {"text": "And there is nothing from his heat"}, {"text": "that hidden doth remain."}]}, {"index": 4, "lines": [{"text": "God''s law is perfect, and converts", "bibleVerseRef": 7}, {"text": "the soul in sin that lies:"}, {"text": "God''s testimony is most sure,"}, {"text": "and makes the simple wise."}]}, {"index": 5, "lines": [{"text": "The statutes of the Lord are right,", "syllables": ["The", "statu-", "tes", "of", "the", "Lord", "are", "right,"], "bibleVerseRef": 8}, {"text": "and do rejoice the heart:"}, {"text": "The Lord''s command is pure, and doth"}, {"text": "light to the eyes impart."}]}, {"index": 6, "lines": [{"text": "Unspotted is the fear of God,", "bibleVerseRef": 9}, {"text": "and doth endure for ever:"}, {"text": "The judgments of the Lord are true"}, {"text": "and righteous altogether.", "syllables": ["and", "righteous", "al-", "to-", "ge-", "ther."]}]}, {"index": 7, "lines": [{"text": "They more than gold, yea, much fine gold,", "bibleVerseRef": 10}, {"text": "to be desired are:"}, {"text": "Than honey, honey from the comb", "syllables": ["Than", "honey-", "-", ",", "honey", "from", "the", "comb"]}, {"text": "that droppeth, sweeter far."}]}, {"index": 8, "lines": [{"text": "Moreover, they thy servant warn", "bibleVerseRef": 11}, {"text": "how he his life should frame:", "syllables": ["how", "he", "his", "life", "should", "frame:"]}, {"text": "A great reward provided is"}, {"text": "for them that keep the same."}]}, {"index": 9, "lines": [{"text": "Who can his errors understand?", "bibleVerseRef": 12}, {"text": "O cleanse thou me within", "syllables": ["O", "cleanse", "thou", "me", "wi-", "thin"]}, {"text": "From secret faults. Thy servant keep", "bibleVerseRef": 13}, {"text": "from all presumptuous sin:"}]}, {"index": 10, "lines": [{"text": "And do not suffer them to have"}, {"text": "dominion over me:", "syllables": ["do-", "mi-", "nio-", "n", "over", "me:"]}, {"text": "Then, righteous and innocent,", "syllables": ["The-", "n,", "righ-", "teous", "and", "in-", "no-", "cent,"]}, {"text": "I from much sin shall be."}]}, {"index": 11, "lines": [{"text": "The words which from my mouth proceed,", "bibleVerseRef": 14}, {"text": "the thoughts sent from my heart,"}, {"text": "Accept, O Lord, for thou my strength"}, {"text": "and my Redeemer art.", "syllables": ["and", "my", "re-", "deeme-", "r", "art."]}]}]', 'CM', NULL, 'The heav''ns God''s glory do declare...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (136, 'reclBirnnTc9qYRPX', 36, '36', '1The wicked man''s transgression
within my heart thus says,
Undoubtedly the fear of God
is not before his eyes.

2Because himself he flattereth
in his own blinded eye,
Until the hatefulness be found
of his iniquity.

3Words from his mouth proceeding are,
fraud and iniquity:
He to be wise, and to do good,
hath left off utterly.

4He mischief, lying on his bed,
most cunningly doth plot:
He sets himself in ways not good,
ill he abhorreth not.

5Thy mercy, Lord, is in the heav''ns;
thy truth doth reach the clouds:
6Thy justice is like mountains great;
thy judgments deep as floods:

Lord, thou preservest man and beast.
7How precious is thy grace!
Therefore in shadow of thy wings
men''s sons their trust shall place.

8They with the fatness of thy house
shall be well satisfy''d;
From rivers of thy pleasures thou
wilt drink to them provide.

9Because of life the fountain pure
remains alone with thee;
And in that purest light of thine
we clearly light shall see.

10Thy loving-kindness unto them
continue that thee know;
And still on men upright in heart
thy righteousness bestow.

11Let not the foot of cruel pride
come, and against me stand;
And let me not removed be,
Lord, by the wicked''s hand.

12There fallen are they, and ruined,
that work iniquities:
Cast down they are, and never shall
be able to arise.', '[{"index": 0, "lines": [{"text": "The wicked man''s transgression", "syllables": ["The", "wic-", "ked", "man''s", "tran-", "sgre-", "s-", "sion"], "bibleVerseRef": 1}, {"text": "within my heart thus says,"}, {"text": "Undoubtedly the fear of God"}, {"text": "is not before his eyes."}]}, {"index": 1, "lines": [{"text": "Because himself he flattereth", "bibleVerseRef": 2}, {"text": "in his own blinded eye,"}, {"text": "Until the hatefulness be found"}, {"text": "of his iniquity."}]}, {"index": 2, "lines": [{"text": "Words from his mouth proceeding are,", "bibleVerseRef": 3}, {"text": "fraud and iniquity:"}, {"text": "He to be wise, and to do good,"}, {"text": "hath left off utterly."}]}, {"index": 3, "lines": [{"text": "He mischief, lying on his bed,", "syllables": ["He", "mis-", "chie-", "f,", "lying", "on", "his", "bed,"], "bibleVerseRef": 4}, {"text": "most cunningly doth plot:"}, {"text": "He sets himself in ways not good,"}, {"text": "ill he abhorreth not."}]}, {"index": 4, "lines": [{"text": "Thy mercy, Lord, is in the heav''ns;", "bibleVerseRef": 5}, {"text": "thy truth doth reach the clouds:"}, {"text": "Thy justice is like mountains great;", "bibleVerseRef": 6}, {"text": "thy judgments deep as floods:"}]}, {"index": 5, "lines": [{"text": "Lord, thou preservest man and beast."}, {"text": "How precious is thy grace!", "syllables": ["How", "precious", "is", "thy", "gra-", "ce!"], "bibleVerseRef": 7}, {"text": "Therefore in shadow of thy wings"}, {"text": "men''s sons their trust shall place.", "syllables": ["men''s", "sons", "their", "trust", "shall", "place."]}]}, {"index": 6, "lines": [{"text": "They with the fatness of thy house", "bibleVerseRef": 8}, {"text": "shall be well satisfy''d;"}, {"text": "From rivers of thy pleasures thou", "syllables": ["From", "rive-", "rs", "of", "thy", "plea-", "sures", "thou"]}, {"text": "wilt drink to them provide."}]}, {"index": 7, "lines": [{"text": "Because of life the fountain pure", "bibleVerseRef": 9}, {"text": "remains alone with thee;"}, {"text": "And in that purest light of thine", "syllables": ["And", "in", "that", "pure-", "st", "light", "of", "thine"]}, {"text": "we clearly light shall see."}]}, {"index": 8, "lines": [{"text": "Thy loving-kindness unto them", "bibleVerseRef": 10}, {"text": "continue that thee know;"}, {"text": "And still on men upright in heart"}, {"text": "thy righteousness bestow."}]}, {"index": 9, "lines": [{"text": "Let not the foot of cruel pride", "bibleVerseRef": 11}, {"text": "come, and against me stand;"}, {"text": "And let me not removed be,"}, {"text": "Lord, by the wicked''s hand."}]}, {"index": 10, "lines": [{"text": "There fallen are they, and ruined,", "syllables": ["There", "fallen", "are", "they,", "and", "ru-", "i-", "ned,"], "bibleVerseRef": 12}, {"text": "that work iniquities:"}, {"text": "Cast down they are, and never shall"}, {"text": "be able to arise."}]}]', 'CM', NULL, 'The wicked man''s transgression...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (168, 'recuqa8SHc7GN47hT', 119, '119:113-120 (15)', '113I hate the thoughts of vanity,
but love thy law do I.
114My shield and hiding-place thou art:
I on thy word rely.

115All ye that evil-doers are
from me depart away;
For the commandments of my God
I purpose to obey.

116According to thy faithful word
uphold and stablish me,
That I may live, and of my hope
ashamed never be.

117Hold thou me up, so shall I be
in peace and safety still;
And to thy statutes have respect
continually I will.

118Thou tread''st down all that love to stray;
false their deceit doth prove.
119Lewd men, like dross, away thou putt''st;
therefore thy law I love.

120For fear of thee my very flesh
doth tremble, all dismay''d;
And of thy righteous judgments, Lord,
my soul is much afraid.
', '[{"index": 0, "lines": [{"text": "I hate the thoughts of vanity,", "bibleVerseRef": 113}, {"text": "but love thy law do I."}, {"text": "My shield and hiding-place thou art:", "syllables": ["My", "shield", "and", "hidin-", "g-pla-", "ce", "thou", "art:"], "bibleVerseRef": 114}, {"text": "I on thy word rely."}]}, {"index": 1, "lines": [{"text": "All ye that evil-doers are", "syllables": ["All", "ye", "that", "e-", "vil-", "-doe-", "rs", "are"], "bibleVerseRef": 115}, {"text": "from me depart away;"}, {"text": "For the commandments of my God"}, {"text": "I purpose to obey.", "syllables": ["I", "pur-", "pose", "to", "obey-", "."]}]}, {"index": 2, "lines": [{"text": "According to thy faithful word", "bibleVerseRef": 116}, {"text": "uphold and stablish me,"}, {"text": "That I may live, and of my hope"}, {"text": "ashamed never be."}]}, {"index": 3, "lines": [{"text": "Hold thou me up, so shall I be", "bibleVerseRef": 117}, {"text": "in peace and safety still;"}, {"text": "And to thy statutes have respect", "syllables": ["And", "to", "thy", "statu-", "tes", "have", "res-", "pect"]}, {"text": "continually I will.", "syllables": ["conti-", "nu-", "a-", "lly", "I", "will."]}]}, {"index": 4, "lines": [{"text": "Thou tread''st down all that love to stray;", "bibleVerseRef": 118}, {"text": "false their deceit doth prove.", "syllables": ["false", "their", "deceit", "doth", "pro-", "ve."]}, {"text": "Lewd men, like dross, away thou putt''st;", "bibleVerseRef": 119}, {"text": "therefore thy law I love."}]}, {"index": 5, "lines": [{"text": "For fear of thee my very flesh", "bibleVerseRef": 120}, {"text": "doth tremble, all dismay''d;", "syllables": ["doth", "tremble-", ",", "all", "dis-", "may''d;"]}, {"text": "And of thy righteous judgments, Lord,"}, {"text": "my soul is much afraid."}]}]', 'CM', 'Part 15', 'I hate the thoughts of vanity...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (182, 'recyFI1rtjIbmRqrY', 54, '54', '1Save me, O God, by thy great name,
and judge me by thy strength:
2My prayer hear, O God; give ear
unto my words at length.

3For they that strangers are to me
do up against me rise;
Oppressors seek my soul, and God
set not before their eyes.

4The Lord my God my helper is,
lo, therefore I am bold:
He taketh part with ev''ry one
that doth my soul uphold.

5Unto mine enemies he shall
mischief and ill repay:
O for thy truth''s sake cut them off,
and sweep them clean away.

6I will a sacrifice to thee
give with free willingness;
Thy name, O Lord, because ''tis good,
with praise I will confess.

7For he hath me delivered
from all adversities;
And his desire mine eye hath seen
upon mine enemies.', '[{"index": 0, "lines": [{"text": "Save me, O God, by thy great name,", "bibleVerseRef": 1}, {"text": "and judge me by thy strength:", "syllables": ["and", "judge", "me", "by", "thy", "strength:"]}, {"text": "My prayer hear, O God; give ear", "bibleVerseRef": 2}, {"text": "unto my words at length."}]}, {"index": 1, "lines": [{"text": "For they that strangers are to me", "bibleVerseRef": 3}, {"text": "do up against me rise;"}, {"text": "Oppressors seek my soul, and God"}, {"text": "set not before their eyes."}]}, {"index": 2, "lines": [{"text": "The Lord my God my helper is,", "bibleVerseRef": 4}, {"text": "lo, therefore I am bold:"}, {"text": "He taketh part with ev''ry one"}, {"text": "that doth my soul uphold."}]}, {"index": 3, "lines": [{"text": "Unto mine enemies he shall", "bibleVerseRef": 5}, {"text": "mischief and ill repay:"}, {"text": "O for thy truth''s sake cut them off,"}, {"text": "and sweep them clean away."}]}, {"index": 4, "lines": [{"text": "I will a sacrifice to thee", "bibleVerseRef": 6}, {"text": "give with free willingness;"}, {"text": "Thy name, O Lord, because ''tis good,"}, {"text": "with praise I will confess."}]}, {"index": 5, "lines": [{"text": "For he hath me delivered", "bibleVerseRef": 7}, {"text": "from all adversities;"}, {"text": "And his desire mine eye hath seen"}, {"text": "upon mine enemies."}]}]', 'CM', NULL, 'Save me, O God, by thy great name...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (46, 'recEbQ7iPzhvU60Gg', 83, '83', '1Keep not, O God, we thee entreat,
O keep not silence now:
Do thou not hold thy peace, O God,
and still no more be thou.

2For, lo, thine enemies a noise
tumultuously have made;
And they that haters are of thee
have lifted up the head.

3Against thy chosen people they
do crafty counsel take;
And they against thy hidden ones
do consultations make.

4Come, let us cut them off, said they,
from being a nation,
That of the name of Isr''el may
no more be mention.

5For with joint heart they plot, in league
against thee they combine.
6The tents of Edom, Ishm''elites,
Moab''s and Hagar''s line;

7Gebal, and Ammon, Amalek,
Philistines, those of Tyre;
8And Assur join''d with them, to help
Lot''s children they conspire.

9Do to them as to Midian,
Jabin at Kison strand;
10And Sis''ra, which at En-dor fell,
as dung to fat the land.

11Like Oreb and like Zeeb make
their noble men to fall;
Like Zeba and Zalmunna like,
make thou their princes all;

12Who said, For our possession
let us God''s houses take.
13My God, them like a wheel, as chaff
before the wind, them make.

14As fire consumes the wood, as flame
doth mountains set on fire,
15Chase and affright them with the storm
and tempest of thine ire.

16Their faces fill with shame, O Lord,
that they may seek thy name.
17Let them confounded be, and vex''d,
and perish in their shame:

18That men may know that thou, to whom
alone doth appertain
The name JEHOVAH, dost most high
o''er all the earth remain.', '[{"index": 0, "lines": [{"text": "Keep not, O God, we thee entreat,", "bibleVerseRef": 1}, {"text": "O keep not silence now:"}, {"text": "Do thou not hold thy peace, O God,"}, {"text": "and still no more be thou."}]}, {"index": 1, "lines": [{"text": "For, lo, thine enemies a noise", "bibleVerseRef": 2}, {"text": "tumultuously have made;"}, {"text": "And they that haters are of thee", "syllables": ["And", "they", "that", "hate-", "rs", "are", "of", "thee"]}, {"text": "have lifted up the head."}]}, {"index": 2, "lines": [{"text": "Against thy chosen people they", "bibleVerseRef": 3}, {"text": "do crafty counsel take;"}, {"text": "And they against thy hidden ones"}, {"text": "do consultations make."}]}, {"index": 3, "lines": [{"text": "Come, let us cut them off, said they,", "bibleVerseRef": 4}, {"text": "from being a nation,", "syllables": ["from", "bei-", "ng", "a", "na-", "tion,"]}, {"text": "That of the name of Isr''el may"}, {"text": "no more be mention.", "syllables": ["no", "more", "be", "men-", "tio-", "n."]}]}, {"index": 4, "lines": [{"text": "For with joint heart they plot, in league", "syllables": ["For", "with", "joint", "heart", "they", "plot,", "in", "league"], "bibleVerseRef": 5}, {"text": "against thee they combine."}, {"text": "The tents of Edom, Ishm''elites,", "bibleVerseRef": 6}, {"text": "Moab''s and Hagar''s line;"}]}, {"index": 5, "lines": [{"text": "Gebal, and Ammon, Amalek,", "syllables": ["ge-", "bal,", "and", "am-", "mon,", "a-", "male-", "k,"], "bibleVerseRef": 7}, {"text": "Philistines, those of Tyre;"}, {"text": "And Assur join''d with them, to help", "bibleVerseRef": 8}, {"text": "Lot''s children they conspire.", "syllables": ["Lot''s", "children", "they", "con-", "spi-", "re."]}]}, {"index": 6, "lines": [{"text": "Do to them as to Midian,", "bibleVerseRef": 9}, {"text": "Jabin at Kison strand;"}, {"text": "And Sis''ra, which at En-dor fell,", "bibleVerseRef": 10}, {"text": "as dung to fat the land."}]}, {"index": 7, "lines": [{"text": "Like Oreb and like Zeeb make", "syllables": ["Li-", "ke", "Ore-", "b", "and", "like", "Zeeb", "make"], "bibleVerseRef": 11}, {"text": "their noble men to fall;"}, {"text": "Like Zeba and Zalmunna like,"}, {"text": "make thou their princes all;"}]}, {"index": 8, "lines": [{"text": "Who said, For our possession", "syllables": ["Who", "sai-", "d,", "For", "our", "pos-", "ses-", "sion"], "bibleVerseRef": 12}, {"text": "let us God''s houses take.", "syllables": ["let", "us", "God''s", "house-", "s", "take."]}, {"text": "My God, them like a wheel, as chaff", "bibleVerseRef": 13}, {"text": "before the wind, them make."}]}, {"index": 9, "lines": [{"text": "As fire consumes the wood, as flame", "syllables": ["As", "fire", "consumes", "the", "wood,", "as", "fla-", "me"], "bibleVerseRef": 14}, {"text": "doth mountains set on fire,"}, {"text": "Chase and affright them with the storm", "bibleVerseRef": 15}, {"text": "and tempest of thine ire."}]}, {"index": 10, "lines": [{"text": "Their faces fill with shame, O Lord,", "syllables": ["Their", "faces", "fill", "with", "shame-", ",", "O", "Lord,"], "bibleVerseRef": 16}, {"text": "that they may seek thy name."}, {"text": "Let them confounded be, and vex''d,", "bibleVerseRef": 17}, {"text": "and perish in their shame:"}]}, {"index": 11, "lines": [{"text": "That men may know that thou, to whom", "bibleVerseRef": 18}, {"text": "alone doth appertain"}, {"text": "The name JEHOVAH, dost most high"}, {"text": "o''er all the earth remain."}]}]', 'CM', NULL, 'Keep not, O God, we thee entreat...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (51, 'recGFYcmEOSMZ6kXB', 82, '82', '1In gods'' assembly God doth stand;
he judgeth gods among.
2How long, accepting persons vile,
will ye give judgment wrong?

3Defend the poor and fatherless;
to poor oppress''d do right.
4The poor and needy ones set free;
rid them from ill men''s might.

5They know not, nor will understand;
in darkness they walk on:
All the foundations of the earth
out of their course are gone.

6I said that ye are gods, and are
sons of the Highest all:
7But ye shall die like men, and as
one of the princes fall.

8O God, do thou raise up thyself,
the earth to judgment call:
For thou, as thine inheritance,
shalt take the nations all.', '[{"index": 0, "lines": [{"text": "In gods'' assembly God doth stand;", "bibleVerseRef": 1}, {"text": "he judgeth gods among."}, {"text": "How long, accepting persons vile,", "bibleVerseRef": 2}, {"text": "will ye give judgment wrong?"}]}, {"index": 1, "lines": [{"text": "Defend the poor and fatherless;", "bibleVerseRef": 3}, {"text": "to poor oppress''d do right."}, {"text": "The poor and needy ones set free;", "bibleVerseRef": 4}, {"text": "rid them from ill men''s might."}]}, {"index": 2, "lines": [{"text": "They know not, nor will understand;", "bibleVerseRef": 5}, {"text": "in darkness they walk on:"}, {"text": "All the foundations of the earth"}, {"text": "out of their course are gone.", "syllables": ["out", "of", "their", "course", "are", "gone."]}]}, {"index": 3, "lines": [{"text": "I said that ye are gods, and are", "bibleVerseRef": 6}, {"text": "sons of the Highest all:"}, {"text": "But ye shall die like men, and as", "bibleVerseRef": 7}, {"text": "one of the princes fall."}]}, {"index": 4, "lines": [{"text": "O God, do thou raise up thyself,", "syllables": ["O", "God,", "do", "thou", "raise", "up", "thyse-", "lf,"], "bibleVerseRef": 8}, {"text": "the earth to judgment call:"}, {"text": "For thou, as thine inheritance,", "syllables": ["For", "thou,", "as", "thine", "inhe-", "ri-", "tan-", "ce,"]}, {"text": "shalt take the nations all."}]}]', 'CM', NULL, 'In gods'' assembly God doth stand...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (71, 'recQMRELhMnQdt84P', 135, '135', '1Praise ye the Lord, the Lord''s name praise;
his servants, praise ye God.
2Who stand in God''s house, in the courts
of our God make abode.

3Praise ye the Lord, for he is good;
unto him praises sing:
Sing praises to his name, because
it is a pleasant thing.

4For Jacob to himself the Lord
did chuse of his good pleasure,
And he hath chosen Israel
for his peculiar treasure.

5Because I know assuredly
the Lord is very great,
And that our Lord above all gods
in glory hath his seat.

6What things soever pleas''d the Lord,
that in the heav''n did he,
And in the earth, the seas,
and all the places deep that be.

7He from the ends of earth doth make
the vapours to ascend;
With rain he lightnings makes, and wind
doth from his treasures send.

8Egypt''s first-born, from man to beast
9who smote. Strange tokens he
On Phar''oh and his servants sent,
Egypt, in midst of thee.

10He smote great nations, slew great kings:
11Sihon of Heshbon king,
And Og of Bashan, and to nought
did Canaan''s kingdoms bring:

12And for a wealthy heritage
their pleasant land he gave,
An heritage which Israel,
his chosen folk, should have.

13Thy name, O Lord, shall still endure,
and thy memorial
With honour shall continu''d be
to generations all.

14For why? the righteous God will judge
his people righteously;
Concerning those that do him serve,
himself repent will he.

15The idols of the nations
of silver are and gold,
And by the hands of men is made
their fashion and mould.

16Mouths have they, but they do not speak;
eyes, but they do not see;
17Ears have they, but hear not; and in
their mouths no breathing be.

18Their makers are like them; so are
all that on them rely.
19O Isr''el''s house, bless God; bless God,
O Aaron''s family.

20O bless the Lord, of Levi''s house
ye who his servants are;
And bless the holy name of God,
all ye the Lord that fear.

21And blessed be the Lord our God
from Sion''s holy hill,
Who dwelleth at Jerusalem.
The Lord O praise ye still.', '[{"index": 0, "lines": [{"text": "Praise ye the Lord, the Lord''s name praise;", "bibleVerseRef": 1}, {"text": "his servants, praise ye God."}, {"text": "Who stand in God''s house, in the courts", "bibleVerseRef": 2}, {"text": "of our God make abode."}]}, {"index": 1, "lines": [{"text": "Praise ye the Lord, for he is good;", "bibleVerseRef": 3}, {"text": "unto him praises sing:", "syllables": ["un-", "to", "him", "praise-", "s", "sing:"]}, {"text": "Sing praises to his name, because", "syllables": ["Sing", "praise-", "s", "to", "his", "name,", "be-", "cause"]}, {"text": "it is a pleasant thing."}]}, {"index": 2, "lines": [{"text": "For Jacob to himself the Lord", "bibleVerseRef": 4}, {"text": "did chuse of his good pleasure,", "syllables": ["did", "chuse", "of", "his", "good", "pleasure,"]}, {"text": "And he hath chosen Israel", "syllables": ["And", "he", "hath", "chose-", "-", "n", "is-", "rael"]}, {"text": "for his peculiar treasure.", "syllables": ["for", "his", "peculi-", "ar", "trea-", "sure."]}]}, {"index": 3, "lines": [{"text": "Because I know assuredly", "bibleVerseRef": 5}, {"text": "the Lord is very great,"}, {"text": "And that our Lord above all gods"}, {"text": "in glory hath his seat."}]}, {"index": 4, "lines": [{"text": "What things soever pleas''d the Lord,", "syllables": ["What", "thi-", "ngs", "soever", "plea-", "s''d", "the", "Lord,"], "bibleVerseRef": 6}, {"text": "that in the heav''n did he,"}, {"text": "And in the earth, the seas,", "syllables": ["And", "in", "the", "ea-", "rth,", "the", "sea-", "s,"]}, {"text": "and all the places deep that be.", "syllables": ["and", "all", "the", "places", "deep", "thatbe."]}]}, {"index": 5, "lines": [{"text": "He from the ends of earth doth make", "bibleVerseRef": 7}, {"text": "the vapours to ascend;"}, {"text": "With rain he lightnings makes, and wind"}, {"text": "doth from his treasures send."}]}, {"index": 6, "lines": [{"text": "Egypt''s first-born, from man to beast", "bibleVerseRef": 8}, {"text": "who smote. Strange tokens he", "syllables": ["who", "smote.", "stran-", "ge", "tokens", "he"], "bibleVerseRef": 9}, {"text": "On Phar''oh and his servants sent,"}, {"text": "Egypt, in midst of thee."}]}, {"index": 7, "lines": [{"text": "He smote great nations, slew great kings:", "syllables": ["He", "smote", "great", "na-", "tions,", "slew", "great", "kings:"], "bibleVerseRef": 10}, {"text": "Sihon of Heshbon king,", "bibleVerseRef": 11}, {"text": "And Og of Bashan, and to nought"}, {"text": "did Canaan''s kingdoms bring:"}]}, {"index": 8, "lines": [{"text": "And for a wealthy heritage", "bibleVerseRef": 12}, {"text": "their pleasant land he gave,"}, {"text": "An heritage which Israel,", "syllables": ["An", "he-", "ri-", "tage", "whi-", "ch", "is-", "rael,"]}, {"text": "his chosen folk, should have.", "syllables": ["his", "chose-", "n", "folk,", "should", "have."]}]}, {"index": 9, "lines": [{"text": "Thy name, O Lord, shall still endure,", "bibleVerseRef": 13}, {"text": "and thy memorial"}, {"text": "With honour shall continu''d be"}, {"text": "to generations all."}]}, {"index": 10, "lines": [{"text": "For why? the righteous God will judge", "syllables": ["For", "why?", "the", "righteous", "God", "will", "jud-", "ge"], "bibleVerseRef": 14}, {"text": "his people righteously;", "syllables": ["his", "people", "righte-", "o-", "us-", "ly;"]}, {"text": "Concerning those that do him serve,"}, {"text": "himself repent will he.", "syllables": ["him-", "self", "repe-", "nt", "will", "he."]}]}, {"index": 11, "lines": [{"text": "The idols of the nations", "syllables": ["The", "i-", "dols", "of", "the", "na-", "tio-", "ns"], "bibleVerseRef": 15}, {"text": "of silver are and gold,"}, {"text": "And by the hands of men is made"}, {"text": "their fashion and mould.", "syllables": ["their", "fa-", "shion", "and", "mou-", "ld."]}]}, {"index": 12, "lines": [{"text": "Mouths have they, but they do not speak;", "bibleVerseRef": 16}, {"text": "eyes, but they do not see;"}, {"text": "Ears have they, but hear not; and in", "bibleVerseRef": 17}, {"text": "their mouths no breathing be."}]}, {"index": 13, "lines": [{"text": "Their makers are like them; so are", "syllables": ["Their", "make-", "rs", "are", "like", "them;", "so", "are"], "bibleVerseRef": 18}, {"text": "all that on them rely."}, {"text": "O Isr''el''s house, bless God; bless God,", "bibleVerseRef": 19}, {"text": "O Aaron''s family."}]}, {"index": 14, "lines": [{"text": "O bless the Lord, of Levi''s house", "bibleVerseRef": 20}, {"text": "ye who his servants are;"}, {"text": "And bless the holy name of God,"}, {"text": "all ye the Lord that fear."}]}, {"index": 15, "lines": [{"text": "And blessed be the Lord our God", "bibleVerseRef": 21}, {"text": "from Sion''s holy hill,", "syllables": ["from", "Sio-", "n''s", "ho-", "ly", "hill,"]}, {"text": "Who dwelleth at Jerusalem.", "syllables": ["Who", "dwel-", "leth", "at", "je-", "ru-", "sale-", "m."]}, {"text": "The Lord O praise ye still."}]}]', 'CM', NULL, 'Praise ye the Lord, the Lord''s name praise...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (59, 'recK8kt9tNmfEOAIr', 145, '145 (First Version)', '1I''ll thee extol, my God, O King;
I''ll bless thy name always.
2Thee will I bless each day, and will
thy name for ever praise.

3Great is the Lord, much to be prais''d;
his greatness search exceeds.
4Race unto race shall praise thy works,
and shew thy mighty deeds.

5I of thy glorious majesty
the honour will record;
I''ll speak of all thy mighty works,
which wondrous are, O Lord.

6Men of thine acts the might shall show,
thine acts that dreadful are;
And I, thy glory to advance,
thy greatness will declare.

7The mem''ry of thy goodness great
they largely shall express;
With songs of praise they shall extol
thy perfect righteousness.

8The Lord is very gracious,
in him compassions flow;
In mercy he is very great,
and is to anger slow.

9The Lord JEHOVAH unto all
his goodness doth declare;
And over all his other works
his tender mercies are.

10Thee all thy works shall praise, O Lord,
and thee thy saints shall bless;
11They shall thy kingdom''s glory show,
thy pow''r by speech express:

12To make the sons of men to know
his acts done mightily,
And of his kingdom th'' excellent
and glorious majesty.

13Thy kingdom shall for ever stand,
thy reign through ages all.
14God raiseth all that are bow''d down,
upholdeth all that fall.

15The eyes of all things wait on thee,
the giver of all good;
And thou, in time convenient,
bestow''st on them their food:

16Thine hand thou open''st lib''rally,
and of thy bounty gives
Enough to satisfy the need
of ev''ry thing that lives.

17The Lord is just in all his ways,
holy in his works all.
18God''s near to all that call on him,
in truth that on him call.

19He will accomplish the desire
of those that do him fear:
He also will deliver them,
and he their cry will hear.

20The Lord preserves all who him love,
that nought can them annoy:
But he all those that wicked are
will utterly destroy.

21My mouth the praises of the Lord
to publish cease shall never:
Let all flesh bless his holy name
for ever and for ever.', '[{"index": 0, "lines": [{"text": "I''ll thee extol, my God, O King;", "bibleVerseRef": 1}, {"text": "I''ll bless thy name always."}, {"text": "Thee will I bless each day, and will", "bibleVerseRef": 2}, {"text": "thy name for ever praise.", "syllables": ["thy", "name", "for", "ever", "praise-", "."]}]}, {"index": 1, "lines": [{"text": "Great is the Lord, much to be prais''d;", "bibleVerseRef": 3}, {"text": "his greatness search exceeds."}, {"text": "Race unto race shall praise thy works,", "bibleVerseRef": 4}, {"text": "and shew thy mighty deeds."}]}, {"index": 2, "lines": [{"text": "I of thy glorious majesty", "bibleVerseRef": 5}, {"text": "the honour will record;"}, {"text": "I''ll speak of all thy mighty works,"}, {"text": "which wondrous are, O Lord."}]}, {"index": 3, "lines": [{"text": "Men of thine acts the might shall show,", "bibleVerseRef": 6}, {"text": "thine acts that dreadful are;"}, {"text": "And I, thy glory to advance,", "syllables": ["And", "I,", "thy", "glory", "to", "ad-", "van-", "ce,"]}, {"text": "thy greatness will declare."}]}, {"index": 4, "lines": [{"text": "The mem''ry of thy goodness great", "bibleVerseRef": 7}, {"text": "they largely shall express;", "syllables": ["they", "large-", "ly", "shall", "ex-", "press;"]}, {"text": "With songs of praise they shall extol"}, {"text": "thy perfect righteousness."}]}, {"index": 5, "lines": [{"text": "The Lord is very gracious,", "syllables": ["The", "Lord", "is", "ve-", "ry", "gra-", "ciou-", "s,"], "bibleVerseRef": 8}, {"text": "in him compassions flow;"}, {"text": "In mercy he is very great,"}, {"text": "and is to anger slow."}]}, {"index": 6, "lines": [{"text": "The Lord JEHOVAH unto all", "bibleVerseRef": 9}, {"text": "his goodness doth declare;"}, {"text": "And over all his other works", "syllables": ["And", "over", "all", "his", "o-", "ther", "wo-", "rks"]}, {"text": "his tender mercies are."}]}, {"index": 7, "lines": [{"text": "Thee all thy works shall praise, O Lord,", "bibleVerseRef": 10}, {"text": "and thee thy saints shall bless;"}, {"text": "They shall thy kingdom''s glory show,", "bibleVerseRef": 11}, {"text": "thy pow''r by speech express:"}]}, {"index": 8, "lines": [{"text": "To make the sons of men to know", "bibleVerseRef": 12}, {"text": "his acts done mightily,"}, {"text": "And of his kingdom th'' excellent"}, {"text": "and glorious majesty."}]}, {"index": 9, "lines": [{"text": "Thy kingdom shall for ever stand,", "syllables": ["Thy", "kin-", "gdom", "shall", "for", "ever", "sta-", "nd,"], "bibleVerseRef": 13}, {"text": "thy reign through ages all.", "syllables": ["thy", "reign", "throu-", "gh", "ages", "all."]}, {"text": "God raiseth all that are bow''d down,", "bibleVerseRef": 14}, {"text": "upholdeth all that fall."}]}, {"index": 10, "lines": [{"text": "The eyes of all things wait on thee,", "bibleVerseRef": 15}, {"text": "the giver of all good;", "syllables": ["the", "give-", "r", "of", "all", "good;"]}, {"text": "And thou, in time convenient,", "syllables": ["And", "thou,", "in", "time", "con-", "ve-", "nie-", "nt,"]}, {"text": "bestow''st on them their food:"}]}, {"index": 11, "lines": [{"text": "Thine hand thou open''st lib''rally,", "syllables": ["Thine", "hand", "thou", "ope-", "n''st", "lib-", "''ral-", "ly,"], "bibleVerseRef": 16}, {"text": "and of thy bounty gives"}, {"text": "Enough to satisfy the need"}, {"text": "of ev''ry thing that lives."}]}, {"index": 12, "lines": [{"text": "The Lord is just in all his ways,", "bibleVerseRef": 17}, {"text": "holy in his works all."}, {"text": "God''s near to all that call on him,", "bibleVerseRef": 18}, {"text": "in truth that on him call."}]}, {"index": 13, "lines": [{"text": "He will accomplish the desire", "bibleVerseRef": 19}, {"text": "of those that do him fear:"}, {"text": "He also will deliver them,", "syllables": ["He", "al-", "so", "will", "de-", "live-", "r", "them,"]}, {"text": "and he their cry will hear."}]}, {"index": 14, "lines": [{"text": "The Lord pr