INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (98, 'recaNKxgsevhgRGAJ', 67, '67 (First Version, Recommended)', '1Lord, bless and pity us,
shine on us with thy face:
