INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (151, 'recp8eD3ww6YW9k69', 148, '148 (First Version)', '1Praise God. From heavens praise the Lord,
in heights praise to him be.
2All ye his angels, praise ye him;
his hosts all, praise him ye.

3O praise ye him, both sun and moon,
praise him, all stars of light.
4Ye heav''ns of heav''ns him praise, and floods
above the heavens'' height.

5Let all the creatures praise the name
of our almighty Lord:
For he commanded, and they were
created by his word.

6He also, for all times to come,
hath them establish''d sure;
He hath appointed them a law,
which ever shall endure.

7Praise ye JEHOVAH from the earth,
dragons, and ev''ry deep:
8Fire, hail, snow, vapour, stormy wind,
his word that fully keep.

9All hills and mountains, fruitful trees,
and all ye cedars high:
10Beasts, and all cattle, creeping things,
and all ye birds that fly.

11Kings of the earth, all nations,
princes, earth''s judges all:
12Both young men, yea, and maidens too,
old men, and children small.

13Let them God''s name praise; for his name
alone is excellent:
His glory reacheth far above
the earth and firmament.

14His people''s horn, the praise of all
his saints, exalteth he;
Ev''n Isr''el''s seed, a people near
to him. The Lord praise ye.', '[{"index": 0, "lines": [{"text": "Praise God. From heavens praise the Lord,", "syllables": ["Praise", "God.", "From", "heave-", "ns", "praise", "the", "Lord,"], "bibleVerseRef": 1}, {"text": "in heights praise to him be."}, {"text": "All ye his angels, praise ye him;", "bibleVerseRef": 2}, {"text": "his hosts all, praise him ye."}]}, {"index": 1, "lines": [{"text": "O praise ye him, both sun and moon,", "bibleVerseRef": 3}, {"text": "praise him, all stars of light."}, {"text": "Ye heav''ns of heav''ns him praise, and floods", "bibleVerseRef": 4}, {"text": "above the heavens'' height.", "syllables": ["a-", "bove", "the", "heave-", "ns''", "height."]}]}, {"index": 2, "lines": [{"text": "Let all the creatures praise the name", "bibleVerseRef": 5}, {"text": "of our almighty Lord:"}, {"text": "For he commanded, and they were"}, {"text": "created by his word.", "syllables": ["crea-", "-", "ted", "by", "his", "word."]}]}, {"index": 3, "lines": [{"text": "He also, for all times to come,", "bibleVerseRef": 6}, {"text": "hath them establish''d sure;"}, {"text": "He hath appointed them a law,"}, {"text": "which ever shall endure.", "syllables": ["whi-", "ch", "ever", "shall", "en-", "dure."]}]}, {"index": 4, "lines": [{"text": "Praise ye JEHOVAH from the earth,", "bibleVerseRef": 7}, {"text": "dragons, and ev''ry deep:"}, {"text": "Fire, hail, snow, vapour, stormy wind,", "bibleVerseRef": 8}, {"text": "his word that fully keep."}]}, {"index": 5, "lines": [{"text": "All hills and mountains, fruitful trees,", "syllables": ["All", "hills", "and", "mountains,", "fru-", "i-", "tful", "trees,"], "bibleVerseRef": 9}, {"text": "and all ye cedars high:"}, {"text": "Beasts, and all cattle, creeping things,", "bibleVerseRef": 10}, {"text": "and all ye birds that fly."}]}, {"index": 6, "lines": [{"text": "Kings of the earth, all nations,", "syllables": ["Kings", "of", "the", "ea-", "rth,", "all", "na-", "tions,"], "bibleVerseRef": 11}, {"text": "princes, earth''s judges all:"}, {"text": "Both young men, yea, and maidens too,", "syllables": ["Both", "young", "men,", "yea,", "and", "maide-", "ns", "too,"], "bibleVerseRef": 12}, {"text": "old men, and children small."}]}, {"index": 7, "lines": [{"text": "Let them God''s name praise; for his name", "bibleVerseRef": 13}, {"text": "alone is excellent:", "syllables": ["a-", "lone", "is", "ex-", "celle-", "nt:"]}, {"text": "His glory reacheth far above"}, {"text": "the earth and firmament."}]}, {"index": 8, "lines": [{"text": "His people''s horn, the praise of all", "syllables": ["His", "peo-", "ple''s", "horn,", "the", "praise", "of", "all"], "bibleVerseRef": 14}, {"text": "his saints, exalteth he;"}, {"text": "Ev''n Isr''el''s seed, a people near", "syllables": ["Ev''n", "isr''el''s", "seed,", "a", "pe-", "o-", "ple", "near"]}, {"text": "to him. The Lord praise ye."}]}]', 'CM', 'First Version', 'Praise God. From heavens praise the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (163, 'recsO2S5yqQenWD7V', 121, '121', '1I to the hills will lift mine eyes,
from whence doth come mine aid.
2My safety cometh from the Lord,
who heav''n and earth hath made.

3Thy foot he''ll not let slide, nor will
he slumber that thee keeps.
4Behold, he that keeps Israel,
he slumbers not, nor sleeps.

5The Lord thee keeps, the Lord thy shade
on thy right hand doth stay:
6The moon by night thee shall not smite,
nor yet the sun by day.

7The Lord shall keep thy soul; he shall
preserve thee from all ill.
8Henceforth thy going out and in
God keep for ever will.', '[{"index": 0, "lines": [{"text": "I to the hills will lift mine eyes,", "bibleVerseRef": 1}, {"text": "from whence doth come mine aid."}, {"text": "My safety cometh from the Lord,", "bibleVerseRef": 2}, {"text": "who heav''n and earth hath made."}]}, {"index": 1, "lines": [{"text": "Thy foot he''ll not let slide, nor will", "syllables": ["Thy", "foot", "he''ll", "not", "let", "slide,", "nor", "will"], "bibleVerseRef": 3}, {"text": "he slumber that thee keeps."}, {"text": "Behold, he that keeps Israel,", "syllables": ["be-", "ho-", "ld,", "he", "that", "keeps", "is-", "rael,"], "bibleVerseRef": 4}, {"text": "he slumbers not, nor sleeps."}]}, {"index": 2, "lines": [{"text": "The Lord thee keeps, the Lord thy shade", "bibleVerseRef": 5}, {"text": "on thy right hand doth stay:"}, {"text": "The moon by night thee shall not smite,", "syllables": ["The", "moon", "by", "night", "thee", "shall", "not", "smite,"], "bibleVerseRef": 6}, {"text": "nor yet the sun by day."}]}, {"index": 3, "lines": [{"text": "The Lord shall keep thy soul; he shall", "bibleVerseRef": 7}, {"text": "preserve thee from all ill."}, {"text": "Henceforth thy going out and in", "bibleVerseRef": 8}, {"text": "God keep for ever will.", "syllables": ["God", "keep", "for", "ever", "wi-", "ll."]}]}]', 'CM', NULL, 'I to the hills will lift mine eyes...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (8, 'rec1vw0tnwXKj7dC1', 139, '139', '1O Lord, thou hast me search''d and known.
2Thou know''st my sitting down,
And rising up; yea, all my thoughts
afar to thee are known.

3My footsteps, and my lying down,
thou compassest always;
Thou also most entirely art
acquaint with all my ways.

4For in my tongue, before I speak,
not any word can be,
But altogether, lo, O Lord,
it is well known to thee.

5Behind, before, thou hast beset,
and laid on me thine hand.
6Such knowledge is too strange for me,
too high to understand.

7From thy Sp''rit whither shall I go?
or from thy presence fly?
8Ascend I heav''n, lo, thou art there;
there, if in hell I lie.

9Take I the morning wings, and dwell
in utmost parts of sea;
10Ev''n there, Lord, shall thy hand me lead,
thy right hand hold shall me.

11If I do say that darkness shall
me cover from thy sight,
Then surely shall the very night
about me be as light.

12Yea, darkness hideth not from thee,
but night doth shine as day:
To thee the darkness and the light
are both alike alway.

13For thou possessed hast my reins,
and thou hast cover''d me,
When I within my mother''s womb
inclosed was by thee.

14Thee will I praise; for fearfully
and strangely made I am;
Thy works are marv''llous, and right well
my soul doth know the same.

15My substance was not hid from thee,
when as in secret I
Was made; and in earth''s lowest parts
was wrought most curiously.

16Thine eyes my substance did behold,
yet being unperfect;
And in the volume of thy book
my members all were writ;

Which after in continuance
were fashion''d ev''ry one,
When as they yet all shapeless were,
and of them there was none.

17How precious also are thy thoughts,
O gracious God, to me!
And in their sum how passing great
and numberless they be!

18If I should count them, than the sand
they more in number be:
What time soever I awake,
I ever am with thee.

19Thou, Lord, wilt sure the wicked slay:
hence from me bloody men.
20Thy foes against thee loudly speak,
and take thy name in vain.

21Do not I hate all those, O Lord,
that hatred bear to thee?
With those that up against thee rise
can I but grieved be?

22With perfect hatred them I hate,
my foes I them do hold.
23Search me, O God, and know my heart,
try me, my thoughts unfold:

24And see if any wicked way
there be at all in me;
And in thine everlasting way
to me a leader be.', '[{"index": 0, "lines": [{"text": "O Lord, thou hast me search''d and known.", "bibleVerseRef": 1}, {"text": "Thou know''st my sitting down,", "bibleVerseRef": 2}, {"text": "And rising up; yea, all my thoughts"}, {"text": "afar to thee are known."}]}, {"index": 1, "lines": [{"text": "My footsteps, and my lying down,", "syllables": ["My", "foot-", "ste-", "ps,", "and", "my", "lying", "down,"], "bibleVerseRef": 3}, {"text": "thou compassest always;"}, {"text": "Thou also most entirely art", "syllables": ["Thou", "also", "most", "en-", "ti-", "re-", "ly", "art"]}, {"text": "acquaint with all my ways.", "syllables": ["acqua-", "int", "with", "all", "my", "ways."]}]}, {"index": 2, "lines": [{"text": "For in my tongue, before I speak,", "syllables": ["For", "in", "my", "tongue,", "be-", "fore", "I", "speak,"], "bibleVerseRef": 4}, {"text": "not any word can be,"}, {"text": "But altogether, lo, O Lord,"}, {"text": "it is well known to thee."}]}, {"index": 3, "lines": [{"text": "Behind, before, thou hast beset,", "bibleVerseRef": 5}, {"text": "and laid on me thine hand."}, {"text": "Such knowledge is too strange for me,", "syllables": ["Such", "knowledge", "is", "too", "stran-", "ge", "for", "me,"], "bibleVerseRef": 6}, {"text": "too high to understand."}]}, {"index": 4, "lines": [{"text": "From thy Sp''rit whither shall I go?", "bibleVerseRef": 7}, {"text": "or from thy presence fly?"}, {"text": "Ascend I heav''n, lo, thou art there;", "bibleVerseRef": 8}, {"text": "there, if in hell I lie."}]}, {"index": 5, "lines": [{"text": "Take I the morning wings, and dwell", "bibleVerseRef": 9}, {"text": "in utmost parts of sea;"}, {"text": "Ev''n there, Lord, shall thy hand me lead,", "bibleVerseRef": 10}, {"text": "thy right hand hold shall me."}]}, {"index": 6, "lines": [{"text": "If I do say that darkness shall", "bibleVerseRef": 11}, {"text": "me cover from thy sight,", "syllables": ["me", "cover", "from", "thy", "si-", "ght,"]}, {"text": "Then surely shall the very night"}, {"text": "about me be as light."}]}, {"index": 7, "lines": [{"text": "Yea, darkness hideth not from thee,", "bibleVerseRef": 12}, {"text": "but night doth shine as day:"}, {"text": "To thee the darkness and the light"}, {"text": "are both alike alway."}]}, {"index": 8, "lines": [{"text": "For thou possessed hast my reins,", "bibleVerseRef": 13}, {"text": "and thou hast cover''d me,", "syllables": ["and", "thou", "hast", "cove-", "r''d", "me,"]}, {"text": "When I within my mother''s womb"}, {"text": "inclosed was by thee."}]}, {"index": 9, "lines": [{"text": "Thee will I praise; for fearfully", "bibleVerseRef": 14}, {"text": "and strangely made I am;", "syllables": ["and", "strange-", "ly", "made", "I", "am;"]}, {"text": "Thy works are marv''llous, and right well"}, {"text": "my soul doth know the same."}]}, {"index": 10, "lines": [{"text": "My substance was not hid from thee,", "syllables": ["My", "substan-", "ce", "was", "not", "hid", "from", "thee,"], "bibleVerseRef": 15}, {"text": "when as in secret I"}, {"text": "Was made; and in earth''s lowest parts", "syllables": ["Was", "made;", "and", "in", "ea-", "rth''s", "lowest", "parts"]}, {"text": "was wrought most curiously."}]}, {"index": 11, "lines": [{"text": "Thine eyes my substance did behold,", "syllables": ["Thine", "eyes", "my", "substan-", "ce", "did", "be-", "hold,"], "bibleVerseRef": 16}, {"text": "yet being unperfect;", "syllables": ["yet", "bei-", "ng", "un-", "per-", "fect;"]}, {"text": "And in the volume of thy book"}, {"text": "my members all were writ;"}]}, {"index": 12, "lines": [{"text": "Which after in continuance", "syllables": ["Which", "after", "in", "con-", "ti-", "nu-", "a-", "nce"]}, {"text": "were fashion''d ev''ry one,"}, {"text": "When as they yet all shapeless were,"}, {"text": "and of them there was none.", "syllables": ["and", "of", "them", "there", "was", "none."]}]}, {"index": 13, "lines": [{"text": "How precious also are thy thoughts,", "bibleVerseRef": 17}, {"tex