INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (54, 'recIwMQ9thPXfJfJL', 17, '17', '1Lord, hear the right, attend my cry,
unto my pray''r give heed,
That doth not in hypocrisy
from feigned lips proceed.

2And from before thy presence forth
my sentence do thou send:
Toward these things that equal are
do thou thine eyes intend.

3Thou prov''dst mine heart, thou visit''dst me
by night, thou didst me try,
Yet nothing found''st; for that my mouth
shall not sin, purpos''d I.

4As for men''s works, I, by the word
that from thy lips doth flow,
Did me preserve out of the paths
wherein destroyers go.

5Hold up my goings, Lord, me guide
in those thy paths divine,
So that my footsteps may not slide
out of those ways of thine.

6I called have on thee, O God,
because thou wilt me hear:
That thou may''st hearken to my speech,
to me incline thine ear.

7Thy wondrous loving-kindness show,
thou that, by thy right hand,
Sav''st them that trust in thee from those
that up against them stand.

8As th'' apple of the eye me keep;
in thy wings shade me close
9From lewd oppressors, compassing
me round, as deadly foes.

10In their own fat they are inclos''d;
their mouth speaks loftily.
11Our steps they compass''d; and to ground
down bowing set their eye.

12He like unto a lion is
that''s greedy of his prey,
Or lion young, which lurking doth
in secret places stay.

13Arise, and disappoint my foe,
and cast him down, O Lord: 
My soul save from the wicked man,
the man which is thy sword.

14From men, which are thy hand, O Lord,
from worldly men me save,
Which only in this present life
their part and portion have.

Whose belly with thy treasure hid
thou fill''st: they children have
In plenty; of their goods the rest
they to their children leave.

15But as for me, I thine own face
in righteousness will see;
And with thy likeness, when I wake,
I satisfy''d shall be.', '[{"index": 0, "lines": [{"text": "Lord, hear the right, attend my cry,", "bibleVerseRef": 1}, {"text": "unto my pray''r give heed,"}, {"text": "That doth not in hypocrisy"}, {"text": "from feigned lips proceed."}]}, {"index": 1, "lines": [{"text": "And from before thy presence forth", "bibleVerseRef": 2}, {"text": "my sentence do thou send:"}, {"text": "Toward these things that equal are", "syllables": ["toward", "these", "things", "that", "e-", "qu-", "al", "are"]}, {"text": "do thou thine eyes intend."}]}, {"index": 2, "lines": [{"text": "Thou prov''dst mine heart, thou visit''dst me", "bibleVerseRef": 3}, {"text": "by night, thou didst me try,"}, {"text": "Yet nothing found''st; for that my mouth"}, {"text": "shall not sin, purpos''d I."}]}, {"index": 3, "lines": [{"text": "As for men''s works, I, by the word", "bibleVerseRef": 4}, {"text": "that from thy lips doth flow,"}, {"text": "Did me preserve out of the paths"}, {"text": "wherein destroyers go.", "syllables": ["wherei-", "-", "n", "des-", "troyers", "go."]}]}, {"index": 4, "lines": [{"text": "Hold up my goings, Lord, me guide", "syllables": ["Hold", "up", "my", "goings,", "Lord,", "me", "gui-", "de"], "bibleVerseRef": 5}, {"text": "in those thy paths divine,"}, {"text": "So that my footsteps may not slide", "syllables": ["So", "that", "my", "footsteps", "may", "not", "sli-", "de"]}, {"text": "out of those ways of thine."}]}, {"index": 5, "lines": [{"text": "I called have on thee, O God,", "bibleVerseRef": 6}, {"text": "because thou wilt me hear:"}, {"text": "That thou may''st hearken to my speech,"}, {"text": "to me incline thine ear.", "syllables": ["to", "me", "incli-", "ne", "thine", "ear."]}]}, {"index": 6, "lines": [{"text": "Thy wondrous loving-kindness show,", "bibleVerseRef": 7}, {"text": "thou that, by thy right hand,"}, {"text": "Sav''st them that trust in thee from those"}, {"text": "that up against them stand."}]}, {"index": 7, "lines": [{"text": "As th'' apple of the eye me keep;", "syllables": ["As", "th''", "apple", "of", "the", "eye", "me", "keep;"], "bibleVerseRef": 8}, {"text": "in thy wings shade me close", "syllables": ["in", "thy", "wings", "shade", "me", "close"]}, {"text": "From lewd oppressors, compassing", "bibleVerseRef": 9}, {"text": "me round, as deadly foes."}]}, {"index": 8, "lines": [{"text": "In their own fat they are inclos''d;", "bibleVerseRef": 10}, {"text": "their mouth speaks loftily."}, {"text": "Our steps they compass''d; and to ground", "bibleVerseRef": 11}, {"text": "down bowing set their eye."}]}, {"index": 9, "lines": [{"text": "He like unto a lion is", "syllables": ["He", "li-", "ke", "un-", "to", "a", "lion", "is"], "bibleVerseRef": 12}, {"text": "that''s greedy of his prey,"}, {"text": "Or lion young, which lurking doth", "syllables": ["Or", "lion", "you-", "ng,", "which", "lur-", "king", "doth"]}, {"text": "in secret places stay."}]}, {"index": 10, "lines": [{"text": "Arise, and disappoint my foe,", "bibleVerseRef": 13}, {"text": "and cast him down, O Lord:"}, {"text": "My soul save from the wicked man,"}, {"text": "the man which is thy sword."}]}, {"index": 11, "lines": [{"text": "From men, which are thy hand, O Lord,", "bibleVerseRef": 14}, {"text": "from worldly men me save,"}, {"text": "Which only in this present life", "syllables": ["Which", "on-", "ly", "in", "this", "prese-", "nt", "life"]}, {"text": "their part and portion have."}]}, {"index": 12, "lines": [{"text": "Whose belly with thy treasure hid"}, {"text": "thou fill''st: they children have"}, {"text": "In plenty; of their goods the rest"}, {"text": "they to their children leave."}]}, {"index": 13, "lines": [{"text": "But as for me, I thine own face", "bibleVerseRef": 15}, {"text": "in righteousness will see;"}, {"text": "And with thy likeness, when I wake,"}, {"text": "I satisfy''d shall be."}]}]', 'CM', NULL, 'Lord, hear the right, attend my cry...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (81, 'recUejXV3IzaEf5sD', 48, '48', '1Great is the Lord, and greatly he
is to be praised still,
Within the city of our God,
upon his holy hill.

2Mount Sion stands most beautiful,
the joy of all the land;
The city of the mighty King
on her north side doth stand.

3The Lord within her palaces
is for a refuge known.
4For, lo, the kings that gather''d were
together, by have gone.

5But when they did behold the same,
they, wond''ring, would not stay;
But, being troubled at the sight,
they thence did haste away.

6Great terror there took hold on them;
they were possess''d with fear;
Their grief came like a woman''s pain,
when she a child doth bear.

7Thou Tarshish ships with east wind break''st:
8As we have heard it told,
So, in the city of the Lord,
our eyes did it behold;

In our God''s city, which his hand
for ever stablish will.
9We of thy loving-kindness thought,
Lord, in thy temple still.

10O Lord, according to thy name,
through all the earth''s thy praise;
And thy right hand, O Lord, is full
of righteousness always.

11Because thy judgments are made known,
let Sion mount rejoice;
Of Judah let the daughters all
send forth a cheerful voice.

12Walk about Sion,
and go round; the high tow''rs thereof tell:
13Consider ye her palaces,
and mark her bulwarks well;

That ye may tell posterity.
14For this God doth abide
Our God for evermore; he will
ev''n unto death us guide.', '[{"index": 0, "lines": [{"text": "Great is the Lord, and greatly he", "bibleVerseRef": 1}, {"text": "is to be praised still,", "syllables": ["is", "to", "be", "praise-", "d", "still,"]}, {"text": "Within the city of our God,"}, {"text": "upon his holy hill."}]}, {"index": 1, "lines": [{"text": "Mount Sion stands most beautiful,", "syllables": ["Mount", "Sion", "sta-", "nds", "most", "beau-", "ti-", "ful,"], "bibleVerseRef": 2}, {"text": "the joy of all the land;"}, {"text": "The city of the mighty King"}, {"text": "on her north side doth stand."}]}, {"index": 2, "lines": [{"text": "The Lord within her palaces", "syllables": ["The", "Lord", "wi-", "thin", "her", "pa-", "lace-", "s"], "bibleVerseRef": 3}, {"text": "is for a refuge known."}, {"text": "For, lo, the kings that gather''d were", "bibleVerseRef": 4}, {"text": "together, by have gone."}]}, {"index": 3, "lines": [{"text": "But when they did behold the same,", "bibleVerseRef": 5}, {"text": "they, wond''ring, would not stay;"}, {"text": "But, being troubled at the sight,", "syllables": ["But,", "being", "trou-", "b-", "led", "at", "the", "sight,"]}, {"text": "they thence did haste away.", "syllables": ["they", "thence", "did", "haste", "a-", "way."]}]}, {"index": 4, "lines": [{"text": "Great terror there took hold on them;", "bibleVerseRef": 6}, {"text": "they were possess''d with fear;"}, {"text": "Their grief came like a woman''s pain,"}, {"text": "when she a child doth bear."}]}, {"index": 5, "lines": [{"text": "Thou Tarshish ships with east wind break''st:", "bibleVerseRef": 7}, {"text": "As we have heard it told,", "bibleVerseRef": 8}, {"text": "So, in the city of the Lord,"}, {"text": "our eyes did it behold;"}]}, {"index": 6, "lines": [{"text": "In our God''s city, which his hand"}, {"text": "for ever stablish will.", "syllables": ["for", "ever", "sta-", "b-", "lish", "will."]}, {"text": "We of thy loving-kindness thought,", "bibleVerseRef": 9}, {"text": "Lord, in thy temple still.", "syllables": ["Lord,", "in", "thy", "te-", "mple", "still."]}]}, {"index": 7, "lines": [{"text": "O Lord, according to thy name,", "bibleVerseRef": 10}, {"text": "through all the earth''s thy praise;"}, {"text": "And thy right hand, O Lord, is full"}, {"text": "of righteousness always."}]}, {"index": 8, "lines": [{"text": "Because thy judgments are made known,", "bibleVerseRef": 11}, {"text": "let Sion mount rejoice;", "syllables": ["let", "Sion", "mount", "re-", "joice-", ";"]}, {"text": "Of Judah let the daughters all"}, {"text": "send forth a cheerful voice."}]}, {"index": 9, "lines": [{"text": "Walk about Sion,", "syllables": ["Wa-", "lk", "a-", "bou-", "-", "t", "Sio-", "n,"], "bibleVerseRef": 12}, {"text": "and go round; the high tow''rs thereof tell:", "syllables": ["and", "go", "round;", "the", "high", "tow''rsthereoftell:"]}, {"text": "Consider ye her palaces,", "syllables": ["con-", "side-", "r", "ye", "her", "pa-", "lace-", "s,"], "bibleVerseRef": 13}, {"text": "and mark her bulwarks well;"}]}, {"index": 10, "lines": [{"text": "That ye may tell posterity."}, {"text": "For this God doth abide", "bibleVerseRef": 14}, {"text": "Our God for evermore; he will", "syllables": ["Our", "God", "for", "eve-", "r-", "more;", "he", "will"]}, {"text": "ev''n unto death us guide.", "syllables": ["ev''n", "unto", "death", "us", "gui-", "de."]}]}]', 'CM', NULL, 'Great is the Lord, and greatly he...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (183, 'recyZip18Gs7BH8yw', 100, '100 (Second Version)', '1O all ye lands, unto the Lord
make ye a joyful noise.
2Serve God with gladness, him before
come with a singing voice.

3Know ye the Lord that he is God;
not we, but he us made:
We are his people, and the sheep
within his pasture fed.

4Enter his gates and courts with praise,
to thank him go ye thither:
To him express your thankfulness,
and bless his name together.

5Because the Lord our God is good,
his mercy faileth never;
And to all generations
his truth endureth ever.', '[{"index": 0, "lines": [{"text": "O all ye lands, unto the Lord", "bibleVerseRef": 1}, {"text": "make ye a joyful noise."}, {"text": "Serve God with gladness, him before", "bibleVerseRef": 2}, {"text": "come with a singing voice."}]}, {"index": 1, "lines": [{"text": "Know ye the Lord that he is God;", "bibleVerseRef": 3}, {"text": "not we, but he us made:"}, {"text": "We are his people, and the sheep", "syllables": ["We", "are", "his", "peo-", "ple,", "and", "the", "sheep"]}, {"text": "within his pasture fed."}]}, {"index": 2, "lines": [{"text": "Enter his gates and courts with praise,", "syllables": ["enter", "his", "ga-", "tes", "and", "courts", "with", "praise,"], "bibleVerseRef": 4}, {"text": "to thank him go ye thither:", "syllables": ["to", "thank", "him", "go", "ye", "thither:"]}, {"text": "To him express your thankfulness,"}, {"text": "and bless his name together.", "syllables": ["and", "bless", "his", "name", "toge-", "ther."]}]}, {"index": 3, "lines": [{"text": "Because the Lord our God is good,", "bibleVerseRef": 5}, {"text": "his mercy faileth never;", "syllables": ["his", "mercy", "fail-", "eth", "ne-", "ver;"]}, {"text": "And to all generations", "syllables": ["And", "to", "all", "ge-", "ne-", "ra-", "tio-", "ns"]}, {"text": "his truth endureth ever."}]}]', 'CM', 'Second Version', 'O all ye lands, unto the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (102, 'recbocfdcBli0LnEO', 130, '130', '1Lord, from the depths to thee I cry''d.
2My voice, Lord, do thou hear:
Unto my supplication''s voice
give an attentive ear.

3Lord, who shall stand, if thou, O Lord,
should''st mark iniquity?
4But yet with thee forgiveness is,
that fear''d thou mayest be.

5I wait for God, my soul doth wait,
my hope is in his word.
6More than they that for morning watch,
my soul waits for the Lord;

I say, more than they that do watch
the morning light to see.
7Let Israel hope in the Lord,
for with him mercies be;

And plenteous redemption
is ever found with him.
8And from all his iniquities
he Isr''el shall redeem.', '[{"index": 0, "lines": [{"text": "Lord, from the depths to thee I cry''d.", "bibleVerseRef": 1}, {"text": "My voice, Lord, do thou hear:", "bibleVerseRef": 2}, {"text": "Unto my supplication''s voice"}, {"text": "give an attentive ear."}]}, {"index": 1, "lines": [{"text": "Lord, who shall stand, if thou, O Lord,", "bibleVerseRef": 3}, {"text": "should''st mark iniquity?"}, {"text": "But yet with thee forgiveness is,", "syllables": ["But", "yet", "with", "thee", "forgi-", "ve-", "ness", "is,"], "bibleVerseRef": 4}, {"text": "that fear''d thou mayest be.", "syllables": ["that", "fea-", "r''d", "thou", "mayest", "be."]}]}, {"index": 2, "lines": [{"text": "I wait for God, my soul doth wait,", "bibleVerseRef": 5}, {"text": "my hope is in his word."}, {"text": "More than they that for morning watch,", "bibleVerseRef": 6}, {"text": "my soul waits for the Lord;"}]}, {"index": 3, "lines": [{"text": "I say, more than they that do watch"}, {"text": "the morning light to see."}, {"text": "Let Israel hope in the Lord,", "syllables": ["Let", "is-", "rael", "hope", "in", "the", "Lo-", "rd,"], "bibleVerseRef": 7}, {"text": "for with him mercies be;"}]}, {"index": 4, "lines": [{"text": "And plenteous redemption"}, {"text": "is ever found with him.", "syllables": ["is", "ever", "fou-", "nd", "with", "him."]}, {"text": "And from all his iniquities", "bibleVerseRef": 8}, {"text": "he Isr''el shall redeem."}]}]', 'CM', NULL, 'Lord, from the depths to thee I cry''d...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (110, 'recdHNU70Otn90s03', 88, '88', '1Lord God, my Saviour, day and night
before thee cry''d have I.
2Before thee let my prayer come;
give ear unto my cry.

3For troubles great do fill my soul;
my life draws nigh the grave.
4I''m counted with those that go down to pit,
and no strength have.

5Ev''n free among the dead, like them
that slain in grave do lie;
Cut off from thy hand, whom no more
thou hast in memory.

6Thou hast me laid in lowest pit,
in deeps and darksome caves.
7Thy wrath lies hard on me, thou hast
me press''d with all thy waves.

8Thou hast put far from me my friends,
thou mad''st them to abhor me;
And I am so shut up, that I
find no evasion for me.

9By reason of affliction
mine eye mourns dolefully:
To thee, Lord, do I call,
and stretch my hands continually.

10Wilt thou shew wonders to the dead?
shall they rise, and thee bless?
11Shall in the grave thy love be told?
in death thy faithfulness?

12Shall thy great wonders in the dark,
or shall thy righteousness
Be known to any in the land
of deep forgetfulness?

13But, Lord, to thee I cry''d; my pray''r
at morn prevent shall thee.
14Why, Lord, dost thou cast off my soul,
and hid''st thy face from me?

15Distress''d am I, and from my youth
I ready am to die;
Thy terrors I have borne, and am
distracted fearfully.

16The dreadful fierceness of thy wrath
quite over me doth go:
Thy terrors great have cut me off,
they did pursue me so.

17For round about me ev''ry day,
like water, they did roll;
And, gathering together, they
have compassed my soul.

18My friends thou hast put far from me,
and him that did me love;
And those that mine acquaintance were
to darkness didst remove.', '[{"index": 0, "lines": [{"text": "Lord God, my Saviour, day and night", "bibleVerseRef": 1}, {"text": "before thee cry''d have I."}, {"text": "Before thee let my prayer come;", "bibleVerseRef": 2}, {"text": "give ear unto my cry."}]}, {"index": 1, "lines": [{"text": "For troubles great do fill my soul;", "bibleVerseRef": 3}, {"text": "my life draws nigh the grave.", "syllables": ["my", "life", "draws", "nigh", "the", "grave."]}, {"text": "I''m counted with those that go down to pit,", "syllables": ["I''m", "counted", "with", "those", "that", "go", "down", "topit,"], "bibleVerseRef": 4}, {"text": "and no strength have.", "syllables": ["and", "no", "stre-", "-", "ngth", "have."]}]}, {"index": 2, "lines": [{"text": "Ev''n free among the dead, like them", "bibleVerseRef": 5}, {"text": "that slain in grave do lie;", "syllables": ["that", "slain", "in", "grave", "do", "lie;"]}, {"text": "Cut off from thy hand, whom no more"}, {"text": "thou hast in memory."}]}, {"index": 3, "lines": [{"text": "Thou hast me laid in lowest pit,", "syllables": ["Thou", "hast", "me", "laid", "in", "lowe-", "st", "pit,"], "bibleVerseRef": 6}, {"text": "in deeps and darksome caves.", "syllables": ["in", "deeps", "and", "darkso-", "me", "caves."]}, {"text": "Thy wrath lies hard on me, thou hast", "bibleVerseRef": 7}, {"text": "me press''d with all thy waves."}]}, {"index": 4, "lines": [{"text": "Thou hast put far from me my friends,", "bibleVerseRef": 8}, {"text": "thou mad''st them to abhor me;", "syllables": ["thou", "mad''st", "them", "to", "abhor", "me;"]}, {"text": "And I am so shut up, that I"}, {"text": "find no evasion for me.", "syllables": ["find", "no", "eva-", "sion", "for", "me."]}]}, {"index": 5, "lines": [{"text": "By reason of affliction", "syllables": ["By", "rea-", "son", "of", "af-", "fli-", "c-", "tion"], "bibleVerseRef": 9}, {"text": "mine eye mourns dolefully:"}, {"text": "To thee, Lord, do I call,", "syllables": ["To", "thee-", "-", ",", "Lord,", "do", "I", "call,"]}, {"text": "and stretch my hands continually.", "syllables": ["and", "stretch", "my", "hands", "continua-", "lly."]}]}, {"index": 6, "lines": [{"text": "Wilt thou shew wonders to the dead?", "bibleVerseRef": 10}, {"text": "shall they rise, and thee bless?"}, {"text": "Shall in the grave thy love be told?", "syllables": ["Shall", "in", "the", "grave", "thy", "love", "be", "told?"], "bibleVerseRef": 11}, {"text": "in death thy faithfulness?"}]}, {"index": 7, "lines": [{"text": "Shall thy great wonders in the dark,", "bibleVerseRef": 12}, {"text": "or shall thy righteousness"}, {"text": "Be known to any in the land"}, {"text": "of deep forgetfulness?"}]}, {"index": 8, "lines": [{"text": "But, Lord, to thee I cry''d; my pray''r", "bibleVerseRef": 13}, {"text": "at morn prevent shall thee.", "syllables": ["at", "morn", "preve-", "nt", "shall", "thee."]}, {"text": "Why, Lord, dost thou cast off my soul,", "bibleVerseRef": 14}, {"text": "and hid''st thy face from me?"}]}, {"index": 9, "lines": [{"text": "Distress''d am I, and from my youth", "bibleVerseRef": 15}, {"text": "I ready am to die;"}, {"text": "Thy terrors I have borne, and am", "syllables": ["Thy", "terrors", "I", "have", "bor-", "ne,", "and", "am"]}, {"text": "distracted fearfully."}]}, {"index": 10, "lines": [{"text": "The dreadful fierceness of thy wrath", "syllables": ["The", "dreadful", "fier-", "ce-", "ness", "of", "thy", "wrath"], "bibleVerseRef": 16}, {"text": "quite over me doth go:", "syllables": ["qui-", "te", "over", "me", "doth", "go:"]}, {"text": "Thy terrors great have cut me off,"}, {"text": "they did pursue me so."}]}, {"index": 11, "lines": [{"text": "For round about me ev''ry day,", "bibleVerseRef": 17}, {"text": "like water, they did roll;", "syllables": ["like", "wate-", "r,", "they", "did", "roll;"]}, {"text": "And, gathering together, they"}, {"text": "have compassed my soul."}]}, {"index": 12, "lines": [{"text": "My friends thou hast put far from me,", "bibleVerseRef": 18}, {"text": "and him that did me love;"}, {"text": "And those that mine acquaintance were", "syllables": ["And", "those", "that", "mine", "acquain-", "tan-", "ce", "were"]}, {"text": "to darkness didst remove."}]}]', 'CM', NULL, 'Lord God, my Saviour, day and night...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (117, 'recg2j5lMDIuAHU6w', 103, '103', '1O thou my soul, bless God the Lord;
and all that in me is
Be stirred up his holy name
to magnify and bless.

2Bless, O my soul, the Lord thy God,
and not forgetful be
Of all his gracious benefits
he hath bestow''d on thee.

3All thine iniquities who doth
most graciously forgive:
Who thy diseases all and pains doth heal,
and thee relieve.

4Who doth redeem thy life, that thou
to death may''st not go down;
Who thee with loving-kindness doth
and tender mercies crown:

5Who with abundance of good things
doth satisfy thy mouth;
So that, ev''n as the eagle''s age,
renewed is thy youth.

6God righteous judgment executes
for all oppressed ones.
7His ways to Moses, he his acts
made known to Isr''el''s sons.

8The Lord our God is merciful,
and he is gracious,
Long-suffering, and slow to wrath,
in mercy plenteous.

9He will not chide continually,
nor keep his anger still.
10With us he dealt not as we sinn''d,
nor did requite our ill.

11For as the heaven in its height
the earth surmounteth far;
So great to those that do him fear
his tender mercies are:

12As far as east is distant from
the west, so far hath he
From us removed, in his love,
all our iniquity.

13Such pity as a father hath
unto his children dear;
Like pity shews the Lord to such
as worship him in fear.

14For he remembers we are dust,
and he our frame well knows.
15Frail man, his days are like the grass,
as flow''r in field he grows:

16For over it the wind doth pass,
and it away is gone;
And of the place where once it was
it shall no more be known.

17But unto them that do him fear
God''s mercy never ends;
And to their children''s children still
his righteousness extends:

18To such as keep his covenant,
and mindful are alway
Of his most just commandements,
that they may them obey.

19The Lord prepared hath his throne
in heavens firm to stand;
And ev''ry thing that being hath
his kingdom doth command.

20O ye his angels, that excel
in strength, bless ye the Lord;
Ye who obey what he commands,
and hearken to his word.

21O bless and magnify the Lord,
ye glorious hosts of his;
Ye ministers, that do fulfil
whate''er his pleasure is.

22O bless the Lord, all ye his works,
wherewith the world is stor''d
In his dominions ev''ry where.
My soul, bless thou the Lord.', '[{"index": 0, "lines": [{"text": "O thou my soul, bless God the Lord;", "bibleVerseRef": 1}, {"text": "and all that in me is"}, {"text": "Be stirred up his holy name"}, {"text": "to magnify and bless."}]}, {"index": 1, "lines": [{"text": "Bless, O my soul, the Lord thy God,", "bibleVerseRef": 2}, {"text": "and not forgetful be"}, {"text": "Of all his gracious benefits"}, {"text": "he hath bestow''d on thee."}]}, {"index": 2, "lines": [{"text": "All thine iniquities who doth", "bibleVerseRef": 3}, {"text": "most graciously forgive:"}, {"text": "Who thy diseases all and pains doth heal,"}, {"text": "and thee relieve.", "syllables": ["and", "thee", "re-", "lieve-", "-", "."]}]}, {"index": 3, "lines": [{"text": "Who doth redeem thy life, that thou", "bibleVerseRef": 4}, {"text": "to death may''st not go down;"}, {"text": "Who thee with loving-kindness doth"}, {"text": "and tender mercies crown:"}]}, {"index": 4, "lines": [{"text": "Who with abundance of good things", "syllables": ["Who", "with", "abun-", "dan-", "ce", "of", "good", "things"], "bibleVerseRef": 5}, {"text": "doth satisfy thy mouth;"}, {"text": "So that, ev''n as the eagle''s age,"}, {"text": "renewed is thy youth."}]}, {"index": 5, "lines": [{"text": "God righteous judgment executes", "syllables": ["God", "ri-", "gh-", "teous", "jud-", "gment", "exe-", "cutes"], "bibleVerseRef": 6}, {"text": "for all oppressed ones."}, {"text": "His ways to Moses, he his acts", "syllables": ["His", "ways", "to", "Mose-", "s,", "he", "his", "acts"], "bibleVerseRef": 7}, {"text": "made known to Isr''el''s sons."}]}, {"index": 6, "lines": [{"text": "The Lord our God is merciful,", "bibleVerseRef": 8}, {"text": "and he is gracious,", "syllables": ["and", "he", "is", "gra-", "ciou-", "s,"]}, {"text": "Long-suffering, and slow to wrath,"}, {"text": "in mercy plenteous.", "syllables": ["in", "mercy", "plen-", "te-", "o-", "us."]}]}, {"index": 7, "lines": [{"text": "He will not chide continually,", "syllables": ["He", "will", "not", "chide", "conti-", "nu-", "a-", "lly,"], "bibleVerseRef": 9}, {"text": "nor keep his anger still."}, {"text": "With us he dealt not as we sinn''d,", "bibleVerseRef": 10}, {"text": "nor did requite our ill.", "syllables": ["nor", "did", "requi-", "te", "our", "ill."]}]}, {"index": 8, "lines": [{"text": "For as the heaven in its height", "syllables": ["For", "as", "the", "heave-", "n", "in", "its", "height"], "bibleVerseRef": 11}, {"text": "the earth surmounteth far;"}, {"text": "So great to those that do him fear"}, {"text": "his tender mercies are:"}]}, {"index": 9, "lines": [{"text": "As far as east is distant from", "bibleVerseRef": 12}, {"text": "the west, so far hath he"}, {"text": "From us removed, in his love,"}, {"text": "all our iniquity."}]}, {"index": 10, "lines": [{"text": "Such pity as a father hath", "bibleVerseRef": 13}, {"text": "unto his children dear;"}, {"text": "Like pity shews the Lord to such"}, {"text": "as worship him in fear."}]}, {"index": 11, "lines": [{"text": "For he remembers we are dust,", "bibleVerseRef": 14}, {"text": "and he our frame well knows.", "syllables": ["and", "he", "our", "frame", "well", "knows."]}, {"text": "Frail man, his days are like the grass,", "bibleVerseRef": 15}, {"text": "as flow''r in field he grows:"}]}, {"index": 12, "lines": [{"text": "For over it the wind doth pass,", "syllables": ["For", "over", "it", "the", "wind", "doth", "pa-", "ss,"], "bibleVerseRef": 16}, {"text": "and it away is gone;"}, {"text": "And of the place where once it was", "syllables": ["And", "of", "the", "place", "where", "once", "it", "was"]}, {"text": "it shall no more be known."}]}, {"index": 13, "lines": [{"text": "But unto them that do him fear", "bibleVerseRef": 17}, {"text": "God''s mercy never ends;"}, {"text": "And to their children''s children still"}, {"text": "his righteousness extends:"}]}, {"index": 14, "lines": [{"text": "To such as keep his covenant,", "syllables": ["To", "such", "as", "keep", "his", "cove-", "-", "nant,"], "bibleVerseRef": 18}, {"text": "and mindful are alway"}, {"text": "Of his most just commandements,"}, {"text": "that they may them obey.", "syllables": ["that", "they", "may", "them", "obey-", "."]}]}, {"index": 15, "lines": [{"text": "The Lord prepared hath his throne", "syllables": ["The", "Lord", "prepa-", "red", "hath", "his", "thro-", "ne"], "bibleVerseRef": 19}, {"text": "in heavens firm to stand;", "syllables": ["in", "heave-", "ns", "firm", "to", "stand;"]}, {"text": "And ev''ry thing that being hath", "syllables": ["And", "ev-", "''ry", "thi-", "ng", "that", "being", "hath"]}, {"text": "his kingdom doth command."}]}, {"index": 16, "lines": [{"text": "O ye his angels, that excel", "bibleVerseRef": 20}, {"text": "in strength, bless ye the Lord;"}, {"text": "Ye who obey what he commands,", "syllables": ["Ye", "who", "obey", "what", "he", "com-", "ma-", "nds,"]}, {"text": "and hearken to his word."}]}, {"index": 17, "lines": [{"text": "O bless and magnify the Lord,", "bibleVerseRef": 21}, {"text": "ye glorious hosts of his;"}, {"text": "Ye ministers, that do fulfil"}, {"text": "whate''er his pleasure is.", "syllables": ["whate''e-", "r", "his", "plea-", "sure", "is."]}]}, {"index": 18, "lines": [{"text": "O bless the Lord, all ye his works,", "bibleVerseRef": 22}, {"text": "wherewith the world is stor''d"}, {"text": "In his dominions ev''ry where."}, {"text": "My soul, bless thou the Lord."}]}]', 'CM', NULL, 'O thou my soul, bless God the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (129, 'reciv9di6m96rOi28', 93, '93', '1The Lord doth reign, and cloth''d is he
with majesty most bright;
His works do shew him cloth''d to be,
and girt about with might.

The world is also stablished,
that it cannot depart.
2Thy throne is fix''d of old, and thou
from everlasting art.

3The floods, O Lord, have lifted up,
they lifted up their voice;
The floods have lifted up their waves,
and made a mighty noise.

4But yet the Lord, that is on high,
is more of might by far
Than noise of many waters is,
or great sea-billows are.

5Thy testimonies ev''ry one
in faithfulness excel;
And holiness for ever, Lord,
thine house becometh well.', '[{"index": 0, "lines": [{"text": "The Lord doth reign, and cloth''d is he", "bibleVerseRef": 1}, {"text": "with majesty most bright;"}, {"text": "His works do shew him cloth''d to be,"}, {"text": "and girt about with might."}]}, {"index": 1, "lines": [{"text": "The world is also stablished,"}, {"text": "that it cannot depart."}, {"text": "Thy throne is fix''d of old, and thou", "syllables": ["Thy", "throne", "is", "fix''d", "of", "old,", "and", "thou"], "bibleVerseRef": 2}, {"text": "from everlasting art.", "syllables": ["from", "eve-", "r-", "las-", "ting", "art."]}]}, {"index": 2, "lines": [{"text": "The floods, O Lord, have lifted up,", "bibleVerseRef": 3}, {"text": "they lifted up their voice;"}, {"text": "The floods have lifted up their waves,"}, {"text": "and made a mighty noise."}]}, {"index": 3, "lines": [{"text": "But yet the Lord, that is on high,", "bibleVerseRef": 4}, {"text": "is more of might by far"}, {"text": "Than noise of many waters is,", "syllables": ["Than", "noise", "of", "ma-", "ny", "wate-", "rs", "is,"]}, {"text": "or great sea-billows are."}]}, {"index": 4, "lines": [{"text": "Thy testimonies ev''ry one", "bibleVerseRef": 5}, {"text": "in faithfulness excel;"}, {"text": "And holiness for ever, Lord,", "syllables": ["And", "ho-", "li-", "ness", "for", "eve-", "r,", "Lord,"]}, {"text": "thine house becometh well."}]}]', 'CM', NULL, 'The Lord doth reign, and cloth''d is he...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (143, 'recmVIjBqARDLV4rk', 119, '119:169-176 (22)', '169O let my earnest pray''r and cry
come near before thee, Lord:
Give understanding unto me,
according to thy word.

170Let my request before thee come:
after thy word me free.
171My lips shall utter praise, when thou
hast taught thy laws to me.

172My tongue of thy most blessed word
shall speak, and it confess;
Because all thy commandements
are perfect righteousness.

173Let thy strong hand make help to me:
thy precepts are my choice.
174I long''d for thy salvation, Lord,
and in thy law rejoice.

175O let my soul live, and it shall
give praises unto thee;
And let thy judgments gracious
be helpful unto me.

176I, like a lost sheep, went astray;
thy servant seek, and find:
For thy commands I suffer''d not
to slip out of my mind.', '[{"index": 0, "lines": [{"text": "O let my earnest pray''r and cry", "bibleVerseRef": 169}, {"text": "come near before thee, Lord:"}, {"text": "Give understanding unto me,"}, {"text": "according to thy word."}]}, {"index": 1, "lines": [{"text": "Let my request before thee come:", "bibleVerseRef": 170}, {"text": "after thy word me free."}, {"text": "My lips shall utter praise, when thou", "bibleVerseRef": 171}, {"text": "hast taught thy laws to me."}]}, {"index": 2, "lines": [{"text": "My tongue of thy most blessed word", "syllables": ["My", "tongue", "of", "thy", "most", "bles-", "sed", "word"], "bibleVerseRef": 172}, {"text": "shall speak, and it confess;"}, {"text": "Because all thy commandements"}, {"text": "are perfect righteousness."}]}, {"index": 3, "lines": [{"text": "Let thy strong hand make help to me:", "bibleVerseRef": 173}, {"text": "thy precepts are my choice."}, {"text": "I long''d for thy salvation, Lord,", "bibleVerseRef": 174}, {"text": "and in thy law rejoice."}]}, {"index": 4, "lines": [{"text": "O let my soul live, and it shall", "bibleVerseRef": 175}, {"text": "give praises unto thee;", "syllables": ["give", "praise-", "s", "un-", "to", "thee;"]}, {"text": "And let thy judgments gracious", "syllables": ["And", "let", "thy", "jud-", "gme-", "nts", "gra-", "cious"]}, {"text": "be helpful unto me."}]}, {"index": 5, "lines": [{"text": "I, like a lost sheep, went astray;", "bibleVerseRef": 176}, {"text": "thy servant seek, and find:"}, {"text": "For thy commands I suffer''d not"}, {"text": "to slip out of my mind."}]}]', 'CM', NULL, 'O let my earnest pray''r and cry...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (176, 'recxBbWIc20TX7ZQC', 119, '119:73-80 (10)', '73Thou mad''st and fashion''dst me: thy laws
to know give wisdom, Lord.
74So who thee fear shall joy to see
me trusting in thy word.

75That very right thy judgments are
I know, and do confess;
And that thou hast afflicted me
in truth and faithfulness.

76O let thy kindness merciful,
I pray thee, comfort me,
As to thy servant faithfully
was promised by thee.

77And let thy tender mercies come
to me, that I may live;
Because thy holy laws to me
sweet delectation give.

78Lord, let the proud ashamed be;
for they, without a cause,
With me perversely dealt: but I
will muse upon thy laws.

79Let such as fear thee, and have known
thy statutes, turn to me.
80My heart let in thy laws be sound,
that sham''d I never be.
', '[{"index": 0, "lines": [{"text": "Thou mad''st and fashion''dst me: thy laws", "bibleVerseRef": 73}, {"text": "to know give wisdom, Lord."}, {"text": "So who thee fear shall joy to see", "bibleVerseRef": 74}, {"text": "me trusting in thy word."}]}, {"index": 1, "lines": [{"text": "That very right thy judgments are", "bibleVerseRef": 75}, {"text": "I know, and do confess;"}, {"text": "And that thou hast afflicted me"}, {"text": "in truth and faithfulness."}]}, {"index": 2, "lines": [{"text": "O let thy kindness merciful,", "bibleVerseRef": 76}, {"text": "I pray thee, comfort me,"}, {"text": "As to thy servant faithfully"}, {"text": "was promised by thee.", "syllables": ["was", "pro-", "mise-", "d", "by", "thee."]}]}, {"index": 3, "lines": [{"text": "And let thy tender mercies come", "bibleVerseRef": 77}, {"text": "to me, that I may live;"}, {"text": "Because thy holy laws to me"}, {"text": "sweet delectation give."}]}, {"index": 4, "lines": [{"text": "Lord, let the proud ashamed be;", "bibleVerseRef": 78}, {"text": "for they, without a cause,"}, {"text": "With me perversely dealt: but I", "syllables": ["With", "me", "perver-", "se-", "ly", "dealt:", "but", "I"]}, {"text": "will muse upon thy laws."}]}, {"index": 5, "lines": [{"text": "Let such as fear thee, and have known", "bibleVerseRef": 79}, {"text": "thy statutes, turn to me.", "syllables": ["thy", "statu-", "tes,", "turn", "to", "me."]}, {"text": "My heart let in thy laws be sound,", "bibleVerseRef": 80}, {"text": "that sham''d I never be."}]}]', 'CM', 'Part 10', 'Thou mad''st and fashion''dst me: thy laws...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (4, 'rec0tlGbfMjtkvCTh', 124, '124 (First Version)', '1Had not the Lord been on our side,
may Israel now say;
2Had not the Lord been on our side,
when men rose us to slay;

3They had us swallow''d quick, when as
their wrath ''gainst us did flame:
4Waters had cover''d us, our soul
had sunk beneath the stream.

5Then had the waters, swelling high,
over our soul made way.
6Bless''d be the Lord, who to their teeth
us gave not for a prey.

7Our soul''s escaped, as a bird
out of the fowler''s snare;
The snare asunder broken is,
and we escaped are.

8Our sure and all-sufficient help
is in JEHOVAH''s name;
His name who did the heav''n create,
and who the earth did frame.', '[{"index": 0, "lines": [{"text": "Had not the Lord been on our side,", "bibleVerseRef": 1}, {"text": "may Israel now say;", "syllables": ["may", "is-", "rae-", "l", "now", "say;"]}, {"text": "Had not the Lord been on our side,", "bibleVerseRef": 2}, {"text": "when men rose us to slay;"}]}, {"index": 1, "lines": [{"text": "They had us swallow''d quick, when as", "syllables": ["They", "had", "us", "swallow''d", "qu-", "ick,", "when", "as"], "bibleVerseRef": 3}, {"text": "their wrath ''gainst us did flame:", "syllables": ["their", "wrath", "''gainst", "us", "did", "flame:"]}, {"text": "Waters had cover''d us, our soul", "syllables": ["Wate-", "rs", "had", "cove-", "r''d", "us,", "our", "soul"], "bibleVerseRef": 4}, {"text": "had sunk beneath the stream."}]}, {"index": 2, "lines": [{"text": "Then had the waters, swelling high,", "syllables": ["Then", "had", "the", "wate-", "rs,", "swel-", "ling", "high,"], "bibleVerseRef": 5}, {"text": "over our soul made way.", "syllables": ["ove-", "r", "our", "soul", "made", "way."]}, {"text": "Bless''d be the Lord, who to their teeth", "bibleVerseRef": 6}, {"text": "us gave not for a prey."}]}, {"index": 3, "lines": [{"text": "Our soul''s escaped, as a bird", "bibleVerseRef": 7}, {"text": "out of the fowler''s snare;", "syllables": ["out", "of", "the", "fowler''s", "sna-", "re;"]}, {"text": "The snare asunder broken is,", "syllables": ["The", "snare", "a-", "sun-", "der", "bro-", "ken", "is,"]}, {"text": "and we escaped are."}]}, {"index": 4, "lines": [{"text": "Our sure and all-sufficient help", "bibleVerseRef": 8}, {"text": "is in JEHOVAH''s name;"}, {"text": "His name who did the heav''n create,", "syllables": ["His", "name", "who", "did", "the", "heav''n", "create-", ","]}, {"text": "and who the earth did frame.", "syllables": ["and", "who", "the", "earth", "did", "frame."]}]}]', 'CM', 'First Version', 'Had not the Lord been on our side...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (78, 'recU9oJ2krgaBL2bw', 46, '46', '1God is our refuge and our strength,
in straits a present aid;
2Therefore, although the earth remove,
we will not be afraid:

Though hills amidst the seas be cast;
3Though waters roaring make,
And troubled be; yea, though the hills,
by swelling seas do shake.

4A river is, whose streams do glad
the city of our God;
The holy place, wherein the Lord
most high hath his abode.

5God in the midst of her doth dwell;
nothing shall her remove:
The Lord to her an helper will,
and that right early, prove.

6The heathen rag''d tumultuously,
the kingdoms moved were:
The Lord God uttered his voice,
the earth did melt for fear.

7The Lord of hosts upon our side
doth constantly remain:
The God of Jacob''s our refuge,
us safely to maintain.

8Come, and behold what wondrous works
have by the Lord been wrought;
Come, see what desolations
he on the earth hath brought.

9Unto the ends of all the earth
wars into peace he turns:
The bow he breaks, the spear he cuts,
in fire the chariot burns.

10Be still, and know that I am God;
among the heathen I
Will be exalted; I on earth
will be exalted high.

11Our God, who is the Lord of hosts,
is still upon our side;
The God of Jacob our refuge
for ever will abide.', '[{"index": 0, "lines": [{"text": "God is our refuge and our strength,", "bibleVerseRef": 1}, {"text": "in straits a present aid;", "syllables": ["in", "strai-", "ts", "a", "present", "aid;"]}, {"text": "Therefore, although the earth remove,", "bibleVerseRef": 2}, {"text": "we will not be afraid:"}]}, {"index": 1, "lines": [{"text": "Though hills amidst the seas be cast;"}, {"text": "Though waters roaring make,", "bibleVerseRef": 3}, {"text": "And troubled be; yea, though the hills,"}, {"text": "by swelling seas do shake."}]}, {"index": 2, "lines": [{"text": "A river is, whose streams do glad", "syllables": ["A", "river", "is,", "whose", "strea-", "ms", "do", "glad"], "bibleVerseRef": 4}, {"text": "the city of our God;"}, {"text": "The holy place, wherein the Lord"}, {"text": "most high hath his abode."}]}, {"index": 3, "lines": [{"text": "God in the midst of her doth dwell;", "bibleVerseRef": 5}, {"text": "nothing shall her remove:"}, {"text": "The Lord to her an helper will,"}, {"text": "and that right early, prove.", "syllables": ["and", "that", "right", "early,", "pro-", "ve."]}]}, {"index": 4, "lines": [{"text": "The heathen rag''d tumultuously,", "bibleVerseRef": 6}, {"text": "the kingdoms moved were:"}, {"text": "The Lord God uttered his voice,"}, {"text": "the earth did melt for fear."}]}, {"index": 5, "lines": [{"text": "The Lord of hosts upon our side", "bibleVerseRef": 7}, {"text": "doth constantly remain:"}, {"text": "The God of Jacob''s our refuge,"}, {"text": "us safely to maintain."}]}, {"index": 6, "lines": [{"text": "Come, and behold what wondrous works", "bibleVerseRef": 8}, {"text": "have by the Lord been wrought;"}, {"text": "Come, see what desolations", "syllables": ["Come-", ",", "see", "what", "de-", "so-", "la-", "tions"]}, {"text": "he on the earth hath brought."}]}, {"index": 7, "lines": [{"text": "Unto the ends of all the earth", "bibleVerseRef": 9}, {"text": "wars into peace he turns:"}, {"text": "The bow he breaks, the spear he cuts,"}, {"text": "in fire the chariot burns."}]}, {"index": 8, "lines": [{"text": "Be still, and know that I am God;", "bibleVerseRef": 10}, {"text": "among the heathen I"}, {"text": "Will be exalted; I on earth"}, {"text": "will be exalted high."}]}, {"index": 9, "lines": [{"text": "Our God, who is the Lord of hosts,", "bibleVerseRef": 11}, {"text": "is still upon our side;"}, {"text": "The God of Jacob our refuge"}, {"text": "for ever will abide.", "syllables": ["for", "ever", "will", "a-", "bide-", "."]}]}]', 'CM', NULL, 'God is our refuge and our strength...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (91, 'recWNTwCM4qv4GLxR', 70, '70 (First Version, Recommended)', '1Lord, haste me to deliver; 
with speed, Lord, succor me.
2Let them that for my soul do seek
shamed and confounded be:

Turned back be they, and shamed,
that in my hurt delight.
3Turned back be they, Ha, ha! that say,
their shaming to requite.

4In thee let all be glad,
and joy that seek for thee:
Let them who thy salvation love
say still, God praisèd be.

5I poor and needy am; come, Lord,
and make no stay:
My help thou and deliv''rer art;
O Lord, make no delay.', '[{"index": 0, "lines": [{"text": "Lord, haste me to deliver;", "syllables": ["Lord,", "haste", "me", "to", "de-", "liver;"], "bibleVerseRef": 1}, {"text": "with speed, Lord, succor me."}, {"text": "Let them that for my soul do seek", "bibleVerseRef": 2}, {"text": "shamed and confounded be:", "syllables": ["shamed", "and", "con-", "foun-", "ded", "be:"]}]}, {"index": 1, "lines": [{"text": "Turned back be they, and shamed,", "syllables": ["turned", "back", "be", "they,", "and", "shamed,"]}, {"text": "that in my hurt delight."}, {"text": "Turned back be they, Ha, ha! that say,", "syllables": ["turned", "back", "be", "they,", "Ha,", "ha!", "that", "say,"], "bibleVerseRef": 3}, {"text": "their shaming to requite.", "syllables": ["their", "shaming", "to", "requ-", "i-", "te."]}]}, {"index": 2, "lines": [{"text": "In thee let all be glad,", "bibleVerseRef": 4}, {"text": "and joy that seek for thee:"}, {"text": "Let them who thy salvation love"}, {"text": "say still, God praisèd be.", "syllables": ["say", "still,", "God", "prai-", "sèd", "be."]}]}, {"index": 3, "lines": [{"text": "I poor and needy am; come, Lord,", "syllables": ["I", "poor", "and", "needy", "am;", "come,Lord,"], "bibleVerseRef": 5}, {"text": "and make no stay:", "syllables": ["and", "make", "no", "stay-", "-", ":"]}, {"text": "My help thou and deliv''rer art;"}, {"text": "O Lord, make no delay."}]}]', 'SM', 'First Version', 'Lord, haste me to deliver...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (114, 'recfJ2iUVLhmwSdH4', 144, '144', '1O blessed ever be the Lord,
who is my strength and might,
Who doth instruct my hands to war,
my fingers teach to fight.

2My goodness, fortress, my high tow''r,
deliverer, and shield,
In whom I trust: who under me
my people makes to yield.

3Lord, what is man, that thou of him
dost so much knowledge take?
Or son of man, that thou of him
so great account dost make?

4Man is like vanity; his days,
as shadows, pass away.
5Lord, bow thy heav''ns, come down, touch thou
the hills, and smoke shall they.

6Cast forth thy lightning, scatter them;
thine arrows shoot, them rout.
7Thine hand send from above, me save;
from great depths draw me out;

And from the hand of children strange,
8Whose mouth speaks vanity;
And their right hand is a right hand
that works deceitfully.

9A new song I to thee will sing,
Lord, on a psaltery;
I on a ten-string''d instrument
will praises sing to thee.

10Ev''n he it is that unto kings
salvation doth send;
Who his own servant David doth
from hurtful sword defend.

11O free me from strange children''s hand,
whose mouth speaks vanity;
And their right hand a right hand is
that works deceitfully.

12That, as the plants, our sons may be
in youth grown up that are;
Our daughters like to corner-stones,
carv''d like a palace fair.

13That to afford all kind of store
our garners may be fill''d;
That our sheep thousands, in our streets
ten thousands they may yield.

14That strong our oxen be for work,
that no in-breaking be,
Nor going out; and that our streets
may from complaints be free.

15Those people blessed are who be
in such a case as this;
Yea, blessed all those people are,
whose God JEHOVAH is.', '[{"index": 0, "lines": [{"text": "O blessed ever be the Lord,", "syllables": ["O", "ble-", "s-", "sed", "ever", "be", "the", "Lord,"], "bibleVerseRef": 1}, {"text": "who is my strength and might,"}, {"text": "Who doth instruct my hands to war,"}, {"text": "my fingers teach to fight."}]}, {"index": 1, "lines": [{"text": "My goodness, fortress, my high tow''r,", "bibleVerseRef": 2}, {"text": "deliverer, and shield,"}, {"text": "In whom I trust: who under me"}, {"text": "my people makes to yield.", "syllables": ["my", "peo-", "ple", "makes", "to", "yield."]}]}, {"index": 2, "lines": [{"text": "Lord, what is man, that thou of him", "bibleVerseRef": 3}, {"text": "dost so much knowledge take?", "syllables": ["dost", "so", "much", "knowled-", "ge", "take?"]}, {"text": "Or son of man, that thou of him"}, {"text": "so great account dost make?"}]}, {"index": 3, "lines": [{"text": "Man is like vanity; his days,", "bibleVerseRef": 4}, {"text": "as shadows, pass away."}, {"text": "Lord, bow thy heav''ns, come down, touch thou", "bibleVerseRef": 5}, {"text": "the hills, and smoke shall they.", "syllables": ["the", "hills,", "and", "smoke", "shall", "they."]}]}, {"index": 4, "lines": [{"text": "Cast forth thy lightning, scatter them;", "bibleVerseRef": 6}, {"text": "thine arrows shoot, them rout."}, {"text": "Thine hand send from above, me save;", "bibleVerseRef": 7}, {"text": "from great depths draw me out;"}]}, {"index": 5, "lines": [{"text": "And from the hand of children strange,", "syllables": ["And", "from", "the", "hand", "of", "children", "stran-", "ge,"]}, {"text": "Whose mouth speaks vanity;", "bibleVerseRef": 8}, {"text": "And their right hand is a right hand"}, {"text": "that works deceitfully."}]}, {"index": 6, "lines": [{"text": "A new song I to thee will sing,", "bibleVerseRef": 9}, {"text": "Lord, on a psaltery;"}, {"text": "I on a ten-string''d instrument"}, {"text": "will praises sing to thee.", "syllables": ["will", "praise-", "s", "sing", "to", "thee."]}]}, {"index": 7, "lines": [{"text": "Ev''n he it is that unto kings", "bibleVerseRef": 10}, {"text": "salvation doth send;", "syllables": ["sal-", "va-", "tion", "doth", "se-", "nd;"]}, {"text": "Who his own servant David doth"}, {"text": "from hurtful sword defend."}]}, {"index": 8, "lines": [{"text": "O free me from strange children''s hand,", "syllables": ["O", "free", "me", "from", "strange", "chil-", "dren''s", "hand,"], "bibleVerseRef": 11}, {"text": "whose mouth speaks vanity;"}, {"text": "And their right hand a right hand is"}, {"text": "that works deceitfully."}]}, {"index": 9, "lines": [{"text": "That, as the plants, our sons may be", "bibleVerseRef": 12}, {"text": "in youth grown up that are;"}, {"text": "Our daughters like to corner-stones,", "syllables": ["Our", "daughters", "like", "to", "cor-", "ner-", "-sto-", "nes,"]}, {"text": "carv''d like a palace fair."}]}, {"index": 10, "lines": [{"text": "That to afford all kind of store", "syllables": ["That", "to", "afford", "all", "kind", "of", "sto-", "re"], "bibleVerseRef": 13}, {"text": "our garners may be fill''d;"}, {"text": "That our sheep thousands, in our streets"}, {"text": "ten thousands they may yield."}]}, {"index": 11, "lines": [{"text": "That strong our oxen be for work,", "syllables": ["That", "stro-", "ng", "our", "oxen", "be", "for", "work,"], "bibleVerseRef": 14}, {"text": "that no in-breaking be,"}, {"text": "Nor going out; and that our streets", "syllables": ["Nor", "going", "out;", "and", "that", "our", "stree-", "ts"]}, {"text": "may from complaints be free."}]}, {"index": 12, "lines": [{"text": "Those people blessed are who be", "syllables": ["Those", "peo-", "ple", "bles-", "sed", "are", "who", "be"], "bibleVerseRef": 15}, {"text": "in such a case as this;"}, {"text": "Yea, blessed all those people are,", "syllables": ["Yea,", "blessed", "all", "those", "pe-", "o-", "ple", "are,"]}, {"text": "whose God JEHOVAH is."}]}]', 'CM', NULL, 'O blessed ever be the Lord...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (122, 'rech8tY5f4VRyHTiy', 118, '118', '1O praise the Lord, for he is good;
his mercy lasteth ever.
2Let those of Israel now say,
His mercy faileth never.

3Now let the house of Aaron say,
His mercy lasteth ever.
4Let those that fear the Lord now say,
His mercy faileth never.

5I in distress call''d on the Lord;
the Lord did answer me:
He in a large place did me set,
from trouble made me free.

6The mighty Lord is on my side,
I will not be afraid;
For any thing that man can do
I shall not be dismay''d.

7The Lord doth take my part with them
that help to succour me:
Therefore on those that do me hate
I my desire shall see.

8Better it is to trust in God
than trust in man''s defence;
9Better to trust in God than make
princes our confidence.

10The nations, joining all in one,
did compass me about:
But in the Lord''s most holy name
I shall them all root out.

11They compass''d me about; I say,
they compass''d me about:
But in the Lord''s most holy name
I shall them all root out.

12Like bees they compass''d me about;
like unto thorns that flame
They quenched are: for them shall I
destroy in God''s own name.

13Thou sore hast thrust, that I might fall,
but my Lord helped me.
14God my salvation is become,
my strength and song is he.

15In dwellings of the righteous
is heard the melody
Of joy and health: the Lord''s right hand
doth ever valiantly.

16The right hand of the mighty Lord
exalted is on high;
The right hand of the mighty Lord
doth ever valiantly.

17I shall not die, but live,
and shall the works of God discover.
18The Lord hath me chastised sore,
but not to death giv''n over.

19O set ye open unto me
the gates of righteousness;
Then will I enter into them,
and I the Lord will bless.

20This is the gate of God, by it
the just shall enter in.
21Thee will I praise, for thou me heard''st
and hast my safety been.

22That stone is made head corner-stone,
which builders did despise:
23This is the doing of the Lord,
and wondrous in our eyes.

24This is the day God made, in it
we''ll joy triumphantly.
25Save now, I pray thee, Lord; I pray,
send now prosperity.

26Blessed is he in God''s great name
that cometh us to save:
We, from the house which to the Lord
pertains, you blessed have.

27God is the Lord, who unto us
hath made light to arise:
Bind ye unto the altar''s horns
with cords the sacrifice.

28Thou art my God, I''ll thee exalt;
my God, I will thee praise.
29Give thanks to God, for he is good:
his mercy lasts always.', '[{"index": 0, "lines": [{"text": "O praise the Lord, for he is good;", "bibleVerseRef": 1}, {"text": "his mercy lasteth ever."}, {"text": "Let those of Israel now say,", "syllables": ["Let", "tho-", "se", "of", "is-", "rael", "now", "say,"], "bibleVerseRef": 2}, {"text": "His mercy faileth never.", "syllables": ["His", "mercy", "fail-", "eth", "ne-", "ver."]}]}, {"index": 1, "lines": [{"text": "Now let the house of Aaron say,", "bibleVerseRef": 3}, {"text": "His mercy lasteth ever."}, {"text": "Let those that fear the Lord now say,", "bibleVerseRef": 4}, {"text": "His mercy faileth never.", "syllables": ["His", "mercy", "fail-", "eth", "ne-", "ver."]}]}, {"index": 2, "lines": [{"text": "I in distress call''d on the Lord;", "bibleVerseRef": 5}, {"text": "the Lord did answer me:"}, {"text": "He in a large place did me set,", "syllables": ["He", "in", "a", "large", "place", "did", "me", "set,"]}, {"text": "from trouble made me free."}]}, {"index": 3, "lines": [{"text": "The mighty Lord is on my side,", "bibleVerseRef": 6}, {"text": "I will not be afraid;"}, {"text": "For any thing that man can do"}, {"text": "I shall not be dismay''d."}]}, {"index": 4, "lines": [{"text": "The Lord doth take my part with them", "bibleVerseRef": 7}, {"text": "that help to succour me:"}, {"text": "Therefore on those that do me hate"}, {"text": "I my desire shall see."}]}, {"index": 5, "lines": [{"text": "Better it is to trust in God", "bibleVerseRef": 8}, {"text": "than trust in man''s defence;"}, {"text": "Better to trust in God than make", "bibleVerseRef": 9}, {"text": "princes our confidence.", "syllables": ["princes", "our", "con-", "fi-", "den-", "ce."]}]}, {"index": 6, "lines": [{"text": "The nations, joining all in one,", "bibleVerseRef": 10}, {"text": "did compass me about:"}, {"text": "But in the Lord''s most holy name"}, {"text": "I shall them all root out."}]}, {"index": 7, "lines": [{"text": "They compass''d me about; I say,", "bibleVerseRef": 11}, {"text": "they compass''d me about:"}, {"text": "But in the Lord''s most holy name"}, {"text": "I shall them all root out."}]}, {"index": 8, "lines": [{"text": "Like bees they compass''d me about;", "bibleVerseRef": 12}, {"text": "like unto thorns that flame", "syllables": ["like", "unto", "thorns", "that", "fla-", "me"]}, {"text": "They quenched are: for them shall I"}, {"text": "destroy in God''s own name."}]}, {"index": 9, "lines": [{"text": "Thou sore hast thrust, that I might fall,", "bibleVerseRef": 13}, {"text": "but my Lord helped me."}, {"text": "God my salvation is become,", "bibleVerseRef": 14}, {"text": "my strength and song is he."}]}, {"index": 10, "lines": [{"text": "In dwellings of the righteous", "syllables": ["In", "dwe-", "l-", "lings", "of", "the", "righ-", "teous"], "bibleVerseRef": 15}, {"text": "is heard the melody"}, {"text": "Of joy and health: the Lord''s right hand"}, {"text": "doth ever valiantly."}]}, {"index": 11, "lines": [{"text": "The right hand of the mighty Lord", "bibleVerseRef": 16}, {"text": "exalted is on high;"}, {"text": "The right hand of the mighty Lord"}, {"text": "doth ever valiantly."}]}, {"index": 12, "lines": [{"text": "I shall not die, but live,", "syllables": ["I", "sha-", "ll", "not", "die,", "but", "live-", ","], "bibleVerseRef": 17}, {"text": "and shall the works of God discover.", "syllables": ["and", "shall", "the", "works", "of", "Goddiscover."]}, {"text": "The Lord hath me chastised sore,", "syllables": ["The", "Lord", "hath", "me", "cha-", "s-", "tised", "sore,"], "bibleVerseRef": 18}, {"text": "but not to death giv''n over."}]}, {"index": 13, "lines": [{"text": "O set ye open unto me", "syllables": ["O", "set", "ye", "ope-", "n", "un-", "to", "me"], "bibleVerseRef": 19}, {"text": "the gates of righteousness;", "syllables": ["the", "gates", "of", "righ-", "teous-", "ness;"]}, {"text": "Then will I enter into them,"}, {"text": "and I the Lord will bless."}]}, {"index": 14, "lines": [{"text": "This is the gate of God, by it", "bibleVerseRef": 20}, {"text": "the just shall enter in."}, {"text": "Thee will I praise, for thou me heard''st", "bibleVerseRef": 21}, {"text": "and hast my safety been."}]}, {"index": 15, "lines": [{"text": "That stone is made head corner-stone,", "syllables": ["That", "stone", "is", "made", "head", "corner-", "-sto-", "ne,"], "bibleVerseRef": 22}, {"text": "which builders did despise:", "syllables": ["which", "bui-", "lders", "did", "des-", "pise:"]}, {"text": "This is the doing of the Lord,", "syllables": ["This", "is", "the", "doi-", "ng", "of", "the", "Lord,"], "bibleVerseRef": 23}, {"text": "and wondrous in our eyes."}]}, {"index": 16, "lines": [{"text": "This is the day God made, in it", "bibleVerseRef": 24}, {"text": "we''ll joy triumphantly.", "syllables": ["we''ll", "joy", "triu-", "m-", "phan-", "tly."]}, {"text": "Save now, I pray thee, Lord; I pray,", "bibleVerseRef": 25}, {"text": "send now prosperity."}]}, {"index": 17, "lines": [{"text": "Blessed is he in God''s great name", "bibleVerseRef": 26}, {"text": "that cometh us to save:"}, {"text": "We, from the house which to the Lord"}, {"text": "pertains, you blessed have."}]}, {"index": 18, "lines": [{"text": "God is the Lord, who unto us", "bibleVerseRef": 27}, {"text": "hath made light to arise:"}, {"text": "Bind ye unto the altar''s horns"}, {"text": "with cords the sacrifice."}]}, {"index": 19, "lines": [{"text": "Thou art my God, I''ll thee exalt;", "bibleVerseRef": 28}, {"text": "my God, I will thee praise."}, {"text": "Give thanks to God, for he is good:", "bibleVerseRef": 29}, {"text": "his mercy lasts always."}]}]', 'CM', NULL, 'O praise the Lord, for he is good...');
INSERT INTO public.psalm_versions (id, airtable_id, psalm_id, psalter_number, lyrics_imported_raw, lyrics_structured, meter, version_label, first_line) VALUES (158, 'recqQFVnnO0M8DdzA', 59, '59', '1My God, deliver me from those
that are mine enemies;
And do thou me defend from those
that up against me rise.

2Do thou deliver me from them
that work iniquity;
And give me safety from the men
of bloody cruelty.

3For, lo, they for my soul lay wait:
the mighty do combine
Against me, Lord; not for my fault,
nor any sin of mine.

4They run, and, without fault in me,
themselves do ready make:
Awake to meet me with thy help;
and do thou notice take.

5Awake therefore, Lord God of hosts,
thou God of Israel,
To visit heathen all: spare none
that wickedly rebel.

6At ev''ning they go to and fro;
they make great noise and sound,
Like to a dog, and often walk
about the city round.

7Behold, they belch out with their mouth,
and in their lips are swords:
For they do say thus, Who is he
that now doth hear our words?

8But thou, O Lord, shalt laugh at them,
and all the heathen mock.
9While he''s in pow''r I''ll wait on thee;
for God is my high rock.

10He of my mercy that is God
betimes shall me prevent;
Upon mine en''mies God shall let
me see mine heart''s content.

11Them slay not, lest my folk forget;
but scatter them abroad
By thy strong pow''r; and bring them down,
O thou our shield and God.

12For their mouth''s sin, and for the words
that from their lips do fly,
Let them be taken in their pride;
because they curse and lie.

13In wrath consume them, them consume,
that so they may not be:
And that in Jacob God doth rule
to th'' earth''s ends let them see.

14At ev''ning let thou them return,
making great noise and sound,
Like to a dog, and often walk
about the city round.

15And let them wander up and down,
in seeking food to eat;
And let them grudge when they shall not
be satisfy''d with meat.

16But of thy pow''r I''ll sing aloud;
at morn thy mercy praise:
For thou to me my refuge wast,
and tow''r, in troublous days.

17O God, thou art my strength, I will
sing praises unto thee;
For God is my defence, a God
of mercy unto me.', '[{"index": 0, "lines": [{"text": "My God, deliver me from those", "syllables": ["My", "God,", "de-", "live-", "r", "me", "from", "those"], "bibleVerseRef": 1}, {"text": "that are mine enemies;"}, {"text": "And do thou me defend from those"}, {"text": "that up against me rise."}]}, {"index": 1, "lines": [{"text": "Do thou deliver me from them", "syllables": ["Do", "thou", "de-", "live-", "r", "me", "from", "them"], "bibleVerseRef": 2}, {"text": "that work iniquity;"}, {"text": "And give me safety from the men"}, {"text": "of bloody cruelty.", "syllables": ["of", "bloo-", "dy", "crue-", "l-", "ty."]}]}, {"index": 2, "lines": [{"text": "For, lo, they for my soul lay wait:", "bibleVerseRef": 3}, {"text": "the mighty do combine"}, {"text": "Against me, Lord; not for my fault,"}, {"text": "nor any sin of mine."}]}, {"index": 3, "lines": [{"text": "They run, and, without fault in me,", "bibleVerseRef": 4}, {"text": "themselves do ready make:", "syllables": ["themsel-", "ves", "do", "rea-", "dy", "make:"]}, {"text": "Awake to meet me with thy help;"}, {"text": "and do thou notice take."}]}, {"index": 4, "lines": [{"text": "Awake therefore, Lord God of hosts,", "bibleVerseRef": 5}, {"text": "thou God of Israel,", "syllables": ["thou", "God", "of", "is-", "rae-", "l,"]}, {"text": "To visit heathen all: spare none", "syllables": ["To", "visit", "heathen", "all:", "spa-", "re", "no-", "ne"]}, {"text": "that wickedly rebel."}]}, {"index": 5, "lines": [{"text": "At ev''ning they go to and fro;", "bibleVerseRef": 6}, {"text": "they make great noise and sound,"}, {"text": "Like to a dog, and often walk"}, {"text": "about the city round."}]}, {"index": 6, "lines": [{"text": "Behold, they belch out with their mouth,", "bibleVerseRef": 7}, {"text": "and in their lips are swords:"}, {"text": "For they do say thus, Who is he"}, {"text": "that now doth hear our words?"}]}, {"index": 7, "lines": [{"text": "But thou, O Lord, shalt laugh at them,", "bibleVerseRef": 8}, {"text": "and all the heathen mock."}, {"text": "While he''s in pow''r I''ll wait on thee;", "bibleVerseRef": 9}, {"text": "for God is my high rock."}]}, {"index": 8, "lines": [{"text": "He of my mercy that is God", "bibleVerseRef": 10}, {"text": "betimes shall me prevent;", "syllables": ["be-", "times", "shall", "me", "preve-", "nt;"]}, {"text": "Upon mine en''mies God shall let"}, {"text": "me see mine heart''s content."}]}, {"index": 9, "lines": [{"text": "Them slay not, lest my folk forget;", "bibleVerseRef": 11}, {"text": "but scatter them abroad", "syllables": ["but", "scatter", "them", "ab-", "ro-", "ad"]}, {"text": "By thy strong pow''r; and bring them down,"}, {"text": "O thou our shield and God."}]}, {"index": 10, "lines": [{"text": "For their mouth''s sin, and for the words", "bibleVerseRef": 12}, {"text": "that from their lips do fly,"}, {"text": "Let them be taken in their pride;"}, {"text": "because they curse and lie.", "syllables": ["because", "they", "cur-", "se", "and", "lie."]}]}, {"index": 11, "lines": [{"text": "In wrath consume them, them consume,", "bibleVerseRef": 13}, {"text": "that so they may not be:"}, {"text": "And that in Jacob God doth rule"}, {"text": "to th'' earth''s ends let them see.", "syllables": ["to", "th''", "earth''s", "ends", "let", "themsee."]}]}, {"index": 12, "lines": [{"text": "At ev''ning let thou them return,", "bibleVerseRef": 14}, {"text": "making great noise and sound,"}, {"text": "Like to a dog, and often walk"}, {"text": "about the city round."}]}, {"index": 13, "lines": [{"text": "And let them wander up and down,", "bibleVerseRef": 15}, {"text": "in seeking food to eat;"}, {"text": "And let them grudge when they shall not", "syllables": ["And", "let", "them", "grudge", "when", "they", "shall", "not"]}, {"text": "be satisfy''d with meat."}]}, {"index": 14, "lines": [{"text": "But of thy pow''r I''ll sing aloud;", "bibleVerseRef": 16}, {"text": "at morn thy mercy praise:"}, {"text": "For thou to me my refuge wast,"}, {"text": "and tow''r, in troublous days."}]}, {"index": 15, "lines": [{"text": "O God, thou art my strength, I will", "bibleVerseRef": 17}, {"text": "sing praises unto thee;", "syllables": ["sing", "praise-", "s", "un-", "to", "thee;"]}, {"text": "For God is my defence, a God"}, {"text": "of mercy unto me."}]}]', 'CM', NULL, 'My God, deliver me from those...');


